CREATE FUNCTION public.fn_hr_reward_file_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ DECLARE file_id uuid; BEGIN FOR file_id IN SELECT jsonb_array_elements_text(NEW.evidence_snapshot)::uuid LOOP IF NOT EXISTS(SELECT 1 FROM sys_file f WHERE f.tenant_id=NEW.tenant_id AND f.park_id=NEW.park_id AND f.id=file_id AND f.biz_type='hr_reward_evidence' AND f.biz_id=NEW.id AND f.status=1 AND f.is_deleted=false FOR SHARE) THEN RAISE EXCEPTION 'reward evidence file owner mismatch'; END IF; END LOOP; RETURN NEW; END $$;



--
-- Name: fn_hr_reward_file_inverse_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_hr_reward_file_inverse_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
 IF EXISTS(SELECT 1 FROM hr_reward_discipline_case c WHERE c.tenant_id=OLD.tenant_id AND c.park_id=OLD.park_id AND c.id=OLD.biz_id AND OLD.biz_type='hr_reward_evidence' AND c.evidence_snapshot ? OLD.id::text AND c.is_deleted=false FOR SHARE) THEN
