--
-- Name: fn_hr_training_participant_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_hr_training_participant_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE ps varchar(24);
BEGIN
 IF TG_OP='DELETE' AND hr_legacy_training_reward_rollback_allowed(TG_TABLE_NAME,OLD.id) THEN RETURN OLD; END IF;
 SELECT status INTO ps FROM hr_training_plan WHERE tenant_id=COALESCE(NEW.tenant_id,OLD.tenant_id) AND park_id=COALESCE(NEW.park_id,OLD.park_id) AND id=COALESCE(NEW.plan_id,OLD.plan_id) FOR SHARE;
 IF TG_OP='INSERT' AND ps<>'draft' THEN RAISE EXCEPTION 'published training participants are immutable'; END IF;
 IF TG_OP='DELETE' AND ps<>'draft' THEN RAISE EXCEPTION 'published training participants are immutable'; END IF;
 IF TG_OP='UPDATE' AND (NEW.tenant_id,NEW.park_id,NEW.plan_id,NEW.employee_id) IS DISTINCT FROM (OLD.tenant_id,OLD.park_id,OLD.plan_id,OLD.employee_id) THEN RAISE EXCEPTION 'training participant ownership is immutable'; END IF;
 IF TG_OP='UPDATE' AND NEW.status IS DISTINCT FROM OLD.status AND NOT ((OLD.status='assigned' AND NEW.status IN('checked_in','completed','cancelled')) OR (OLD.status='checked_in' AND NEW.status IN('completed','cancelled'))) THEN RAISE EXCEPTION 'invalid training participant transition'; END IF;
 IF TG_OP='UPDATE' AND OLD.status='completed' AND (NEW.status,NEW.checked_in_at,NEW.completed_at,NEW.completed_hours,NEW.score,NEW.evaluation,NEW.actual_cost,NEW.certificate_file_id) IS DISTINCT FROM (OLD.status,OLD.checked_in_at,OLD.completed_at,OLD.completed_hours,OLD.score,OLD.evaluation,OLD.actual_cost,OLD.certificate_file_id) THEN RAISE EXCEPTION 'completed training result requires correction'; END IF;
 RETURN COALESCE(NEW,OLD);
END $$;



--
-- Name: fn_hr_training_plan_fact_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_hr_training_plan_fact_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE ps varchar(24); expected integer;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'training plan facts revisions are append only'; END IF;
 SELECT status INTO ps FROM hr_training_plan
  WHERE tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND id=NEW.plan_id AND NOT is_deleted FOR UPDATE;
 IF ps IS NULL OR ps NOT IN('published','in_progress','completed') THEN
  RAISE EXCEPTION 'training plan facts revision requires a published active or completed plan';
 END IF;
 SELECT COALESCE(max(sequence_no),0)+1 INTO expected FROM hr_training_plan_fact_revision
  WHERE tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND plan_id=NEW.plan_id;
 IF NEW.sequence_no<>expected THEN RAISE EXCEPTION 'training plan facts revision sequence is stale'; END IF;
 RETURN NEW;
END $$;



--
-- Name: fn_hr_training_plan_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_hr_training_plan_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN
  IF hr_legacy_training_reward_rollback_allowed(TG_TABLE_NAME,OLD.id) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'training plan is immutable';
 END IF;
 IF NEW.status IS DISTINCT FROM OLD.status AND NOT ((OLD.status='draft' AND NEW.status='published') OR (OLD.status='published' AND NEW.status='in_progress') OR (OLD.status='in_progress' AND NEW.status IN('completed','cancelled'))) THEN RAISE EXCEPTION 'invalid training plan transition'; END IF;
 IF OLD.status<>'draft' AND (NEW.course_id,NEW.course_version_id,NEW.mandatory,NEW.start_date,NEW.end_date,NEW.budget_amount,NEW.cost_currency,NEW.participant_scope,NEW.snapshot,NEW.published_at) IS DISTINCT FROM (OLD.course_id,OLD.course_version_id,OLD.mandatory,OLD.start_date,OLD.end_date,OLD.budget_amount,OLD.cost_currency,OLD.participant_scope,OLD.snapshot,OLD.published_at) THEN RAISE EXCEPTION 'published training plan snapshot is immutable'; END IF;
 IF OLD.status IN('completed','cancelled') AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'terminal training plan is immutable'; END IF;
 RETURN NEW;
END $$;



--
-- Name: fn_hr_training_position_requirement_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_hr_training_position_requirement_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'training position requirement is immutable'; END IF;
 IF (NEW.tenant_id,NEW.park_id,NEW.position_id,NEW.course_id,NEW.course_version_id,NEW.create_by,NEW.create_time) IS DISTINCT FROM (OLD.tenant_id,OLD.park_id,OLD.position_id,OLD.course_id,OLD.course_version_id,OLD.create_by,OLD.create_time) THEN RAISE EXCEPTION 'training position requirement identity is immutable'; END IF;
 IF OLD.status='disabled' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'disabled training position requirement is immutable'; END IF;
 IF NEW.status IS DISTINCT FROM OLD.status AND NOT(OLD.status='enabled' AND NEW.status='disabled') THEN RAISE EXCEPTION 'invalid training position requirement transition'; END IF;
 IF OLD.status='enabled' AND NEW.status='enabled' AND (NEW.disabled_by,NEW.disabled_at) IS DISTINCT FROM (OLD.disabled_by,OLD.disabled_at) THEN RAISE EXCEPTION 'enabled training position requirement cannot be altered'; END IF;
 RETURN NEW;
END $$;



--
-- Name: fn_party_identity_protected_audit_assign_retention(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_party_identity_protected_audit_assign_retention() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE party_value uuid; object_time timestamptz; days_value integer; action_value varchar(32);
BEGIN
  IF TG_TABLE_NAME='biz_party_identity_assignment_audit' THEN
    party_value:=NEW.party_id; object_time:=NEW.occurred_at;
  ELSIF TG_TABLE_NAME='biz_party_identity_decision' THEN
    party_value:=NEW.party_id; object_time:=NEW.create_time;
  ELSIF NEW.biz_type='party_identity_submission'
        AND NEW.biz_id::text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
    SELECT party_id INTO party_value FROM public.biz_party_identity_submission
      WHERE tenant_id=NEW.tenant_id::text AND park_id=NEW.park_id::text AND id=NEW.biz_id::uuid;
    object_time:=NEW.create_time;
  ELSE
    RETURN NEW;
  END IF;
  IF party_value IS NULL THEN RETURN NEW; END IF;
  INSERT INTO public.biz_party_identity_retention_policy(tenant_id,park_id)
    VALUES(NEW.tenant_id::text,NEW.park_id::text) ON CONFLICT(tenant_id,park_id) DO NOTHING;
  SELECT protected_audit_days,protected_audit_action INTO days_value,action_value
  FROM public.biz_party_identity_retention_policy
  WHERE tenant_id=NEW.tenant_id::text AND park_id=NEW.park_id::text;
  INSERT INTO public.biz_party_identity_retention_assignment(
    tenant_id,park_id,party_id,category,object_id,retention_until,expiry_action,state,source)
  VALUES(NEW.tenant_id::text,NEW.park_id::text,party_value,'protected_audit',NEW.id,
    COALESCE(object_time,now())+make_interval(days=>days_value),action_value,'active','policy')
  ON CONFLICT(tenant_id,park_id,category,object_id) DO NOTHING;
  RETURN NEW;
END;
$_$;



--
-- Name: hr_assert_legacy_archive_identity_kinds(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_assert_legacy_archive_identity_kinds() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE registry_kind varchar(32); file_owner uuid; archive_owner uuid;
BEGIN
  IF TG_TABLE_NAME='hr_legacy_archive_record' THEN
    SELECT identity_kind INTO registry_kind FROM hr_legacy_identity_registry
      WHERE tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND id=NEW.identity_registry_id;
    IF registry_kind IS DISTINCT FROM 'archive_record' THEN RAISE EXCEPTION 'HR_LEGACY_ARCHIVE_IDENTITY_KIND_INVALID'; END IF;
  ELSE
    SELECT identity_kind,owner_employee_id INTO registry_kind,file_owner FROM hr_legacy_identity_registry
      WHERE tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND id=NEW.identity_registry_id;
    IF registry_kind IS DISTINCT FROM 'file_logical' THEN RAISE EXCEPTION 'HR_LEGACY_FILE_IDENTITY_KIND_INVALID'; END IF;
    IF NEW.archive_record_id IS NOT NULL THEN
      SELECT registry.owner_employee_id INTO archive_owner
      FROM hr_legacy_archive_record archive
      JOIN hr_legacy_identity_registry registry ON (registry.tenant_id,registry.park_id,registry.id)=(archive.tenant_id,archive.park_id,archive.identity_registry_id)
      WHERE archive.tenant_id=NEW.tenant_id AND archive.park_id=NEW.park_id AND archive.id=NEW.archive_record_id;
      IF NOT FOUND OR archive_owner IS DISTINCT FROM file_owner THEN RAISE EXCEPTION 'HR_LEGACY_FILE_OWNER_MISMATCH'; END IF;
    END IF;
  END IF;
  RETURN NEW;
END $$;



--
-- Name: hr_assert_legacy_identity_t0_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_assert_legacy_identity_t0_owner() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE record_map legacy_record_map%ROWTYPE;
BEGIN
  IF NEW.owner_record_map_id IS NULL THEN RETURN NEW; END IF;
  SELECT * INTO record_map FROM legacy_record_map WHERE id=NEW.owner_record_map_id;
  IF NOT FOUND
    OR NOT record_map.is_active
    OR record_map.mapping_status NOT IN ('loaded','verified')
    OR record_map.source_system<>'yuzhou-v10'
    OR record_map.source_table<>'dbo.person'
    OR record_map.source_system<>NEW.owner_source_system
    OR record_map.source_table<>NEW.owner_source_table
    OR record_map.source_identity_sha256<>NEW.owner_source_identity_sha256
    OR record_map.target_table<>'hr_employee'
    OR record_map.target_id IS DISTINCT FROM NEW.owner_employee_id
  THEN
    RAISE EXCEPTION 'HR_LEGACY_OWNER_REQUIRES_EXACT_T0_RECORD_MAP';
  END IF;
  RETURN NEW;
END $$;



--
-- Name: hr_assert_legacy_materialization_source(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_assert_legacy_materialization_source() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE batch_row hr_legacy_archive_materialization_batch%ROWTYPE;
DECLARE source_matches integer;
BEGIN
  IF NEW.materialization_batch_id IS NULL THEN RETURN NEW; END IF;
  SELECT * INTO batch_row
  FROM hr_legacy_archive_materialization_batch
  WHERE tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND id=NEW.materialization_batch_id
  FOR SHARE;
  IF NOT FOUND OR batch_row.status<>'unpublished' THEN
    RAISE EXCEPTION 'HR_LEGACY_ARCHIVE_MATERIALIZATION_BATCH_NOT_OPEN';
  END IF;
  IF TG_TABLE_NAME='hr_legacy_identity_registry' THEN
    SELECT count(*)::integer INTO source_matches FROM (
      SELECT 1 FROM hr_legacy_t5_record source
       WHERE source.import_batch_id=batch_row.source_t5_import_batch_id
         AND source.source_table=NEW.source_table
         AND source.source_identity_sha256=NEW.source_identity_sha256
         AND source.source_row_sha256=NEW.source_row_sha256
      UNION ALL
      SELECT 1 FROM hr_legacy_t5_file_evidence source
       WHERE source.import_batch_id=batch_row.source_t5_import_batch_id
         AND source.source_table=NEW.source_table
         AND source.source_identity_sha256=NEW.source_identity_sha256
         AND source.source_row_sha256=NEW.source_row_sha256
    ) source;
    IF source_matches<>1 THEN RAISE EXCEPTION 'HR_LEGACY_ARCHIVE_SOURCE_NOT_EXACT'; END IF;
  ELSE
    IF NOT EXISTS(
      SELECT 1 FROM hr_legacy_identity_registry registry
       WHERE registry.tenant_id=NEW.tenant_id AND registry.park_id=NEW.park_id
         AND registry.id=NEW.identity_registry_id
         AND registry.materialization_batch_id=NEW.materialization_batch_id
    ) THEN RAISE EXCEPTION 'HR_LEGACY_ARCHIVE_MATERIALIZATION_BATCH_MISMATCH'; END IF;
  END IF;
  RETURN NEW;
END $$;



--
-- Name: hr_assign_employment_event_no(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_assign_employment_event_no() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  prefix_value text;
  period_value text;
  next_value integer;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.event_no IS DISTINCT FROM OLD.event_no THEN
    RAISE EXCEPTION 'HR_EMPLOYMENT_EVENT_NO_IMMUTABLE: event number cannot be changed';
  END IF;

  IF NEW.is_historical_import THEN
    NEW.event_no := coalesce(NEW.event_no, NEW.legacy_event_no);
    RETURN NEW;
  END IF;

  prefix_value := CASE
    WHEN NEW.event_type IN ('start_probation', 'confirm_employment') THEN 'JZ'
    WHEN NEW.event_type IN ('transfer', 'suspend') THEN 'DZ'
    WHEN NEW.event_type = 'depart' THEN 'LZ'
    WHEN NEW.event_type = 'resume' THEN 'FZ'
    ELSE NULL
  END;

  IF prefix_value IS NULL THEN
    IF NEW.event_no IS NOT NULL THEN
      RAISE EXCEPTION 'HR_EMPLOYMENT_EVENT_NO_UNEXPECTED: this event type must not carry a lifecycle number';
    END IF;
    RETURN NEW;
  END IF;

  period_value := to_char(NEW.effective_date, 'YYYYMM');
  IF NEW.event_no IS NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(
      NEW.tenant_id || ':' || NEW.park_id || ':' || prefix_value || ':' || period_value,
      0
    ));
    SELECT coalesce(max(right(event_no, 4)::integer), 0) + 1
    INTO next_value
    FROM hr_employment_event
    WHERE tenant_id = NEW.tenant_id
      AND park_id = NEW.park_id
      AND event_no ~ ('^' || prefix_value || period_value || '[0-9]{4}$');
    IF next_value > 9999 THEN
      RAISE EXCEPTION 'HR_EMPLOYMENT_EVENT_NO_EXHAUSTED: monthly event number sequence is full';
    END IF;
    NEW.event_no := prefix_value || period_value || lpad(next_value::text, 4, '0');
  ELSIF NEW.event_no !~ ('^' || prefix_value || period_value || '[0-9]{4}$') THEN
    RAISE EXCEPTION 'HR_EMPLOYMENT_EVENT_NO_INVALID: supplied event number does not match type and effective month';
  END IF;
  RETURN NEW;
END
$_$;



--
-- Name: hr_attendance_leave_cancellation_approval_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_attendance_leave_cancellation_approval_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE cancellation public.hr_attendance_leave_cancellation%ROWTYPE; approval public.hr_approval_request%ROWTYPE;
BEGIN
  SELECT * INTO cancellation FROM public.hr_attendance_leave_cancellation WHERE approval_request_id=NEW.id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT * INTO approval FROM public.hr_approval_request WHERE id=NEW.id;
  IF NOT FOUND OR approval.is_deleted OR approval.tenant_id<>cancellation.tenant_id OR approval.park_id<>cancellation.park_id
    OR approval.applicant_employee_id<>cancellation.employee_id OR approval.subject_employee_id<>cancellation.employee_id
    OR approval.request_type<>'attendance_request' OR approval.payload->>'kind' IS DISTINCT FROM 'leave_cancellation'
    OR approval.payload->>'sourceRequestId' IS DISTINCT FROM cancellation.source_request_id::text
    OR approval.status IS DISTINCT FROM (CASE WHEN cancellation.status='cancelled' THEN 'withdrawn' ELSE cancellation.status END) THEN
    RAISE EXCEPTION 'HR_LEAVE_CANCELLATION_APPROVAL_PROJECTION_DRIFT';
  END IF;
  RETURN NULL;
END $$;



--
-- Name: hr_attendance_leave_cancellation_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_attendance_leave_cancellation_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE source public.hr_attendance_request%ROWTYPE; approval public.hr_approval_request%ROWTYPE;
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'HR_LEAVE_CANCELLATION_RETAINED'; END IF;
  SELECT * INTO source FROM public.hr_attendance_request WHERE id=NEW.source_request_id FOR SHARE;
  IF NOT FOUND OR source.tenant_id<>NEW.tenant_id OR source.park_id<>NEW.park_id
    OR source.employee_id<>NEW.employee_id OR source.is_deleted OR source.request_type<>'leave'
    OR source.status<>'approved' OR source.version<>NEW.source_request_version
    OR source.start_at IS NULL OR source.end_at IS NULL
    OR NEW.start_at<source.start_at OR NEW.end_at>source.end_at THEN
    RAISE EXCEPTION 'HR_LEAVE_CANCELLATION_SOURCE_INVALID';
  END IF;
  PERFORM 1 FROM public.hr_employee WHERE id=NEW.employee_id AND tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND NOT is_deleted FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'HR_LEAVE_CANCELLATION_EMPLOYEE_INVALID'; END IF;
  SELECT * INTO approval FROM public.hr_approval_request WHERE id=NEW.approval_request_id FOR SHARE;
  IF NOT FOUND OR approval.tenant_id<>NEW.tenant_id OR approval.park_id<>NEW.park_id OR approval.is_deleted
    OR approval.applicant_employee_id<>NEW.employee_id OR approval.subject_employee_id<>NEW.employee_id
    OR approval.request_type<>'attendance_request' OR approval.payload->>'kind' IS DISTINCT FROM 'leave_cancellation'
    OR approval.payload->>'sourceRequestId' IS DISTINCT FROM NEW.source_request_id::text
    OR approval.status IS DISTINCT FROM (CASE WHEN NEW.status='cancelled' THEN 'withdrawn' ELSE NEW.status END) THEN
    RAISE EXCEPTION 'HR_LEAVE_CANCELLATION_APPROVAL_INVALID';
  END IF;
  IF NEW.status='approved' AND EXISTS(SELECT 1 FROM public.hr_employee WHERE id=NEW.employee_id AND user_id=NEW.updated_by) THEN
    RAISE EXCEPTION 'HR_LEAVE_CANCELLATION_SELF_APPROVAL_FORBIDDEN';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.status<>'draft' OR NEW.version<>1 THEN RAISE EXCEPTION 'HR_LEAVE_CANCELLATION_INITIAL_STATE_INVALID'; END IF;
  ELSE
    IF ROW(NEW.id,NEW.tenant_id,NEW.park_id,NEW.employee_id,NEW.source_request_id,NEW.source_request_version,NEW.approval_request_id,NEW.cancellation_no,NEW.created_by,NEW.created_at)
      IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.park_id,OLD.employee_id,OLD.source_request_id,OLD.source_request_version,OLD.approval_request_id,OLD.cancellation_no,OLD.created_by,OLD.created_at)
      OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'HR_LEAVE_CANCELLATION_IDENTITY_OR_VERSION_CHANGED'; END IF;
    IF OLD.status IN ('approved','cancelled')
      OR NOT ((OLD.status='draft' AND NEW.status IN ('draft','submitted','cancelled'))
        OR (OLD.status='returned' AND NEW.status IN ('returned','submitted','cancelled'))
        OR (OLD.status='submitted' AND NEW.status IN ('approved','returned','cancelled')))
      OR (OLD.status='submitted' AND ROW(NEW.start_at,NEW.end_at,NEW.reason) IS DISTINCT FROM ROW(OLD.start_at,OLD.end_at,OLD.reason)) THEN
      RAISE EXCEPTION 'HR_LEAVE_CANCELLATION_TRANSITION_INVALID';
    END IF;
  END IF;
  RETURN NEW;
END $$;



--
-- Name: hr_attendance_leave_cancellation_history_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_attendance_leave_cancellation_history_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'HR_LEAVE_CANCELLATION_HISTORY_IMMUTABLE'; END IF;
  PERFORM 1 FROM public.hr_attendance_leave_cancellation c
    WHERE c.id=NEW.cancellation_id AND c.tenant_id=NEW.tenant_id AND c.park_id=NEW.park_id
      AND c.employee_id=NEW.employee_id AND c.source_request_id=NEW.source_request_id AND c.version=NEW.version
      AND c.status=NEW.status AND c.start_at=NEW.start_at AND c.end_at=NEW.end_at AND c.reason=NEW.reason
      AND c.updated_by=NEW.actor_user_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'HR_LEAVE_CANCELLATION_HISTORY_SNAPSHOT_INVALID'; END IF;
  RETURN NEW;
END $$;



