--
-- Name: hr_departure_application_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_departure_application_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF OLD.is_historical_import THEN RAISE EXCEPTION 'HR_DEPARTURE_HISTORICAL_IMMUTABLE'; END IF;
 IF OLD.status IN('cancelled','applied') THEN RAISE EXCEPTION 'HR_DEPARTURE_TERMINAL_IMMUTABLE'; END IF;
 IF (OLD.status,NEW.status) NOT IN(
   ('draft','draft'),('draft','submitted'),('draft','cancelled'),
   ('returned','returned'),('returned','submitted'),('returned','cancelled'),
   ('submitted','approved'),('submitted','returned'),('submitted','cancelled'),('approved','approved'),('approved','applied')
 ) THEN RAISE EXCEPTION 'HR_DEPARTURE_TRANSITION_INVALID: % -> %',OLD.status,NEW.status; END IF;
 IF OLD.status NOT IN('draft','returned') AND (
   NEW.application_name,NEW.subject_employee_id,NEW.application_date,NEW.planned_departure_date,
   NEW.departure_type,NEW.reason,NEW.before_snapshot
 ) IS DISTINCT FROM (
   OLD.application_name,OLD.subject_employee_id,OLD.application_date,OLD.planned_departure_date,
   OLD.departure_type,OLD.reason,OLD.before_snapshot
 ) THEN RAISE EXCEPTION 'HR_DEPARTURE_SUBMITTED_FACTS_IMMUTABLE'; END IF;
 IF OLD.status<>'approved' AND (
   NEW.interview_status,NEW.interview_by,NEW.interview_at,NEW.interview_place,NEW.interview_summary,
   NEW.survey_status,NEW.survey_by,NEW.survey_at,NEW.survey_reason_codes,NEW.survey_summary,
   NEW.handover_status,NEW.handover_by,NEW.handover_at,NEW.handover_to_employee_id,NEW.handover_summary,
   NEW.wage_status,NEW.wage_by,NEW.wage_at,NEW.wage_note,
   NEW.archive_status,NEW.archive_by,NEW.archive_at,NEW.archive_note
 ) IS DISTINCT FROM (
   OLD.interview_status,OLD.interview_by,OLD.interview_at,OLD.interview_place,OLD.interview_summary,
   OLD.survey_status,OLD.survey_by,OLD.survey_at,OLD.survey_reason_codes,OLD.survey_summary,
   OLD.handover_status,OLD.handover_by,OLD.handover_at,OLD.handover_to_employee_id,OLD.handover_summary,
   OLD.wage_status,OLD.wage_by,OLD.wage_at,OLD.wage_note,
   OLD.archive_status,OLD.archive_by,OLD.archive_at,OLD.archive_note
 ) THEN RAISE EXCEPTION 'HR_DEPARTURE_CLEARANCE_REQUIRES_APPROVAL'; END IF;
 IF OLD.interview_status<>'pending' AND (NEW.interview_status,NEW.interview_by,NEW.interview_at,NEW.interview_place,NEW.interview_summary) IS DISTINCT FROM (OLD.interview_status,OLD.interview_by,OLD.interview_at,OLD.interview_place,OLD.interview_summary) THEN RAISE EXCEPTION 'HR_DEPARTURE_INTERVIEW_IMMUTABLE'; END IF;
 IF OLD.survey_status<>'pending' AND (NEW.survey_status,NEW.survey_by,NEW.survey_at,NEW.survey_reason_codes,NEW.survey_summary) IS DISTINCT FROM (OLD.survey_status,OLD.survey_by,OLD.survey_at,OLD.survey_reason_codes,OLD.survey_summary) THEN RAISE EXCEPTION 'HR_DEPARTURE_SURVEY_IMMUTABLE'; END IF;
 IF OLD.handover_status<>'pending' AND (NEW.handover_status,NEW.handover_by,NEW.handover_at,NEW.handover_to_employee_id,NEW.handover_summary) IS DISTINCT FROM (OLD.handover_status,OLD.handover_by,OLD.handover_at,OLD.handover_to_employee_id,OLD.handover_summary) THEN RAISE EXCEPTION 'HR_DEPARTURE_HANDOVER_IMMUTABLE'; END IF;
 IF OLD.wage_status<>'pending' AND (NEW.wage_status,NEW.wage_by,NEW.wage_at,NEW.wage_note) IS DISTINCT FROM (OLD.wage_status,OLD.wage_by,OLD.wage_at,OLD.wage_note) THEN RAISE EXCEPTION 'HR_DEPARTURE_WAGE_IMMUTABLE'; END IF;
 IF OLD.archive_status='closed' AND (NEW.archive_status,NEW.archive_by,NEW.archive_at,NEW.archive_note) IS DISTINCT FROM (OLD.archive_status,OLD.archive_by,OLD.archive_at,OLD.archive_note) THEN RAISE EXCEPTION 'HR_DEPARTURE_ARCHIVE_IMMUTABLE'; END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_development_action_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_development_action_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'development action cannot be deleted';END IF;
 IF (NEW.tenant_id,NEW.park_id,NEW.plan_id,NEW.action_no,NEW.action_name,NEW.owner_employee_id,NEW.due_date,NEW.created_by,NEW.created_at) IS DISTINCT FROM (OLD.tenant_id,OLD.park_id,OLD.plan_id,OLD.action_no,OLD.action_name,OLD.owner_employee_id,OLD.due_date,OLD.created_by,OLD.created_at) THEN RAISE EXCEPTION 'development action identity is immutable';END IF;
 IF OLD.status IN('completed','cancelled') AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'terminal development action is immutable';END IF;
 IF NEW.status IS DISTINCT FROM OLD.status AND NOT((OLD.status='pending' AND NEW.status IN('in_progress','completed','cancelled'))OR(OLD.status='in_progress' AND NEW.status IN('completed','cancelled')))THEN RAISE EXCEPTION 'invalid development action transition';END IF;RETURN NEW;
END$$;



--
-- Name: hr_development_action_insert_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_development_action_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$DECLARE v_status varchar(24);v_start date;v_end date;BEGIN
 SELECT status,start_date,end_date INTO v_status,v_start,v_end FROM hr_development_plan WHERE (id,tenant_id,park_id)=(NEW.plan_id,NEW.tenant_id,NEW.park_id) FOR UPDATE;
 IF v_status IN('completed','cancelled') THEN RAISE EXCEPTION 'development plan is terminal';END IF;
 IF NEW.due_date<v_start OR NEW.due_date>v_end THEN RAISE EXCEPTION 'development action due date is outside the plan';END IF;
 RETURN NEW;
END$$;



--
-- Name: hr_development_plan_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_development_plan_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'development plan cannot be deleted';END IF;
 IF (NEW.tenant_id,NEW.park_id,NEW.employee_id,NEW.profile_snapshot_id,NEW.plan_code,NEW.plan_name,NEW.development_goal,NEW.start_date,NEW.end_date,NEW.created_by,NEW.created_at) IS DISTINCT FROM (OLD.tenant_id,OLD.park_id,OLD.employee_id,OLD.profile_snapshot_id,OLD.plan_code,OLD.plan_name,OLD.development_goal,OLD.start_date,OLD.end_date,OLD.created_by,OLD.created_at) THEN RAISE EXCEPTION 'development plan snapshot is immutable';END IF;
 IF OLD.status IN('completed','cancelled') AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'terminal development plan is immutable';END IF;
 IF NEW.status IS DISTINCT FROM OLD.status AND NOT((OLD.status='draft' AND NEW.status IN('active','cancelled'))OR(OLD.status='active' AND NEW.status IN('completed','cancelled')))THEN RAISE EXCEPTION 'invalid development plan transition';END IF;RETURN NEW;
END$$;



--
-- Name: hr_employee_departure_workflow_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_employee_departure_workflow_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.employment_status='departed' AND OLD.employment_status<>'departed' AND NOT EXISTS(
   SELECT 1 FROM hr_departure_application d
   WHERE d.tenant_id=NEW.tenant_id AND d.park_id=NEW.park_id AND d.subject_employee_id=NEW.id
     AND d.is_deleted=false AND d.status='approved' AND d.planned_departure_date=NEW.departure_date
     AND d.interview_status IN('completed','waived') AND d.survey_status IN('completed','waived')
     AND d.handover_status IN('completed','waived') AND d.wage_status IN('settled','waived') AND d.archive_status='closed'
 ) THEN RAISE EXCEPTION 'HR_EMPLOYEE_DEPARTURE_WORKFLOW_REQUIRED'; END IF;
 IF NEW.employment_status=OLD.employment_status AND NEW.departure_date IS DISTINCT FROM OLD.departure_date THEN
   RAISE EXCEPTION 'HR_EMPLOYEE_DEPARTURE_DATE_WORKFLOW_REQUIRED';
 END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_employee_feedback_action_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_employee_feedback_action_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE r public.hr_employee_feedback%ROWTYPE;prior public.hr_employee_feedback_action%ROWTYPE;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'EMPLOYEE_FEEDBACK_HISTORY_IMMUTABLE';END IF;
 SELECT * INTO r FROM public.hr_employee_feedback WHERE(id,tenant_id,park_id)=(NEW.feedback_id,NEW.tenant_id,NEW.park_id) FOR UPDATE;
 SELECT * INTO prior FROM public.hr_employee_feedback_action WHERE(id,tenant_id,park_id,feedback_id)=(NEW.previous_action_id,NEW.tenant_id,NEW.park_id,NEW.feedback_id);
 IF r.id IS NULL OR r.current_action_id IS DISTINCT FROM NEW.id OR r.version IS DISTINCT FROM NEW.version_no OR r.updated_by IS DISTINCT FROM NEW.actor_user_id OR r.updated_at IS DISTINCT FROM NEW.created_at OR NEW.created_at IS DISTINCT FROM transaction_timestamp() OR NEW.snapshot IS DISTINCT FROM jsonb_build_object('kind',r.kind,'title',r.title,'content',r.content,'reply',r.reply,'status',r.status) OR NEW.to_status IS DISTINCT FROM r.status THEN RAISE EXCEPTION 'EMPLOYEE_FEEDBACK_HISTORY_INVALID';END IF;
 IF NEW.version_no=1 THEN
  IF NEW.action<>'create' OR NEW.previous_action_id IS NOT NULL OR NEW.from_status IS NOT NULL OR NEW.to_status<>'draft' THEN RAISE EXCEPTION 'EMPLOYEE_FEEDBACK_HISTORY_START_INVALID';END IF;
 ELSE
  IF prior.id IS NULL OR prior.version_no<>NEW.version_no-1 OR NEW.from_status IS DISTINCT FROM prior.to_status OR NEW.action IS DISTINCT FROM (CASE WHEN NEW.to_status='draft' THEN 'edit' WHEN NEW.to_status='submitted' THEN 'submit' WHEN NEW.to_status='cancelled' THEN 'cancel' WHEN NEW.to_status='withdrawn' THEN 'withdraw' WHEN NEW.to_status='answered' THEN 'reply' END) THEN RAISE EXCEPTION 'EMPLOYEE_FEEDBACK_HISTORY_CHAIN_INVALID';END IF;
 END IF;RETURN NEW;
END $$;



--
-- Name: hr_employee_feedback_authorized(character varying, character varying, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_employee_feedback_authorized(t character varying, p character varying, u uuid, cap text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 SELECT public.hr_performance_channel_actor_has(t,p,u,'hr:approvals') AND public.hr_performance_channel_actor_has(t,p,u,cap)
$$;



--
-- Name: hr_employee_feedback_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_employee_feedback_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE own boolean;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'EMPLOYEE_FEEDBACK_IMMUTABLE';END IF;
 SELECT EXISTS(SELECT 1 FROM public.hr_employee WHERE(id,tenant_id,park_id,user_id)=(NEW.employee_id,NEW.tenant_id,NEW.park_id,NEW.updated_by) AND NOT is_deleted) INTO own;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'draft' OR NEW.version<>1 OR NEW.reply IS NOT NULL OR NEW.created_by IS DISTINCT FROM NEW.updated_by OR NOT own OR NOT public.hr_employee_feedback_authorized(NEW.tenant_id,NEW.park_id,NEW.updated_by,'hr:approval:self_manage') OR NEW.created_at IS DISTINCT FROM transaction_timestamp() THEN RAISE EXCEPTION 'EMPLOYEE_FEEDBACK_CREATE_INVALID';END IF;
 ELSE
  IF(NEW.id,NEW.tenant_id,NEW.park_id,NEW.employee_id,NEW.created_by,NEW.created_at) IS DISTINCT FROM(OLD.id,OLD.tenant_id,OLD.park_id,OLD.employee_id,OLD.created_by,OLD.created_at) OR NEW.version<>OLD.version+1 OR NEW.current_action_id=OLD.current_action_id OR OLD.status IN('answered','withdrawn','cancelled') THEN RAISE EXCEPTION 'EMPLOYEE_FEEDBACK_VERSION_OR_TERMINAL';END IF;
  IF OLD.status='draft' AND NEW.status='draft' AND(NEW.kind,NEW.title,NEW.content) IS NOT DISTINCT FROM(OLD.kind,OLD.title,OLD.content) THEN RAISE EXCEPTION 'EMPLOYEE_FEEDBACK_UNCHANGED';END IF;
  IF NOT((OLD.status='draft' AND NEW.status IN('draft','submitted','cancelled')) OR(OLD.status='submitted' AND NEW.status IN('withdrawn','answered'))) THEN RAISE EXCEPTION 'EMPLOYEE_FEEDBACK_TRANSITION_INVALID';END IF;
  IF NEW.status='answered' THEN
   IF own OR NEW.updated_by=NEW.created_by OR NOT public.hr_employee_feedback_authorized(NEW.tenant_id,NEW.park_id,NEW.updated_by,'hr:approval:park_review') THEN RAISE EXCEPTION 'EMPLOYEE_FEEDBACK_REPLY_AUTHORITY';END IF;
  ELSIF NOT own OR NOT public.hr_employee_feedback_authorized(NEW.tenant_id,NEW.park_id,NEW.updated_by,'hr:approval:self_manage') THEN RAISE EXCEPTION 'EMPLOYEE_FEEDBACK_OWNER_REQUIRED';END IF;
  IF(NEW.kind,NEW.title,NEW.content) IS DISTINCT FROM(OLD.kind,OLD.title,OLD.content) AND NOT(OLD.status='draft' AND NEW.status='draft') THEN RAISE EXCEPTION 'EMPLOYEE_FEEDBACK_CONTENT_FROZEN';END IF;
 END IF;
 IF NEW.updated_at IS DISTINCT FROM transaction_timestamp() THEN RAISE EXCEPTION 'EMPLOYEE_FEEDBACK_TIME_INVALID';END IF;RETURN NEW;
END $$;



--
-- Name: hr_employee_feedback_head_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_employee_feedback_head_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.hr_employee_feedback r JOIN public.hr_employee_feedback_action a ON(a.id,a.tenant_id,a.park_id,a.feedback_id)=(r.current_action_id,r.tenant_id,r.park_id,r.id) WHERE(r.id,r.tenant_id,r.park_id)=(NEW.id,NEW.tenant_id,NEW.park_id) AND a.version_no=r.version AND a.version_no=(SELECT max(version_no) FROM public.hr_employee_feedback_action WHERE(feedback_id,tenant_id,park_id)=(r.id,r.tenant_id,r.park_id))) THEN RAISE EXCEPTION 'EMPLOYEE_FEEDBACK_HEAD_INVALID';END IF;RETURN NULL;
END $$;



--
-- Name: hr_employee_position_assignment_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_employee_position_assignment_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  position_row hr_position%ROWTYPE;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF (NEW.tenant_id, NEW.park_id, NEW.primary_org_id, NEW.position_id, NEW.is_deleted)
       IS NOT DISTINCT FROM
       (OLD.tenant_id, OLD.park_id, OLD.primary_org_id, OLD.position_id, OLD.is_deleted)
       AND NOT (OLD.employment_status = 'departed' AND NEW.employment_status <> 'departed') THEN
      RETURN NEW;
    END IF;
  END IF;
  IF NEW.is_deleted OR NEW.position_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT * INTO position_row FROM hr_position
    WHERE id = NEW.position_id AND tenant_id = NEW.tenant_id AND park_id = NEW.park_id
    FOR SHARE;
  IF NOT FOUND OR position_row.is_deleted THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'hr_employee_position_assignment',
      MESSAGE = 'Employee position is unavailable in this scope';
  END IF;
  -- Departed assignments are history. Rehire must pass the current assignment rules.
  IF NEW.employment_status <> 'departed' AND
     (position_row.status <> 'enabled' OR position_row.org_id IS DISTINCT FROM NEW.primary_org_id) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'hr_employee_position_assignment',
      MESSAGE = 'Current employee position must be enabled in the assigned organization';
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: hr_employee_rest_day_check_schedule(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_employee_rest_day_check_schedule() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND (NEW.tenant_id,NEW.park_id,NEW.employee_id,NEW.work_date,NEW.id) IS DISTINCT FROM (OLD.tenant_id,OLD.park_id,OLD.employee_id,OLD.work_date,OLD.id) THEN RAISE EXCEPTION 'Rest-day identity is immutable' USING ERRCODE='23514'; END IF;
 PERFORM 1 FROM hr_employee WHERE tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND id=NEW.employee_id FOR UPDATE;
 IF NEW.is_rest AND EXISTS(SELECT 1 FROM hr_employee_schedule WHERE tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND employee_id=NEW.employee_id AND work_date=NEW.work_date AND NOT is_deleted) THEN RAISE EXCEPTION 'Employee rest-day conflicts with schedule' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_employee_rest_day_history_append_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_employee_rest_day_history_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN RAISE EXCEPTION 'Employee rest-day history is append-only'; END $$;



--
-- Name: hr_employee_schedule_check_rest_day(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_employee_schedule_check_rest_day() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 PERFORM 1 FROM hr_employee WHERE tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND id=NEW.employee_id FOR UPDATE;
 IF NOT NEW.is_deleted AND EXISTS(SELECT 1 FROM hr_employee_rest_day WHERE tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND employee_id=NEW.employee_id AND work_date=NEW.work_date AND is_rest) THEN RAISE EXCEPTION 'Employee schedule conflicts with rest-day' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_feedback360_append_only_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_feedback360_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN RAISE EXCEPTION '360 feedback evidence is append-only'; END $$;



--
-- Name: hr_feedback360_assignment_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_feedback360_assignment_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION '360 assignment is immutable'; END IF;
 IF OLD.status='submitted' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'submitted 360 assignment is immutable'; END IF;
 IF (NEW.tenant_id,NEW.park_id,NEW.subject_id,NEW.nomination_id,NEW.reviewer_employee_id,NEW.relation_type,NEW.questionnaire_snapshot,NEW.create_time) IS DISTINCT FROM (OLD.tenant_id,OLD.park_id,OLD.subject_id,OLD.nomination_id,OLD.reviewer_employee_id,OLD.relation_type,OLD.questionnaire_snapshot,OLD.create_time) THEN RAISE EXCEPTION '360 assignment identity is immutable'; END IF;
 IF NEW.status IS DISTINCT FROM OLD.status AND NOT (OLD.status='pending' AND NEW.status IN('submitted','expired')) THEN RAISE EXCEPTION 'invalid 360 assignment transition'; END IF; RETURN NEW; END $$;



--
-- Name: hr_feedback360_assignment_insert_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_feedback360_assignment_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE n record; subject_status varchar(20); snapshot jsonb; BEGIN
 SELECT subject_id,nominee_employee_id,relation_type,status INTO n FROM hr_feedback360_nomination
  WHERE (id,tenant_id,park_id)=(NEW.nomination_id,NEW.tenant_id,NEW.park_id) FOR SHARE;
 SELECT s.status,c.questionnaire_snapshot INTO subject_status,snapshot FROM hr_feedback360_subject s
  JOIN hr_feedback360_cycle c ON(c.id,c.tenant_id,c.park_id)=(s.cycle_id,s.tenant_id,s.park_id)
  WHERE (s.id,s.tenant_id,s.park_id)=(NEW.subject_id,NEW.tenant_id,NEW.park_id) FOR SHARE OF s,c;
 IF n.status IS DISTINCT FROM 'approved' OR (NEW.subject_id,NEW.reviewer_employee_id,NEW.relation_type) IS DISTINCT FROM (n.subject_id,n.nominee_employee_id,n.relation_type) THEN RAISE EXCEPTION '360 assignment must exactly match an approved nomination'; END IF;
 IF subject_status NOT IN('nominating','responding') OR NEW.questionnaire_snapshot IS DISTINCT FROM snapshot THEN RAISE EXCEPTION '360 assignment snapshot or subject state is invalid'; END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_feedback360_cycle_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_feedback360_cycle_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' AND OLD.status<>'draft' THEN RAISE EXCEPTION 'active 360 cycle is immutable'; END IF;
 IF TG_OP='UPDATE' AND (NEW.tenant_id,NEW.park_id,NEW.cycle_code,NEW.cycle_name,NEW.model_version_id,NEW.questionnaire_version_id,NEW.model_snapshot,NEW.questionnaire_snapshot,NEW.minimum_anonymous_responses,NEW.self_result_policy,NEW.manager_result_policy,NEW.nomination_end,NEW.response_end,NEW.create_by,NEW.create_time,NEW.legacy_feedback_cycle_id,NEW.legacy_source) IS DISTINCT FROM (OLD.tenant_id,OLD.park_id,OLD.cycle_code,OLD.cycle_name,OLD.model_version_id,OLD.questionnaire_version_id,OLD.model_snapshot,OLD.questionnaire_snapshot,OLD.minimum_anonymous_responses,OLD.self_result_policy,OLD.manager_result_policy,OLD.nomination_end,OLD.response_end,OLD.create_by,OLD.create_time,OLD.legacy_feedback_cycle_id,OLD.legacy_source) THEN RAISE EXCEPTION '360 cycle snapshot is immutable'; END IF;
 IF TG_OP='UPDATE' AND NEW.status IS DISTINCT FROM OLD.status AND NOT ((OLD.status='draft' AND NEW.status='nominating') OR (OLD.status='nominating' AND NEW.status='responding')) THEN RAISE EXCEPTION 'invalid 360 cycle transition'; END IF;
 IF TG_OP='UPDATE' AND NEW.status=OLD.status AND OLD.status<>'draft' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'active 360 cycle is immutable outside a state transition'; END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;



--
-- Name: hr_feedback360_model_root_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_feedback360_model_root_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.status<>'draft' THEN RAISE EXCEPTION 'published competency root is immutable'; END IF;
  RETURN OLD;
 END IF;
 IF (to_jsonb(NEW)-ARRAY['status','current_version_no','update_by','update_time']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['status','current_version_no','update_by','update_time']) THEN
  RAISE EXCEPTION 'competency model identity is immutable';
 END IF;
 IF OLD.status='retired' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'retired competency model is immutable'; END IF;
 IF (OLD.status='published' AND NEW.status<>'published') OR
    (OLD.status='draft' AND NEW.status NOT IN('draft','published')) THEN RAISE EXCEPTION 'invalid competency root transition'; END IF;
 IF NEW.current_version_no<OLD.current_version_no OR NEW.current_version_no<1 THEN RAISE EXCEPTION 'competency version pointer cannot regress'; END IF;
 IF NOT EXISTS(SELECT 1 FROM hr_competency_model_version v WHERE
    (v.model_id,v.tenant_id,v.park_id,v.version_no)=(NEW.id,NEW.tenant_id,NEW.park_id,NEW.current_version_no)) THEN
  RAISE EXCEPTION 'competency version pointer must reference its scoped version';
 END IF;
 IF OLD.status='draft' AND NEW.status='published' AND NOT EXISTS(SELECT 1 FROM hr_competency_model_version v WHERE
    (v.model_id,v.tenant_id,v.park_id,v.version_no)=(NEW.id,NEW.tenant_id,NEW.park_id,NEW.current_version_no) AND v.status='published') THEN
  RAISE EXCEPTION 'published competency version required';
 END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_feedback360_nomination_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_feedback360_nomination_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE subject_employee uuid; subject_manager uuid; subject_org uuid; nominee_manager uuid; nominee_org uuid; subject_status varchar(20); BEGIN
 SELECT s.employee_id,s.manager_employee_id,e.primary_org_id,s.status INTO subject_employee,subject_manager,subject_org,subject_status
   FROM hr_feedback360_subject s JOIN hr_employee e ON(e.id,e.tenant_id,e.park_id)=(s.employee_id,s.tenant_id,s.park_id)
  WHERE (s.id,s.tenant_id,s.park_id)=(NEW.subject_id,NEW.tenant_id,NEW.park_id) FOR SHARE OF s,e;
 SELECT manager_employee_id,primary_org_id INTO nominee_manager,nominee_org FROM hr_employee
  WHERE (id,tenant_id,park_id)=(NEW.nominee_employee_id,NEW.tenant_id,NEW.park_id) AND is_deleted=false AND employment_status='active' FOR SHARE;
 IF subject_status NOT IN('nominating','responding') OR nominee_org IS NULL THEN RAISE EXCEPTION '360 nomination is outside an active scoped relationship'; END IF;
 IF NEW.relation_type='self' AND NEW.nominee_employee_id<>subject_employee THEN RAISE EXCEPTION 'invalid 360 self relation'; END IF;
 IF NEW.relation_type<>'self' AND NEW.nominee_employee_id=subject_employee THEN RAISE EXCEPTION '360 subject cannot forge an external reviewer identity'; END IF;
 IF NEW.relation_type='manager' AND NEW.nominee_employee_id IS DISTINCT FROM subject_manager THEN RAISE EXCEPTION 'invalid 360 manager relation'; END IF;
 IF NEW.relation_type='subordinate' AND nominee_manager IS DISTINCT FROM subject_employee THEN RAISE EXCEPTION 'invalid 360 subordinate relation'; END IF;
 IF NEW.relation_type='peer' AND nominee_org IS DISTINCT FROM subject_org THEN RAISE EXCEPTION 'invalid 360 peer relation'; END IF;
 IF NEW.relation_type='collaborator' THEN RAISE EXCEPTION '360 collaborator relation requires an authoritative source'; END IF;
 IF TG_OP='UPDATE' THEN
   IF (NEW.tenant_id,NEW.park_id,NEW.subject_id,NEW.nominee_employee_id,NEW.relation_type,NEW.nominated_by,NEW.nominated_at) IS DISTINCT FROM (OLD.tenant_id,OLD.park_id,OLD.subject_id,OLD.nominee_employee_id,OLD.relation_type,OLD.nominated_by,OLD.nominated_at) THEN RAISE EXCEPTION '360 nomination identity is immutable'; END IF;
   IF OLD.status<>'pending' OR NEW.status NOT IN('approved','rejected') THEN RAISE EXCEPTION 'invalid 360 nomination transition'; END IF;
   IF NEW.decided_by=NEW.nominated_by THEN RAISE EXCEPTION '360 nomination and approval must be separated'; END IF;
 END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_feedback360_questionnaire_root_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_feedback360_questionnaire_root_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.status<>'draft' THEN RAISE EXCEPTION 'published questionnaire root is immutable'; END IF;
  RETURN OLD;
 END IF;
 IF (to_jsonb(NEW)-ARRAY['status','current_version_no','update_by','update_time']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['status','current_version_no','update_by','update_time']) THEN
  RAISE EXCEPTION 'questionnaire identity is immutable';
 END IF;
 IF OLD.status='retired' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'retired questionnaire is immutable'; END IF;
 IF (OLD.status='published' AND NEW.status<>'published') OR
    (OLD.status='draft' AND NEW.status NOT IN('draft','published')) THEN RAISE EXCEPTION 'invalid questionnaire root transition'; END IF;
 IF NEW.current_version_no<OLD.current_version_no OR NEW.current_version_no<1 THEN RAISE EXCEPTION 'questionnaire version pointer cannot regress'; END IF;
 IF NOT EXISTS(SELECT 1 FROM hr_feedback_questionnaire_version v WHERE
    (v.questionnaire_id,v.tenant_id,v.park_id,v.version_no)=(NEW.id,NEW.tenant_id,NEW.park_id,NEW.current_version_no)) THEN
  RAISE EXCEPTION 'questionnaire version pointer must reference its scoped version';
 END IF;
 IF OLD.status='draft' AND NEW.status='published' AND NOT EXISTS(SELECT 1 FROM hr_feedback_questionnaire_version v WHERE
    (v.questionnaire_id,v.tenant_id,v.park_id,v.version_no)=(NEW.id,NEW.tenant_id,NEW.park_id,NEW.current_version_no) AND v.status='published') THEN
  RAISE EXCEPTION 'published questionnaire version required';
 END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_feedback360_response_insert_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_feedback360_response_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE assignment_status varchar(16); relation varchar(20); reviewer uuid; subject_employee uuid; subject_status varchar(20); snapshot jsonb; question jsonb; answer jsonb; BEGIN
 SELECT a.status,a.relation_type,a.reviewer_employee_id,s.employee_id,s.status,a.questionnaire_snapshot
   INTO assignment_status,relation,reviewer,subject_employee,subject_status,snapshot FROM hr_feedback360_assignment a JOIN hr_feedback360_subject s ON(s.id,s.tenant_id,s.park_id)=(a.subject_id,a.tenant_id,a.park_id)
  WHERE (a.id,a.tenant_id,a.park_id)=(NEW.assignment_id,NEW.tenant_id,NEW.park_id) FOR UPDATE OF a FOR SHARE OF s;
 IF assignment_status IS DISTINCT FROM 'pending' OR subject_status IS DISTINCT FROM 'responding' OR ((relation='self') IS DISTINCT FROM (reviewer=subject_employee)) THEN RAISE EXCEPTION '360 response identity or subject state is invalid'; END IF;
  IF jsonb_typeof(NEW.answers)<>'object' THEN RAISE EXCEPTION '360 answers must be an object'; END IF;
 FOR question IN SELECT value FROM jsonb_array_elements(snapshot->'questions') LOOP
   answer:=NEW.answers->(question->>'code');
   IF COALESCE((question->>'required')::boolean,false) AND answer IS NULL THEN RAISE EXCEPTION 'required 360 answer is missing'; END IF;
   IF answer IS NOT NULL AND question->>'type'='rating' AND (NOT answer ? 'score' OR (SELECT count(*) FROM jsonb_object_keys(answer))<>1 OR (answer->>'score')::numeric NOT BETWEEN 0 AND 100) THEN RAISE EXCEPTION 'invalid 360 rating answer'; END IF;
   IF answer IS NOT NULL AND question->>'type'='text' AND (NOT answer ? 'text' OR (SELECT count(*) FROM jsonb_object_keys(answer))<>1) THEN RAISE EXCEPTION 'invalid 360 text answer'; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(NEW.answers) keys(k) WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot->'questions') q WHERE q->>'code'=keys.k)) THEN RAISE EXCEPTION 'unknown 360 answer'; END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_feedback360_response_sync_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_feedback360_response_sync_assignment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 UPDATE hr_feedback360_assignment SET status='submitted',submitted_at=NEW.submitted_at
  WHERE (id,tenant_id,park_id)=(NEW.assignment_id,NEW.tenant_id,NEW.park_id) AND status='pending';
 IF NOT FOUND THEN RAISE EXCEPTION '360 assignment is no longer open'; END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_feedback360_result_threshold_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_feedback360_result_threshold_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE cfg integer; actual integer; expected numeric(7,2); manager_policy varchar(16); self_policy varchar(16); BEGIN
 SELECT c.minimum_anonymous_responses,c.manager_result_policy,c.self_result_policy INTO cfg,manager_policy,self_policy FROM hr_feedback360_subject s JOIN hr_feedback360_cycle c ON(c.id,c.tenant_id,c.park_id)=(s.cycle_id,s.tenant_id,s.park_id) WHERE s.id=NEW.subject_id AND s.tenant_id=NEW.tenant_id AND s.park_id=NEW.park_id AND s.status='closed' FOR SHARE OF s,c;
 IF cfg IS NULL THEN RAISE EXCEPTION '360 subject must be closed before result publication'; END IF;
 SELECT count(DISTINCT a.id)::int,round(avg((r.answers->(q.item->>'code')->>'score')::numeric),2)
   INTO actual,expected
   FROM hr_feedback360_response r
   JOIN hr_feedback360_assignment a ON(a.id,a.tenant_id,a.park_id)=(r.assignment_id,r.tenant_id,r.park_id)
   JOIN hr_feedback360_subject s ON(s.id,s.tenant_id,s.park_id)=(a.subject_id,a.tenant_id,a.park_id)
   JOIN hr_feedback360_cycle c ON(c.id,c.tenant_id,c.park_id)=(s.cycle_id,s.tenant_id,s.park_id)
   CROSS JOIN LATERAL jsonb_array_elements(c.questionnaire_snapshot->'questions') q(item)
  WHERE a.subject_id=NEW.subject_id AND a.tenant_id=NEW.tenant_id AND a.park_id=NEW.park_id
    AND q.item->>'type'='rating' AND q.item->>'dimensionCode'=NEW.dimension_code AND r.answers->(q.item->>'code') ? 'score'
    AND CASE NEW.relation_group WHEN 'self' THEN a.relation_type='self' AND self_policy='separate'
          WHEN 'manager' THEN a.relation_type='manager' AND manager_policy='separate'
          ELSE a.relation_type NOT IN('self','manager') OR (a.relation_type='manager' AND manager_policy='anonymous') END;
 IF NEW.relation_group='others' AND (NEW.minimum_required<>cfg OR NEW.response_count<>actual OR actual<cfg) THEN RAISE EXCEPTION '360 anonymous result threshold has not been reached'; END IF;
 IF NEW.relation_group IN('self','manager') AND (NEW.minimum_required<>1 OR NEW.response_count<>actual OR actual<1) THEN RAISE EXCEPTION '360 separate result requires a response'; END IF;
 IF NEW.average_score IS DISTINCT FROM expected THEN RAISE EXCEPTION '360 result average must be database-derived'; END IF;
 RETURN NEW; END $$;



--
-- Name: hr_feedback360_subject_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_feedback360_subject_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE result_count integer; anonymous_count integer; required_threshold integer; expected_count integer; low_count integer; BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION '360 subject is immutable'; END IF;
 IF (NEW.tenant_id,NEW.park_id,NEW.cycle_id,NEW.employee_id,NEW.employee_snapshot,NEW.manager_employee_id,NEW.create_time) IS DISTINCT FROM (OLD.tenant_id,OLD.park_id,OLD.cycle_id,OLD.employee_id,OLD.employee_snapshot,OLD.manager_employee_id,OLD.create_time) THEN RAISE EXCEPTION '360 subject snapshot is immutable'; END IF;
 IF OLD.status='published' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'published 360 subject is immutable'; END IF;
 IF NEW.status IS DISTINCT FROM OLD.status AND NOT ((OLD.status='nominating' AND NEW.status='responding') OR (OLD.status='responding' AND NEW.status='closed') OR (OLD.status='closed' AND NEW.status='published')) THEN RAISE EXCEPTION 'invalid 360 subject transition'; END IF;
 IF NEW.status=OLD.status AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION '360 subject can only change through a valid state transition'; END IF;
 IF OLD.status='closed' AND NEW.status='published' THEN
   SELECT count(*) INTO result_count FROM hr_feedback360_dimension_result WHERE (subject_id,tenant_id,park_id)=(OLD.id,OLD.tenant_id,OLD.park_id);
   SELECT c.minimum_anonymous_responses,count(r.id) FILTER(WHERE a.relation_type NOT IN('self','manager') OR (a.relation_type='manager' AND c.manager_result_policy='anonymous'))
     INTO required_threshold,anonymous_count FROM hr_feedback360_cycle c
     LEFT JOIN hr_feedback360_assignment a ON(a.subject_id,a.tenant_id,a.park_id)=(OLD.id,OLD.tenant_id,OLD.park_id)
     LEFT JOIN hr_feedback360_response r ON(r.assignment_id,r.tenant_id,r.park_id)=(a.id,a.tenant_id,a.park_id)
    WHERE (c.id,c.tenant_id,c.park_id)=(OLD.cycle_id,OLD.tenant_id,OLD.park_id)
    GROUP BY c.minimum_anonymous_responses;
   WITH scored AS (
     SELECT q.item->>'dimensionCode' dimension_code,
            CASE WHEN a.relation_type='self' THEN 'self' WHEN a.relation_type='manager' AND c.manager_result_policy='separate' THEN 'manager' ELSE 'others' END relation_group,
            a.id assignment_id,c.minimum_anonymous_responses anon_threshold
       FROM hr_feedback360_response r
       JOIN hr_feedback360_assignment a ON(a.id,a.tenant_id,a.park_id)=(r.assignment_id,r.tenant_id,r.park_id)
       JOIN hr_feedback360_cycle c ON(c.id,c.tenant_id,c.park_id)=(OLD.cycle_id,OLD.tenant_id,OLD.park_id)
       CROSS JOIN LATERAL jsonb_array_elements(c.questionnaire_snapshot->'questions') q(item)
      WHERE a.subject_id=OLD.id AND a.tenant_id=OLD.tenant_id AND a.park_id=OLD.park_id
        AND q.item->>'type'='rating' AND r.answers->(q.item->>'code') ? 'score'
        AND NOT (a.relation_type='self' AND c.self_result_policy='excluded')
   ), grouped AS (
     SELECT dimension_code,relation_group,count(DISTINCT assignment_id)::int response_count,max(anon_threshold) anon_threshold
       FROM scored GROUP BY dimension_code,relation_group
   )
   SELECT count(*) FILTER(WHERE response_count>=CASE WHEN relation_group='others' THEN anon_threshold ELSE 1 END),
          count(*) FILTER(WHERE relation_group='others' AND response_count<anon_threshold)
     INTO expected_count,low_count FROM grouped;
   IF result_count=0 OR result_count<>expected_count OR low_count>0 OR (anonymous_count>0 AND anonymous_count<required_threshold) THEN RAISE EXCEPTION '360 result publication threshold has not been reached'; END IF;
 END IF;
 RETURN NEW; END $$;



--
-- Name: hr_feedback360_subject_insert_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_feedback360_subject_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE cycle_status varchar(20); BEGIN
 SELECT status INTO cycle_status FROM hr_feedback360_cycle WHERE (id,tenant_id,park_id)=(NEW.cycle_id,NEW.tenant_id,NEW.park_id) FOR SHARE;
 IF cycle_status IS DISTINCT FROM 'draft' THEN RAISE EXCEPTION '360 subjects can only be frozen while the cycle is draft'; END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_feedback360_version_child_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_feedback360_version_child_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE s varchar(16); r record; BEGIN r:=CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
 IF TG_TABLE_NAME='hr_competency_dimension' THEN SELECT status INTO s FROM hr_competency_model_version WHERE id=r.model_version_id AND tenant_id=r.tenant_id AND park_id=r.park_id FOR SHARE;
 ELSIF TG_TABLE_NAME='hr_competency_behavior_anchor' THEN SELECT v.status INTO s FROM hr_competency_dimension d JOIN hr_competency_model_version v ON(v.id,v.tenant_id,v.park_id)=(d.model_version_id,d.tenant_id,d.park_id) WHERE d.id=r.dimension_id AND d.tenant_id=r.tenant_id AND d.park_id=r.park_id FOR SHARE OF v;
 ELSE SELECT status INTO s FROM hr_feedback_questionnaire_version WHERE id=r.questionnaire_version_id AND tenant_id=r.tenant_id AND park_id=r.park_id FOR SHARE; END IF;
 IF s IS DISTINCT FROM 'draft' THEN RAISE EXCEPTION 'published competency or questionnaire version is immutable'; END IF; RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END $$;



--
-- Name: hr_feedback360_version_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_feedback360_version_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' AND OLD.status<>'draft' THEN RAISE EXCEPTION 'published competency or questionnaire version is immutable'; END IF;
 IF TG_OP='UPDATE' AND (to_jsonb(NEW)-ARRAY['status','published_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','published_at']) THEN RAISE EXCEPTION 'competency or questionnaire version identity is immutable'; END IF;
 IF TG_OP='UPDATE' AND OLD.status<>'draft' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'published competency or questionnaire version is immutable'; END IF;
 IF TG_OP='UPDATE' AND NEW.status IS DISTINCT FROM OLD.status AND NOT (OLD.status='draft' AND NEW.status='published') THEN RAISE EXCEPTION 'invalid competency or questionnaire version transition'; END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;



--
-- Name: hr_freeze_payroll_reconciliation_source(character varying, character varying, uuid, uuid, date, text, text, integer, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_freeze_payroll_reconciliation_source(p_tenant character varying, p_park character varying, p_batch uuid, p_book uuid, p_month date, p_binding text, p_expected_source text, p_expected_snapshots integer, p_expected_items integer, p_actor uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE payload jsonb; actual_hash text; result_id uuid;
BEGIN
  IF p_actor IS NULL OR p_binding IS NULL OR p_binding !~ '^[0-9a-f]{64}$'
    OR p_expected_source IS NULL OR p_expected_source !~ '^[0-9a-f]{64}$'
    OR p_expected_snapshots IS NULL OR p_expected_items IS NULL THEN
    RAISE EXCEPTION 'RECONCILIATION_SOURCE_ARGUMENT_INVALID';
  END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 1000 THEN
    RAISE EXCEPTION 'RECONCILIATION_SOURCE_REASON_REQUIRED';
  END IF;
  payload=public.hr_build_payroll_reconciliation_source(p_tenant,p_park,p_batch,p_book,p_month,
    p_binding,p_expected_snapshots,p_expected_items);
  actual_hash=encode(public.digest(payload::text,'sha256'),'hex');
  IF actual_hash<>p_expected_source THEN RAISE EXCEPTION 'RECONCILIATION_SOURCE_CONTENT_DRIFT'; END IF;
  INSERT INTO public.hr_payroll_reconciliation_source(tenant_id,park_id,legacy_batch_id,book_id,
    period_month,operation_id,binding_sha256,source_sha256,snapshot_count,item_count,frozen_input,created_by,review_reason)
    VALUES(p_tenant,p_park,p_batch,p_book,p_month,payload->>'operationId',p_binding,actual_hash,
      p_expected_snapshots,p_expected_items,payload,p_actor,btrim(p_reason))
    ON CONFLICT(tenant_id,park_id,legacy_batch_id,book_id,period_month,source_sha256) DO NOTHING
    RETURNING id INTO result_id;
  IF result_id IS NULL THEN
    SELECT id INTO STRICT result_id FROM public.hr_payroll_reconciliation_source
      WHERE tenant_id=p_tenant AND park_id=p_park AND legacy_batch_id=p_batch
        AND book_id=p_book AND period_month=p_month AND source_sha256=actual_hash;
  END IF;
  RETURN result_id;
END $_$;



--
-- Name: hr_goal_cycle_state_guard_t6(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_goal_cycle_state_guard_t6() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE open_goal boolean;
BEGIN
 IF OLD.status='closed' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'closed goal cycle is immutable' USING ERRCODE='55000'; END IF;
 IF NEW.status<>OLD.status AND NOT (OLD.status='draft' AND NEW.status='active' OR OLD.status='active' AND NEW.status='closed') THEN RAISE EXCEPTION 'invalid goal cycle transition' USING ERRCODE='23514'; END IF;
 IF OLD.status='active' AND NEW.status='closed' THEN SELECT EXISTS(SELECT 1 FROM hr_goal WHERE tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND cycle_id=NEW.id AND is_deleted=false AND status NOT IN('completed','cancelled')) INTO open_goal;IF open_goal THEN RAISE EXCEPTION 'goal cycle has open goals' USING ERRCODE='23514';END IF;END IF;
 RETURN NEW;
END$$;



--
-- Name: hr_goal_state_guard_t6(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_goal_state_guard_t6() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE parent_status varchar(32); open_child boolean;
BEGIN
 IF OLD.status IN('completed','cancelled') AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'terminal goal is immutable' USING ERRCODE='55000'; END IF;
 IF NEW.status<>OLD.status THEN
   IF NOT (OLD.status='draft' AND NEW.status='active' OR OLD.status='active' AND NEW.status IN('completed','cancelled')) THEN RAISE EXCEPTION 'invalid goal transition' USING ERRCODE='23514'; END IF;
   IF NEW.status='active' THEN
     IF NEW.parent_goal_id IS NULL THEN SELECT status INTO parent_status FROM hr_goal_cycle WHERE tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND id=NEW.cycle_id FOR SHARE;
     ELSE SELECT status INTO parent_status FROM hr_goal WHERE tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND id=NEW.parent_goal_id FOR SHARE; END IF;
     IF parent_status<>'active' THEN RAISE EXCEPTION 'goal parent must be active' USING ERRCODE='23514'; END IF;
   END IF;
   IF NEW.status IN('completed','cancelled') THEN SELECT EXISTS(SELECT 1 FROM hr_goal WHERE tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND parent_goal_id=NEW.id AND is_deleted=false AND status NOT IN('completed','cancelled')) INTO open_child;IF open_child THEN RAISE EXCEPTION 'goal has open children' USING ERRCODE='23514'; END IF; END IF;
 END IF;
 RETURN NEW;
END$$;



--
-- Name: hr_goal_validate_t6(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_goal_validate_t6() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE c hr_goal_cycle%ROWTYPE;p hr_goal%ROWTYPE;parent_org uuid;sum_weight numeric;owner_primary uuid;
BEGIN
 SELECT * INTO c FROM hr_goal_cycle WHERE id=NEW.cycle_id AND tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND is_deleted=false FOR UPDATE;
 IF NOT FOUND OR c.status='closed' THEN RAISE EXCEPTION 'goal cycle unavailable' USING ERRCODE='23514'; END IF;
 IF NEW.start_date<c.start_date OR NEW.due_date>c.end_date THEN RAISE EXCEPTION 'goal dates outside cycle' USING ERRCODE='23514'; END IF;
 IF NEW.parent_goal_id IS NULL THEN
   IF NEW.goal_level<>'group' THEN RAISE EXCEPTION 'only group goal may be root' USING ERRCODE='23514'; END IF;
 ELSE
   SELECT * INTO p FROM hr_goal WHERE id=NEW.parent_goal_id AND tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND is_deleted=false FOR UPDATE;
   IF NOT FOUND OR p.cycle_id<>NEW.cycle_id OR p.status NOT IN('draft','active') THEN RAISE EXCEPTION 'parent goal unavailable' USING ERRCODE='23514'; END IF;
   IF NEW.start_date<p.start_date OR NEW.due_date>p.due_date THEN RAISE EXCEPTION 'child dates outside parent' USING ERRCODE='23514'; END IF;
   IF p.goal_level='group' AND NEW.goal_level<>'department' OR p.goal_level='employee' OR p.goal_level='department' AND NEW.goal_level NOT IN('department','employee') THEN RAISE EXCEPTION 'invalid goal hierarchy' USING ERRCODE='23514'; END IF;
   IF p.goal_level='department' THEN
     IF NEW.goal_level='department' THEN
       WITH RECURSIVE d AS(SELECT id,parent_id FROM sys_org WHERE id=NEW.owner_org_id AND tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND is_deleted=false UNION ALL SELECT o.id,o.parent_id FROM sys_org o JOIN d ON d.parent_id=o.id WHERE o.tenant_id=NEW.tenant_id AND o.park_id=NEW.park_id AND o.is_deleted=false) SELECT parent_id INTO parent_org FROM d WHERE parent_id=p.owner_org_id LIMIT 1;
       IF parent_org IS NULL THEN RAISE EXCEPTION 'department owner outside parent organization' USING ERRCODE='23514'; END IF;
     ELSE
       SELECT primary_org_id INTO owner_primary FROM hr_employee WHERE id=NEW.owner_employee_id AND tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND is_deleted=false;
       IF owner_primary IS NULL THEN RAISE EXCEPTION 'employee goal owner has no organization' USING ERRCODE='23514'; END IF;
       WITH RECURSIVE d AS(SELECT id,parent_id FROM sys_org WHERE id=owner_primary AND tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND is_deleted=false UNION ALL SELECT o.id,o.parent_id FROM sys_org o JOIN d ON d.parent_id=o.id WHERE o.tenant_id=NEW.tenant_id AND o.park_id=NEW.park_id AND o.is_deleted=false) SELECT id INTO parent_org FROM d WHERE id=p.owner_org_id LIMIT 1;
       IF parent_org IS NULL THEN RAISE EXCEPTION 'employee owner outside parent organization' USING ERRCODE='23514'; END IF;
     END IF;
   END IF;
 END IF;
 SELECT COALESCE(SUM(weight),0) INTO sum_weight FROM hr_goal WHERE tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND cycle_id=NEW.cycle_id AND parent_goal_id IS NOT DISTINCT FROM NEW.parent_goal_id AND is_deleted=false AND id<>NEW.id;
 IF sum_weight+NEW.weight>1.0000 THEN RAISE EXCEPTION 'sibling goal weight exceeds 100 percent' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END$$;



