--
-- Name: hr_job_change_application_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_job_change_application_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF OLD.is_historical_import THEN RAISE EXCEPTION 'HR_JOB_CHANGE_HISTORICAL_IMMUTABLE'; END IF;
 IF OLD.status IN('cancelled','applied') THEN RAISE EXCEPTION 'HR_JOB_CHANGE_TERMINAL_IMMUTABLE'; END IF;
 IF (OLD.status,NEW.status) NOT IN(
   ('draft','draft'),('draft','submitted'),('draft','cancelled'),
   ('returned','returned'),('returned','submitted'),('returned','cancelled'),
   ('submitted','approved'),('submitted','returned'),('submitted','cancelled'),('approved','applied')
 ) THEN RAISE EXCEPTION 'HR_JOB_CHANGE_TRANSITION_INVALID: % -> %',OLD.status,NEW.status; END IF;
 IF OLD.status NOT IN('draft','returned') AND (
   NEW.application_name,NEW.subject_employee_id,NEW.application_date,NEW.effective_date,NEW.change_type,
   NEW.before_org_id,NEW.before_position_id,NEW.after_org_id,NEW.after_position_id,NEW.reason,
   NEW.before_snapshot,NEW.after_snapshot
 ) IS DISTINCT FROM (
   OLD.application_name,OLD.subject_employee_id,OLD.application_date,OLD.effective_date,OLD.change_type,
   OLD.before_org_id,OLD.before_position_id,OLD.after_org_id,OLD.after_position_id,OLD.reason,
   OLD.before_snapshot,OLD.after_snapshot
 ) THEN RAISE EXCEPTION 'HR_JOB_CHANGE_SUBMITTED_FACTS_IMMUTABLE'; END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_legacy_archive_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_legacy_archive_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP='DELETE' AND TG_TABLE_NAME='hr_legacy_archive_record'
    AND OLD.materialization_batch_id IS NOT NULL
    AND hr_t5a_controlled_rollback_matches(OLD.tenant_id,OLD.park_id,OLD.materialization_batch_id)
  THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'HR_LEGACY_ARCHIVE_IMMUTABLE';
END $$;



--
-- Name: hr_legacy_archive_redact_source_fields(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_legacy_archive_redact_source_fields(p_payload jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT COALESCE(jsonb_object_agg(item.key,item.value),'{}'::jsonb)
  FROM jsonb_each(COALESCE(p_payload,'{}'::jsonb)) item
  WHERE lower(item.key) NOT IN('password','passwd','pwd','photo','cont','content','blob','binary')
$$;



--
-- Name: hr_legacy_archive_source_field_projection(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_legacy_archive_source_field_projection() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  source_payload jsonb;
BEGIN
  SELECT source.record_payload INTO source_payload
  FROM hr_legacy_identity_registry registry
  JOIN hr_legacy_archive_materialization_batch materialization
    ON materialization.id=registry.materialization_batch_id
   AND materialization.tenant_id=registry.tenant_id
   AND materialization.park_id=registry.park_id
  JOIN hr_legacy_t5_record source
    ON source.import_batch_id=materialization.source_t5_import_batch_id
   AND source.tenant_id=registry.tenant_id
   AND source.park_id=registry.park_id
   AND source.source_table=registry.source_table
   AND source.source_identity_sha256=registry.source_identity_sha256
  WHERE registry.id=NEW.identity_registry_id
    AND registry.tenant_id=NEW.tenant_id
    AND registry.park_id=NEW.park_id
    AND registry.identity_kind='archive_record';

  IF source_payload IS NOT NULL THEN
    -- The source extractor already excludes credentials and binary photo/file
    -- bodies. Keep that boundary explicit here as a second line of defence.
    source_payload := hr_legacy_archive_redact_source_fields(source_payload);
    NEW.restricted_safe_projection := NEW.restricted_safe_projection
      || jsonb_build_object('legacyFields',source_payload);
  END IF;
  RETURN NEW;
END $$;



--
-- Name: hr_legacy_dictionary_item_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_legacy_dictionary_item_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE parent_status varchar(16);
BEGIN
  SELECT status INTO parent_status
  FROM hr_legacy_dictionary_version
  WHERE id = COALESCE(NEW.version_id,OLD.version_id)
    AND tenant_id = COALESCE(NEW.tenant_id,OLD.tenant_id)
    AND park_id = COALESCE(NEW.park_id,OLD.park_id)
  FOR SHARE;
  IF parent_status IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION 'HR_LEGACY_DICTIONARY_ITEM_IMMUTABLE';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;



--
-- Name: hr_legacy_dictionary_item_touch_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_legacy_dictionary_item_touch_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE hr_legacy_dictionary_version
  SET update_by=CASE WHEN TG_OP='DELETE' THEN OLD.update_by ELSE NEW.update_by END,
      update_time=now(),version=version+1
  WHERE id=CASE WHEN TG_OP='DELETE' THEN OLD.version_id ELSE NEW.version_id END
    AND tenant_id=CASE WHEN TG_OP='DELETE' THEN OLD.tenant_id ELSE NEW.tenant_id END
    AND park_id=CASE WHEN TG_OP='DELETE' THEN OLD.park_id ELSE NEW.park_id END
    AND status='draft';
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;



--
-- Name: hr_legacy_dictionary_items_sha256(character varying, character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_legacy_dictionary_items_sha256(p_tenant_id character varying, p_park_id character varying, p_version_id uuid) RETURNS character
    LANGUAGE sql STABLE
    AS $$
  SELECT encode(digest(convert_to(coalesce(jsonb_agg(
    jsonb_build_object(
      'source_code',source_code,'source_name',source_name,'source_value',source_value,
      'source_identity_sha256',source_identity_sha256,'source_row_sha256',source_row_sha256,
      'decision',decision,'target_domain',target_domain,'target_value',target_value,
      'reason_code',reason_code,'review_note',review_note
    ) ORDER BY source_identity_sha256,id)::text,'[]'),'UTF8'),'sha256'),'hex')
  FROM hr_legacy_dictionary_item
  WHERE tenant_id=p_tenant_id AND park_id=p_park_id AND version_id=p_version_id AND is_deleted=false
$$;



--
-- Name: hr_legacy_dictionary_version_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_legacy_dictionary_version_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION 'HR_LEGACY_DICTIONARY_APPROVED_IMMUTABLE';
    END IF;
    RETURN OLD;
  END IF;

  IF OLD.status = 'approved' THEN
    IF NEW.status <> 'superseded'
       OR (NEW.tenant_id,NEW.park_id,NEW.source_system,NEW.dictionary_code,
           NEW.source_table,NEW.source_snapshot_sha256,NEW.source_row_count,NEW.decision_items_sha256,
           NEW.approved_by,NEW.approved_at,NEW.verification_mode,NEW.machine_attestation_sha256,
           NEW.machine_evidence_root_sha256,NEW.verified_at,NEW.verification_actor_kind,
           NEW.decision_note,NEW.create_by,NEW.create_time,NEW.is_deleted,NEW.remark)
          IS DISTINCT FROM
          (OLD.tenant_id,OLD.park_id,OLD.source_system,OLD.dictionary_code,
           OLD.source_table,OLD.source_snapshot_sha256,OLD.source_row_count,OLD.decision_items_sha256,
           OLD.approved_by,OLD.approved_at,OLD.verification_mode,OLD.machine_attestation_sha256,
           OLD.machine_evidence_root_sha256,OLD.verified_at,OLD.verification_actor_kind,
           OLD.decision_note,OLD.create_by,OLD.create_time,OLD.is_deleted,OLD.remark) THEN
      RAISE EXCEPTION 'HR_LEGACY_DICTIONARY_APPROVED_IMMUTABLE';
    END IF;
  ELSIF OLD.status = 'superseded' THEN
    RAISE EXCEPTION 'HR_LEGACY_DICTIONARY_SUPERSEDED_IMMUTABLE';
  ELSIF NEW.status NOT IN ('draft','approved') THEN
    RAISE EXCEPTION 'HR_LEGACY_DICTIONARY_TRANSITION_INVALID';
  END IF;
  IF OLD.status = 'draft' AND NEW.status = 'approved' THEN
    IF NEW.decision_items_sha256 IS DISTINCT FROM
       hr_legacy_dictionary_items_sha256(NEW.tenant_id,NEW.park_id,NEW.id) THEN
      RAISE EXCEPTION 'HR_LEGACY_DICTIONARY_ITEMS_SHA_MISMATCH';
    END IF;
  END IF;
  RETURN NEW;
END $$;



--
-- Name: hr_legacy_training_reward_rollback_allowed(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_legacy_training_reward_rollback_allowed(p_target_table text, p_target_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE active_run text:=current_setting('yuzhou.training_reward_rollback',true);
BEGIN
  IF active_run IS NULL OR current_database()!~'^jinhu_hr_migration_lab_[A-Za-z0-9_]{6,64}$' THEN RETURN false; END IF;
  RETURN EXISTS(
    SELECT 1 FROM hr_legacy_training_reward_projection p
    JOIN migration_batch b ON b.id=p.migration_batch_id
    WHERE b.run_id=active_run AND b.target_database=current_database() AND b.status='succeeded' AND p.status='staged'
      AND ((p_target_table='hr_training_course' AND p.training_course_id=p_target_id)
        OR (p_target_table='hr_training_course_version' AND p.training_course_version_id=p_target_id)
        OR (p_target_table='hr_training_plan' AND p.training_plan_id=p_target_id)
        OR (p_target_table='hr_training_participant' AND p.training_participant_id=p_target_id)
        OR (p_target_table='hr_reward_discipline_category' AND p.reward_category_id=p_target_id)
        OR (p_target_table='hr_reward_discipline_category_version' AND p.reward_category_version_id=p_target_id))
  );
END $_$;



