--
-- Name: hr_payroll_correction_window_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_correction_window_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE p hr_payroll_period%ROWTYPE; r hr_payroll_run%ROWTYPE; original_rule uuid; head integer;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Payroll correction windows cannot be deleted'; END IF;
 SELECT * INTO p FROM hr_payroll_period WHERE (id,tenant_id,park_id)=(NEW.period_id,NEW.tenant_id,NEW.park_id) FOR UPDATE;
 IF NOT FOUND OR p.is_deleted OR p.status<>'closed' THEN RAISE EXCEPTION 'Correction window requires a closed scoped period'; END IF;
 IF TG_OP='INSERT' THEN
  SELECT * INTO r FROM hr_payroll_run WHERE (id,tenant_id,park_id,period_id)=(NEW.original_run_id,NEW.tenant_id,NEW.park_id,NEW.period_id) FOR SHARE;
  SELECT v.rule_set_id INTO original_rule FROM hr_payroll_formal_run_evidence e JOIN hr_payroll_rule_version v
   ON (v.id,v.tenant_id,v.park_id)=(e.rule_version_id,e.tenant_id,e.park_id)
   WHERE (e.run_id,e.tenant_id,e.park_id)=(NEW.original_run_id,NEW.tenant_id,NEW.park_id);
  IF r.id IS NULL OR r.is_deleted OR r.status<>'confirmed' OR r.version<>NEW.original_run_version
   OR original_rule IS DISTINCT FROM NEW.rule_set_id OR NEW.status<>'open' OR NEW.version<>1 THEN
   RAISE EXCEPTION 'Correction window requires the current confirmed formal run';
  END IF;
  IF EXISTS(SELECT 1 FROM hr_payroll_run s WHERE (s.correction_of_run_id,s.tenant_id,s.park_id)=(r.id,r.tenant_id,r.park_id) AND NOT s.is_deleted AND s.status<>'cancelled') THEN
   RAISE EXCEPTION 'An active payroll correction already exists';
  END IF;
  SELECT coalesce(max(revision_no),0) INTO head FROM hr_payroll_formal_input WHERE
   (period_id,rule_set_id,tenant_id,park_id)=(NEW.period_id,NEW.rule_set_id,NEW.tenant_id,NEW.park_id);
  IF NEW.input_head_at_open<>head THEN RAISE EXCEPTION 'Payroll correction input head changed'; END IF;
 ELSE
  IF OLD.status<>'open' OR NEW.status NOT IN('completed','cancelled') OR NEW.version<>OLD.version+1
   OR (to_jsonb(NEW)-ARRAY['status','version','closed_by','closed_at','close_reason','completed_run_id'])
    IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','version','closed_by','closed_at','close_reason','completed_run_id']) THEN
   RAISE EXCEPTION 'Payroll correction window identity or terminal state is immutable';
  END IF;
  IF NEW.status='completed' AND NOT EXISTS(SELECT 1 FROM hr_payroll_run s JOIN hr_payroll_formal_input i
    ON (i.id,i.tenant_id,i.park_id)=(s.formal_input_id,s.tenant_id,s.park_id)
    WHERE (s.id,s.tenant_id,s.park_id,s.period_id,s.correction_of_run_id,i.correction_window_id)=
     (NEW.completed_run_id,NEW.tenant_id,NEW.park_id,NEW.period_id,NEW.original_run_id,NEW.id)
     AND NOT s.is_deleted AND s.status='confirmed') THEN RAISE EXCEPTION 'Correction completion requires its confirmed result'; END IF;
  IF NEW.status='cancelled' AND EXISTS(SELECT 1 FROM hr_payroll_run s JOIN hr_payroll_formal_input i
    ON (i.id,i.tenant_id,i.park_id)=(s.formal_input_id,s.tenant_id,s.park_id)
    WHERE (i.correction_window_id,i.tenant_id,i.park_id)=(NEW.id,NEW.tenant_id,NEW.park_id) AND NOT s.is_deleted AND s.status<>'cancelled') THEN
   RAISE EXCEPTION 'Cancel the pending payroll result before closing its window';
  END IF;
 END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_payroll_formal_action_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_formal_action_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE r hr_payroll_run%ROWTYPE; reviewer uuid;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Payroll review actions are immutable'; END IF;
 SELECT * INTO r FROM hr_payroll_run WHERE id=NEW.run_id AND tenant_id=NEW.tenant_id AND park_id=NEW.park_id FOR UPDATE;
 IF NOT FOUND OR r.version<>NEW.version_before OR r.is_deleted OR (NEW.action<>'cancel' AND NEW.actor_id=r.create_by) THEN RAISE EXCEPTION 'Invalid payroll reviewer or stale version'; END IF;
 IF NEW.action='review' AND r.status<>'calculated' THEN RAISE EXCEPTION 'Payroll must be calculated before review'; END IF;
 IF NEW.action='confirm' THEN
  SELECT actor_id INTO reviewer FROM hr_payroll_formal_run_action WHERE run_id=NEW.run_id AND action='review';
  IF r.status<>'reviewing' OR reviewer IS NULL THEN RAISE EXCEPTION 'Payroll confirmation requires completed independent review'; END IF;
 END IF;
 IF NEW.action='cancel' AND r.status NOT IN('calculated','reviewing') THEN RAISE EXCEPTION 'Confirmed payroll cannot be cancelled'; END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_payroll_formal_evidence_hash(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_formal_evidence_hash() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN NEW.snapshot_sha256:=encode(sha256(convert_to(NEW.snapshot::text,'UTF8')),'hex'); RETURN NEW; END $$;



--
-- Name: hr_payroll_formal_evidence_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_formal_evidence_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN RAISE EXCEPTION 'Formal payroll evidence is immutable'; END $$;



--
-- Name: hr_payroll_formal_evidence_input_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_formal_evidence_input_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM hr_payroll_run r WHERE (r.id,r.tenant_id,r.park_id,r.formal_input_id)=(NEW.run_id,NEW.tenant_id,NEW.park_id,NEW.input_id)) THEN
  RAISE EXCEPTION 'Formal payroll run input must match frozen evidence';
 END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_payroll_formal_input_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_formal_input_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE period_status text; next_revision integer; w hr_payroll_correction_window%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'payroll input versions cannot be deleted'; END IF;
 SELECT status INTO period_status FROM hr_payroll_period WHERE
  (id,tenant_id,park_id)=(NEW.period_id,NEW.tenant_id,NEW.park_id) AND NOT is_deleted FOR UPDATE;
 IF NEW.correction_window_id IS NULL THEN
  IF period_status IS DISTINCT FROM 'open' THEN RAISE EXCEPTION 'payroll input requires an open scoped period'; END IF;
 ELSE
  SELECT * INTO w FROM hr_payroll_correction_window WHERE
   (id,period_id,tenant_id,park_id)=(NEW.correction_window_id,NEW.period_id,NEW.tenant_id,NEW.park_id) FOR UPDATE;
  IF period_status IS DISTINCT FROM 'closed' OR w.id IS NULL OR w.status<>'open'
   OR NEW.rule_set_id<>w.rule_set_id OR NEW.revision_no<=w.input_head_at_open THEN
   RAISE EXCEPTION 'payroll input requires its current correction window';
  END IF;
  IF (SELECT array_agg(value->>'employeeId' ORDER BY value->>'employeeId') FROM jsonb_array_elements(NEW.employees)) IS DISTINCT FROM
    (SELECT array_agg(employee_id::text ORDER BY employee_id::text) FROM hr_payslip WHERE
      (run_id,tenant_id,park_id)=(w.original_run_id,w.tenant_id,w.park_id) AND NOT is_deleted) THEN
   RAISE EXCEPTION 'payroll correction input must preserve its original roster';
  END IF;
 END IF;
 IF TG_OP='INSERT' THEN
  SELECT coalesce(max(revision_no),0)+1 INTO next_revision FROM hr_payroll_formal_input WHERE
   (tenant_id,park_id,period_id,rule_set_id)=(NEW.tenant_id,NEW.park_id,NEW.period_id,NEW.rule_set_id);
  IF NEW.revision_no<>next_revision OR NEW.status<>'draft' OR NEW.version<>1 OR NEW.authored_by<>NEW.created_by THEN RAISE EXCEPTION 'invalid payroll input draft revision'; END IF;
 ELSE
  IF OLD.status='confirmed' THEN RAISE EXCEPTION 'confirmed payroll inputs are immutable'; END IF;
  IF NEW.status='confirmed' AND EXISTS(SELECT 1 FROM hr_payroll_formal_input later WHERE
   (later.tenant_id,later.park_id,later.period_id,later.rule_set_id)=(NEW.tenant_id,NEW.park_id,NEW.period_id,NEW.rule_set_id)
   AND later.revision_no>NEW.revision_no) THEN RAISE EXCEPTION 'newer payroll input revision exists'; END IF;
  IF NEW.version<>OLD.version+1 OR
   (to_jsonb(NEW)-ARRAY['employees','snapshot_sha256','reason','version','status','authored_by','updated_at','confirmed_by','confirmed_at']) IS DISTINCT FROM
   (to_jsonb(OLD)-ARRAY['employees','snapshot_sha256','reason','version','status','authored_by','updated_at','confirmed_by','confirmed_at']) THEN RAISE EXCEPTION 'payroll input identity or version changed'; END IF;
  IF NEW.status='confirmed' AND (NEW.employees IS DISTINCT FROM OLD.employees OR NEW.reason IS DISTINCT FROM OLD.reason OR NEW.authored_by IS DISTINCT FROM OLD.authored_by) THEN RAISE EXCEPTION 'confirmation cannot edit payroll inputs'; END IF;
 END IF;
 IF NEW.correction_window_id IS NULL THEN
  NEW.snapshot_sha256:=encode(sha256(convert_to(jsonb_build_object('periodId',NEW.period_id,'ruleVersionId',NEW.rule_version_id,'employees',NEW.employees)::text,'UTF8')),'hex');
 ELSE
  NEW.snapshot_sha256:=encode(sha256(convert_to(jsonb_build_object('periodId',NEW.period_id,'ruleVersionId',NEW.rule_version_id,'employees',NEW.employees,'correctionWindowId',NEW.correction_window_id)::text,'UTF8')),'hex');
 END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_payroll_formal_item_frozen(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_formal_item_frozen() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM hr_payslip s JOIN hr_payroll_formal_run_evidence e ON (e.run_id,e.tenant_id,e.park_id)=(s.run_id,s.tenant_id,s.park_id)
  WHERE s.id=CASE WHEN TG_OP='INSERT' THEN NEW.payslip_id ELSE OLD.payslip_id END)
  OR (TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM hr_payslip s JOIN hr_payroll_formal_run_evidence e ON (e.run_id,e.tenant_id,e.park_id)=(s.run_id,s.tenant_id,s.park_id) WHERE s.id=NEW.payslip_id))
  THEN RAISE EXCEPTION 'Formal payslip items are frozen'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $$;



--
-- Name: hr_payroll_formal_payslip_frozen(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_formal_payslip_frozen() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM hr_payroll_formal_run_evidence WHERE run_id=OLD.run_id AND tenant_id=OLD.tenant_id AND park_id=OLD.park_id) THEN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Formal payslip evidence is frozen'; END IF;
  IF (NEW.id,NEW.tenant_id,NEW.park_id,NEW.run_id,NEW.employee_id,NEW.compensation_snapshot,NEW.gross_amount,NEW.deduction_amount,NEW.personal_tax,NEW.net_amount,NEW.is_deleted)
   IS DISTINCT FROM (OLD.id,OLD.tenant_id,OLD.park_id,OLD.run_id,OLD.employee_id,OLD.compensation_snapshot,OLD.gross_amount,OLD.deduction_amount,OLD.personal_tax,OLD.net_amount,OLD.is_deleted)
   THEN RAISE EXCEPTION 'Formal payslip evidence is frozen'; END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_payroll_formal_rule_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_formal_rule_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE current_head integer;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'payroll rule versions cannot be deleted'; END IF;
 IF TG_OP='INSERT' THEN
  SELECT head_revision INTO current_head FROM hr_payroll_rule_set
   WHERE (id,tenant_id,park_id)=(NEW.rule_set_id,NEW.tenant_id,NEW.park_id) FOR UPDATE;
  IF current_head IS NULL OR NEW.revision_no<>current_head+1 OR NEW.version<>1 OR NEW.status<>'draft' OR NEW.authored_by<>NEW.created_by THEN
   RAISE EXCEPTION 'payroll rule draft revision must follow its scoped parent';
  END IF;
  UPDATE hr_payroll_rule_set SET head_revision=NEW.revision_no
   WHERE (id,tenant_id,park_id)=(NEW.rule_set_id,NEW.tenant_id,NEW.park_id);
 ELSE
  IF OLD.status IN('approved','rejected') THEN RAISE EXCEPTION 'reviewed payroll rule version is immutable'; END IF;
  IF NEW.version<>OLD.version+1 OR
   (to_jsonb(NEW)-ARRAY['definition','definition_evidence','definition_sha256','reason','status','version','updated_at','effective_from','reviewed_by','reviewed_at','review_reason','authored_by','submitted_by']) IS DISTINCT FROM
   (to_jsonb(OLD)-ARRAY['definition','definition_evidence','definition_sha256','reason','status','version','updated_at','effective_from','reviewed_by','reviewed_at','review_reason','authored_by','submitted_by']) THEN
   RAISE EXCEPTION 'payroll rule identity or optimistic version changed';
  END IF;
  IF OLD.status='draft' AND NEW.status NOT IN('draft','submitted') THEN RAISE EXCEPTION 'draft must be submitted before review'; END IF;
  IF NEW.status='submitted' AND NEW.authored_by IS DISTINCT FROM OLD.authored_by THEN RAISE EXCEPTION 'submission cannot change rule authorship'; END IF;
  IF OLD.status='submitted' AND (NEW.status NOT IN('approved','rejected') OR
   NEW.definition IS DISTINCT FROM OLD.definition OR NEW.definition_evidence IS DISTINCT FROM OLD.definition_evidence OR NEW.reason IS DISTINCT FROM OLD.reason OR
   NEW.authored_by IS DISTINCT FROM OLD.authored_by OR NEW.submitted_by IS DISTINCT FROM OLD.submitted_by) THEN
   RAISE EXCEPTION 'submitted payroll definition is frozen until review';
  END IF;
 END IF;
 NEW.definition_sha256:=encode(sha256(convert_to(jsonb_build_object('definition',NEW.definition,'evidence',NEW.definition_evidence)::text,'UTF8')),'hex');
 RETURN NEW;
END $$;



--
-- Name: hr_payroll_formal_run_frozen(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_formal_run_frozen() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM hr_payroll_formal_run_evidence WHERE run_id=OLD.id) THEN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Formal payroll run is frozen'; END IF;
  IF (NEW.id,NEW.tenant_id,NEW.park_id,NEW.period_id,NEW.run_no,NEW.correction_of_run_id,NEW.formal_input_id,NEW.employee_count,NEW.gross_total,NEW.deduction_total,NEW.net_total,NEW.calculated_at,NEW.create_by,NEW.is_deleted)
   IS DISTINCT FROM (OLD.id,OLD.tenant_id,OLD.park_id,OLD.period_id,OLD.run_no,OLD.correction_of_run_id,OLD.formal_input_id,OLD.employee_count,OLD.gross_total,OLD.deduction_total,OLD.net_total,OLD.calculated_at,OLD.create_by,OLD.is_deleted)
   THEN RAISE EXCEPTION 'Formal payroll run is frozen'; END IF;
  IF NEW.status IS DISTINCT FROM OLD.status THEN
   IF NEW.version<>OLD.version+1 OR NOT EXISTS(SELECT 1 FROM hr_payroll_formal_run_action a
    WHERE a.run_id=OLD.id AND a.version_before=OLD.version AND a.actor_id=NEW.update_by
      AND ((OLD.status='calculated' AND NEW.status='reviewing' AND a.action='review' AND NEW.reviewed_at IS NOT NULL)
        OR (OLD.status='reviewing' AND NEW.status='confirmed' AND a.action='confirm' AND NEW.confirmed_by=a.actor_id AND NEW.confirmed_at IS NOT NULL)
        OR (OLD.status IN('calculated','reviewing') AND NEW.status='cancelled' AND a.action='cancel')))
    THEN RAISE EXCEPTION 'Use governed payroll review and confirmation'; END IF;
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $$;



--
-- Name: hr_payroll_formal_run_window_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_formal_run_window_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE period_status text; i hr_payroll_formal_input%ROWTYPE; w hr_payroll_correction_window%ROWTYPE;
BEGIN
 IF NEW.formal_input_id IS NULL THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status THEN RETURN NEW; END IF;
 SELECT status INTO period_status FROM hr_payroll_period WHERE
  (id,tenant_id,park_id)=(NEW.period_id,NEW.tenant_id,NEW.park_id) AND NOT is_deleted FOR UPDATE;
 SELECT * INTO i FROM hr_payroll_formal_input WHERE (id,tenant_id,park_id,period_id)=(NEW.formal_input_id,NEW.tenant_id,NEW.park_id,NEW.period_id) FOR SHARE;
 IF i.id IS NULL OR i.status<>'confirmed' THEN RAISE EXCEPTION 'Formal payroll requires confirmed scoped inputs'; END IF;
 IF i.correction_window_id IS NULL THEN
  IF period_status IS DISTINCT FROM 'open' THEN RAISE EXCEPTION 'Formal payroll period is closed'; END IF;
 ELSE
  SELECT * INTO w FROM hr_payroll_correction_window WHERE
   (id,period_id,tenant_id,park_id)=(i.correction_window_id,NEW.period_id,NEW.tenant_id,NEW.park_id) FOR UPDATE;
  IF period_status IS DISTINCT FROM 'closed' OR w.id IS NULL OR w.status<>'open'
   OR NEW.correction_of_run_id IS DISTINCT FROM w.original_run_id OR i.rule_set_id<>w.rule_set_id
   OR i.revision_no<=w.input_head_at_open THEN RAISE EXCEPTION 'Formal payroll requires its active correction window'; END IF;
 END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_payroll_legacy_batch_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_legacy_batch_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.status='published' THEN RAISE EXCEPTION 'Published legacy payroll batch is immutable'; END IF;
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'Legacy payroll batch deletion requires the dedicated rollback procedure';
  END IF;
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;



--
-- Name: hr_payroll_legacy_fact_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_legacy_fact_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE batch_status varchar(32);
BEGIN
  IF TG_OP='UPDATE' THEN RAISE EXCEPTION 'Legacy payroll facts are append-only'; END IF;
  IF TG_TABLE_NAME='hr_payroll_legacy_snapshot_item' THEN
    SELECT b.status INTO batch_status FROM hr_payroll_legacy_snapshot s JOIN hr_payroll_legacy_batch b ON b.id=s.batch_id AND b.tenant_id=s.tenant_id AND b.park_id=s.park_id WHERE s.id=CASE WHEN TG_OP='INSERT' THEN NEW.snapshot_id ELSE OLD.snapshot_id END AND s.tenant_id=CASE WHEN TG_OP='INSERT' THEN NEW.tenant_id ELSE OLD.tenant_id END AND s.park_id=CASE WHEN TG_OP='INSERT' THEN NEW.park_id ELSE OLD.park_id END;
  ELSIF TG_TABLE_NAME='hr_payroll_review_case' THEN
    SELECT status INTO batch_status FROM hr_payroll_legacy_batch WHERE id=CASE WHEN TG_OP='INSERT' THEN NEW.batch_id ELSE OLD.batch_id END AND tenant_id=CASE WHEN TG_OP='INSERT' THEN NEW.tenant_id ELSE OLD.tenant_id END AND park_id=CASE WHEN TG_OP='INSERT' THEN NEW.park_id ELSE OLD.park_id END;
  ELSE
    SELECT status INTO batch_status FROM hr_payroll_legacy_batch WHERE id=CASE WHEN TG_OP='INSERT' THEN NEW.batch_id ELSE OLD.batch_id END AND tenant_id=CASE WHEN TG_OP='INSERT' THEN NEW.tenant_id ELSE OLD.tenant_id END AND park_id=CASE WHEN TG_OP='INSERT' THEN NEW.park_id ELSE OLD.park_id END;
  END IF;
  IF TG_OP='INSERT' THEN
    IF batch_status IS NULL OR batch_status='published' THEN RAISE EXCEPTION 'Published or unknown legacy payroll batch rejects new facts'; END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'Legacy payroll fact deletion requires the dedicated rollback procedure';
END $$;



--
-- Name: hr_payroll_legacy_snapshot_item_insert_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_legacy_snapshot_item_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM (
      SELECT DISTINCT tenant_id,park_id,snapshot_id
      FROM inserted_snapshot_items
    ) inserted
    LEFT JOIN hr_payroll_legacy_snapshot snapshot
      ON snapshot.id=inserted.snapshot_id
     AND snapshot.tenant_id=inserted.tenant_id
     AND snapshot.park_id=inserted.park_id
    LEFT JOIN hr_payroll_legacy_batch batch
      ON batch.id=snapshot.batch_id
     AND batch.tenant_id=snapshot.tenant_id
     AND batch.park_id=snapshot.park_id
    WHERE snapshot.id IS NULL
       OR batch.id IS NULL
       OR batch.status='published'
  ) THEN
    RAISE EXCEPTION 'Published or unknown legacy payroll batch rejects new facts';
  END IF;
  RETURN NULL;
END $$;



--
-- Name: hr_payroll_legacy_snapshot_item_mutation_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_legacy_snapshot_item_mutation_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP='UPDATE' THEN
    RAISE EXCEPTION 'Legacy payroll facts are append-only';
  END IF;
  RAISE EXCEPTION 'Legacy payroll fact deletion requires the dedicated rollback procedure';
END $$;



--
-- Name: hr_payroll_period_close_commit_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_period_close_commit_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM hr_payroll_period p WHERE (p.id,p.tenant_id,p.park_id,p.version,p.update_by)=
  (NEW.period_id,NEW.tenant_id,NEW.park_id,NEW.period_version+1,NEW.created_by) AND p.status='closed' AND NOT p.is_deleted) THEN
  RAISE EXCEPTION 'Payroll close record and period must commit together';
 END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_payroll_period_close_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_period_close_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE p hr_payroll_period%ROWTYPE;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Payroll period close records are immutable'; END IF;
 SELECT * INTO p FROM hr_payroll_period WHERE (id,tenant_id,park_id)=(NEW.period_id,NEW.tenant_id,NEW.park_id) FOR UPDATE;
 IF NOT FOUND OR p.is_deleted OR p.status<>'open' OR p.version<>NEW.period_version THEN
  RAISE EXCEPTION 'Payroll close requires the current open period';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM hr_payroll_run r WHERE (r.period_id,r.tenant_id,r.park_id)=(p.id,p.tenant_id,p.park_id) AND NOT r.is_deleted AND r.status='confirmed')
  OR EXISTS(SELECT 1 FROM hr_payroll_run r WHERE (r.period_id,r.tenant_id,r.park_id)=(p.id,p.tenant_id,p.park_id) AND NOT r.is_deleted AND r.status NOT IN('confirmed','cancelled')) THEN
  RAISE EXCEPTION 'Payroll close requires confirmed runs and no pending run';
 END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_payroll_period_closed_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_period_closed_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF OLD.status='closed' THEN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Closed payroll periods are frozen'; END IF;
  IF (NEW.id,NEW.tenant_id,NEW.park_id,NEW.period_month,NEW.start_date,NEW.end_date,NEW.status,NEW.is_deleted)
   IS DISTINCT FROM (OLD.id,OLD.tenant_id,OLD.park_id,OLD.period_month,OLD.start_date,OLD.end_date,OLD.status,OLD.is_deleted) THEN
   RAISE EXCEPTION 'Closed payroll periods are frozen';
  END IF;
 END IF;
 IF TG_OP='UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
  IF OLD.status<>'open' OR NEW.status<>'closed' OR NEW.version<>OLD.version+1
   OR NOT EXISTS(SELECT 1 FROM hr_payroll_period_close c WHERE (c.period_id,c.tenant_id,c.park_id,c.period_version,c.created_by)=(OLD.id,OLD.tenant_id,OLD.park_id,OLD.version,NEW.update_by))
   OR (NEW.id,NEW.tenant_id,NEW.park_id,NEW.period_month,NEW.start_date,NEW.end_date,NEW.is_deleted)
     IS DISTINCT FROM (OLD.id,OLD.tenant_id,OLD.park_id,OLD.period_month,OLD.start_date,OLD.end_date,OLD.is_deleted) THEN
   RAISE EXCEPTION 'Use governed payroll period close';
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $$;



--
-- Name: hr_payroll_reconciliation_append_only_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_reconciliation_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
  RAISE EXCEPTION 'Payroll reconciliation evidence is append-only';
END $$;



--
-- Name: hr_payroll_reconciliation_policy_append_only_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_reconciliation_policy_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
  RAISE EXCEPTION 'Payroll reconciliation policy versions are append-only';
END $$;



--
-- Name: hr_payroll_reconciliation_policy_current_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_reconciliation_policy_current_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ DECLARE old_version integer; new_version integer; BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Current payroll reconciliation policy cannot be deleted'; END IF;
  SELECT version_no INTO old_version FROM hr_payroll_reconciliation_policy_version WHERE tenant_id=OLD.tenant_id AND park_id=OLD.park_id AND book_id=OLD.book_id AND id=OLD.policy_version_id;
  SELECT version_no INTO new_version FROM hr_payroll_reconciliation_policy_version WHERE tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND book_id=NEW.book_id AND id=NEW.policy_version_id;
  IF new_version IS NULL OR old_version IS NULL OR new_version<=old_version OR (NEW.tenant_id,NEW.park_id,NEW.book_id)<>(OLD.tenant_id,OLD.park_id,OLD.book_id) THEN RAISE EXCEPTION 'Current payroll reconciliation policy must advance to a newer approved version'; END IF;
  RETURN NEW;
END $$;



--
-- Name: hr_payroll_reconciliation_policy_scope_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_reconciliation_policy_scope_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
  IF NOT EXISTS(SELECT 1 FROM hr_payroll_item_version version JOIN hr_payroll_item_definition definition ON definition.id=version.item_definition_id AND definition.tenant_id=version.tenant_id AND definition.park_id=version.park_id WHERE version.id=NEW.net_item_version_id AND version.tenant_id=NEW.tenant_id AND version.park_id=NEW.park_id AND definition.book_id=NEW.book_id AND version.enabled=true AND version.value_type='decimal' AND version.is_deleted=false AND definition.is_deleted=false) THEN
    RAISE EXCEPTION 'Payroll reconciliation net item must be a current enabled decimal item in the same book';
  END IF;
  RETURN NEW;
END $$;



--
-- Name: hr_payroll_reconciliation_run_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_reconciliation_run_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
  IF TG_OP='DELETE' OR NOT ((OLD.status='calculating' AND NEW.status='review' AND NEW.difference_count>=0) OR (OLD.status='review' AND NEW.status IN('accepted','rejected') AND NEW.difference_count=OLD.difference_count))
    OR (to_jsonb(NEW)-ARRAY['status','difference_count','update_time','update_by'])<>(to_jsonb(OLD)-ARRAY['status','difference_count','update_time','update_by']) THEN
    RAISE EXCEPTION 'Payroll reconciliation runs are immutable after calculation';
  END IF;
  RETURN NEW;
END $$;



--
-- Name: hr_payroll_result_modern_insurance_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_result_modern_insurance_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE revision public.hr_insurance_owned_revision%ROWTYPE; month_value date;
BEGIN
  IF NEW.insurance_modern_revision_id IS NULL THEN RETURN NEW; END IF;
  SELECT * INTO revision FROM public.hr_insurance_owned_revision WHERE id=NEW.insurance_modern_revision_id
    AND tenant_id=NEW.tenant_id AND park_id=NEW.park_id;
  IF NOT FOUND OR revision.employee_id<>NEW.employee_id THEN RAISE EXCEPTION 'HR_PAYROLL_MODERN_INSURANCE_SOURCE_INVALID'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(jsonb_build_array('insurance-owned-family',NEW.tenant_id,NEW.park_id,revision.employee_id,revision.period_month)::text,0));
  PERFORM 1 FROM public.hr_insurance_owned_revision WHERE id=revision.id FOR UPDATE;
  SELECT period.period_month INTO month_value FROM public.hr_payroll_reconciliation_run run
    JOIN public.hr_attendance_payroll_input_batch attendance ON attendance.id=run.attendance_input_batch_id
      AND attendance.tenant_id=run.tenant_id AND attendance.park_id=run.park_id
    JOIN public.hr_attendance_period period ON period.id=attendance.period_id
      AND period.tenant_id=attendance.tenant_id AND period.park_id=attendance.park_id
    WHERE run.id=NEW.run_id AND run.tenant_id=NEW.tenant_id AND run.park_id=NEW.park_id;
  IF month_value IS DISTINCT FROM revision.period_month OR EXISTS(
    SELECT 1 FROM public.hr_insurance_owned_revision WHERE tenant_id=NEW.tenant_id AND park_id=NEW.park_id
      AND employee_id=revision.employee_id AND period_month=revision.period_month AND revision_no>revision.revision_no) THEN
    RAISE EXCEPTION 'HR_PAYROLL_MODERN_INSURANCE_SOURCE_STALE_OR_MONTH_MISMATCH';
  END IF;
  RETURN NEW;
END $$;



--
-- Name: hr_payroll_review_action_append_only_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_review_action_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'Legacy payroll review actions are append-only';
END $$;



--
-- Name: hr_payroll_review_action_insert_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_payroll_review_action_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  prior_terminal boolean;
BEGIN
  PERFORM 1
  FROM public.hr_payroll_review_case
  WHERE tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND id=NEW.review_case_id
  FOR UPDATE;

  SELECT EXISTS (
    SELECT 1 FROM public.hr_payroll_review_action
    WHERE tenant_id=NEW.tenant_id AND park_id=NEW.park_id
      AND review_case_id=NEW.review_case_id AND is_deleted=false
      AND action IN ('resolve','reject')
  ) INTO prior_terminal;
  IF prior_terminal THEN
    RAISE EXCEPTION 'Legacy payroll review case already has a terminal action';
  END IF;
  RETURN NEW;
END $$;



--
-- Name: hr_performance_appeal_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_appeal_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'performance appeal is immutable'; END IF;
 IF (NEW.tenant_id,NEW.park_id,NEW.cycle_employee_id,NEW.appeal_no,NEW.reason,NEW.submitted_by,NEW.submitted_at) IS DISTINCT FROM (OLD.tenant_id,OLD.park_id,OLD.cycle_employee_id,OLD.appeal_no,OLD.reason,OLD.submitted_by,OLD.submitted_at) THEN RAISE EXCEPTION 'performance appeal identity is immutable'; END IF;
 IF OLD.status<>'submitted' OR NEW.status NOT IN('upheld','rejected') THEN RAISE EXCEPTION 'invalid performance appeal transition'; END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_performance_append_only_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN RAISE EXCEPTION 'performance review evidence is append-only'; END $$;



--
-- Name: hr_performance_calibration_batch_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_calibration_batch_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'performance calibration batch is immutable'; END IF;
 IF (NEW.tenant_id,NEW.park_id,NEW.cycle_id,NEW.batch_name,NEW.meeting_at,NEW.created_by,NEW.create_time) IS DISTINCT FROM (OLD.tenant_id,OLD.park_id,OLD.cycle_id,OLD.batch_name,OLD.meeting_at,OLD.created_by,OLD.create_time) THEN RAISE EXCEPTION 'performance calibration batch identity is immutable'; END IF;
 IF NEW.status IS DISTINCT FROM OLD.status AND NOT ((OLD.status='draft' AND NEW.status='active') OR (OLD.status='active' AND NEW.status='completed')) THEN RAISE EXCEPTION 'invalid performance calibration transition'; END IF;
 IF OLD.status='completed' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'completed performance calibration batch is immutable'; END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_performance_calibration_entry_insert_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_calibration_entry_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ DECLARE batch_row record;ce record;expected_before numeric;expected_after numeric; channel_review record;channel_input jsonb;channel_result jsonb;channel_before numeric; BEGIN
 SELECT x.*,c.template_snapshot INTO channel_review FROM hr_performance_cycle_employee x JOIN hr_performance_review_cycle c ON(c.id,c.tenant_id,c.park_id)=(x.cycle_id,x.tenant_id,x.park_id) WHERE(x.id,x.tenant_id,x.park_id)=(NEW.cycle_employee_id,NEW.tenant_id,NEW.park_id) FOR UPDATE OF x,c;
 IF NEW.calculation_mode IS DISTINCT FROM channel_review.calculation_mode THEN RAISE EXCEPTION 'calibration mode mismatch';END IF;
 IF channel_review.calculation_mode='five_channel_v1' THEN
  IF channel_review.status<>'calibration' OR NEW.input_revision_id IS DISTINCT FROM channel_review.current_input_revision_id OR NOT hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.actor_user_id,'hr:performance:calibrate') OR EXISTS(SELECT 1 FROM hr_employee e WHERE e.id=channel_review.employee_id AND e.user_id=NEW.actor_user_id) OR NOT EXISTS(SELECT 1 FROM hr_performance_calibration_batch b JOIN hr_performance_calibration_participant p ON(p.batch_id,p.tenant_id,p.park_id)=(b.id,b.tenant_id,b.park_id) WHERE(b.id,b.tenant_id,b.park_id,b.cycle_id)=(NEW.batch_id,NEW.tenant_id,NEW.park_id,channel_review.cycle_id) AND b.status='active' AND p.participant_user_id=NEW.actor_user_id) THEN RAISE EXCEPTION 'calibration input/actor/batch mismatch';END IF;
  SELECT input INTO channel_input FROM hr_performance_channel_input_revision WHERE id=NEW.input_revision_id;
  channel_result:=hr_performance_channel_calculate(channel_review.template_snapshot,channel_input,NEW.input_revision_id);
  channel_before:=COALESCE(channel_review.calibrated_score,channel_review.manager_score);
  IF NOT hr_performance_channel_final_ready(channel_review.template_snapshot,channel_input) OR channel_result->'complete' IS DISTINCT FROM 'true'::jsonb OR channel_result->'grade'->>'status' IS DISTINCT FROM 'RESOLVED' OR NEW.before_score IS DISTINCT FROM channel_before OR NEW.after_score IS DISTINCT FROM(channel_result->>'score')::numeric OR NEW.calculation_evidence IS DISTINCT FROM channel_result THEN RAISE EXCEPTION 'calibration requires complete unique result evidence';END IF;RETURN NEW;
 END IF;


 SELECT * INTO batch_row FROM hr_performance_calibration_batch WHERE id=NEW.batch_id AND tenant_id=NEW.tenant_id AND park_id=NEW.park_id FOR UPDATE;
 SELECT x.*,c.template_snapshot INTO ce FROM hr_performance_cycle_employee x JOIN hr_performance_review_cycle c ON(c.id,c.tenant_id,c.park_id)=(x.cycle_id,x.tenant_id,x.park_id) WHERE x.id=NEW.cycle_employee_id AND x.tenant_id=NEW.tenant_id AND x.park_id=NEW.park_id FOR UPDATE OF x,c;
 IF batch_row.id IS NULL OR batch_row.status<>'active' OR ce.id IS NULL OR ce.cycle_id<>batch_row.cycle_id OR ce.status<>'calibration' THEN RAISE EXCEPTION 'calibration entry is outside its active batch';END IF;
 SELECT COALESCE((SELECT after_score FROM hr_performance_calibration_entry WHERE tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND batch_id=NEW.batch_id AND cycle_employee_id=NEW.cycle_employee_id ORDER BY entry_no DESC LIMIT 1),ce.manager_score) INTO expected_before;
 expected_after:=hr_performance_snapshot_score(ce.template_snapshot,NEW.dimension_scores);
 IF expected_before IS NULL OR NEW.before_score<>expected_before OR NEW.after_score<>expected_after THEN RAISE EXCEPTION 'calibration adjustment is not reproducible';END IF;
 RETURN NEW;END $$;



--
-- Name: hr_performance_channel_action_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_action_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE ce record;i jsonb;result jsonb;expected_permission text;employee_user uuid;
BEGIN
 SELECT x.*,c.template_snapshot INTO ce FROM hr_performance_cycle_employee x JOIN hr_performance_review_cycle c ON(c.id,c.tenant_id,c.park_id)=(x.cycle_id,x.tenant_id,x.park_id) WHERE(x.id,x.tenant_id,x.park_id)=(NEW.cycle_employee_id,NEW.tenant_id,NEW.park_id) FOR UPDATE OF x,c;
 IF ce.calculation_mode<>'five_channel_v1' THEN RETURN NEW;END IF;
 IF NEW.action_type='baseline' THEN IF NEW.input_revision_id IS NOT NULL OR NEW.result_snapshot<>'{}'::jsonb THEN RAISE EXCEPTION 'invalid channel baseline';END IF;RETURN NEW;END IF;
 IF NEW.actor_user_id IS NULL OR NEW.from_status IS DISTINCT FROM ce.status THEN RAISE EXCEPTION 'channel action actor/stage mismatch';END IF;
 SELECT user_id INTO employee_user FROM hr_employee WHERE(id,tenant_id,park_id)=(ce.employee_id,ce.tenant_id,ce.park_id);
 expected_permission:=CASE NEW.action_type WHEN 'self_submitted' THEN 'hr:performance:self_review' WHEN 'manager_submitted' THEN 'hr:performance:manager_review' WHEN 'calibration_adjusted' THEN 'hr:performance:calibrate' WHEN 'result_finalized' THEN 'hr:performance:calibrate' WHEN 'acknowledged' THEN 'hr:performance:acknowledge' WHEN 'appealed' THEN 'hr:performance:appeal' WHEN 'appeal_upheld' THEN 'hr:performance:appeal_review' WHEN 'appeal_rejected' THEN 'hr:performance:appeal_review' END;
 IF expected_permission IS NULL OR NOT hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.actor_user_id,expected_permission) THEN RAISE EXCEPTION 'channel action permission required';END IF;
 IF NEW.action_type IN('acknowledged','appealed','self_submitted') AND NEW.actor_user_id IS DISTINCT FROM employee_user THEN RAISE EXCEPTION 'employee action actor mismatch';END IF;
 IF NEW.action_type IN('calibration_adjusted','result_finalized','appeal_upheld','appeal_rejected') AND NEW.actor_user_id=employee_user THEN RAISE EXCEPTION 'self finalization is not allowed';END IF;
 IF NEW.action_type IN('self_submitted','manager_submitted','calibration_adjusted','result_finalized','appeal_upheld','appeal_rejected') THEN
  IF NEW.input_revision_id IS NULL OR(NEW.action_type<>'appeal_rejected' AND NEW.input_revision_id IS DISTINCT FROM ce.current_input_revision_id) THEN RAISE EXCEPTION 'action input revision mismatch';END IF;
  SELECT input INTO i FROM hr_performance_channel_input_revision WHERE(id,tenant_id,park_id,cycle_employee_id)=(NEW.input_revision_id,NEW.tenant_id,NEW.park_id,NEW.cycle_employee_id);
  result:=hr_performance_channel_calculate(ce.template_snapshot,i,NEW.input_revision_id);
  IF NEW.result_snapshot IS DISTINCT FROM result THEN RAISE EXCEPTION 'action calculation evidence mismatch';END IF;
  IF NEW.action_type IN('result_finalized','appeal_upheld','appeal_rejected') AND(NOT hr_performance_channel_final_ready(ce.template_snapshot,i) OR result->'complete' IS DISTINCT FROM 'true'::jsonb OR result->'grade'->>'status' IS DISTINCT FROM 'RESOLVED') THEN RAISE EXCEPTION 'final action requires complete unique result';END IF;
 END IF;
 IF NEW.action_type IN('calibration_adjusted','result_finalized') AND NOT EXISTS(SELECT 1 FROM hr_performance_calibration_batch b JOIN hr_performance_calibration_participant p ON(p.batch_id,p.tenant_id,p.park_id)=(b.id,b.tenant_id,b.park_id) WHERE(b.cycle_id,b.tenant_id,b.park_id)=(ce.cycle_id,ce.tenant_id,ce.park_id) AND b.status='active' AND p.participant_user_id=NEW.actor_user_id) THEN RAISE EXCEPTION 'active calibration participation required';END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_performance_channel_actor_has(character varying, character varying, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_actor_has(t character varying, p character varying, u uuid, permission_code text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 SELECT EXISTS(SELECT 1 FROM public.sys_user actor JOIN public.rel_user_role ur ON(ur.user_id,ur.tenant_id)=(actor.id,actor.tenant_id)
 JOIN public.sys_role r ON(r.id,r.tenant_id)=(ur.role_id,ur.tenant_id)
 LEFT JOIN public.rel_role_perm rp ON(rp.role_id,rp.tenant_id,rp.park_id)=(r.id,ur.tenant_id,p) AND NOT rp.is_deleted
 LEFT JOIN public.sys_permission perm ON(perm.id,perm.tenant_id)=(rp.permission_id,rp.tenant_id) AND NOT perm.is_deleted AND perm.is_enabled AND perm.status='enabled'
 WHERE actor.tenant_id=t AND actor.id=u AND actor.is_enabled AND NOT actor.is_deleted AND actor.status='enabled' AND NOT ur.is_deleted AND NOT r.is_deleted AND r.is_enabled AND r.status='enabled'
 AND ((r.code='SUPER_ADMIN' AND r.role_scope='platform' AND r.is_super AND r.is_system AND r.is_builtin)
 OR (ur.park_id=p AND(r.role_scope='tenant' OR r.park_id=p) AND(r.is_super OR permission_code IS NULL OR perm.code IN(permission_code,'*')))))
$$;



--
-- Name: hr_performance_channel_appeal_decision_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_appeal_decision_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE ce record;a record;
BEGIN
 SELECT * INTO ce FROM hr_performance_cycle_employee WHERE(id,tenant_id,park_id)=(NEW.cycle_employee_id,NEW.tenant_id,NEW.park_id) FOR UPDATE;
 IF ce.calculation_mode='five_channel_v1' THEN
  SELECT * INTO a FROM hr_performance_review_action WHERE(cycle_employee_id,tenant_id,park_id)=(ce.id,ce.tenant_id,ce.park_id) AND reference_id=NEW.id AND action_type=CASE NEW.status WHEN 'upheld' THEN 'appeal_upheld' ELSE 'appeal_rejected' END ORDER BY action_no DESC LIMIT 1;
  IF ce.status<>'appealed' OR a.id IS NULL OR a.actor_user_id IS DISTINCT FROM NEW.resolved_by THEN RAISE EXCEPTION 'appeal decision requires exact action evidence';END IF;
 END IF;RETURN NEW;
END $$;



--
-- Name: hr_performance_channel_author_scope_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_author_scope_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE field text;u uuid;old_u text;
BEGIN
 FOREACH field IN ARRAY TG_ARGV LOOP
  u:=(to_jsonb(NEW)->>field)::uuid;
  IF u IS NOT NULL THEN
   IF NOT EXISTS(SELECT 1 FROM sys_user WHERE id=u AND tenant_id=NEW.tenant_id) THEN RAISE EXCEPTION 'performance author must belong to the same tenant';END IF;
   old_u:=CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD)->>field ELSE NULL END;
   IF TG_OP='INSERT' AND TG_TABLE_NAME='hr_performance_channel_definition_revision' AND NOT hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,u,'hr:performance_template:manage') THEN RAISE EXCEPTION 'definition revision requires current template management';END IF;
   IF(TG_OP='INSERT' OR u::text IS DISTINCT FROM old_u) AND NOT hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,u,NULL) THEN RAISE EXCEPTION 'performance author lacks active selected-park authorization';END IF;
  END IF;
 END LOOP;RETURN NEW;
END $$;



--
-- Name: hr_performance_channel_batch_complete_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_batch_complete_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
 IF NEW.status='completed' AND OLD.status IS DISTINCT FROM NEW.status AND EXISTS(SELECT 1 FROM hr_performance_review_cycle c WHERE(c.id,c.tenant_id,c.park_id)=(NEW.cycle_id,NEW.tenant_id,NEW.park_id) AND c.template_snapshot->>'calculationMode'='five_channel_v1') AND EXISTS(SELECT 1 FROM hr_performance_cycle_employee e WHERE(e.cycle_id,e.tenant_id,e.park_id)=(NEW.cycle_id,NEW.tenant_id,NEW.park_id) AND e.status='calibration') THEN RAISE EXCEPTION 'pending channel employees keep the batch active';END IF;RETURN NEW;
END $$;



--
-- Name: hr_performance_channel_calculate(jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_calculate(t jsonb, i jsonb, rid uuid) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE d jsonb;tally numeric;g jsonb;candidate jsonb;complete boolean;
BEGIN
 IF NOT public.hr_performance_channel_input_valid(i,t->'channelWorkflow') THEN RAISE EXCEPTION 'invalid channel input';END IF;
 SELECT NOT EXISTS(SELECT 1 FROM public.hr_performance_channel_cells(i) WHERE field NOT IN('selfAppraisal','appraisal','description','salaryReference','detailAppraisal') AND cell->>'state'='UNPROVIDED') INTO complete;
 IF complete THEN
  SELECT jsonb_agg(jsonb_build_object('id',a->'id','selfValue',a->'channels'->'s'->'value','mItemValue',a->'channels'->'m'->'value','itemValue',a->'channels'->'t'->'value','xItemValue',a->'channels'->'x'->'value','cItemValue',a->'channels'->'c'->'value') ORDER BY ord) INTO d FROM jsonb_array_elements(i->'details') WITH ORDINALITY x(a,ord);
  tally:=public.hr_performance_five_channel_snapshot_total_v1(t->'channelDefinition'->'weights',COALESCE(d,'[]'::jsonb),jsonb_build_object('masterValue',i->'adjustments'->'master'->'value','timekeepValue',i->'adjustments'->'timekeep'->'value','bonusValue',i->'adjustments'->'bonus'->'value'));
 END IF;
 SELECT public.hr_performance_threshold_snapshot_grade_v1(tally,COALESCE(jsonb_agg(jsonb_build_object('id',a->'id','grade',a->'code','minValue',a->'minValue')),'[]'::jsonb)) INTO g FROM jsonb_array_elements(t->'channelDefinition'->'gradeCandidates') a;
 IF g->>'status'='RESOLVED' THEN SELECT a INTO candidate FROM jsonb_array_elements(t->'channelDefinition'->'gradeCandidates') a WHERE (a->>'minValue')::numeric=(g->>'winningMinValue')::numeric;END IF;
 RETURN jsonb_build_object('schemaVersion',1,'mathVersion','five_channel_v1','inputRevisionId',rid,'complete',complete,'score',tally::text,'grade',g,'gradeCandidate',candidate,'levelCode',candidate->>'code','levelName',candidate->>'code');
END $$;



--
-- Name: hr_performance_channel_cells(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_cells(i jsonb) RETURNS TABLE(detail_id text, field text, cell jsonb)
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT a->>'id',c.key,c.value FROM jsonb_array_elements(i->'details') a CROSS JOIN LATERAL jsonb_each(a->'channels') c UNION ALL SELECT a->>'id','detailAppraisal',a->'appraisal' FROM jsonb_array_elements(i->'details') a WHERE a ? 'appraisal' UNION ALL SELECT NULL,c.key,c.value FROM jsonb_each(i->'adjustments') c UNION ALL SELECT NULL,c.key,c.value FROM jsonb_each(i->'master') c
$$;



--
-- Name: hr_performance_channel_child_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_child_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
 IF EXISTS(SELECT 1 FROM hr_performance_template_version WHERE (id,tenant_id,park_id)=(NEW.template_version_id,NEW.tenant_id,NEW.park_id) AND calculation_mode='five_channel_v1') THEN RAISE EXCEPTION 'five-channel definitions do not use dimension children'; END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_performance_channel_config_valid_v1(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_config_valid_v1(v jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE r jsonb; g jsonb; x jsonb; ids text[]; guides text[];
BEGIN
 IF NOT public.hr_performance_channel_object_v1(v,ARRAY['schemaVersion','displayName','departmentLabel','weights','channels','adjustmentPolicy','items','gradeCandidates']) THEN RETURN false; END IF;
 IF v->'schemaVersion' IS DISTINCT FROM '1'::jsonb OR NOT public.hr_performance_channel_scalar_v1(v->'displayName','text',120) OR NOT public.hr_performance_channel_scalar_v1(v->'departmentLabel','text',30) THEN RETURN false; END IF;
 IF NOT public.hr_performance_channel_object_v1(v->'weights',ARRAY['sPercent','mPercent','tPercent','xPercent','cPercent']) THEN RETURN false; END IF;
 FOR x IN SELECT value FROM jsonb_each(v->'weights') LOOP IF NOT public.hr_performance_channel_scalar_v1(x,'int') THEN RETURN false; END IF; END LOOP;
 IF NOT public.hr_performance_channel_object_v1(v->'channels',ARRAY['s','m','t','x','c']) OR NOT public.hr_performance_channel_object_v1(v->'adjustmentPolicy',ARRAY['master','timekeep','bonus']) THEN RETURN false; END IF;
 FOR x IN SELECT value FROM jsonb_each(v->'channels') LOOP IF NOT public.hr_performance_channel_policy_v1(x,false) THEN RETURN false; END IF; END LOOP;
 FOR x IN SELECT value FROM jsonb_each(v->'adjustmentPolicy') LOOP IF NOT public.hr_performance_channel_policy_v1(x,true) THEN RETURN false; END IF; END LOOP;
 IF jsonb_typeof(v->'items') IS DISTINCT FROM 'array' OR jsonb_typeof(v->'gradeCandidates') IS DISTINCT FROM 'array' THEN RETURN false; END IF;
 ids:=ARRAY[]::text[];
 FOR r IN SELECT value FROM jsonb_array_elements(v->'items') LOOP
  IF NOT public.hr_performance_channel_object_v1(r,ARRAY['id','name','fullValue','order','sourceAssessmentRef','guides']) THEN RETURN false; END IF;
  IF jsonb_typeof(r->'id') IS DISTINCT FROM 'string' OR char_length(r->>'id') NOT BETWEEN 1 AND 128 OR r->>'id'=ANY(ids) THEN RETURN false; END IF; ids:=array_append(ids,r->>'id');
  IF NOT(public.hr_performance_channel_scalar_v1(r->'name','text',100) AND public.hr_performance_channel_scalar_v1(r->'fullValue','decimal') AND public.hr_performance_channel_scalar_v1(r->'order','order') AND public.hr_performance_channel_scalar_v1(r->'sourceAssessmentRef','int')) OR jsonb_typeof(r->'guides') IS DISTINCT FROM 'array' THEN RETURN false; END IF;
  guides:=ARRAY[]::text[];
  FOR g IN SELECT value FROM jsonb_array_elements(r->'guides') LOOP
   IF NOT public.hr_performance_channel_object_v1(g,ARRAY['id','grade','description','minValue','maxValue','order']) THEN RETURN false; END IF;
   IF jsonb_typeof(g->'id') IS DISTINCT FROM 'string' OR char_length(g->>'id') NOT BETWEEN 1 AND 128 OR g->>'id'=ANY(guides) THEN RETURN false; END IF; guides:=array_append(guides,g->>'id');
   IF NOT(public.hr_performance_channel_scalar_v1(g->'grade','text',64) AND public.hr_performance_channel_scalar_v1(g->'description','text',500) AND public.hr_performance_channel_scalar_v1(g->'minValue','decimal') AND public.hr_performance_channel_scalar_v1(g->'maxValue','decimal') AND public.hr_performance_channel_scalar_v1(g->'order','order')) THEN RETURN false; END IF;
  END LOOP;
 END LOOP;
 ids:=ARRAY[]::text[];
 FOR r IN SELECT value FROM jsonb_array_elements(v->'gradeCandidates') LOOP
  IF NOT public.hr_performance_channel_object_v1(r,ARRAY['id','code','description','sourceOrderText','sourceAssessmentRef','minValue','maxValue']) THEN RETURN false; END IF;
  IF jsonb_typeof(r->'id') IS DISTINCT FROM 'string' OR char_length(r->>'id') NOT BETWEEN 1 AND 128 OR r->>'id'=ANY(ids) THEN RETURN false; END IF; ids:=array_append(ids,r->>'id');
  IF jsonb_typeof(r->'code') IS DISTINCT FROM 'string' OR NOT(public.hr_performance_channel_scalar_v1(r->'code','text',64) AND public.hr_performance_channel_scalar_v1(r->'description','text',500) AND public.hr_performance_channel_scalar_v1(r->'sourceOrderText','text',2) AND public.hr_performance_channel_scalar_v1(r->'sourceAssessmentRef','int') AND public.hr_performance_channel_scalar_v1(r->'minValue','decimal') AND public.hr_performance_channel_scalar_v1(r->'maxValue','decimal')) THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
END $$;



--
-- Name: hr_performance_channel_cycle_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_cycle_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v record;d jsonb;w record;source_r public.hr_performance_source_activation_receipt%ROWTYPE;
BEGIN
 IF TG_OP='UPDATE' AND NEW.source_activation_receipt_id IS DISTINCT FROM OLD.source_activation_receipt_id THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_CYCLE_LINK_IMMUTABLE';END IF;
 IF NEW.source_activation_receipt_id IS NOT NULL THEN
 SELECT * INTO source_r FROM public.hr_performance_source_activation_receipt WHERE(id,tenant_id,park_id)=(NEW.source_activation_receipt_id,NEW.tenant_id,NEW.park_id);
 IF source_r.id IS NULL OR source_r.kind<>'review' OR source_r.cycle_id<>NEW.id OR source_r.template_version_id<>NEW.template_version_id OR NEW.cycle_code IS DISTINCT FROM source_r.request->>'cycleCode' OR NEW.cycle_name IS DISTINCT FROM source_r.request->>'cycleName' OR NEW.selected_employee_ids IS DISTINCT FROM jsonb_build_array(source_r.employee_id) OR NEW.applicable_org_ids IS DISTINCT FROM jsonb_build_array(source_r.binding->>'orgId') OR NEW.business_period_ref IS DISTINCT FROM source_r.binding->>'businessPeriodRef' OR NEW.start_date IS DISTINCT FROM(source_r.binding->>'startDate')::date OR NEW.end_date IS DISTINCT FROM(source_r.binding->>'endDate')::date OR NEW.correction_reason IS NOT NULL OR NEW.predecessor_review_ids IS NOT NULL OR NEW.create_by IS DISTINCT FROM source_r.created_by OR NEW.create_time IS DISTINCT FROM source_r.created_at OR(TG_OP='INSERT' AND source_r.created_xid IS DISTINCT FROM pg_current_xact_id()) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_CYCLE_INVALID';END IF;
 END IF;
 SELECT * INTO v FROM hr_performance_template_version WHERE(id,tenant_id,park_id)=(NEW.template_version_id,NEW.tenant_id,NEW.park_id) FOR SHARE;
 IF v.calculation_mode='five_channel_v1' THEN
  IF TG_OP='INSERT' AND(NEW.status<>'planning' OR NEW.published_at IS NOT NULL) THEN RAISE EXCEPTION 'channel cycle must start in unpublished planning';END IF;
  SELECT config INTO d FROM hr_performance_channel_definition_revision WHERE id=v.channel_definition_revision_id;
  SELECT * INTO w FROM hr_performance_channel_workflow_revision WHERE id=v.channel_workflow_revision_id;
  IF v.status<>'published' OR NOT hr_performance_channel_workflow_valid(w.policy,d,true) OR NEW.template_snapshot->>'calculationMode' IS DISTINCT FROM 'five_channel_v1' OR NEW.template_snapshot->>'currentRevisionId' IS DISTINCT FROM v.channel_definition_revision_id::text OR NEW.template_snapshot->>'workflowRevisionId' IS DISTINCT FROM v.channel_workflow_revision_id::text OR NEW.template_snapshot->'channelDefinition' IS DISTINCT FROM d OR NEW.template_snapshot->'channelWorkflow' IS DISTINCT FROM w.policy THEN RAISE EXCEPTION 'channel cycle must freeze exact published revisions';END IF;
 ELSIF NEW.template_snapshot ? 'calculationMode' AND NEW.template_snapshot->>'calculationMode' IS DISTINCT FROM 'dimension_weighted_v1' THEN RAISE EXCEPTION 'invalid frozen mode';END IF;
 IF v.calculation_mode='five_channel_v1' AND TG_OP='UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
  IF NOT EXISTS(SELECT 1 FROM hr_performance_cycle_employee e WHERE(e.cycle_id,e.tenant_id,e.park_id)=(NEW.id,NEW.tenant_id,NEW.park_id)) OR EXISTS(SELECT 1 FROM hr_performance_cycle_employee e WHERE(e.cycle_id,e.tenant_id,e.park_id)=(NEW.id,NEW.tenant_id,NEW.park_id) AND ((NEW.status='manager_review' AND e.status='self_review') OR(NEW.status='calibration' AND e.status IN('self_review','manager_review')) OR(NEW.status='employee_acknowledged' AND e.status IN('self_review','manager_review','calibration')) OR(NEW.status='confirmed' AND e.status<>'confirmed'))) THEN RAISE EXCEPTION 'channel cycle stage requires employee evidence';END IF;
 END IF;
 IF TG_OP='UPDATE' AND(NEW.correction_reason,NEW.business_period_ref,NEW.selected_employee_ids,NEW.predecessor_review_ids) IS DISTINCT FROM(OLD.correction_reason,OLD.business_period_ref,OLD.selected_employee_ids,OLD.predecessor_review_ids) THEN RAISE EXCEPTION 'correction identity is immutable';END IF;
 IF NEW.predecessor_review_ids IS NOT NULL THEN
  IF jsonb_typeof(NEW.predecessor_review_ids)<>'array' OR jsonb_typeof(NEW.selected_employee_ids) IS DISTINCT FROM 'array' OR (SELECT count(DISTINCT value) FROM jsonb_array_elements(NEW.predecessor_review_ids))<>jsonb_array_length(NEW.predecessor_review_ids) OR (SELECT count(DISTINCT value) FROM jsonb_array_elements(NEW.selected_employee_ids))<>jsonb_array_length(NEW.selected_employee_ids) OR jsonb_array_length(NEW.predecessor_review_ids)=0 OR jsonb_array_length(NEW.predecessor_review_ids)<>jsonb_array_length(NEW.selected_employee_ids) OR NEW.correction_reason IS NULL OR length(btrim(NEW.correction_reason))<2 OR NEW.business_period_ref IS NULL OR length(btrim(NEW.business_period_ref))=0 THEN RAISE EXCEPTION 'explicit correction identity required';END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(NEW.predecessor_review_ids) ids(id) WHERE NOT EXISTS(SELECT 1 FROM hr_performance_cycle_employee ce WHERE(ce.id,ce.tenant_id,ce.park_id)=(ids.id::uuid,NEW.tenant_id,NEW.park_id) AND ce.status='confirmed' AND NEW.selected_employee_ids ? ce.employee_id::text)) THEN RAISE EXCEPTION 'confirmed correction predecessor required';END IF;
 ELSIF NEW.source_activation_receipt_id IS NULL AND(NEW.selected_employee_ids IS NOT NULL OR NEW.correction_reason IS NOT NULL OR NEW.business_period_ref IS NOT NULL) THEN RAISE EXCEPTION 'incomplete correction identity';END IF;RETURN NEW;
END $$;



--
-- Name: hr_performance_channel_employee_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_employee_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE c record;r record;source_r public.hr_performance_source_activation_receipt%ROWTYPE;
BEGIN
 SELECT * INTO c FROM hr_performance_review_cycle WHERE(id,tenant_id,park_id)=(NEW.cycle_id,NEW.tenant_id,NEW.park_id) FOR SHARE;
 IF c.source_activation_receipt_id IS NOT NULL THEN
 SELECT * INTO source_r FROM public.hr_performance_source_activation_receipt WHERE(id,tenant_id,park_id)=(c.source_activation_receipt_id,NEW.tenant_id,NEW.park_id);
 IF source_r.id IS NULL OR source_r.review_id<>NEW.id OR source_r.employee_id<>NEW.employee_id OR NEW.predecessor_review_id IS NOT NULL OR(TG_OP='INSERT' AND source_r.created_xid IS DISTINCT FROM pg_current_xact_id()) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_COHORT_INVALID';END IF;
 END IF;
 IF NEW.calculation_mode IS DISTINCT FROM COALESCE(c.template_snapshot->>'calculationMode','dimension_weighted_v1') THEN RAISE EXCEPTION 'employee mode must match frozen cycle';END IF;
 IF TG_OP='INSERT' AND NEW.calculation_mode='five_channel_v1' AND(NEW.status NOT IN('planning','self_review') OR num_nonnulls(NEW.self_score,NEW.manager_score,NEW.calibrated_score,NEW.final_score,NEW.final_level_code,NEW.final_level_name,NEW.result_finalized_at,NEW.acknowledged_at,NEW.confirmed_at,NEW.current_input_revision_id,NEW.final_input_revision_id,NEW.final_grade_evidence)>0) THEN RAISE EXCEPTION 'channel employee must start without score or result evidence';END IF;
 IF TG_OP='INSERT' AND c.source_activation_receipt_id IS NULL AND c.selected_employee_ids IS NOT NULL AND (NOT c.selected_employee_ids ? NEW.employee_id::text OR NEW.predecessor_review_id IS NULL OR NOT c.predecessor_review_ids ? NEW.predecessor_review_id::text OR NOT EXISTS(SELECT 1 FROM hr_performance_cycle_employee p WHERE(p.id,p.tenant_id,p.park_id,p.employee_id)=(NEW.predecessor_review_id,NEW.tenant_id,NEW.park_id,NEW.employee_id) AND p.status='confirmed')) THEN RAISE EXCEPTION 'employee is outside explicit correction selection';END IF;
 IF c.selected_employee_ids IS NULL AND NEW.predecessor_review_id IS NOT NULL THEN RAISE EXCEPTION 'predecessor requires correction cycle';END IF;
 IF TG_OP='UPDATE' THEN
  IF(NEW.calculation_mode,NEW.predecessor_review_id) IS DISTINCT FROM(OLD.calculation_mode,OLD.predecessor_review_id) THEN RAISE EXCEPTION 'employee mode/correction identity is immutable';END IF;
  IF NEW.current_input_revision_id IS DISTINCT FROM OLD.current_input_revision_id THEN
   SELECT * INTO r FROM hr_performance_channel_input_revision WHERE(id,tenant_id,park_id,cycle_employee_id)=(NEW.current_input_revision_id,NEW.tenant_id,NEW.park_id,NEW.id);
   IF r.id IS NULL OR r.previous_revision_id IS DISTINCT FROM OLD.current_input_revision_id THEN RAISE EXCEPTION 'invalid input successor';END IF;
  END IF;
 END IF;RETURN NEW;
END $$;



--
-- Name: hr_performance_channel_final_ready(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_final_ready(t jsonb, i jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$ SELECT public.hr_performance_channel_stage_complete(t,i,'self_review') AND public.hr_performance_channel_stage_complete(t,i,'manager_review') AND public.hr_performance_channel_stage_complete(t,i,'calibration') $$;



--
-- Name: hr_performance_channel_finite_score(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_finite_score(n numeric) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ SELECT n IS NULL OR (n::text NOT IN('NaN','Infinity','-Infinity') AND scale(n)<=2) $$;



--
-- Name: hr_performance_channel_head_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_head_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM hr_performance_template_version v JOIN hr_performance_channel_definition_revision r ON (r.id,r.tenant_id,r.park_id,r.template_version_id)=(v.channel_definition_revision_id,v.tenant_id,v.park_id,v.id) WHERE (v.id,v.tenant_id,v.park_id)=(NEW.template_version_id,NEW.tenant_id,NEW.park_id) AND r.revision_no>=(SELECT max(h.revision_no) FROM hr_performance_channel_definition_revision h WHERE (h.template_version_id,h.tenant_id,h.park_id)=(v.id,v.tenant_id,v.park_id))) THEN RAISE EXCEPTION 'definition head must advance atomically'; END IF;
 RETURN NULL;
END $$;



--
-- Name: hr_performance_channel_input_head_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_input_head_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM hr_performance_cycle_employee ce JOIN hr_performance_channel_input_revision r ON r.id=ce.current_input_revision_id WHERE(ce.id,ce.tenant_id,ce.park_id)=(NEW.cycle_employee_id,NEW.tenant_id,NEW.park_id) AND r.revision_no=(SELECT max(revision_no) FROM hr_performance_channel_input_revision h WHERE(h.cycle_employee_id,h.tenant_id,h.park_id)=(ce.id,ce.tenant_id,ce.park_id))) THEN RAISE EXCEPTION 'input head must advance atomically';END IF;RETURN NULL;
END $$;



--
-- Name: hr_performance_channel_input_revision_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_input_revision_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE ce record;cycle_row record;previous record;c record;old_cell jsonb;p jsonb;role_name text;permission_name text;actor record;changed integer:=0;source_r public.hr_performance_source_activation_receipt%ROWTYPE;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'channel input revisions are append-only';END IF;
 IF NEW.created_at<transaction_timestamp()-interval '30 seconds' OR NEW.created_at>clock_timestamp()+interval '1 second' THEN RAISE EXCEPTION 'input revision time must be current';END IF;
 SELECT cycle_id INTO ce FROM hr_performance_cycle_employee WHERE(id,tenant_id,park_id)=(NEW.cycle_employee_id,NEW.tenant_id,NEW.park_id);
 SELECT * INTO cycle_row FROM hr_performance_review_cycle WHERE(id,tenant_id,park_id)=(ce.cycle_id,NEW.tenant_id,NEW.park_id) FOR UPDATE;
 SELECT * INTO ce FROM hr_performance_cycle_employee WHERE(id,tenant_id,park_id)=(NEW.cycle_employee_id,NEW.tenant_id,NEW.park_id) FOR UPDATE;
 IF ce.id IS NULL OR ce.calculation_mode<>'five_channel_v1' OR ce.status NOT IN('self_review','manager_review','calibration','appealed') OR ce.current_input_revision_id IS DISTINCT FROM NEW.previous_revision_id OR NOT hr_performance_channel_input_valid(NEW.input,cycle_row.template_snapshot->'channelWorkflow') THEN RAISE EXCEPTION 'invalid or stale channel input revision';END IF;
 IF NEW.source_activation_receipt_id IS NOT NULL THEN
 SELECT * INTO source_r FROM public.hr_performance_source_activation_receipt WHERE(id,tenant_id,park_id)=(NEW.source_activation_receipt_id,NEW.tenant_id,NEW.park_id);
 IF source_r.id IS NULL OR source_r.created_xid IS DISTINCT FROM pg_current_xact_id() OR source_r.mode<>'qualified_source' OR cycle_row.source_activation_receipt_id IS DISTINCT FROM source_r.id OR source_r.review_id<>NEW.cycle_employee_id OR source_r.baseline_revision_id<>NEW.id OR NEW.previous_revision_id IS DISTINCT FROM source_r.initial_revision_id OR NEW.revision_no<>2 OR ce.current_input_revision_id IS DISTINCT FROM source_r.initial_revision_id OR ce.status<>'self_review' OR NEW.created_by IS DISTINCT FROM source_r.created_by OR NEW.created_at IS DISTINCT FROM source_r.created_at OR NEW.input IS DISTINCT FROM public.hr_performance_source_activation_expected_input(source_r.id) OR EXISTS(SELECT 1 FROM public.hr_performance_review_action WHERE cycle_employee_id=ce.id) OR NOT public.hr_performance_channel_workflow_valid(cycle_row.template_snapshot->'channelWorkflow',cycle_row.template_snapshot->'channelDefinition',true) OR NOT public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance:manage') OR NOT public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance_template:manage') THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_BASELINE_INVALID';END IF;
 IF NEW.input->'master'->'salaryReference'->>'state'='VALUE' AND NOT(public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance:read') AND public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance:manage') AND public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:compensation:manage')) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_SALARY_REQUIRED';END IF;
 RETURN NEW;
 END IF;
 SELECT e.* INTO actor FROM hr_employee e WHERE e.tenant_id=NEW.tenant_id AND e.park_id=NEW.park_id AND e.user_id=NEW.created_by AND NOT e.is_deleted ORDER BY e.id LIMIT 1;
 IF NEW.previous_revision_id IS NULL THEN
  IF NOT hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance:manage') THEN RAISE EXCEPTION 'initial input requires cycle management';END IF;
  IF NEW.revision_no<>1 OR EXISTS(SELECT 1 FROM hr_performance_channel_cells(NEW.input) WHERE cell->>'state'<>'UNPROVIDED') THEN RAISE EXCEPTION 'initial input must be unprovided';END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO previous FROM hr_performance_channel_input_revision WHERE(id,tenant_id,park_id,cycle_employee_id)=(NEW.previous_revision_id,NEW.tenant_id,NEW.park_id,NEW.cycle_employee_id);
 IF previous.id IS NULL OR NEW.revision_no<>previous.revision_no+1 THEN RAISE EXCEPTION 'invalid input predecessor';END IF;
 FOR c IN SELECT * FROM hr_performance_channel_cells(NEW.input) LOOP
  SELECT cell INTO old_cell FROM hr_performance_channel_cells(previous.input) prior_cell WHERE prior_cell.detail_id IS NOT DISTINCT FROM c.detail_id AND prior_cell.field=c.field;
  IF c.cell IS NOT DISTINCT FROM old_cell THEN CONTINUE;END IF;changed:=changed+1;
  p:=hr_performance_channel_policy_for(cycle_row.template_snapshot->'channelDefinition',cycle_row.template_snapshot->'channelWorkflow',c.field);
  IF c.cell->>'state'='UNPROVIDED' OR c.cell->>'actorUserId' IS DISTINCT FROM NEW.created_by::text OR (c.cell->>'changedAt')::timestamptz IS DISTINCT FROM NEW.created_at OR (c.cell->>'state'='EXPLICIT_NULL' AND (p->'required'='true'::jsonb OR p->'allowExplicitNull' IS DISTINCT FROM 'true'::jsonb)) THEN RAISE EXCEPTION 'invalid input author or NULL policy';END IF;
  IF ce.status='appealed' THEN
   IF cycle_row.template_snapshot->'channelWorkflow'->'appealReviewAllowed'->c.field IS DISTINCT FROM 'true'::jsonb OR EXISTS(SELECT 1 FROM hr_employee e WHERE(e.id,e.tenant_id,e.park_id)=(ce.employee_id,ce.tenant_id,ce.park_id) AND e.user_id=NEW.created_by) OR NOT EXISTS(SELECT 1 FROM hr_performance_appeal a WHERE(a.cycle_employee_id,a.tenant_id,a.park_id)=(ce.id,ce.tenant_id,ce.park_id) AND a.status='submitted') THEN RAISE EXCEPTION 'appeal field amendment is not allowed';END IF;
  ELSE
   role_name:=CASE ce.status WHEN 'self_review' THEN 'self' WHEN 'manager_review' THEN 'manager' WHEN 'calibration' THEN 'calibrator' END;
   IF p->>'stage' IS DISTINCT FROM ce.status OR NOT p->'allowedActors' ? role_name THEN RAISE EXCEPTION 'field is outside its stage';END IF;
   IF role_name='self' AND actor.id IS DISTINCT FROM ce.employee_id THEN RAISE EXCEPTION 'self field actor mismatch';END IF;
   IF role_name='manager' AND (actor.id=ce.employee_id OR NOT EXISTS(SELECT 1 FROM hr_employee e WHERE(e.id,e.tenant_id,e.park_id)=(ce.employee_id,ce.tenant_id,ce.park_id) AND e.manager_employee_id=actor.id)) THEN RAISE EXCEPTION 'manager field actor mismatch';END IF;
   IF role_name='calibrator' AND (actor.id=ce.employee_id OR NOT EXISTS(SELECT 1 FROM hr_performance_calibration_batch b JOIN hr_performance_calibration_participant p ON(p.batch_id,p.tenant_id,p.park_id)=(b.id,b.tenant_id,b.park_id) WHERE(b.cycle_id,b.tenant_id,b.park_id)=(ce.cycle_id,ce.tenant_id,ce.park_id) AND b.status='active' AND p.participant_user_id=NEW.created_by)) THEN RAISE EXCEPTION 'calibration field actor mismatch';END IF;
  END IF;
  permission_name:=CASE ce.status WHEN 'self_review' THEN 'hr:performance:self_review' WHEN 'manager_review' THEN 'hr:performance:manager_review' WHEN 'calibration' THEN 'hr:performance:calibrate' WHEN 'appealed' THEN 'hr:performance:appeal_review' END;
  IF NOT hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,permission_name) THEN RAISE EXCEPTION 'current performance field permission required';END IF;
  IF c.field='salaryReference' AND NOT(hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance:read') AND hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance:manage') AND hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:compensation:manage')) THEN RAISE EXCEPTION 'salary reference authority required';END IF;
 END LOOP;
 IF changed=0 THEN RAISE EXCEPTION 'input amendment is empty';END IF;RETURN NEW;
END $$;



--
-- Name: hr_performance_channel_input_valid(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_input_valid(i jsonb, w jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE r record;v jsonb;ids text[]:=ARRAY[]::text[];t text;
BEGIN
 IF NOT public.hr_performance_channel_object_v1(i,ARRAY['schemaVersion','details','adjustments','master']) OR i->'schemaVersion' IS DISTINCT FROM '1'::jsonb OR jsonb_typeof(i->'details') IS DISTINCT FROM 'array' OR NOT public.hr_performance_channel_object_v1(i->'adjustments',ARRAY['master','timekeep','bonus']) OR NOT public.hr_performance_channel_object_v1(i->'master',ARRAY['selfAppraisal','appraisal','description','salaryReference']) THEN RETURN false;END IF;
 IF jsonb_array_length(i->'details')<>jsonb_array_length(w->'detailDefinitions') THEN RETURN false;END IF;
 FOR v IN SELECT value FROM jsonb_array_elements(i->'details') LOOP
  IF NOT public.hr_performance_channel_object_v1(v,ARRAY['id','itemId','channels']||CASE WHEN w ? 'detailAppraisalPolicy' THEN ARRAY['appraisal'] ELSE ARRAY[]::text[] END) OR NOT public.hr_performance_channel_object_v1(v->'channels',ARRAY['s','m','t','x','c']) OR v->>'id'=ANY(ids) OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(w->'detailDefinitions') def WHERE def->'id'=v->'id' AND def->'itemId'=v->'itemId') THEN RETURN false;END IF;ids:=array_append(ids,v->>'id');
 END LOOP;
 FOR r IN SELECT * FROM public.hr_performance_channel_cells(i) LOOP
  v:=r.cell;IF NOT public.hr_performance_channel_object_v1(v,ARRAY['state','value','actorUserId','changedAt','evidence']) OR v->>'state' NOT IN('UNPROVIDED','EXPLICIT_NULL','VALUE') OR jsonb_typeof(v->'state')<>'string' THEN RETURN false;END IF;
  IF v->>'state'='UNPROVIDED' THEN IF v IS DISTINCT FROM '{"state":"UNPROVIDED","value":null,"actorUserId":null,"changedAt":null,"evidence":null}'::jsonb THEN RETURN false;END IF;
  ELSE
   IF jsonb_typeof(v->'actorUserId') IS DISTINCT FROM 'string' OR jsonb_typeof(v->'changedAt') IS DISTINCT FROM 'string' OR jsonb_typeof(v->'evidence') IS DISTINCT FROM 'string' OR char_length(v->>'evidence') NOT BETWEEN 2 AND 1000 OR v->>'evidence' !~ '[^[:space:]]' THEN RETURN false;END IF;
   IF v->>'state'='EXPLICIT_NULL' THEN IF v->'value' IS DISTINCT FROM 'null'::jsonb THEN RETURN false;END IF;
   ELSIF r.field IN('selfAppraisal','appraisal','description','detailAppraisal') THEN IF jsonb_typeof(v->'value') IS DISTINCT FROM 'string' OR char_length(v->>'value')>(CASE WHEN r.field='detailAppraisal' THEN 200 ELSE 500 END) OR (r.field='detailAppraisal' AND w->'detailAppraisalPolicy'->'required'='true'::jsonb AND btrim(v->>'value',U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF')='') THEN RETURN false;END IF;
   ELSIF r.field='salaryReference' THEN t:=v->>'value';IF jsonb_typeof(v->'value') IS DISTINCT FROM 'string' OR t !~ '^-?[0-9]+([.][0-9]{1,4})?$' OR length(ltrim(split_part(ltrim(t,'-'),'.',1),'0'))>15 THEN RETURN false;END IF;
   ELSE IF v->'value'='null'::jsonb OR NOT public.hr_performance_channel_scalar_v1(v->'value','decimal') THEN RETURN false;END IF;
   END IF;
  END IF;
 END LOOP;RETURN true;
END $_$;



--
-- Name: hr_performance_channel_object_v1(jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_object_v1(v jsonb, keys text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN jsonb_typeof(v)='object' THEN (SELECT count(*) FROM jsonb_object_keys(v))=cardinality(keys) AND v ?& keys ELSE false END
$$;



--
-- Name: hr_performance_channel_policy_for(jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_policy_for(d jsonb, w jsonb, f text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$ SELECT CASE WHEN f IN('s','m','t','x','c') THEN d->'channels'->f WHEN f IN('master','timekeep','bonus') THEN d->'adjustmentPolicy'->f WHEN f='detailAppraisal' THEN w->'detailAppraisalPolicy' ELSE w->'masterPolicies'->f END $$;



--
-- Name: hr_performance_channel_policy_v1(jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_policy_v1(v jsonb, adjustment boolean) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE keys text[]:=ARRAY['businessName','stage','allowedActors','required','allowExplicitNull'];
BEGIN
 IF adjustment THEN keys:=keys||ARRAY['sourceSwitch','inputMode']; END IF;
 IF NOT public.hr_performance_channel_object_v1(v,keys) THEN RETURN false; END IF;
 IF NOT(public.hr_performance_channel_scalar_v1(v->'businessName','text',120) AND public.hr_performance_channel_scalar_v1(v->'required','bool') AND public.hr_performance_channel_scalar_v1(v->'allowExplicitNull','bool')) THEN RETURN false; END IF;
 IF NOT(v->'stage'='null'::jsonb OR (jsonb_typeof(v->'stage')='string' AND v->>'stage' IN('self_review','manager_review','calibration'))) THEN RETURN false; END IF;
 IF jsonb_typeof(v->'allowedActors') IS DISTINCT FROM 'array' THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(v->'allowedActors') a WHERE jsonb_typeof(a)<>'string' OR a#>>'{}' NOT IN('self','manager','calibrator')) OR (SELECT count(*)<>count(DISTINCT a) FROM jsonb_array_elements(v->'allowedActors') a) THEN RETURN false; END IF;
 IF adjustment AND NOT(public.hr_performance_channel_scalar_v1(v->'sourceSwitch','bool') AND (v->'inputMode'='null'::jsonb OR v->'inputMode'='"manual_with_evidence"'::jsonb)) THEN RETURN false; END IF;
 RETURN true;
END $$;



--
-- Name: hr_performance_channel_revision_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_revision_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v record; p record; prev integer;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'performance definition revisions are append-only'; END IF;
 SELECT * INTO v FROM hr_performance_template_version WHERE (id,tenant_id,park_id)=(NEW.template_version_id,NEW.tenant_id,NEW.park_id);
 SELECT * INTO p FROM hr_performance_template WHERE (id,tenant_id,park_id)=(v.template_id,NEW.tenant_id,NEW.park_id) FOR UPDATE;
 SELECT * INTO v FROM hr_performance_template_version WHERE (id,tenant_id,park_id)=(NEW.template_version_id,NEW.tenant_id,NEW.park_id) FOR UPDATE;
 IF v.id IS NULL OR v.calculation_mode<>'five_channel_v1' OR v.status<>'draft' OR p.status='retired' OR p.current_version_no<>v.version_no THEN RAISE EXCEPTION 'definition requires current channel draft'; END IF;
 IF NEW.previous_revision_id IS NULL THEN
  IF NEW.revision_no<>1 OR v.channel_definition_revision_id<>NEW.id THEN RAISE EXCEPTION 'invalid initial definition'; END IF;
 ELSE
  SELECT revision_no INTO prev FROM hr_performance_channel_definition_revision WHERE (id,tenant_id,park_id,template_version_id)=(NEW.previous_revision_id,NEW.tenant_id,NEW.park_id,NEW.template_version_id);
  IF prev IS NULL OR NEW.revision_no<>prev+1 OR v.channel_definition_revision_id IS DISTINCT FROM NEW.previous_revision_id THEN RAISE EXCEPTION 'stale definition revision'; END IF;
 END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_performance_channel_scalar_v1(jsonb, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_scalar_v1(v jsonb, kind text, lim integer DEFAULT 0) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE t text; n numeric;
BEGIN
 IF v IS NULL THEN RETURN false; END IF;
 IF v='null'::jsonb THEN RETURN true; END IF;
 t:=v#>>'{}';
 IF kind='text' THEN RETURN jsonb_typeof(v)='string' AND char_length(t)<=lim;
 ELSIF kind='bool' THEN RETURN jsonb_typeof(v)='boolean';
 ELSIF kind='order' THEN
  IF jsonb_typeof(v)<>'number' THEN RETURN false; END IF;
  n:=t::numeric; RETURN n=trunc(n) AND n>=-2147483648 AND n<=2147483647;
 ELSIF kind='int' THEN
  IF jsonb_typeof(v)<>'string' OR t !~ '^-?[0-9]+$' THEN RETURN false; END IF;
 ELSIF kind='decimal' THEN
  IF jsonb_typeof(v)<>'string' OR t !~ '^-?[0-9]+([.][0-9]{1,2})?$' THEN RETURN false; END IF;
  RETURN length(ltrim(split_part(ltrim(t,'-'),'.',1),'0'))<=16;
 ELSE RETURN false;
 END IF;
 n:=t::numeric; RETURN n>=-2147483648 AND n<=2147483647;
EXCEPTION WHEN numeric_value_out_of_range THEN RETURN false;
END $_$;



--
-- Name: hr_performance_channel_stage_complete(jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_stage_complete(t jsonb, i jsonb, stage text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 SELECT NOT EXISTS(SELECT 1 FROM public.hr_performance_channel_cells(i) c CROSS JOIN LATERAL(SELECT public.hr_performance_channel_policy_for(t->'channelDefinition',t->'channelWorkflow',c.field) p) x WHERE p->>'stage'=stage AND ((c.field NOT IN('selfAppraisal','appraisal','description','salaryReference','detailAppraisal') AND c.cell->>'state'='UNPROVIDED') OR (p->'required'='true'::jsonb AND(c.cell->>'state'<>'VALUE' OR(c.field IN('selfAppraisal','appraisal','description','detailAppraisal') AND (CASE WHEN c.field='detailAppraisal' THEN btrim(c.cell->>'value',U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF')='' ELSE c.cell->>'value' !~ '[^[:space:]]' END)))) OR (c.cell->>'state'='EXPLICIT_NULL' AND p->'allowExplicitNull'<>'true'::jsonb)))
$$;



--
-- Name: hr_performance_channel_version_pair_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_version_pair_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
 IF NEW.channel_workflow_revision_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM hr_performance_template_version v JOIN hr_performance_channel_workflow_revision w ON w.id=v.channel_workflow_revision_id WHERE(v.id,v.tenant_id,v.park_id)=(NEW.id,NEW.tenant_id,NEW.park_id) AND w.definition_revision_id=v.channel_definition_revision_id) THEN RAISE EXCEPTION 'definition and workflow revisions must advance together';END IF;RETURN NULL;
END $$;



--
-- Name: hr_performance_channel_workflow_head_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_workflow_head_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM hr_performance_template_version v JOIN hr_performance_channel_workflow_revision r ON r.id=v.channel_workflow_revision_id WHERE(v.id,v.tenant_id,v.park_id)=(NEW.template_version_id,NEW.tenant_id,NEW.park_id) AND r.definition_revision_id=v.channel_definition_revision_id AND r.revision_no=(SELECT max(revision_no) FROM hr_performance_channel_workflow_revision h WHERE(h.template_version_id,h.tenant_id,h.park_id)=(v.id,v.tenant_id,v.park_id))) THEN RAISE EXCEPTION 'workflow head must advance atomically';END IF;RETURN NULL;
END $$;



--
-- Name: hr_performance_channel_workflow_revision_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_workflow_revision_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v record;par record;d jsonb;n integer;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'workflow revisions are append-only';END IF;
 IF NOT hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance_template:manage') THEN RAISE EXCEPTION 'workflow revision requires current template management';END IF;
 SELECT * INTO v FROM hr_performance_template_version WHERE(id,tenant_id,park_id)=(NEW.template_version_id,NEW.tenant_id,NEW.park_id);
 SELECT * INTO par FROM hr_performance_template WHERE(id,tenant_id,park_id)=(v.template_id,NEW.tenant_id,NEW.park_id) FOR UPDATE;
 SELECT * INTO v FROM hr_performance_template_version WHERE(id,tenant_id,park_id)=(NEW.template_version_id,NEW.tenant_id,NEW.park_id) FOR UPDATE;
 IF v.id IS NULL OR v.status<>'draft' OR v.calculation_mode<>'five_channel_v1' OR par.status='retired' OR par.current_version_no<>v.version_no OR v.channel_definition_revision_id<>NEW.definition_revision_id OR v.channel_workflow_revision_id IS DISTINCT FROM NEW.previous_revision_id THEN RAISE EXCEPTION 'stale workflow definition';END IF;
 SELECT config INTO d FROM hr_performance_channel_definition_revision WHERE id=NEW.definition_revision_id;
 IF NOT hr_performance_channel_workflow_valid(NEW.policy,d,false) THEN RAISE EXCEPTION 'invalid workflow policy';END IF;
 IF NEW.previous_revision_id IS NULL THEN n:=0;ELSE SELECT revision_no INTO n FROM hr_performance_channel_workflow_revision WHERE(id,tenant_id,park_id,template_version_id)=(NEW.previous_revision_id,NEW.tenant_id,NEW.park_id,NEW.template_version_id);END IF;
 IF n IS NULL OR NEW.revision_no<>n+1 THEN RAISE EXCEPTION 'invalid workflow predecessor';END IF;RETURN NEW;
END $$;



--
-- Name: hr_performance_channel_workflow_valid(jsonb, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_channel_workflow_valid(p jsonb, d jsonb, publish boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE x jsonb;k text;v jsonb;seen text[]:=ARRAY[]::text[];actor text;extended boolean:=p ? 'detailAppraisalPolicy';fields text[]:=ARRAY['s','m','t','x','c','master','timekeep','bonus','selfAppraisal','appraisal','description','salaryReference'];
BEGIN
 IF extended THEN fields:=array_append(fields,'detailAppraisal');END IF;
 IF NOT public.hr_performance_channel_object_v1(p,ARRAY['schemaVersion','detailDefinitions','masterPolicies','appealReviewAllowed']||CASE WHEN extended THEN ARRAY['detailAppraisalPolicy'] ELSE ARRAY[]::text[] END) OR p->'schemaVersion' IS DISTINCT FROM '1'::jsonb OR jsonb_typeof(p->'detailDefinitions') IS DISTINCT FROM 'array' OR NOT public.hr_performance_channel_config_valid_v1(d) THEN RETURN false;END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(p->'detailDefinitions') LOOP
  IF NOT public.hr_performance_channel_object_v1(x,ARRAY['id','itemId']) OR jsonb_typeof(x->'id') IS DISTINCT FROM 'string' OR char_length(x->>'id') NOT BETWEEN 1 AND 128 OR x->>'id'=ANY(seen) OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(d->'items') a WHERE a->'id'=x->'itemId') THEN RETURN false;END IF;seen:=array_append(seen,x->>'id');
 END LOOP;
 IF NOT public.hr_performance_channel_object_v1(p->'masterPolicies',ARRAY['selfAppraisal','appraisal','description','salaryReference']) OR NOT public.hr_performance_channel_object_v1(p->'appealReviewAllowed',fields) THEN RETURN false;END IF;
 FOR v IN SELECT value FROM jsonb_each(p->'appealReviewAllowed') LOOP IF NOT public.hr_performance_channel_scalar_v1(v,'bool') OR (publish AND v='null'::jsonb) THEN RETURN false;END IF;END LOOP;
 FOR k,v IN SELECT key,value FROM jsonb_each(p->'masterPolicies') UNION ALL SELECT 'detailAppraisal',p->'detailAppraisalPolicy' WHERE extended LOOP
  IF NOT public.hr_performance_channel_object_v1(v,ARRAY['stage','allowedActors','required','allowExplicitNull']) OR NOT public.hr_performance_channel_policy_v1(v||'{"businessName":null}'::jsonb,false) THEN RETURN false;END IF;
 END LOOP;
 IF publish THEN
  IF cardinality(seen)=0 OR jsonb_array_length(d->'items')=0 OR jsonb_array_length(d->'gradeCandidates')=0 THEN RETURN false;END IF;
  FOR v IN SELECT value FROM jsonb_each(d->'channels') UNION ALL SELECT value FROM jsonb_each(d->'adjustmentPolicy') UNION ALL SELECT value FROM jsonb_each(p->'masterPolicies') UNION ALL SELECT p->'detailAppraisalPolicy' WHERE extended LOOP
   actor:=CASE v->>'stage' WHEN 'self_review' THEN 'self' WHEN 'manager_review' THEN 'manager' WHEN 'calibration' THEN 'calibrator' END;
   IF actor IS NULL OR NOT v->'allowedActors' ? actor OR jsonb_typeof(v->'required') IS DISTINCT FROM 'boolean' OR jsonb_typeof(v->'allowExplicitNull') IS DISTINCT FROM 'boolean' OR (v->'required'='true'::jsonb AND v->'allowExplicitNull'='true'::jsonb) THEN RETURN false;END IF;
  END LOOP;
  IF EXISTS(SELECT 1 FROM jsonb_each(d->'adjustmentPolicy') a WHERE a.value->>'inputMode' IS DISTINCT FROM 'manual_with_evidence') THEN RETURN false;END IF;
 END IF;
 RETURN true;
END $$;



--
-- Name: hr_performance_child_freeze_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_child_freeze_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ DECLARE r record; published boolean;BEGIN r:=CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;SELECT v.status='published' INTO published FROM hr_performance_template_version v WHERE v.id=r.template_version_id AND v.tenant_id=r.tenant_id AND v.park_id=r.park_id FOR SHARE;IF COALESCE(published,false) THEN RAISE EXCEPTION 'published performance configuration is immutable'; END IF; RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END $$;



--
-- Name: hr_performance_cycle_employee_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_cycle_employee_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ DECLARE r record; cycle_status varchar(24);BEGIN
 r:=CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
 SELECT status INTO cycle_status FROM hr_performance_review_cycle WHERE id=r.cycle_id AND tenant_id=r.tenant_id AND park_id=r.park_id FOR SHARE;
 IF TG_OP='INSERT' AND cycle_status<>'planning' THEN RAISE EXCEPTION 'published performance cycle employees are frozen'; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'performance cycle employee is immutable'; END IF;
 IF TG_OP='UPDATE' AND (NEW.tenant_id,NEW.park_id,NEW.cycle_id,NEW.employee_id,NEW.employee_snapshot,NEW.goal_snapshot,NEW.create_time) IS DISTINCT FROM (OLD.tenant_id,OLD.park_id,OLD.cycle_id,OLD.employee_id,OLD.employee_snapshot,OLD.goal_snapshot,OLD.create_time) THEN RAISE EXCEPTION 'performance cycle employee snapshot is immutable'; END IF;
 IF TG_OP='UPDATE' AND NEW.status IS DISTINCT FROM OLD.status AND NOT ((OLD.status='planning' AND NEW.status='self_review') OR (OLD.status='self_review' AND NEW.status='manager_review') OR (OLD.status='manager_review' AND NEW.status='calibration') OR (OLD.status='calibration' AND NEW.status='employee_acknowledged') OR (OLD.status='employee_acknowledged' AND NEW.status IN('appealed','confirmed')) OR (OLD.status='appealed' AND NEW.status='confirmed')) THEN RAISE EXCEPTION 'invalid performance employee transition'; END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;



--
-- Name: hr_performance_cycle_employee_result_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_cycle_employee_result_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ DECLARE template jsonb; scores jsonb; expected numeric; expected_level record; channel_template jsonb;channel_input jsonb;channel_result jsonb;channel_action record;channel_sub record; BEGIN
 IF OLD.calculation_mode='five_channel_v1' THEN
  IF OLD.status='confirmed' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'confirmed performance result is immutable';END IF;
  SELECT template_snapshot INTO channel_template FROM hr_performance_review_cycle WHERE(id,tenant_id,park_id)=(NEW.cycle_id,NEW.tenant_id,NEW.park_id) FOR SHARE;
  IF NEW.self_score IS DISTINCT FROM OLD.self_score OR (OLD.status='self_review' AND NEW.status='manager_review') THEN
   SELECT * INTO channel_sub FROM hr_performance_review_submission WHERE(tenant_id,park_id,cycle_employee_id)=(NEW.tenant_id,NEW.park_id,NEW.id) AND submission_type='self' ORDER BY submission_no DESC LIMIT 1;
   IF channel_sub.id IS NULL OR NEW.self_score IS DISTINCT FROM channel_sub.computed_score THEN RAISE EXCEPTION 'self score requires submission evidence';END IF;
  END IF;
  IF NEW.manager_score IS DISTINCT FROM OLD.manager_score OR(OLD.status='manager_review' AND NEW.status='calibration') THEN
   SELECT * INTO channel_sub FROM hr_performance_review_submission WHERE(tenant_id,park_id,cycle_employee_id)=(NEW.tenant_id,NEW.park_id,NEW.id) AND submission_type='manager' ORDER BY submission_no DESC LIMIT 1;
   IF channel_sub.id IS NULL OR NEW.manager_score IS DISTINCT FROM channel_sub.computed_score THEN RAISE EXCEPTION 'manager score requires submission evidence';END IF;
  END IF;
  IF NEW.calibrated_score IS DISTINCT FROM OLD.calibrated_score AND NEW.status='calibration' AND NOT EXISTS(SELECT 1 FROM hr_performance_calibration_entry e WHERE(e.cycle_employee_id,e.tenant_id,e.park_id)=(NEW.id,NEW.tenant_id,NEW.park_id) AND e.input_revision_id=NEW.current_input_revision_id AND e.after_score IS NOT DISTINCT FROM NEW.calibrated_score) THEN RAISE EXCEPTION 'calibrated score requires current entry evidence';END IF;
  IF OLD.status='calibration' AND NEW.status='employee_acknowledged' AND NEW.calibrated_score IS DISTINCT FROM NEW.final_score THEN RAISE EXCEPTION 'final calibration score mismatch';END IF;
  IF NEW.status IN('self_review','manager_review','calibration') AND (NEW.final_score IS NOT NULL OR NEW.final_input_revision_id IS NOT NULL OR NEW.final_grade_evidence IS NOT NULL) THEN RAISE EXCEPTION 'channel result cannot finalize early';END IF;
  IF OLD.status='employee_acknowledged' AND NEW.status IN('appealed','confirmed') THEN
   SELECT * INTO channel_action FROM hr_performance_review_action WHERE(tenant_id,park_id,cycle_employee_id)=(NEW.tenant_id,NEW.park_id,NEW.id) AND action_type=CASE NEW.status WHEN 'appealed' THEN 'appealed' ELSE 'acknowledged' END ORDER BY action_no DESC LIMIT 1;
   IF channel_action.id IS NULL OR (NEW.status='confirmed' AND(NEW.acknowledged_at IS NULL OR NEW.confirmed_at IS NULL)) THEN RAISE EXCEPTION 'employee acknowledgement/appeal evidence required';END IF;
  END IF;
  IF NEW.status IN('employee_acknowledged','appealed','confirmed') THEN
   IF NEW.final_input_revision_id IS NULL OR NEW.final_score IS NULL OR NEW.final_grade_evidence IS NULL THEN RAISE EXCEPTION 'channel final evidence is required';END IF;
   SELECT input INTO channel_input FROM hr_performance_channel_input_revision WHERE(id,tenant_id,park_id,cycle_employee_id)=(NEW.final_input_revision_id,NEW.tenant_id,NEW.park_id,NEW.id);
   channel_result:=hr_performance_channel_calculate(channel_template,channel_input,NEW.final_input_revision_id);
   IF NOT hr_performance_channel_final_ready(channel_template,channel_input) OR channel_result->'complete' IS DISTINCT FROM 'true'::jsonb OR channel_result->'grade'->>'status' IS DISTINCT FROM 'RESOLVED' OR NEW.final_score IS DISTINCT FROM(channel_result->>'score')::numeric OR NEW.final_level_code IS DISTINCT FROM channel_result->>'levelCode' OR NEW.final_level_name IS DISTINCT FROM channel_result->>'levelName' OR NEW.final_grade_evidence IS DISTINCT FROM channel_result THEN RAISE EXCEPTION 'channel final result is not reproducible';END IF;
   IF OLD.status='calibration' OR (OLD.status='appealed' AND NEW.status='confirmed') THEN
    SELECT * INTO channel_action FROM hr_performance_review_action WHERE(tenant_id,park_id,cycle_employee_id)=(NEW.tenant_id,NEW.park_id,NEW.id) AND action_type IN('result_finalized','appeal_upheld','appeal_rejected') ORDER BY action_no DESC LIMIT 1;
    IF channel_action.id IS NULL OR channel_action.input_revision_id IS DISTINCT FROM NEW.final_input_revision_id OR channel_action.result_snapshot IS DISTINCT FROM channel_result OR channel_action.actor_user_id IS NULL OR EXISTS(SELECT 1 FROM hr_employee e WHERE e.id=NEW.employee_id AND e.user_id=channel_action.actor_user_id) THEN RAISE EXCEPTION 'channel final action evidence required';END IF;
    IF NOT hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,channel_action.actor_user_id,CASE WHEN OLD.status='appealed' THEN 'hr:performance:appeal_review' ELSE 'hr:performance:calibrate' END) THEN RAISE EXCEPTION 'channel final permission required';END IF;
    IF channel_action.action_type='appeal_rejected' AND(NEW.final_input_revision_id,NEW.final_score,NEW.final_grade_evidence) IS DISTINCT FROM(OLD.final_input_revision_id,OLD.final_score,OLD.final_grade_evidence) THEN RAISE EXCEPTION 'rejected appeal must preserve result';END IF;
   ELSIF(NEW.final_input_revision_id,NEW.final_score,NEW.final_grade_evidence,NEW.final_level_code,NEW.final_level_name) IS DISTINCT FROM(OLD.final_input_revision_id,OLD.final_score,OLD.final_grade_evidence,OLD.final_level_code,OLD.final_level_name) THEN RAISE EXCEPTION 'result amendment requires calibration or appeal decision';END IF;
  END IF;
  RETURN NEW;
 END IF;


 IF OLD.status='confirmed' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'confirmed performance result is immutable'; END IF;
 IF NEW.status IN('self_review','manager_review','calibration') AND (NEW.final_score IS NOT NULL OR NEW.final_level_code IS NOT NULL OR NEW.result_finalized_at IS NOT NULL) THEN RAISE EXCEPTION 'performance result cannot be finalized before calibration'; END IF;
 IF NEW.status IN('employee_acknowledged','appealed','confirmed') AND NEW.final_score IS NULL THEN RAISE EXCEPTION 'performance result is required after calibration'; END IF;
 IF NEW.final_score IS NOT NULL AND (OLD.final_score IS NULL OR NEW.final_score IS DISTINCT FROM OLD.final_score OR NEW.final_level_code IS DISTINCT FROM OLD.final_level_code) THEN
  SELECT template_snapshot INTO template FROM hr_performance_review_cycle WHERE id=NEW.cycle_id AND tenant_id=NEW.tenant_id AND park_id=NEW.park_id FOR SHARE;
  IF OLD.status='appealed' AND NEW.status='confirmed' THEN
   SELECT CASE WHEN action_type='appeal_upheld' THEN result_snapshot->'dimensionScores' ELSE NULL END INTO scores FROM hr_performance_review_action WHERE tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND cycle_employee_id=NEW.id AND action_type IN('appeal_upheld','appeal_rejected') ORDER BY action_no DESC LIMIT 1;
   IF scores IS NULL THEN expected:=OLD.final_score;ELSE expected:=hr_performance_snapshot_score(template,scores);END IF;
  ELSE
   SELECT dimension_scores INTO scores FROM hr_performance_calibration_entry WHERE tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND cycle_employee_id=NEW.id ORDER BY create_time DESC,id DESC LIMIT 1;
   IF scores IS NULL THEN SELECT dimension_scores INTO scores FROM hr_performance_review_submission WHERE tenant_id=NEW.tenant_id AND park_id=NEW.park_id AND cycle_employee_id=NEW.id AND submission_type='manager' ORDER BY submission_no DESC LIMIT 1;END IF;
   IF scores IS NULL THEN RAISE EXCEPTION 'performance final result has no frozen score evidence';END IF;
   expected:=hr_performance_snapshot_score(template,scores);
  END IF;
  SELECT value->>'code' code,value->>'name' name INTO expected_level FROM jsonb_array_elements(template->'levels') WHERE expected>=(value->>'scoreMin')::numeric AND expected<=(value->>'scoreMax')::numeric ORDER BY (value->>'scoreMin')::numeric DESC LIMIT 1;
  IF NEW.final_score<>expected OR expected_level.code IS NULL OR NEW.final_level_code<>expected_level.code OR NEW.final_level_name<>expected_level.name THEN RAISE EXCEPTION 'performance final result is not reproducible';END IF;
 END IF;
 RETURN NEW;END $$;



--
-- Name: hr_performance_cycle_freeze_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_cycle_freeze_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'performance cycle is immutable'; END IF;
 IF (NEW.tenant_id,NEW.park_id,NEW.id,NEW.cycle_code,NEW.create_by,NEW.create_time) IS DISTINCT FROM (OLD.tenant_id,OLD.park_id,OLD.id,OLD.cycle_code,OLD.create_by,OLD.create_time) THEN RAISE EXCEPTION 'performance cycle identity is immutable'; END IF;
 IF OLD.status<>'planning' AND (NEW.template_version_id,NEW.template_snapshot,NEW.applicable_org_ids,NEW.start_date,NEW.end_date) IS DISTINCT FROM (OLD.template_version_id,OLD.template_snapshot,OLD.applicable_org_ids,OLD.start_date,OLD.end_date) THEN RAISE EXCEPTION 'published performance cycle snapshot is immutable'; END IF;
 IF NEW.status IS DISTINCT FROM OLD.status AND NOT ((OLD.status='planning' AND NEW.status='self_review') OR (OLD.status='self_review' AND NEW.status='manager_review') OR (OLD.status='manager_review' AND NEW.status='calibration') OR (OLD.status='calibration' AND NEW.status='employee_acknowledged') OR (OLD.status='employee_acknowledged' AND NEW.status IN('appealed','confirmed')) OR (OLD.status='appealed' AND NEW.status='confirmed')) THEN RAISE EXCEPTION 'invalid performance cycle transition'; END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_performance_evidence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ DECLARE r record; cycle_status varchar(20);BEGIN
 r:=CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
 IF TG_OP='UPDATE' OR TG_OP='DELETE' THEN RAISE EXCEPTION 'performance evidence is append-only'; END IF;
 SELECT c.status INTO cycle_status FROM hr_performance_cycle_employee ce JOIN hr_performance_review_cycle c ON c.id=ce.cycle_id AND c.tenant_id=ce.tenant_id AND c.park_id=ce.park_id WHERE ce.id=r.cycle_employee_id AND ce.tenant_id=r.tenant_id AND ce.park_id=r.park_id FOR SHARE OF c;
 IF cycle_status<>'planning' THEN RAISE EXCEPTION 'published performance evidence is frozen'; END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_performance_five_channel_snapshot_total_v1(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_five_channel_snapshot_total_v1(p_weights jsonb, p_details jsonb, p_adjustments jsonb) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  weight_keys constant text[] := ARRAY['sPercent','mPercent','tPercent','xPercent','cPercent'];
  value_keys constant text[] := ARRAY['selfValue','mItemValue','itemValue','xItemValue','cItemValue'];
  adjustment_keys constant text[] := ARRAY['masterValue','timekeepValue','bonusValue'];
  weights numeric[] := ARRAY[0,0,0,0,0]::numeric[];
  sums numeric[] := ARRAY[0,0,0,0,0]::numeric[];
  adjustment numeric := 0;
  row_value jsonb;
  field_value jsonb;
  key_name text;
  i integer;
  parsed numeric;
BEGIN
  IF jsonb_typeof(p_weights) IS DISTINCT FROM 'object'
     OR NOT p_weights ?& weight_keys OR p_weights - weight_keys <> '{}'::jsonb
     OR jsonb_typeof(p_adjustments) IS DISTINCT FROM 'object'
     OR NOT p_adjustments ?& adjustment_keys OR p_adjustments - adjustment_keys <> '{}'::jsonb
     OR jsonb_typeof(p_details) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Invalid channel snapshot shape';
  END IF;
  FOR i IN 1..5 LOOP
    field_value := p_weights -> weight_keys[i];
    IF field_value <> 'null'::jsonb THEN
      IF jsonb_typeof(field_value) <> 'string' OR (field_value #>> '{}') !~ '^-?[0-9]+$' THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Invalid channel weight';
      END IF;
      weights[i] := (field_value #>> '{}')::integer;
    END IF;
  END LOOP;
  FOREACH key_name IN ARRAY adjustment_keys LOOP
    field_value := p_adjustments -> key_name;
    IF field_value <> 'null'::jsonb THEN
      IF jsonb_typeof(field_value) <> 'string' OR (field_value #>> '{}') !~ '^-?[0-9]+([.][0-9]{1,2})?$' THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Invalid channel adjustment';
      END IF;
      adjustment := adjustment + (field_value #>> '{}')::numeric(18,2);
    END IF;
  END LOOP;
  FOR row_value IN SELECT value FROM jsonb_array_elements(p_details) LOOP
    IF jsonb_typeof(row_value) IS DISTINCT FROM 'object'
       OR NOT row_value ?& (value_keys || ARRAY['id'])
       OR row_value - (value_keys || ARRAY['id']) <> '{}'::jsonb
       OR jsonb_typeof(row_value -> 'id') IS DISTINCT FROM 'string'
       OR length(row_value ->> 'id') NOT BETWEEN 1 AND 128 THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Invalid channel detail';
    END IF;
    FOR i IN 1..5 LOOP
      field_value := row_value -> value_keys[i];
      IF field_value <> 'null'::jsonb THEN
        IF jsonb_typeof(field_value) <> 'string' OR (field_value #>> '{}') !~ '^-?[0-9]+([.][0-9]{1,2})?$' THEN
          RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Invalid channel detail value';
        END IF;
        parsed := (field_value #>> '{}')::numeric(18,2);
        sums[i] := sums[i] + parsed;
      END IF;
    END LOOP;
  END LOOP;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_details) GROUP BY value ->> 'id' HAVING count(*) > 1) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Duplicate channel detail identity';
  END IF;
  IF jsonb_array_length(p_details)=0 THEN RETURN NULL; END IF;
  -- Cast the COMPLETE M/X/C sums even when the corresponding weight is zero.
  sums[2] := sums[2]::numeric(18,0);
  sums[4] := sums[4]::numeric(18,0);
  sums[5] := sums[5]::numeric(18,0);
  RETURN round(sums[1]*weights[1]/100::numeric + sums[2]*weights[2]/100::numeric
    + sums[3]*weights[3]/100::numeric + sums[4]*weights[4]/100::numeric
    + sums[5]*weights[5]/100::numeric + adjustment,2);
EXCEPTION WHEN numeric_value_out_of_range THEN
  RAISE EXCEPTION USING ERRCODE='22003', MESSAGE='Channel snapshot numeric range exceeded';
END
$_$;



