CREATE FUNCTION public.hr_performance_freeze_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN RAISE EXCEPTION 'published performance configuration is immutable'; END $$;



--
-- Name: hr_performance_participant_insert_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_participant_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE batch_status varchar(16);BEGIN SELECT status INTO batch_status FROM hr_performance_calibration_batch WHERE id=NEW.batch_id AND tenant_id=NEW.tenant_id AND park_id=NEW.park_id FOR UPDATE;IF batch_status IS DISTINCT FROM 'draft' THEN RAISE EXCEPTION 'calibration participants are frozen after activation';END IF;RETURN NEW;END $$;



--
-- Name: hr_performance_snapshot_score(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_snapshot_score(p_template jsonb, p_scores jsonb) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE d jsonb; total numeric:=0; supplied numeric; seen integer:=0;
BEGIN
 IF jsonb_typeof(p_template->'dimensions')<>'array' OR jsonb_typeof(p_scores)<>'object' THEN RAISE EXCEPTION 'invalid performance score payload'; END IF;
 FOR d IN SELECT value FROM jsonb_array_elements(p_template->'dimensions') LOOP
  IF NOT p_scores ? (d->>'code') THEN RAISE EXCEPTION 'missing dimension score'; END IF;
  supplied:=(p_scores->>(d->>'code'))::numeric;
  IF supplied<(d->>'scoreMin')::numeric OR supplied>(d->>'scoreMax')::numeric THEN RAISE EXCEPTION 'dimension score outside frozen range'; END IF;
  total:=total+supplied*(d->>'weight')::numeric; seen:=seen+1;
 END LOOP;
 IF seen=0 OR (SELECT count(*) FROM jsonb_object_keys(p_scores))<>seen THEN RAISE EXCEPTION 'unknown dimension score'; END IF;
 RETURN round(total,2);
END $$;



--
-- Name: hr_performance_source_activation_build_input(jsonb, jsonb, jsonb, uuid, uuid, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_source_activation_build_input(content jsonb, workflow jsonb, mapping jsonb, master_id uuid, actor uuid, at timestamp with time zone, rid uuid) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
WITH facts AS(SELECT f FROM jsonb_array_elements(content->'facts') f),master AS(SELECT f FROM facts WHERE f->>'family'='master_result' AND f->>'sourceFactId'=master_id::text),details AS(
 SELECT m.value map,f.f FROM jsonb_array_elements(mapping->'details') m JOIN facts f ON f.f->>'family'='dimension_result' AND f.f->>'identitySha256'=m.value->>'sourceIdentitySha256'
),detail_inputs AS(
 SELECT map->>'sourceIdentitySha256' identity,jsonb_build_object('id',map->'detailId','itemId',map->'itemId','channels',(SELECT jsonb_object_agg(c.field,public.hr_performance_source_activation_cell(f->'values'->c.source,actor,at,'source-activation:'||rid||':dimension_result:'||(map->>'sourceIdentitySha256')||':'||c.field)) FROM(VALUES('s','source_self_value'),('m','source_m_item_value'),('t','source_item_value'),('x','source_x_item_value'),('c','source_c_item_value'))c(field,source))) || CASE WHEN workflow ? 'detailAppraisalPolicy' THEN jsonb_build_object('appraisal',public.hr_performance_source_activation_cell(f->'values'->'source_appraisal',actor,at,'source-activation:'||rid||':dimension_result:'||(map->>'sourceIdentitySha256')||':detailAppraisal')) ELSE '{}'::jsonb END value FROM details
)
SELECT jsonb_build_object('schemaVersion',1,'details',COALESCE((SELECT jsonb_agg(value ORDER BY identity COLLATE "C") FROM detail_inputs),'[]'::jsonb),'adjustments',(SELECT jsonb_object_agg(c.field,public.hr_performance_source_activation_cell((SELECT f->'values'->c.source FROM master),actor,at,'source-activation:'||rid||':master_result:'||COALESCE((SELECT f->>'identitySha256' FROM master),'')||':'||c.field)) FROM(VALUES('master','source_master_value'),('timekeep','source_timekeep_value'),('bonus','source_bonus_value'))c(field,source)),'master',(SELECT jsonb_object_agg(c.field,public.hr_performance_source_activation_cell((SELECT f->'values'->c.source FROM master),actor,at,'source-activation:'||rid||':master_result:'||COALESCE((SELECT f->>'identitySha256' FROM master),'')||':'||c.field)) FROM(VALUES('selfAppraisal','source_self_appraisal'),('appraisal','source_appraisal'),('description','source_description'),('salaryReference','source_pay'))c(field,source)))
$$;



--
-- Name: hr_performance_source_activation_cell(jsonb, uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_source_activation_cell(v jsonb, actor uuid, at timestamp with time zone, evidence text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
SELECT CASE WHEN v IS NULL OR v='null'::jsonb THEN '{"state":"UNPROVIDED","value":null,"actorUserId":null,"changedAt":null,"evidence":null}'::jsonb ELSE jsonb_build_object('state','VALUE','value',v,'actorUserId',actor,'changedAt',at,'evidence',evidence) END
$$;



--
-- Name: hr_performance_source_activation_derive_definition(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_source_activation_derive_definition(content jsonb, mapping jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
WITH facts AS(SELECT f FROM jsonb_array_elements(content->'facts') f),profile AS(SELECT f->'values' v FROM facts WHERE f->>'family'='template_profile' AND f->'identitySha256'=mapping->'profileIdentitySha256'),policy AS(SELECT '{"businessName":null,"stage":null,"allowedActors":[],"required":null,"allowExplicitNull":null}'::jsonb p),
items AS(SELECT m map,f->'values' v FROM jsonb_array_elements(mapping->'items') m JOIN facts ON f->>'family'='dimension_profile' AND f->'identitySha256'=m->'sourceIdentitySha256'),
guides AS(SELECT m map,f->'values' v FROM jsonb_array_elements(mapping->'guides') m JOIN facts ON f->>'family'='dimension_level_guide' AND f->'identitySha256'=m->'sourceIdentitySha256'),
grades AS(SELECT m map,f->'values' v FROM jsonb_array_elements(mapping->'grades') m JOIN facts ON f->>'family'='level_rule' AND f->'identitySha256'=m->'sourceIdentitySha256')
SELECT jsonb_build_object('schemaVersion',1,'displayName',v->'source_assessment_name','departmentLabel',v->'source_department','weights',jsonb_build_object('sPercent',v->'source_s_percent','mPercent',v->'source_m_percent','tPercent',v->'source_t_percent','xPercent',v->'source_x_percent','cPercent',v->'source_c_percent'),'channels',(SELECT jsonb_object_agg(k,policy.p) FROM unnest(ARRAY['s','m','t','x','c'])k CROSS JOIN policy),'adjustmentPolicy',(SELECT jsonb_object_agg(k,policy.p||jsonb_build_object('sourceSwitch',v->('source_'||k),'inputMode',NULL)) FROM unnest(ARRAY['master','timekeep','bonus'])k CROSS JOIN policy),
'items',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',i.map->'itemId','name',i.v->'source_item_name','fullValue',i.v->'source_full_value','order',(i.v->>'source_my_order')::int,'sourceAssessmentRef',i.v->'source_assessment_id','guides',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',g.map->'guideId','grade',g.v->'source_grade','description',g.v->'source_description','minValue',g.v->'source_min_value','maxValue',g.v->'source_max_value','order',(g.v->>'source_my_order')::int) ORDER BY g.map->>'sourceIdentitySha256' COLLATE "C") FROM guides g WHERE g.map->'itemId'=i.map->'itemId'),'[]'::jsonb)) ORDER BY i.map->>'sourceIdentitySha256' COLLATE "C") FROM items i),'[]'::jsonb),
'gradeCandidates',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',map->'gradeId','code',v->'source_ass_grade','description',v->'source_description','sourceOrderText',v->'source_my_order','sourceAssessmentRef',v->'source_assessment_id','minValue',v->'source_min_value','maxValue',v->'source_max_value') ORDER BY map->>'sourceIdentitySha256' COLLATE "C") FROM grades),'[]'::jsonb)) FROM profile
$$;



--
-- Name: hr_performance_source_activation_differences(character varying, character varying, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_source_activation_differences(t character varying, p character varying, draft uuid, revision uuid, profile_identity text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
WITH selected AS(SELECT r.snapshot,m.content FROM public.hr_performance_source_draft_revision r JOIN public.hr_performance_source_manifest m ON m.id=r.manifest_id WHERE(r.id,r.tenant_id,r.park_id,r.draft_id)=(revision,t,p,draft)),
proposal AS(SELECT public.hr_performance_source_activation_derive_definition(s.content,public.hr_performance_source_activation_mapping(t,p,draft,revision,profile_identity,false)) value FROM selected s),
changes AS(SELECT jsonb_build_object('family',a->'family','sourceFactId',a->'sourceFactId','field',kv.key,'originalValue',o->'values'->kv.key,'currentValue',kv.value) value FROM selected s CROSS JOIN LATERAL jsonb_array_elements(s.snapshot->'records')a JOIN LATERAL jsonb_array_elements(s.content->'facts')o ON(o->'family',o->'sourceFactId')=(a->'family',a->'sourceFactId') CROSS JOIN LATERAL jsonb_each(a->'values')kv WHERE a->>'family' IN('dimension_result','master_result') AND kv.key IN('source_self_value','source_m_item_value','source_item_value','source_x_item_value','source_c_item_value','source_appraisal','source_master_value','source_timekeep_value','source_bonus_value','source_self_appraisal','source_description','source_pay') AND kv.value IS DISTINCT FROM o->'values'->kv.key),
definition_fields AS(SELECT COALESCE(jsonb_agg('definition.'||kv.key ORDER BY kv.key COLLATE "C"),'[]'::jsonb) fields FROM selected s,proposal p CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(s.snapshot->'definition')='object' THEN s.snapshot->'definition' ELSE '{}'::jsonb END)kv WHERE kv.value IS DISTINCT FROM p.value->kv.key),
pending AS(SELECT COALESCE(jsonb_agg(value ORDER BY value->>'family' COLLATE "C",value->>'sourceFactId' COLLATE "C",value->>'field' COLLATE "C"),'[]'::jsonb) changes FROM changes),
result AS(SELECT jsonb_build_object('sha256',encode(sha256(convert_to(f.fields::text,'UTF8')),'hex'),'count',jsonb_array_length(f.fields),'fields',f.fields) definition,jsonb_build_object('sha256',encode(sha256(convert_to(p.changes::text,'UTF8')),'hex'),'count',jsonb_array_length(p.changes),'changes',p.changes) pending,s.snapshot FROM definition_fields f,pending p,selected s)
SELECT jsonb_build_object('definitionDifference',definition,'pendingInputDifference',pending,'differenceSha256',encode(sha256(convert_to(jsonb_build_object('definitionDifference',definition,'pendingInputDifference',pending,'configuredDefinition',snapshot->'definition','configuredWorkflow',snapshot->'workflow')::text,'UTF8')),'hex')) FROM result
$$;



--
-- Name: hr_performance_source_activation_expected_input(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_source_activation_expected_input(receipt_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
 SELECT public.hr_performance_source_activation_build_input(m.content,d.snapshot->'workflow',r.mapping,r.source_fact_id,r.created_by,r.created_at,r.id) FROM public.hr_performance_source_activation_receipt r JOIN public.hr_performance_source_manifest m ON m.id=r.manifest_id JOIN public.hr_performance_source_draft_revision d ON d.id=r.draft_revision_id WHERE r.id=receipt_id AND r.mode='qualified_source'
$$;



--
-- Name: hr_performance_source_activation_final_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_source_activation_final_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE r public.hr_performance_source_activation_receipt%ROWTYPE;d record;v record;c record;e record;i record;b record;q jsonb;parent record;
BEGIN
 SELECT * INTO r FROM public.hr_performance_source_activation_receipt WHERE id=NEW.id;
 SELECT * INTO d FROM public.hr_performance_source_draft_revision WHERE id=r.draft_revision_id;
 SELECT * INTO v FROM public.hr_performance_template_version WHERE(id,tenant_id,park_id)=(r.template_version_id,r.tenant_id,r.park_id);
 SELECT * INTO parent FROM public.hr_performance_template WHERE(id,tenant_id,park_id)=(r.template_id,r.tenant_id,r.park_id);
 IF parent.id IS NULL OR parent.is_deleted OR parent.current_version_no IS DISTINCT FROM v.version_no OR v.version_name IS DISTINCT FROM r.request->'target'->>'versionName' OR v.create_by IS DISTINCT FROM r.created_by OR v.create_time IS DISTINCT FROM r.created_at OR(r.request->'target'->>'mode'='new' AND(parent.template_code IS DISTINCT FROM r.request->'target'->>'templateCode' OR parent.template_name IS DISTINCT FROM r.request->'target'->>'templateName' OR parent.create_by IS DISTINCT FROM r.created_by OR parent.create_time IS DISTINCT FROM r.created_at)) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_FINAL_TARGET_INVALID';END IF;
 IF r.created_xid IS DISTINCT FROM pg_current_xact_id() OR v.id IS NULL OR v.template_id<>r.template_id OR v.calculation_mode<>'five_channel_v1' OR v.channel_definition_revision_id IS DISTINCT FROM r.definition_revision_id OR v.channel_workflow_revision_id IS DISTINCT FROM r.workflow_revision_id OR NOT EXISTS(SELECT 1 FROM public.hr_performance_channel_definition_revision x WHERE x.id=r.definition_revision_id AND x.config=d.snapshot->'definition' AND x.revision_no=1 AND x.previous_revision_id IS NULL AND x.created_by=r.created_by AND x.created_at=r.created_at) OR(r.workflow_revision_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.hr_performance_channel_workflow_revision x WHERE x.id=r.workflow_revision_id AND x.policy=d.snapshot->'workflow' AND x.definition_revision_id=r.definition_revision_id AND x.revision_no=1 AND x.previous_revision_id IS NULL AND x.created_by=r.created_by AND x.created_at=r.created_at)) OR v.status IS DISTINCT FROM (CASE r.kind WHEN 'template' THEN 'draft' ELSE 'published' END) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_FINAL_TEMPLATE_INVALID';END IF;
 IF r.kind='review' THEN
  SELECT * INTO c FROM public.hr_performance_review_cycle WHERE(id,tenant_id,park_id)=(r.cycle_id,r.tenant_id,r.park_id) FOR UPDATE;
  SELECT * INTO e FROM public.hr_performance_cycle_employee WHERE(id,tenant_id,park_id)=(r.review_id,r.tenant_id,r.park_id) FOR UPDATE;
  SELECT * INTO i FROM public.hr_performance_channel_input_revision WHERE id=r.initial_revision_id;
  SELECT * INTO b FROM public.hr_performance_channel_input_revision WHERE id=r.baseline_revision_id;
  IF c.id IS NULL OR e.id IS NULL OR c.source_activation_receipt_id IS DISTINCT FROM r.id OR c.status<>'self_review' OR e.cycle_id<>c.id OR e.employee_id<>r.employee_id OR e.status<>'self_review' OR e.create_time IS DISTINCT FROM r.created_at OR e.predecessor_review_id IS NOT NULL OR e.current_input_revision_id IS DISTINCT FROM COALESCE(r.baseline_revision_id,r.initial_revision_id) OR num_nonnulls(e.self_score,e.manager_score,e.calibrated_score,e.final_score,e.final_level_code,e.result_finalized_at,e.confirmed_at,e.final_input_revision_id)>0 OR(SELECT count(*) FROM public.hr_performance_cycle_employee WHERE cycle_id=c.id)<>1 OR(SELECT count(*) FROM public.hr_performance_channel_input_revision WHERE cycle_employee_id=e.id)<>(CASE r.mode WHEN 'qualified_source' THEN 2 ELSE 1 END) OR i.id IS NULL OR i.revision_no<>1 OR i.previous_revision_id IS NOT NULL OR i.created_by<>r.created_by OR i.created_at<>r.created_at OR i.source_activation_receipt_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.hr_performance_channel_cells(i.input) WHERE cell->>'state'<>'UNPROVIDED') OR(r.mode='qualified_source' AND(b.id IS NULL OR b.source_activation_receipt_id IS DISTINCT FROM r.id OR b.revision_no<>2 OR b.previous_revision_id IS DISTINCT FROM i.id OR b.input IS DISTINCT FROM public.hr_performance_source_activation_expected_input(r.id))) OR EXISTS(SELECT 1 FROM public.hr_performance_review_action WHERE cycle_employee_id=e.id) OR EXISTS(SELECT 1 FROM public.hr_performance_review_submission WHERE cycle_employee_id=e.id) OR EXISTS(SELECT 1 FROM public.hr_performance_calibration_batch WHERE cycle_id=c.id) OR EXISTS(SELECT 1 FROM public.hr_performance_appeal WHERE cycle_employee_id=e.id) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_FINAL_REVIEW_INVALID';END IF;
 END IF;
 q:=public.hr_performance_source_activation_qualification(r.tenant_id,r.park_id,r.created_by,r.draft_id,r.draft_revision_id);
 IF q IS DISTINCT FROM r.qualification OR q->'gates'->'SOURCE_GENERATION' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_FINAL_GENERATION_CHANGED';END IF;
 RETURN NULL;
END $$;



--
-- Name: hr_performance_source_activation_mapping(character varying, character varying, uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_source_activation_mapping(t character varying, p character varying, draft uuid, revision uuid, profile_identity text, manual boolean DEFAULT false) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
WITH source AS(SELECT r.source_fact_id,r.snapshot,m.migration_batch_id FROM public.hr_performance_source_draft d JOIN public.hr_performance_source_draft_revision r ON(r.id,r.tenant_id,r.park_id,r.draft_id)=(revision,t,p,d.id) JOIN public.hr_performance_source_manifest m ON m.id=r.manifest_id WHERE(d.id,d.tenant_id,d.park_id)=(draft,t,p)),
profile AS(SELECT f.* FROM public.hr_performance_legacy_template_profile f JOIN source s ON(f.tenant_id,f.park_id,f.migration_batch_id)=(t,p,s.migration_batch_id) WHERE f.source_identity_sha256=profile_identity AND NOT manual),
items AS(SELECT f.* FROM public.hr_performance_legacy_dimension_profile f JOIN profile a ON(f.legacy_template_profile_id,f.tenant_id,f.park_id,f.migration_batch_id)=(a.id,t,p,a.migration_batch_id) AND f.source_assessment_id=a.source_assessment),
grades AS(SELECT f.* FROM public.hr_performance_legacy_level_rule f JOIN profile a ON(f.legacy_template_profile_id,f.tenant_id,f.park_id,f.migration_batch_id)=(a.id,t,p,a.migration_batch_id) AND f.source_assessment_id=a.source_assessment),
guides AS(SELECT f.*,i.source_identity_sha256 item_identity FROM public.hr_performance_legacy_dimension_level_guide f JOIN items i ON(f.legacy_dimension_profile_id,f.tenant_id,f.park_id,f.migration_batch_id)=(i.id,t,p,i.migration_batch_id) AND f.source_item_id=i.source_item_id),
master AS(SELECT m.* FROM public.hr_performance_legacy_master_result m JOIN source s ON(m.id,m.tenant_id,m.park_id,m.migration_batch_id)=(s.source_fact_id,t,p,s.migration_batch_id)),
details AS(SELECT f.*,i.source_identity_sha256 item_identity FROM public.hr_performance_legacy_dimension_result f JOIN master m ON(f.tenant_id,f.park_id,f.migration_batch_id)=(t,p,m.migration_batch_id) AND f.source_session_id IS NOT DISTINCT FROM m.source_session_id AND f.source_person_code IS NOT DISTINCT FROM m.source_person_code JOIN items i ON(f.legacy_dimension_profile_id,f.source_item_id)=(i.id,i.source_item_id))
SELECT jsonb_build_object('profileIdentitySha256',CASE WHEN manual THEN NULL ELSE profile_identity END,'items',COALESCE((SELECT jsonb_agg(jsonb_build_object('sourceIdentitySha256',source_identity_sha256,'itemId','item:'||source_identity_sha256) ORDER BY source_identity_sha256 COLLATE "C") FROM items),'[]'::jsonb),'grades',COALESCE((SELECT jsonb_agg(jsonb_build_object('sourceIdentitySha256',source_identity_sha256,'gradeId','grade:'||source_identity_sha256) ORDER BY source_identity_sha256 COLLATE "C") FROM grades),'[]'::jsonb),'guides',COALESCE((SELECT jsonb_agg(jsonb_build_object('sourceIdentitySha256',source_identity_sha256,'itemId','item:'||item_identity,'guideId','guide:'||source_identity_sha256) ORDER BY source_identity_sha256 COLLATE "C") FROM guides),'[]'::jsonb),'details',COALESCE((SELECT jsonb_agg(jsonb_build_object('sourceIdentitySha256',source_identity_sha256,'detailId','detail:'||source_identity_sha256,'itemId','item:'||item_identity) ORDER BY source_identity_sha256 COLLATE "C") FROM details),'[]'::jsonb))
WHERE manual OR (EXISTS(SELECT 1 FROM profile) AND (SELECT count(*) FROM details)=(SELECT count(*) FROM public.hr_performance_legacy_dimension_result f JOIN master m ON(f.tenant_id,f.park_id,f.migration_batch_id)=(t,p,m.migration_batch_id) AND f.source_session_id IS NOT DISTINCT FROM m.source_session_id AND f.source_person_code IS NOT DISTINCT FROM m.source_person_code))
$$;



--
-- Name: hr_performance_source_activation_mapping_config_valid(jsonb, jsonb, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_source_activation_mapping_config_valid(mapping jsonb, definition jsonb, workflow jsonb, qualified boolean) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE item jsonb;guide jsonb;grade jsonb;actual jsonb;
BEGIN
 IF NOT public.hr_performance_channel_config_valid_v1(definition) OR(workflow IS NOT NULL AND workflow<>'null'::jsonb AND NOT public.hr_performance_channel_workflow_valid(workflow,definition,qualified)) THEN RETURN false;END IF;
 IF qualified AND(workflow IS NULL OR workflow='null'::jsonb) THEN RETURN false;END IF;
 IF mapping->'profileIdentitySha256'='null'::jsonb THEN RETURN NOT qualified;END IF;
 IF jsonb_array_length(mapping->'items')<>jsonb_array_length(definition->'items') OR jsonb_array_length(mapping->'grades')<>jsonb_array_length(definition->'gradeCandidates') THEN RETURN false;END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(mapping->'items') LOOP
 SELECT value INTO actual FROM jsonb_array_elements(definition->'items') WHERE value->'id'=item->'itemId';IF actual IS NULL OR jsonb_array_length(actual->'guides')<>(SELECT count(*) FROM jsonb_array_elements(mapping->'guides') g WHERE g->'itemId'=item->'itemId') THEN RETURN false;END IF;
 FOR guide IN SELECT value FROM jsonb_array_elements(mapping->'guides') WHERE value->'itemId'=item->'itemId' LOOP IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(actual->'guides') a WHERE a->'id'=guide->'guideId') THEN RETURN false;END IF;END LOOP;
 END LOOP;
 FOR grade IN SELECT value FROM jsonb_array_elements(mapping->'grades') LOOP IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(definition->'gradeCandidates') a WHERE a->'id'=grade->'gradeId') THEN RETURN false;END IF;END LOOP;
 IF qualified AND(jsonb_array_length(mapping->'details')=0 OR(SELECT jsonb_agg(jsonb_build_object('id',a->'detailId','itemId',a->'itemId') ORDER BY a->>'detailId' COLLATE "C") FROM jsonb_array_elements(mapping->'details') a) IS DISTINCT FROM(SELECT jsonb_agg(a ORDER BY a->>'id' COLLATE "C") FROM jsonb_array_elements(workflow->'detailDefinitions') a)) THEN RETURN false;END IF;RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;



--
-- Name: hr_performance_source_activation_qualification(character varying, character varying, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_source_activation_qualification(t character varying, p character varying, actor uuid, draft uuid, revision uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
WITH selected AS MATERIALIZED (
 SELECT d.kind,d.current_revision_id,r.id revision_id,r.source_fact_id,r.snapshot,m.id manifest_id,m.migration_batch_id,m.manifest_sha256,m.content
 FROM public.hr_performance_source_draft d JOIN public.hr_performance_source_draft_revision r ON(r.id,r.tenant_id,r.park_id,r.draft_id)=(revision,t,p,d.id)
 JOIN public.hr_performance_source_manifest m ON(m.id,m.tenant_id,m.park_id)=(r.manifest_id,t,p)
 WHERE(d.id,d.tenant_id,d.park_id)=(draft,t,p) AND (public.hr_performance_channel_actor_has(t,p,actor,CASE d.kind WHEN 'template' THEN 'hr:performance_template:read' ELSE 'hr:performance:read' END) OR public.hr_performance_channel_actor_has(t,p,actor,CASE d.kind WHEN 'template' THEN 'hr:performance_template:manage' ELSE 'hr:performance:manage' END))
),generation AS MATERIALIZED(SELECT public.hr_performance_source_generation(t,p,s.kind,s.source_fact_id) g FROM selected s),owner AS MATERIALIZED(
 SELECT b.*,o.status operation_status,o.intent,o.execution_contract_version,o.sealed_plan_sha256 operation_plan,o.code_sha operation_code,o.source_snapshot_sha256 operation_source,o.mapping_contract_sha256 operation_mapping,o.target_identity_sha256 operation_target,o.target_scope_sha256 operation_scope,o.target_tenant_id,o.target_park_id,ph.status phase_status,ph.after_canonical_sha256
 FROM selected s JOIN public.migration_batch b ON b.id=s.migration_batch_id LEFT JOIN public.hr_yuzhou_production_import_operation o ON o.operation_id=b.production_import_operation_id LEFT JOIN public.hr_yuzhou_production_import_phase ph ON(ph.operation_id,ph.phase)=(o.operation_id,'T0')
),r308 AS MATERIALIZED(SELECT r.* FROM public.hr_yuzhou_performance_relations_production_receipt r JOIN owner o ON r.operation_id=o.production_import_operation_id),r310 AS MATERIALIZED(SELECT r.* FROM public.hr_yuzhou_performance_fact_identity_production_receipt r JOIN owner o ON r.operation_id=o.production_import_operation_id),r311 AS MATERIALIZED(SELECT r.* FROM public.hr_yuzhou_performance_facts_production_receipt r JOIN owner o ON r.operation_id=o.production_import_operation_id),r309 AS MATERIALIZED(SELECT r.* FROM public.hr_yuzhou_performance_person_assessment_operation r JOIN owner o ON(r.migration_batch_id,r.parent_import_operation_id)=(o.id,o.production_import_operation_id) WHERE(r.target_tenant_id,r.target_park_id)=(t,p)),
full_set AS MATERIALIZED(SELECT f.* FROM selected s CROSS JOIN LATERAL public.hr_yuzhou_performance_full_fact_set_v1(t,p,s.migration_batch_id) f),identity_set AS MATERIALIZED(SELECT f.* FROM selected s CROSS JOIN LATERAL public.hr_yuzhou_performance_fact_identity_set_v1(t,p,s.migration_batch_id) f),map_state AS MATERIALIZED(SELECT f.* FROM selected s CROSS JOIN LATERAL public.hr_yuzhou_performance_owner_map_state_v1(t,p,s.migration_batch_id) f),
master AS MATERIALIZED(SELECT f.* FROM public.hr_performance_legacy_master_result f JOIN selected s ON s.kind='review' AND(f.id,f.tenant_id,f.park_id)=(s.source_fact_id,t,p)),weight AS MATERIALIZED(SELECT r.* FROM public.hr_performance_legacy_ass_compute_weight_resolution r JOIN master m ON(r.legacy_master_result_id,r.tenant_id,r.park_id,r.migration_batch_id)=(m.id,t,p,m.migration_batch_id)),expected_weight AS MATERIALIZED(SELECT e.* FROM master m CROSS JOIN LATERAL public.hr_performance_yuzhou_ass_compute_weight_expectation(m.id) e),
profile AS MATERIALIZED(SELECT f.* FROM public.hr_performance_legacy_template_profile f JOIN selected s ON(f.tenant_id,f.park_id,f.migration_batch_id)=(t,p,s.migration_batch_id) WHERE(s.kind='template' AND f.id=s.source_fact_id) OR(s.kind='review' AND f.id=(SELECT person_template_profile_id FROM weight))),
result_facts AS MATERIALIZED(
 SELECT 'master_result'::text family,m.id,m.source_person_code,m.migration_batch_id FROM master m UNION ALL
 SELECT 'dimension_result',f.id,f.source_person_code,f.migration_batch_id FROM public.hr_performance_legacy_dimension_result f JOIN master m ON(f.tenant_id,f.park_id,f.migration_batch_id)=(t,p,m.migration_batch_id) AND f.source_session_id IS NOT DISTINCT FROM m.source_session_id AND f.source_person_code IS NOT DISTINCT FROM m.source_person_code
),t0_candidates AS MATERIALIZED(
 SELECT map.id map_id,map.source_identity_sha256,employee.id employee_id
 FROM public.legacy_record_map map JOIN public.hr_yuzhou_production_import_projection_receipt pr ON(pr.legacy_record_map_id,pr.phase)=(map.id,'T0')
 JOIN public.hr_yuzhou_production_import_record rec ON(rec.operation_id,rec.phase,rec.source_identity_sha256)=(pr.operation_id,pr.phase,pr.source_identity_sha256)
 JOIN public.hr_yuzhou_production_import_operation op ON op.operation_id=rec.operation_id JOIN public.hr_yuzhou_production_import_phase ph ON(ph.operation_id,ph.phase)=(op.operation_id,'T0')
 JOIN public.migration_batch b ON b.id=pr.migration_batch_id JOIN public.hr_employee employee ON(employee.id,employee.tenant_id,employee.park_id)=(map.target_id,t,p) AND NOT employee.is_deleted
 WHERE op.status='succeeded' AND op.intent='production_import' AND op.execution_contract_version=2 AND(op.target_tenant_id,op.target_park_id)=(t,p) AND ph.status='succeeded'
 AND(b.id,b.production_import_operation_id,b.source_system,b.execution_context,b.production_import_phase,b.status,b.target_database)=(map.batch_id,op.operation_id,'yuzhou-v10','production_import','T0','succeeded',current_database())
 AND map.source_system='yuzhou-v10' AND map.source_table='dbo.person' AND map.source_pk_canonical='sha256:'||map.source_identity_sha256 AND map.mapping_status='verified' AND map.is_active AND map.target_table='hr_employee'
 AND(rec.source_system,rec.source_table,rec.source_pk_canonical,rec.target_table,rec.target_id)=('yuzhou-v10','dbo.person',map.source_pk_canonical,'hr_employee',map.target_id) AND rec.disposition IN('insert','merge','skip_approved') AND rec.rollback_status='not_started'
),result_resolution AS MATERIALIZED(
 SELECT f.*,r.id resolution_id,r.person_resolution_status,r.source_person_identity_sha256,r.owner_t0_record_map_id,r.target_employee_id,
 (SELECT count(*) FROM t0_candidates c WHERE c.source_identity_sha256=public.hr_performance_yuzhou_person_identity_sha256(f.source_person_code)) candidate_count,
 (SELECT c.map_id FROM t0_candidates c WHERE c.source_identity_sha256=public.hr_performance_yuzhou_person_identity_sha256(f.source_person_code) LIMIT 1) candidate_map,
 (SELECT c.employee_id FROM t0_candidates c WHERE c.source_identity_sha256=public.hr_performance_yuzhou_person_identity_sha256(f.source_person_code) LIMIT 1) candidate_employee
 FROM result_facts f LEFT JOIN public.hr_performance_legacy_identity_resolution r ON(r.tenant_id,r.park_id,r.migration_batch_id,r.fact_kind,r.person_role)=(t,p,f.migration_batch_id,f.family,'subject') AND CASE f.family WHEN 'master_result' THEN r.legacy_master_result_id ELSE r.legacy_dimension_result_id END=f.id
),migration_claims AS(
 SELECT v.filename,v.checksum FROM r308 a,r310 b,r311 c CROSS JOIN LATERAL(VALUES
 ('000305_hr_performance_yuzhou_legacy_relations.sql',a.migration_305_sha256),('000306_hr_performance_yuzhou_identity_resolution.sql',a.migration_306_sha256),
 ('000308_hr_yuzhou_performance_relations_production.sql',b.migration_308_sha256),('000310_hr_yuzhou_performance_fact_identity_production.sql',b.migration_310_sha256),
 ('000300_hr_performance_yuzhou_legacy_model.sql',c.migration_300_sha256),('000301_hr_performance_yuzhou_legacy_writer.sql',c.migration_301_sha256),('000302_hr_performance_yuzhou_legacy_master.sql',c.migration_302_sha256),('000303_hr_performance_yuzhou_legacy_master_writer.sql',c.migration_303_sha256),('000310_hr_yuzhou_performance_fact_identity_production.sql',c.migration_310_sha256),('000311_hr_yuzhou_performance_facts_production.sql',c.migration_311_sha256))v(filename,checksum)
 UNION ALL SELECT '000307_hr_performance_yuzhou_ass_compute_weight_relation.sql',migration_307_sha256 FROM r309 UNION ALL SELECT '000308_hr_yuzhou_performance_relations_production.sql',migration_308_sha256 FROM r309
),gates AS MATERIALIZED(
 SELECT 'SOURCE_GENERATION'::text code,COALESCE((SELECT s.current_revision_id=revision AND g.g IS NOT NULL AND g.g->'content'=s.content AND g.g->>'manifestSha256'=s.manifest_sha256 FROM selected s,generation g),false) passed
 UNION ALL SELECT 'IMPORT_OWNER',COALESCE((SELECT o.operation_status='succeeded' AND o.intent='production_import' AND o.execution_contract_version=2 AND(o.target_tenant_id,o.target_park_id)=(t,p) AND o.phase_status='succeeded' AND o.status='succeeded' FROM owner o),false)
 UNION ALL SELECT 'RECEIPT_CHAIN',COALESCE((SELECT a.status='succeeded' AND b.status='succeeded' AND c.status='succeeded' AND a.rolled_back_at IS NULL AND b.rolled_back_at IS NULL AND c.rolled_back_at IS NULL AND a.rollback_operation_id IS NULL AND b.rollback_operation_id IS NULL AND c.rollback_operation_id IS NULL AND a.rollback_receipt_sha256 IS NULL AND b.rollback_receipt_sha256 IS NULL AND b.extension_rollback_nonce_sha256 IS NULL AND c.rollback_receipt_sha256 IS NULL
 AND ROW(a.migration_batch_id,a.sealed_plan_sha256,a.code_sha,a.source_snapshot_sha256,a.mapping_contract_sha256,a.target_identity_sha256,a.tenant_id,a.park_id,a.target_scope_sha256,a.t0_phase_receipt_sha256) IS NOT DISTINCT FROM ROW(o.id,o.operation_plan,o.operation_code,o.operation_source,o.operation_mapping,o.operation_target,t,p,o.operation_scope,o.after_canonical_sha256)
 AND ROW(c.migration_batch_id,c.sealed_plan_sha256,c.code_sha,c.source_snapshot_sha256,c.mapping_contract_sha256,c.target_identity_sha256,c.tenant_id,c.park_id,c.target_scope_sha256,c.t0_phase_receipt_sha256) IS NOT DISTINCT FROM ROW(a.migration_batch_id,a.sealed_plan_sha256,a.code_sha,a.source_snapshot_sha256,a.mapping_contract_sha256,a.target_identity_sha256,a.tenant_id,a.park_id,a.target_scope_sha256,a.t0_phase_receipt_sha256)
 AND ROW(b.migration_batch_id,b.sealed_plan_sha256,b.code_sha,b.source_snapshot_sha256,b.mapping_contract_sha256,b.target_identity_sha256,b.tenant_id,b.park_id,b.target_scope_sha256,b.t0_phase_receipt_sha256) IS NOT DISTINCT FROM ROW(a.migration_batch_id,a.sealed_plan_sha256,a.code_sha,a.source_snapshot_sha256,a.mapping_contract_sha256,a.target_identity_sha256,a.tenant_id,a.park_id,a.target_scope_sha256,a.t0_phase_receipt_sha256)
 AND(b.parent_relations_receipt_sha256,b.fact_loader_receipt_sha256,b.fact_set_sha256,b.dimension_rows,b.master_rows) IS NOT DISTINCT FROM(a.receipt_sha256,c.receipt_sha256,c.identity_fact_set_sha256,c.dimension_result_rows,c.master_result_rows) FROM r308 a,r310 b,r311 c,owner o),false)
 UNION ALL SELECT 'MIGRATION_CHECKSUMS',EXISTS(SELECT 1 FROM migration_claims) AND NOT EXISTS(SELECT 1 FROM migration_claims c WHERE NOT EXISTS(SELECT 1 FROM public.schema_migrations m JOIN public.sys_schema_migration_history h USING(filename,checksum,status) WHERE(m.filename,m.checksum,m.status)=(c.filename,c.checksum,'succeeded')))
 UNION ALL SELECT 'FULL_FACT_CONSERVATION',COALESCE((SELECT ROW(f.template_rows,f.level_rule_rows,f.dimension_rows,f.guide_rows,f.dimension_result_rows,f.master_result_rows,f.active_fact_maps,f.full_fact_set_sha256) IS NOT DISTINCT FROM ROW(c.template_rows,c.level_rule_rows,c.dimension_rows,c.guide_rows,c.dimension_result_rows,c.master_result_rows,c.active_fact_maps,c.full_fact_set_sha256) AND ROW(i.dimension_rows,i.master_rows,i.fact_rows,i.fact_set_sha256) IS NOT DISTINCT FROM ROW(b.dimension_rows,b.master_rows,b.fact_rows,b.fact_set_sha256) AND public.hr_yuzhou_performance_fact_identity_state_v1(t,p,s.migration_batch_id) IS NOT DISTINCT FROM b.resolution_state_sha256 FROM full_set f,identity_set i,r310 b,r311 c,selected s),false)
 UNION ALL SELECT 'OWNER_MAP_CONSERVATION',COALESCE((SELECT ROW(m.fact_owner_maps,m.relation_owner_maps,m.verified_owner_maps,m.owner_map_state_sha256) IS NOT DISTINCT FROM ROW(b.fact_owner_maps,b.relation_owner_maps,b.verified_owner_maps,b.owner_map_state_sha256) AND m.invalid_owner_maps=0 AND m.loaded_owner_maps=0 AND m.owner_maps=m.distinct_owner_maps AND m.owner_maps=m.active_target_maps AND m.owner_maps=m.verified_owner_maps FROM map_state m,r310 b),false)
 UNION ALL SELECT 'IMPORT_ITEM_DISCREPANCY',NOT EXISTS(SELECT 1 FROM public.migration_batch_item i JOIN selected s ON i.batch_id=s.migration_batch_id WHERE i.source_object IN('dbo.assessmentcode','dbo.assgradecode','dbo.assitem','dbo.assitemgradedes','dbo.assessmentdetail','dbo.assessmentmaster') AND i.phase IN('load','verify') AND i.status IN('failed','quarantined'))
 UNION ALL SELECT 'PERSON_ASSESSMENT_OPERATION',s.kind='template' OR COALESCE((SELECT o.status='succeeded' AND o.started_at IS NOT NULL AND o.finished_at IS NOT NULL AND o.rolled_back_at IS NULL AND(o.code_sha,o.source_snapshot_sha256,o.mapping_contract_sha256,o.target_identity_sha256,o.target_scope_sha256,o.t0_artifact_sha256) IS NOT DISTINCT FROM (a.code_sha,a.source_snapshot_sha256,a.mapping_contract_sha256,a.target_identity_sha256,a.target_scope_sha256,a.t0_phase_receipt_sha256) AND public.hr_yuzhou_performance_person_assessment_owner_state_sha256(s.migration_batch_id) IS NOT DISTINCT FROM o.owner_state_sha256 AND public.hr_yuzhou_performance_person_assessment_state_sha256(s.migration_batch_id,'succeeded',o.binding_sha256) IS NOT DISTINCT FROM o.applied_state_sha256 AND o.applied_evidence_rows=(SELECT count(*) FROM public.hr_performance_legacy_person_assessment_evidence e WHERE(e.migration_batch_id,e.tenant_id,e.park_id)=(s.migration_batch_id,t,p)) AND o.applied_master_rows=(SELECT count(*) FROM public.hr_performance_legacy_master_result m WHERE(m.migration_batch_id,m.tenant_id,m.park_id)=(s.migration_batch_id,t,p)) AND o.applied_resolution_rows=(SELECT count(*) FROM public.hr_performance_legacy_ass_compute_weight_resolution r WHERE(r.migration_batch_id,r.tenant_id,r.park_id)=(s.migration_batch_id,t,p)) FROM r309 o,r308 a),false) FROM selected s
 UNION ALL SELECT 'PROFILE_RESOLUTION',s.kind='template' OR COALESCE((SELECT w.person_resolution_status='resolved' AND w.source_person_evidence_count=1 AND w.person_template_candidate_count=1 AND w.detail_resolution_status='resolved' AND w.detail_template_candidate_count=1 AND w.comparison_status='matched' AND w.person_template_profile_id IS NOT NULL AND w.person_template_profile_id=w.detail_template_profile_id
 AND ROW(w.source_person_identity_sha256,w.source_person_evidence_count,w.source_person_assessment_id,w.person_template_candidate_count,w.person_template_profile_id,w.person_resolution_status,w.detail_template_candidate_count,w.detail_template_profile_id,w.detail_resolution_status,w.comparison_status) IS NOT DISTINCT FROM ROW(e.source_person_identity_sha256,e.source_person_evidence_count,e.source_person_assessment_id,e.person_template_candidate_count,e.person_template_profile_id,e.person_resolution_status,e.detail_template_candidate_count,e.detail_template_profile_id,e.detail_resolution_status,e.comparison_status)
 AND w.evidence_sha256 IS NOT DISTINCT FROM public.hr_performance_yuzhou_ass_compute_weight_evidence_sha256(w.legacy_master_result_id,w.source_person_identity_sha256,w.source_person_evidence_count,w.source_person_assessment_id,w.person_template_candidate_count,w.person_template_profile_id,w.person_resolution_status,w.detail_template_candidate_count,w.detail_template_profile_id,w.detail_resolution_status,w.comparison_status)
 AND (SELECT count(*) FROM public.hr_performance_legacy_person_assessment_evidence pe JOIN profile pr ON pe.source_assessment_id=pr.source_assessment WHERE(pe.migration_batch_id,pe.tenant_id,pe.park_id,pe.source_person_identity_sha256)=(s.migration_batch_id,t,p,w.source_person_identity_sha256) AND pe.evidence_sha256 IS NOT DISTINCT FROM public.hr_performance_yuzhou_person_assessment_evidence_sha256(pe.source_person_identity_sha256,pe.source_assessment_id))=1 FROM weight w,expected_weight e),false) FROM selected s
 UNION ALL SELECT 'RESULT_SUBJECT_IDENTITY',s.kind='template' OR (EXISTS(SELECT 1 FROM result_facts WHERE family='dimension_result') AND NOT EXISTS(SELECT 1 FROM result_resolution r WHERE r.resolution_id IS NULL OR r.person_resolution_status IS DISTINCT FROM 'resolved' OR r.source_person_identity_sha256 IS DISTINCT FROM public.hr_performance_yuzhou_person_identity_sha256(r.source_person_code) OR r.candidate_count<>1 OR r.owner_t0_record_map_id IS DISTINCT FROM r.candidate_map OR r.target_employee_id IS DISTINCT FROM r.candidate_employee OR r.target_employee_id IS DISTINCT FROM (SELECT target_employee_id FROM result_resolution WHERE family='master_result'))) FROM selected s
 UNION ALL SELECT 'PROFILE_CATALOG',EXISTS(SELECT 1 FROM profile)
),result AS(
 SELECT jsonb_build_object('sourceQualified',(SELECT bool_and(passed) FROM gates),'qualificationGateCodes',COALESCE((SELECT jsonb_agg(code ORDER BY code COLLATE "C") FROM gates WHERE NOT passed),'[]'::jsonb),'manifestSha256',s.manifest_sha256,'profileIdentitySha256',(SELECT source_identity_sha256 FROM profile),'resolvedEmployeeId',CASE WHEN s.kind='review' THEN (SELECT target_employee_id FROM result_resolution WHERE family='master_result') END,'qualificationCounts',jsonb_build_object('selectedDetails',(SELECT count(*) FROM result_facts WHERE family='dimension_result'),'factRows',(SELECT fact_rows FROM identity_set),'unresolvedSubjects',(SELECT unmatched_rows+ambiguous_rows+not_applicable_rows FROM r310)),'gates',(SELECT jsonb_object_agg(code,passed ORDER BY code COLLATE "C") FROM gates),
 'qualificationHash',encode(sha256(convert_to(jsonb_build_object('contract','formal-activation-v1','manifestSha256',s.manifest_sha256,'receipt308Sha256',(SELECT receipt_sha256 FROM r308),'receipt310Sha256',(SELECT receipt_sha256 FROM r310),'receipt311Sha256',(SELECT receipt_sha256 FROM r311),'operation309Id',CASE WHEN s.kind='review' THEN (SELECT operation_id FROM r309) END,'operation309StateSha256',CASE WHEN s.kind='review' THEN (SELECT applied_state_sha256 FROM r309) END,'profileIdentitySha256',(SELECT source_identity_sha256 FROM profile),'employeeId',CASE WHEN s.kind='review' THEN (SELECT target_employee_id FROM result_resolution WHERE family='master_result') END,'gates',(SELECT jsonb_object_agg(code,passed ORDER BY code COLLATE "C") FROM gates))::text,'UTF8')),'hex')) value FROM selected s
) SELECT value FROM result
$$;



--
-- Name: hr_performance_source_activation_receipt_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_source_activation_receipt_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE d record;r record;m record;q jsonb;expected_mapping jsonb;diff jsonb;v record;parent record;input jsonb;c record;policy jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_RECEIPT_IMMUTABLE';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.tenant_id||':'||NEW.park_id||':'||NEW.kind||':'||NEW.source_identity_sha256,0));
 SELECT * INTO d FROM public.hr_performance_source_draft WHERE(id,tenant_id,park_id)=(NEW.draft_id,NEW.tenant_id,NEW.park_id) FOR UPDATE;
 SELECT * INTO r FROM public.hr_performance_source_draft_revision WHERE(id,tenant_id,park_id,draft_id)=(NEW.draft_revision_id,NEW.tenant_id,NEW.park_id,NEW.draft_id);
 SELECT * INTO m FROM public.hr_performance_source_manifest WHERE(id,tenant_id,park_id)=(NEW.manifest_id,NEW.tenant_id,NEW.park_id);
 IF d.id IS NULL OR r.id IS NULL OR m.id IS NULL OR d.kind IS DISTINCT FROM NEW.kind OR d.current_revision_id IS DISTINCT FROM r.id OR r.manifest_id IS DISTINCT FROM m.id OR r.source_fact_id IS DISTINCT FROM NEW.source_fact_id OR d.source_identity_sha256 IS DISTINCT FROM NEW.source_identity_sha256 OR NEW.binding IS DISTINCT FROM r.snapshot->'binding' OR NEW.created_xid IS DISTINCT FROM pg_current_xact_id() OR NEW.created_at IS DISTINCT FROM transaction_timestamp() THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_IDENTITY_INVALID';END IF;
 IF NOT public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance_template:manage') OR(NEW.kind='review' AND NOT public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance:manage')) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_PERMISSION_REQUIRED';END IF;
 q:=public.hr_performance_source_activation_qualification(NEW.tenant_id,NEW.park_id,NEW.created_by,d.id,r.id);
 IF q IS NULL OR q IS DISTINCT FROM NEW.qualification OR q->>'qualificationHash' IS DISTINCT FROM NEW.qualification_sha256 OR q->'gates'->'SOURCE_GENERATION' IS DISTINCT FROM 'true'::jsonb OR(NEW.mode='qualified_source' AND q->'sourceQualified' IS DISTINCT FROM 'true'::jsonb) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_QUALIFICATION_CHANGED';END IF;
 IF NOT public.hr_performance_source_activation_request_valid(NEW.request,NEW.kind) OR NEW.request->>'expectedRevisionId' IS DISTINCT FROM r.id::text OR NEW.request->>'expectedManifestSha256' IS DISTINCT FROM m.manifest_sha256 OR NEW.request->>'expectedQualificationSha256' IS DISTINCT FROM NEW.qualification_sha256 OR NEW.request->>'reason' IS DISTINCT FROM NEW.reason OR(NEW.kind='review' AND NEW.request->>'mode' IS DISTINCT FROM NEW.mode) OR NEW.request_sha256 IS DISTINCT FROM encode(sha256(convert_to(jsonb_build_object('route',CASE NEW.kind WHEN 'template' THEN 'activate-template' ELSE 'activate-review' END,'draftRevisionId',r.id,'body',NEW.request)::text,'UTF8')),'hex') OR NEW.business_key_sha256 IS DISTINCT FROM encode(sha256(convert_to(jsonb_build_object('kind',NEW.kind,'sourceIdentitySha256',NEW.source_identity_sha256,'predecessorReceiptId',NULL)::text,'UTF8')),'hex') THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_REQUEST_INVALID';END IF;
 expected_mapping:=public.hr_performance_source_activation_mapping(NEW.tenant_id,NEW.park_id,d.id,r.id,q->>'profileIdentitySha256',NEW.mode='manual_current');
 IF expected_mapping IS NULL OR expected_mapping IS DISTINCT FROM NEW.mapping OR NOT public.hr_performance_source_activation_mapping_config_valid(NEW.mapping,r.snapshot->'definition',r.snapshot->'workflow',NEW.mode='qualified_source') OR(NEW.kind='review' AND NOT public.hr_performance_channel_workflow_valid(r.snapshot->'workflow',r.snapshot->'definition',true)) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_MAPPING_INVALID';END IF;
 diff:=public.hr_performance_source_activation_differences(NEW.tenant_id,NEW.park_id,d.id,r.id,q->>'profileIdentitySha256');
 IF NEW.definition_difference IS DISTINCT FROM diff->'definitionDifference' OR NEW.pending_input_difference IS DISTINCT FROM diff->'pendingInputDifference' OR NEW.request->>'acknowledgedDifferenceSha256' IS DISTINCT FROM diff->>'differenceSha256' THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_DIFFERENCE_CHANGED';END IF;
 IF EXISTS(SELECT 1 FROM public.hr_performance_template_version WHERE id=NEW.template_version_id) OR EXISTS(SELECT 1 FROM public.hr_performance_channel_definition_revision WHERE id=NEW.definition_revision_id) OR EXISTS(SELECT 1 FROM public.hr_performance_channel_workflow_revision WHERE id=NEW.workflow_revision_id) OR EXISTS(SELECT 1 FROM public.hr_performance_review_cycle WHERE id=NEW.cycle_id) OR EXISTS(SELECT 1 FROM public.hr_performance_cycle_employee WHERE id=NEW.review_id) OR EXISTS(SELECT 1 FROM public.hr_performance_channel_input_revision WHERE id IN(NEW.initial_revision_id,NEW.baseline_revision_id)) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_TARGET_NOT_FRESH';END IF;
 IF NEW.request->'target'->>'mode'='new' THEN
  IF EXISTS(SELECT 1 FROM public.hr_performance_template WHERE id=NEW.template_id) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_TARGET_NOT_FRESH';END IF;
 ELSE
  SELECT * INTO parent FROM public.hr_performance_template WHERE(id,tenant_id,park_id)=(NEW.template_id,NEW.tenant_id,NEW.park_id) AND NOT is_deleted FOR UPDATE;
  SELECT * INTO v FROM public.hr_performance_template_version WHERE(template_id,tenant_id,park_id,version_no)=(parent.id,NEW.tenant_id,NEW.park_id,parent.current_version_no) FOR UPDATE;
  IF parent.id IS NULL OR parent.status='retired' OR NEW.request->'target'->>'templateId' IS DISTINCT FROM parent.id::text OR NEW.request->'target'->>'expectedVersionId' IS DISTINCT FROM v.id::text OR NEW.request->'target'->>'expectedDefinitionRevisionId' IS DISTINCT FROM v.channel_definition_revision_id::text OR NEW.request->'target'->>'expectedWorkflowRevisionId' IS DISTINCT FROM v.channel_workflow_revision_id::text THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_TARGET_CHANGED';END IF;
 END IF;
 IF (r.snapshot->'workflow' IS NULL OR r.snapshot->'workflow'='null'::jsonb) IS DISTINCT FROM (NEW.workflow_revision_id IS NULL) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_WORKFLOW_ID_INVALID';END IF;
 IF NEW.kind='review' THEN
  IF NEW.binding->>'employeeId' IS DISTINCT FROM NEW.employee_id::text OR NOT EXISTS(SELECT 1 FROM public.hr_employee e JOIN public.sys_org o ON(o.id,o.tenant_id,o.park_id)=(e.primary_org_id,e.tenant_id,e.park_id) WHERE(e.id,e.tenant_id,e.park_id)=(NEW.employee_id,NEW.tenant_id,NEW.park_id) AND NOT e.is_deleted AND e.employment_status<>'departed' AND NOT o.is_deleted AND o.status='enabled' AND o.id::text=NEW.binding->>'orgId') OR NEW.binding->>'startDate' IS NULL OR NEW.binding->>'endDate' IS NULL OR (NEW.binding->>'startDate')::date>(NEW.binding->>'endDate')::date OR length(btrim(NEW.binding->>'businessPeriodRef')) IS NULL OR length(btrim(NEW.binding->>'businessPeriodRef'))=0 OR(NEW.mode='qualified_source' AND q->>'resolvedEmployeeId' IS DISTINCT FROM NEW.employee_id::text) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_BINDING_INVALID';END IF;
 END IF;
 IF NEW.mode='qualified_source' THEN
  input:=public.hr_performance_source_activation_build_input(m.content,r.snapshot->'workflow',NEW.mapping,NEW.source_fact_id,NEW.created_by,NEW.created_at,NEW.id);
  IF NOT public.hr_performance_channel_input_valid(input,r.snapshot->'workflow') THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_SOURCE_POLICY_TEXT_CONFLICT';END IF;
  IF NOT(r.snapshot->'workflow' ? 'detailAppraisalPolicy') AND EXISTS(SELECT 1 FROM jsonb_array_elements(m.content->'facts')f WHERE f->>'family'='dimension_result' AND EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.mapping->'details') detail WHERE detail->'sourceIdentitySha256'=f->'identitySha256') AND f->'values'->'source_appraisal'<>'null'::jsonb) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_APPRAISAL_POLICY_REQUIRED';END IF;
  FOR c IN SELECT * FROM public.hr_performance_channel_cells(input) LOOP policy:=public.hr_performance_channel_policy_for(r.snapshot->'definition',r.snapshot->'workflow',c.field);IF c.cell->>'state'='VALUE' AND policy->'required'='true'::jsonb AND c.field IN('detailAppraisal','selfAppraisal','appraisal','description') AND length(btrim(c.cell->>'value'))=0 THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_SOURCE_POLICY_TEXT_CONFLICT';END IF;END LOOP;
  IF input->'master'->'salaryReference'->>'state'='VALUE' AND NOT(public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance:read') AND public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:compensation:manage')) THEN RAISE EXCEPTION 'SOURCE_ACTIVATION_SALARY_REQUIRED';END IF;
 END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_performance_source_activation_request_valid(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_source_activation_request_valid(r jsonb, kind text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE k text;target jsonb;
BEGIN
 IF NOT public.hr_performance_channel_object_v1(r,ARRAY['expectedRevisionId','expectedManifestSha256','expectedQualificationSha256','target','reason','acknowledgedDifferenceSha256']||CASE WHEN kind='review' THEN ARRAY['mode','cycleCode','cycleName'] ELSE ARRAY[]::text[] END) THEN RETURN false;END IF;
 FOR k IN SELECT unnest(ARRAY['expectedRevisionId','expectedManifestSha256','expectedQualificationSha256','reason','acknowledgedDifferenceSha256']||CASE WHEN kind='review' THEN ARRAY['mode','cycleCode','cycleName'] ELSE ARRAY[]::text[] END) LOOP IF jsonb_typeof(r->k)<>'string' THEN RETURN false;END IF;END LOOP;
 IF r->>'expectedRevisionId' !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' OR r->>'expectedManifestSha256' !~ '^[0-9a-f]{64}$' OR r->>'expectedQualificationSha256' !~ '^[0-9a-f]{64}$' OR r->>'acknowledgedDifferenceSha256' !~ '^[0-9a-f]{64}$' OR NOT public.hr_performance_source_activation_text_valid(r->'reason',2,2000) THEN RETURN false;END IF;
 target:=r->'target';IF target->>'mode'='new' THEN
 IF NOT public.hr_performance_channel_object_v1(target,ARRAY['mode','templateCode','templateName','versionName']) THEN RETURN false;END IF;
 FOR k IN SELECT unnest(ARRAY['templateCode','templateName','versionName']) LOOP IF NOT public.hr_performance_source_activation_text_valid(target->k,1,CASE k WHEN 'templateCode' THEN 64 ELSE 120 END) THEN RETURN false;END IF;END LOOP;
 ELSIF target->>'mode'='new_version' THEN
 IF NOT public.hr_performance_channel_object_v1(target,ARRAY['mode','templateId','expectedVersionId','expectedDefinitionRevisionId','expectedWorkflowRevisionId','versionName']) OR NOT public.hr_performance_source_activation_text_valid(target->'versionName',1,120) THEN RETURN false;END IF;
 FOR k IN SELECT unnest(ARRAY['templateId','expectedVersionId','expectedDefinitionRevisionId','expectedWorkflowRevisionId']) LOOP IF k='expectedWorkflowRevisionId' AND target->k='null'::jsonb THEN CONTINUE;END IF;IF jsonb_typeof(target->k)<>'string' OR target->>k !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN RETURN false;END IF;END LOOP;
 ELSE RETURN false;END IF;
 IF kind='review' AND(r->>'mode' NOT IN('qualified_source','manual_current') OR NOT public.hr_performance_source_activation_text_valid(r->'cycleCode',1,64) OR NOT public.hr_performance_source_activation_text_valid(r->'cycleName',1,120)) THEN RETURN false;END IF;RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $_$;



--
-- Name: hr_performance_source_activation_text_valid(jsonb, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_source_activation_text_valid(v jsonb, min_length integer, max_length integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT COALESCE(jsonb_typeof(v)='string' AND length(v#>>'{}') BETWEEN min_length AND max_length AND length(btrim(v#>>'{}',U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF'))>=min_length,false)
$$;



--
-- Name: hr_performance_source_draft_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_source_draft_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE r public.hr_performance_source_draft_revision%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'SOURCE_DRAFT_IMMUTABLE';END IF;
 IF TG_OP='INSERT' THEN
 IF NEW.created_at IS DISTINCT FROM transaction_timestamp() OR NOT public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,CASE NEW.kind WHEN 'template' THEN 'hr:performance_template:manage' ELSE 'hr:performance:manage' END) THEN RAISE EXCEPTION 'SOURCE_PERMISSION_REQUIRED';END IF;RETURN NEW;END IF;
 IF (to_jsonb(NEW)-'current_revision_id') IS DISTINCT FROM (to_jsonb(OLD)-'current_revision_id') OR NEW.current_revision_id IS NULL OR NEW.current_revision_id=OLD.current_revision_id THEN RAISE EXCEPTION 'SOURCE_DRAFT_IDENTITY_IMMUTABLE';END IF;
 SELECT * INTO r FROM public.hr_performance_source_draft_revision WHERE id=NEW.current_revision_id AND draft_id=NEW.id AND tenant_id=NEW.tenant_id AND park_id=NEW.park_id;
 IF r.id IS NULL OR r.previous_revision_id IS DISTINCT FROM OLD.current_revision_id THEN RAISE EXCEPTION 'SOURCE_HEAD_INVALID';END IF;RETURN NEW;
END $$;



--
-- Name: hr_performance_source_field_valid(text, text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_source_field_valid(f text, k text, v jsonb, editable boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE typ text;allowed boolean;
BEGIN
 SELECT a->>'type',(a->>'editable')::boolean INTO typ,allowed FROM jsonb_array_elements('[{"family": "template_profile", "field": "source_assessment", "type": "integer", "editable": false}, {"family": "template_profile", "field": "source_assessment_name", "type": "varchar(50)", "editable": true}, {"family": "template_profile", "field": "source_department", "type": "varchar(30)", "editable": true}, {"family": "template_profile", "field": "source_m_percent", "type": "integer", "editable": true}, {"family": "template_profile", "field": "source_t_percent", "type": "integer", "editable": true}, {"family": "template_profile", "field": "source_x_percent", "type": "integer", "editable": true}, {"family": "template_profile", "field": "source_c_percent", "type": "integer", "editable": true}, {"family": "template_profile", "field": "source_s_percent", "type": "integer", "editable": true}, {"family": "template_profile", "field": "source_timekeep", "type": "boolean", "editable": true}, {"family": "template_profile", "field": "source_bonus", "type": "boolean", "editable": true}, {"family": "template_profile", "field": "source_master", "type": "boolean", "editable": true}, {"family": "level_rule", "field": "source_ass_grade", "type": "varchar(12)", "editable": false}, {"family": "level_rule", "field": "source_description", "type": "varchar(500)", "editable": true}, {"family": "level_rule", "field": "source_my_order", "type": "varchar(2)", "editable": true}, {"family": "level_rule", "field": "source_assessment_id", "type": "integer", "editable": false}, {"family": "level_rule", "field": "source_min_value", "type": "integer", "editable": true}, {"family": "level_rule", "field": "source_max_value", "type": "integer", "editable": true}, {"family": "dimension_profile", "field": "source_item_id", "type": "integer", "editable": false}, {"family": "dimension_profile", "field": "source_assessment_id", "type": "integer", "editable": false}, {"family": "dimension_profile", "field": "source_item_name", "type": "varchar(100)", "editable": true}, {"family": "dimension_profile", "field": "source_full_value", "type": "numeric(18,2)", "editable": true}, {"family": "dimension_profile", "field": "source_my_order", "type": "integer", "editable": true}, {"family": "dimension_level_guide", "field": "source_guide_id", "type": "integer", "editable": false}, {"family": "dimension_level_guide", "field": "source_item_id", "type": "integer", "editable": false}, {"family": "dimension_level_guide", "field": "source_grade", "type": "varchar(12)", "editable": true}, {"family": "dimension_level_guide", "field": "source_description", "type": "varchar(500)", "editable": true}, {"family": "dimension_level_guide", "field": "source_min_value", "type": "integer", "editable": true}, {"family": "dimension_level_guide", "field": "source_max_value", "type": "integer", "editable": true}, {"family": "dimension_level_guide", "field": "source_my_order", "type": "integer", "editable": true}, {"family": "dimension_result", "field": "source_detail_id", "type": "integer", "editable": false}, {"family": "dimension_result", "field": "source_session_id", "type": "integer", "editable": false}, {"family": "dimension_result", "field": "source_person_code", "type": "varchar(10)", "editable": false}, {"family": "dimension_result", "field": "source_item_id", "type": "integer", "editable": false}, {"family": "dimension_result", "field": "source_self_value", "type": "numeric(18,2)", "editable": true}, {"family": "dimension_result", "field": "source_m_item_value", "type": "numeric(18,2)", "editable": true}, {"family": "dimension_result", "field": "source_item_value", "type": "numeric(18,2)", "editable": true}, {"family": "dimension_result", "field": "source_x_item_value", "type": "numeric(18,2)", "editable": true}, {"family": "dimension_result", "field": "source_c_item_value", "type": "numeric(18,2)", "editable": true}, {"family": "dimension_result", "field": "source_self_grade", "type": "varchar(12)", "editable": false}, {"family": "dimension_result", "field": "source_ass_grade", "type": "varchar(12)", "editable": false}, {"family": "dimension_result", "field": "source_appraisal", "type": "varchar(200)", "editable": true}, {"family": "master_result", "field": "source_master_id", "type": "integer", "editable": false}, {"family": "master_result", "field": "source_session_id", "type": "integer", "editable": false}, {"family": "master_result", "field": "source_person_code", "type": "varchar(10)", "editable": false}, {"family": "master_result", "field": "source_self_grade", "type": "varchar(12)", "editable": false}, {"family": "master_result", "field": "source_ass_grade", "type": "varchar(12)", "editable": false}, {"family": "master_result", "field": "source_self_value", "type": "numeric(18,2)", "editable": false}, {"family": "master_result", "field": "source_item_value", "type": "numeric(18,2)", "editable": false}, {"family": "master_result", "field": "source_m_item_value", "type": "numeric(18,0)", "editable": false}, {"family": "master_result", "field": "source_x_item_value", "type": "numeric(18,0)", "editable": false}, {"family": "master_result", "field": "source_c_item_value", "type": "numeric(18,0)", "editable": false}, {"family": "master_result", "field": "source_master_value", "type": "numeric(18,2)", "editable": true}, {"family": "master_result", "field": "source_timekeep_value", "type": "numeric(18,2)", "editable": true}, {"family": "master_result", "field": "source_bonus_value", "type": "numeric(18,2)", "editable": true}, {"family": "master_result", "field": "source_total_value", "type": "numeric(18,2)", "editable": false}, {"family": "master_result", "field": "source_self_appraisal", "type": "varchar(500)", "editable": true}, {"family": "master_result", "field": "source_appraisal", "type": "varchar(500)", "editable": true}, {"family": "master_result", "field": "source_pay", "type": "numeric(19,4)", "editable": true}, {"family": "master_result", "field": "source_assessment_person", "type": "varchar(50)", "editable": false}, {"family": "master_result", "field": "source_recorded_at", "type": "timestamp without time zone", "editable": false}, {"family": "master_result", "field": "source_operator_code", "type": "varchar(10)", "editable": false}, {"family": "master_result", "field": "source_description", "type": "varchar(500)", "editable": true}]'::jsonb) a WHERE a->>'family'=f AND a->>'field'=k;
 IF typ IS NULL OR (editable AND NOT allowed) THEN RETURN false;END IF;
 IF v='null'::jsonb THEN RETURN true;END IF;
 IF typ='boolean' THEN RETURN jsonb_typeof(v)='boolean';END IF;
 IF jsonb_typeof(v) IS DISTINCT FROM 'string' THEN RETURN false;END IF;
 IF typ='integer' THEN RETURN v#>>'{}' ~ '^-?[0-9]+$' AND (v#>>'{}')::numeric BETWEEN -2147483648 AND 2147483647;END IF;
 IF typ LIKE 'numeric%' THEN RETURN v#>>'{}' ~ CASE WHEN typ='numeric(19,4)' THEN '^-?[0-9]+([.][0-9]{1,4})?$' WHEN typ='numeric(18,0)' THEN '^-?[0-9]+$' ELSE '^-?[0-9]+([.][0-9]{1,2})?$' END AND abs((v#>>'{}')::numeric)<CASE WHEN typ='numeric(19,4)' THEN 1000000000000000::numeric WHEN typ='numeric(18,0)' THEN 1000000000000000000::numeric ELSE 10000000000000000::numeric END;END IF;
 IF typ LIKE 'varchar%' THEN RETURN length(v#>>'{}')<=substring(typ FROM '[0-9]+')::int;END IF;
 RETURN v#>>'{}' ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{6}$';
EXCEPTION WHEN OTHERS THEN RETURN false;
END $_$;



--
-- Name: hr_performance_source_generation(character varying, character varying, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_source_generation(t character varying, p character varying, k text, s uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
WITH selected AS (
 SELECT migration_batch_id,source_identity_sha256::text identity,id,legacy_template_profile_id profile_id,source_session_id session_id,source_person_code person_code FROM public.hr_performance_legacy_master_result WHERE k='review' AND id=s AND tenant_id=t AND park_id=p
 UNION ALL SELECT migration_batch_id,source_identity_sha256::text,id,id,NULL,NULL FROM public.hr_performance_legacy_template_profile WHERE k='template' AND id=s AND tenant_id=t AND park_id=p
),facts AS (
SELECT 'template_profile'::text family,'dbo.assessmentcode'::text source_table,'hr_performance_legacy_template_profile'::text target_table,f.id,f.migration_batch_id,f.legacy_record_map_id,f.source_identity_sha256::text identity,f.source_row_sha256::text row_hash,jsonb_build_object('source_assessment',f.source_assessment::text,'source_assessment_name',f.source_assessment_name::text,'source_department',f.source_department::text,'source_m_percent',f.source_m_percent::text,'source_t_percent',f.source_t_percent::text,'source_x_percent',f.source_x_percent::text,'source_c_percent',f.source_c_percent::text,'source_s_percent',f.source_s_percent::text,'source_timekeep',f.source_timekeep,'source_bonus',f.source_bonus,'source_master',f.source_master) values FROM public.hr_performance_legacy_template_profile f WHERE f.tenant_id=t AND f.park_id=p AND f.migration_batch_id=(SELECT migration_batch_id FROM selected)
 UNION ALL
SELECT 'level_rule'::text family,'dbo.assgradecode'::text source_table,'hr_performance_legacy_level_rule'::text target_table,f.id,f.migration_batch_id,f.legacy_record_map_id,f.source_identity_sha256::text identity,f.source_row_sha256::text row_hash,jsonb_build_object('source_ass_grade',f.source_ass_grade::text,'source_description',f.source_description::text,'source_my_order',f.source_my_order::text,'source_assessment_id',f.source_assessment_id::text,'source_min_value',f.source_min_value::text,'source_max_value',f.source_max_value::text) values FROM public.hr_performance_legacy_level_rule f WHERE f.tenant_id=t AND f.park_id=p AND f.migration_batch_id=(SELECT migration_batch_id FROM selected)
 UNION ALL
SELECT 'dimension_profile'::text family,'dbo.assitem'::text source_table,'hr_performance_legacy_dimension_profile'::text target_table,f.id,f.migration_batch_id,f.legacy_record_map_id,f.source_identity_sha256::text identity,f.source_row_sha256::text row_hash,jsonb_build_object('source_item_id',f.source_item_id::text,'source_assessment_id',f.source_assessment_id::text,'source_item_name',f.source_item_name::text,'source_full_value',f.source_full_value::text,'source_my_order',f.source_my_order::text) values FROM public.hr_performance_legacy_dimension_profile f WHERE f.tenant_id=t AND f.park_id=p AND f.migration_batch_id=(SELECT migration_batch_id FROM selected)
 UNION ALL
SELECT 'dimension_level_guide'::text family,'dbo.assitemgradedes'::text source_table,'hr_performance_legacy_dimension_level_guide'::text target_table,f.id,f.migration_batch_id,f.legacy_record_map_id,f.source_identity_sha256::text identity,f.source_row_sha256::text row_hash,jsonb_build_object('source_guide_id',f.source_guide_id::text,'source_item_id',f.source_item_id::text,'source_grade',f.source_grade::text,'source_description',f.source_description::text,'source_min_value',f.source_min_value::text,'source_max_value',f.source_max_value::text,'source_my_order',f.source_my_order::text) values FROM public.hr_performance_legacy_dimension_level_guide f WHERE f.tenant_id=t AND f.park_id=p AND f.migration_batch_id=(SELECT migration_batch_id FROM selected)
 UNION ALL
SELECT 'dimension_result'::text family,'dbo.assessmentdetail'::text source_table,'hr_performance_legacy_dimension_result'::text target_table,f.id,f.migration_batch_id,f.legacy_record_map_id,f.source_identity_sha256::text identity,f.source_row_sha256::text row_hash,jsonb_build_object('source_detail_id',f.source_detail_id::text,'source_session_id',f.source_session_id::text,'source_person_code',f.source_person_code::text,'source_item_id',f.source_item_id::text,'source_self_value',f.source_self_value::text,'source_m_item_value',f.source_m_item_value::text,'source_item_value',f.source_item_value::text,'source_x_item_value',f.source_x_item_value::text,'source_c_item_value',f.source_c_item_value::text,'source_self_grade',f.source_self_grade::text,'source_ass_grade',f.source_ass_grade::text,'source_appraisal',f.source_appraisal::text) values FROM public.hr_performance_legacy_dimension_result f WHERE f.tenant_id=t AND f.park_id=p AND f.migration_batch_id=(SELECT migration_batch_id FROM selected)
 UNION ALL
SELECT 'master_result'::text family,'dbo.assessmentmaster'::text source_table,'hr_performance_legacy_master_result'::text target_table,f.id,f.migration_batch_id,f.legacy_record_map_id,f.source_identity_sha256::text identity,f.source_row_sha256::text row_hash,jsonb_build_object('source_master_id',f.source_master_id::text,'source_session_id',f.source_session_id::text,'source_person_code',f.source_person_code::text,'source_self_grade',f.source_self_grade::text,'source_ass_grade',f.source_ass_grade::text,'source_self_value',f.source_self_value::text,'source_item_value',f.source_item_value::text,'source_m_item_value',f.source_m_item_value::text,'source_x_item_value',f.source_x_item_value::text,'source_c_item_value',f.source_c_item_value::text,'source_master_value',f.source_master_value::text,'source_timekeep_value',f.source_timekeep_value::text,'source_bonus_value',f.source_bonus_value::text,'source_total_value',f.source_total_value::text,'source_self_appraisal',f.source_self_appraisal::text,'source_appraisal',f.source_appraisal::text,'source_pay',f.source_pay::text,'source_assessment_person',f.source_assessment_person::text,'source_recorded_at',to_char(f.source_recorded_at,'YYYY-MM-DD"T"HH24:MI:SS.US'),'source_operator_code',f.source_operator_code::text,'source_description',f.source_description::text) values FROM public.hr_performance_legacy_master_result f WHERE f.tenant_id=t AND f.park_id=p AND f.migration_batch_id=(SELECT migration_batch_id FROM selected)
),evidence AS (
 SELECT f.*,jsonb_build_object('id',m.id,'batchId',m.batch_id,'sourceSystem',m.source_system,'sourceTable',m.source_table,'sourcePkCanonical',m.source_pk_canonical,'sourceIdentitySha256',m.source_identity_sha256,'sourceRowSha256',m.source_row_sha256,'targetTable',m.target_table,'targetId',m.target_id,'mappingStatus',m.mapping_status,'isActive',m.is_active) map,
 COALESCE(m.batch_id=f.migration_batch_id AND m.source_system='yuzhou-v10' AND m.source_table=f.source_table AND m.source_pk_canonical='sha256:'||f.identity AND m.source_identity_sha256=f.identity AND m.source_row_sha256=f.row_hash AND m.target_table=f.target_table AND m.target_id=f.id AND m.mapping_status='verified' AND m.is_active,false) valid
 FROM facts f LEFT JOIN public.legacy_record_map m ON m.id=f.legacy_record_map_id
),record_set AS (
 SELECT *,jsonb_build_object('family',family,'identitySha256',identity,'sourceFactId',id,'values',values) record FROM evidence
),batch AS (
 SELECT jsonb_build_object('id',b.id,'runId',b.run_id,'sourceSystem',b.source_system,'sourceSnapshotSha256',b.source_snapshot_sha256,'targetDatabase',b.target_database,'phase',b.phase,'status',b.status,'executionContext',b.execution_context,'productionImportPhase',b.production_import_phase) evidence
 FROM public.migration_batch b WHERE b.id=(SELECT migration_batch_id FROM selected) AND b.source_system='yuzhou-v10' AND b.execution_context='production_import' AND b.production_import_phase='T0' AND b.target_database=current_database() AND b.status='succeeded'
),complete AS (
 SELECT jsonb_build_object('schemaVersion',1,'batch',(SELECT evidence FROM batch),'facts',COALESCE(jsonb_agg(record||jsonb_build_object('sourceRowSha256',row_hash,'map',map) ORDER BY family COLLATE "C",identity COLLATE "C",id),'[]'::jsonb)) content FROM record_set
),baseline AS (
 SELECT jsonb_build_object('schemaVersion',1,'records',COALESCE(jsonb_agg(record ORDER BY family COLLATE "C",identity COLLATE "C",id),'[]'::jsonb),'binding',jsonb_build_object('employeeId',NULL,'orgId',NULL,'startDate',NULL,'endDate',NULL,'businessPeriodRef',NULL),'definition',NULL,'workflow',NULL) snapshot FROM record_set
 WHERE family IN('level_rule','dimension_profile','dimension_level_guide') OR (family='template_profile' AND (k='review' OR id=(SELECT profile_id FROM selected))) OR (k='review' AND family='master_result' AND id=s) OR (k='review' AND family='dimension_result' AND values->>'source_session_id' IS NOT DISTINCT FROM (SELECT session_id::text FROM selected) AND values->>'source_person_code' IS NOT DISTINCT FROM (SELECT person_code FROM selected))
)
SELECT jsonb_build_object('content',content,'manifestSha256',encode(sha256(convert_to(content::text,'UTF8')),'hex'),'snapshot',(SELECT snapshot FROM baseline),'sourceIdentitySha256',(SELECT identity FROM selected),'migrationBatchId',(SELECT migration_batch_id FROM selected),'familyCounts',(SELECT jsonb_object_agg(family,n) FROM (SELECT family,count(*) n FROM facts GROUP BY family) counts)) FROM complete
WHERE EXISTS(SELECT 1 FROM selected) AND EXISTS(SELECT 1 FROM batch) AND NOT EXISTS(SELECT 1 FROM evidence WHERE NOT valid) AND NOT EXISTS(SELECT 1 FROM facts f CROSS JOIN LATERAL jsonb_each(f.values) kv WHERE NOT public.hr_performance_source_field_valid(f.family,kv.key,kv.value))
$$;



--
-- Name: hr_performance_source_head_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_source_head_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE did uuid;t varchar;p varchar;
BEGIN
 did:=(to_jsonb(NEW)->>CASE TG_TABLE_NAME WHEN 'hr_performance_source_draft' THEN 'id' ELSE 'draft_id' END)::uuid;t:=NEW.tenant_id;p:=NEW.park_id;
 IF NOT EXISTS(SELECT 1 FROM public.hr_performance_source_draft d JOIN public.hr_performance_source_draft_revision r ON(r.id,r.tenant_id,r.park_id,r.draft_id)=(d.current_revision_id,d.tenant_id,d.park_id,d.id) WHERE(d.id,d.tenant_id,d.park_id)=(did,t,p) AND r.revision_no=(SELECT max(revision_no) FROM public.hr_performance_source_draft_revision h WHERE h.draft_id=d.id)) THEN RAISE EXCEPTION 'SOURCE_HEAD_MUST_ADVANCE';END IF;RETURN NULL;
END $$;



--
-- Name: hr_performance_source_manifest_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_source_manifest_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE f jsonb;g jsonb;k text;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'SOURCE_MANIFEST_IMMUTABLE';END IF;
 IF NEW.created_at IS DISTINCT FROM transaction_timestamp() OR NOT EXISTS(SELECT 1 FROM public.sys_user WHERE id=NEW.created_by AND tenant_id=NEW.tenant_id) THEN RAISE EXCEPTION 'SOURCE_ACTOR_INVALID';END IF;
 SELECT value INTO f FROM jsonb_array_elements(NEW.content->'facts') WHERE value->>'family' IN('template_profile','master_result') LIMIT 1;
 k:=CASE f->>'family' WHEN 'template_profile' THEN 'template' ELSE 'review' END;
 g:=public.hr_performance_source_generation(NEW.tenant_id,NEW.park_id,k,(f->>'sourceFactId')::uuid);
 IF g IS NULL OR NEW.content IS DISTINCT FROM g->'content' OR NEW.manifest_sha256 IS DISTINCT FROM g->>'manifestSha256' OR NEW.migration_batch_id::text IS DISTINCT FROM g->>'migrationBatchId' THEN RAISE EXCEPTION 'SOURCE_NOT_CURRENT';END IF;
 IF NOT public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance_template:manage') AND NOT public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance:manage') THEN RAISE EXCEPTION 'SOURCE_PERMISSION_REQUIRED';END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_performance_source_revision_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_source_revision_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE d public.hr_performance_source_draft%ROWTYPE;m public.hr_performance_source_manifest%ROWTYPE;prior public.hr_performance_source_draft_revision%ROWTYPE;g jsonb;r jsonb;oldr jsonb;kv record;i integer;pay jsonb;oldpay jsonb;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'SOURCE_REVISION_IMMUTABLE';END IF;
 SELECT * INTO d FROM public.hr_performance_source_draft WHERE id=NEW.draft_id AND tenant_id=NEW.tenant_id AND park_id=NEW.park_id FOR UPDATE;
 IF d.id IS NULL OR NEW.created_at IS DISTINCT FROM transaction_timestamp() OR NOT public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,CASE d.kind WHEN 'template' THEN 'hr:performance_template:manage' ELSE 'hr:performance:manage' END) THEN RAISE EXCEPTION 'SOURCE_PERMISSION_REQUIRED';END IF;
 SELECT * INTO m FROM public.hr_performance_source_manifest WHERE id=NEW.manifest_id AND tenant_id=NEW.tenant_id AND park_id=NEW.park_id;
 IF d.kind='template' AND NEW.snapshot->'binding'->>'employeeId' IS NOT NULL THEN RAISE EXCEPTION 'SOURCE_PERMISSION_REQUIRED';END IF;
 IF m.id IS NULL OR NOT public.hr_performance_source_snapshot_valid(NEW.snapshot,NEW.tenant_id,NEW.park_id) THEN RAISE EXCEPTION 'SOURCE_SNAPSHOT_INVALID';END IF;
 IF NEW.previous_revision_id IS NULL THEN
 IF NEW.origin<>'source' OR NEW.revision_no<>1 OR NEW.reason<>'source intake' OR d.current_revision_id<>NEW.id OR EXISTS(SELECT 1 FROM public.hr_performance_source_draft_revision WHERE draft_id=d.id) THEN RAISE EXCEPTION 'SOURCE_ORIGIN_INVALID';END IF;
 ELSE
 SELECT * INTO prior FROM public.hr_performance_source_draft_revision WHERE id=NEW.previous_revision_id AND draft_id=d.id AND tenant_id=d.tenant_id AND park_id=d.park_id;
 IF prior.id IS NULL OR d.current_revision_id<>prior.id OR NEW.revision_no<>prior.revision_no+1 OR NEW.origin='source' THEN RAISE EXCEPTION 'STALE_REVISION';END IF;
 END IF;
 IF NEW.origin IN('source','refresh') THEN
 -- STABLE helper shares this INSERT statement's snapshot, including reused manifests.
 g:=public.hr_performance_source_generation(NEW.tenant_id,NEW.park_id,d.kind,NEW.source_fact_id);
 IF g IS NULL OR g->'content' IS DISTINCT FROM m.content OR g->>'manifestSha256' IS DISTINCT FROM m.manifest_sha256 OR g->'snapshot' IS DISTINCT FROM NEW.snapshot OR g->>'sourceIdentitySha256' IS DISTINCT FROM d.source_identity_sha256 OR g->>'migrationBatchId' IS DISTINCT FROM m.migration_batch_id::text THEN RAISE EXCEPTION 'SOURCE_NOT_CURRENT';END IF;
 IF NEW.origin='refresh' AND (NEW.manifest_id=prior.manifest_id OR EXISTS(SELECT 1 FROM public.hr_performance_source_draft_revision WHERE draft_id=d.id AND origin='human')) THEN RAISE EXCEPTION 'HUMAN_REFRESH_CONFLICT';END IF;
 ELSE
 IF NEW.manifest_id<>prior.manifest_id OR NEW.source_fact_id<>prior.source_fact_id OR NEW.snapshot=prior.snapshot OR jsonb_array_length(NEW.snapshot->'records')<>jsonb_array_length(prior.snapshot->'records') THEN RAISE EXCEPTION 'SOURCE_HUMAN_IDENTITY_INVALID';END IF;
 FOR i IN 0..jsonb_array_length(NEW.snapshot->'records')-1 LOOP
 r:=NEW.snapshot->'records'->i;oldr:=prior.snapshot->'records'->i;
 IF r-'values' IS DISTINCT FROM oldr-'values' THEN RAISE EXCEPTION 'SOURCE_HUMAN_IDENTITY_INVALID';END IF;
 FOR kv IN SELECT * FROM jsonb_each(r->'values') LOOP IF kv.value IS DISTINCT FROM oldr->'values'->kv.key AND NOT public.hr_performance_source_field_valid(r->>'family',kv.key,kv.value,true) THEN RAISE EXCEPTION 'SOURCE_FIXED_FIELD';END IF;END LOOP;
 END LOOP;
 END IF;
 SELECT value->'values'->'source_pay' INTO pay FROM jsonb_array_elements(NEW.snapshot->'records') WHERE value->>'family'='master_result';
 SELECT value->'values'->'source_pay' INTO oldpay FROM jsonb_array_elements(prior.snapshot->'records') WHERE value->>'family'='master_result';
 IF d.kind='review' AND ((NEW.origin='source' AND pay IS DISTINCT FROM 'null'::jsonb) OR (NEW.origin<>'source' AND pay IS DISTINCT FROM oldpay)) AND NOT (public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance:read') AND public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:performance:manage') AND public.hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.created_by,'hr:compensation:manage')) THEN RAISE EXCEPTION 'SOURCE_SALARY_PERMISSION_REQUIRED';END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_performance_source_snapshot_valid(jsonb, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_source_snapshot_valid(s jsonb, t character varying, p character varying) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE b jsonb;r jsonb;kv record;expected int;
BEGIN
 IF jsonb_typeof(s) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(s))<>5 OR NOT s ?& ARRAY['schemaVersion','records','binding','definition','workflow'] OR s->'schemaVersion'<>'1'::jsonb OR jsonb_typeof(s->'records') IS DISTINCT FROM 'array' THEN RETURN false;END IF;
 b:=s->'binding';IF jsonb_typeof(b) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(b))<>5 OR NOT b ?& ARRAY['employeeId','orgId','startDate','endDate','businessPeriodRef'] THEN RETURN false;END IF;
 IF b->>'employeeId' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.hr_employee WHERE id=(b->>'employeeId')::uuid AND tenant_id=t AND park_id=p AND NOT is_deleted) THEN RETURN false;END IF;
 IF b->>'orgId' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.sys_org WHERE id=(b->>'orgId')::uuid AND tenant_id=t AND park_id=p AND NOT is_deleted AND status='enabled') THEN RETURN false;END IF;
 FOR kv IN SELECT * FROM jsonb_each(b) LOOP
 IF kv.value='null'::jsonb THEN CONTINUE;END IF;
 IF jsonb_typeof(kv.value)<>'string' THEN RETURN false;END IF;
 IF kv.key IN('startDate','endDate') AND (kv.value#>>'{}' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR to_char((kv.value#>>'{}')::date,'YYYY-MM-DD')<>kv.value#>>'{}') THEN RETURN false;END IF;
 END LOOP;
 IF b->>'startDate'>b->>'endDate' OR (b->>'businessPeriodRef' IS NOT NULL AND(length(btrim(b->>'businessPeriodRef'))=0 OR length(b->>'businessPeriodRef')>120)) THEN RETURN false;END IF;
 IF s->'definition'<>'null'::jsonb AND NOT public.hr_performance_channel_config_valid_v1(s->'definition') THEN RETURN false;END IF;
 IF s->'workflow'<>'null'::jsonb AND (s->'definition'='null'::jsonb OR NOT public.hr_performance_channel_workflow_valid(s->'workflow',s->'definition',false)) THEN RETURN false;END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(s->'records') LOOP
 IF jsonb_typeof(r) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(r))<>4 OR NOT r ?& ARRAY['family','identitySha256','sourceFactId','values'] OR r->>'identitySha256' !~ '^[0-9a-f]{64}$' OR jsonb_typeof(r->'values') IS DISTINCT FROM 'object' THEN RETURN false;END IF;
 SELECT CASE r->>'family' WHEN 'template_profile' THEN 11 WHEN 'level_rule' THEN 6 WHEN 'dimension_profile' THEN 5 WHEN 'dimension_level_guide' THEN 7 WHEN 'dimension_result' THEN 12 WHEN 'master_result' THEN 21 ELSE 0 END INTO expected;
 IF expected=0 OR (SELECT count(*) FROM jsonb_object_keys(r->'values'))<>expected THEN RETURN false;END IF;
 FOR kv IN SELECT * FROM jsonb_each(r->'values') LOOP IF NOT public.hr_performance_source_field_valid(r->>'family',kv.key,kv.value) THEN RETURN false;END IF;END LOOP;
 END LOOP;RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $_$;



--
-- Name: hr_performance_submission_insert_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_submission_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ DECLARE ce record; cycle_snapshot jsonb; expected numeric; channel_review record;channel_input jsonb;channel_result jsonb;channel_actor uuid; BEGIN
 SELECT x.*,c.template_snapshot INTO channel_review FROM hr_performance_cycle_employee x JOIN hr_performance_review_cycle c ON(c.id,c.tenant_id,c.park_id)=(x.cycle_id,x.tenant_id,x.park_id) WHERE(x.id,x.tenant_id,x.park_id)=(NEW.cycle_employee_id,NEW.tenant_id,NEW.park_id) FOR UPDATE OF x,c;
 IF NEW.calculation_mode IS DISTINCT FROM channel_review.calculation_mode THEN RAISE EXCEPTION 'submission mode mismatch';END IF;
 IF channel_review.calculation_mode='five_channel_v1' THEN
  IF channel_review.status IS DISTINCT FROM (CASE NEW.submission_type WHEN 'self' THEN 'self_review' WHEN 'manager' THEN 'manager_review' END) OR NEW.input_revision_id IS DISTINCT FROM channel_review.current_input_revision_id THEN RAISE EXCEPTION 'submission input/stage mismatch';END IF;
  SELECT id INTO channel_actor FROM hr_employee WHERE(tenant_id,park_id,user_id)=(NEW.tenant_id,NEW.park_id,NEW.actor_user_id) AND NOT is_deleted ORDER BY id LIMIT 1;
  IF NEW.actor_employee_id IS DISTINCT FROM channel_actor OR NOT hr_performance_channel_actor_has(NEW.tenant_id,NEW.park_id,NEW.actor_user_id,CASE NEW.submission_type WHEN 'self' THEN 'hr:performance:self_review' ELSE 'hr:performance:manager_review' END) OR (NEW.submission_type='self' AND channel_actor IS DISTINCT FROM channel_review.employee_id) OR (NEW.submission_type='manager' AND (channel_actor IS NULL OR channel_actor=channel_review.employee_id OR NOT EXISTS(SELECT 1 FROM hr_employee e WHERE e.id=channel_review.employee_id AND e.manager_employee_id=channel_actor))) THEN RAISE EXCEPTION 'submission actor mismatch';END IF;
  SELECT input INTO channel_input FROM hr_performance_channel_input_revision WHERE(id,tenant_id,park_id,cycle_employee_id)=(NEW.input_revision_id,NEW.tenant_id,NEW.park_id,NEW.cycle_employee_id);
  IF NOT hr_performance_channel_stage_complete(channel_review.template_snapshot,channel_input,channel_review.status) THEN RAISE EXCEPTION 'stage input is incomplete';END IF;
  channel_result:=hr_performance_channel_calculate(channel_review.template_snapshot,channel_input,NEW.input_revision_id);
  IF NEW.computed_score IS DISTINCT FROM(channel_result->>'score')::numeric OR NEW.calculation_evidence IS DISTINCT FROM channel_result THEN RAISE EXCEPTION 'channel submission evidence mismatch';END IF;RETURN NEW;
 END IF;


 SELECT x.*,c.template_snapshot INTO ce FROM hr_performance_cycle_employee x JOIN hr_performance_review_cycle c ON(c.id,c.tenant_id,c.park_id)=(x.cycle_id,x.tenant_id,x.park_id) WHERE x.id=NEW.cycle_employee_id AND x.tenant_id=NEW.tenant_id AND x.park_id=NEW.park_id FOR UPDATE OF x,c;
 IF ce.id IS NULL OR (NEW.submission_type='self' AND ce.status<>'self_review') OR (NEW.submission_type='manager' AND ce.status<>'manager_review') THEN RAISE EXCEPTION 'performance submission is outside its stage'; END IF;
 expected:=hr_performance_snapshot_score(ce.template_snapshot,NEW.dimension_scores);
 IF NEW.computed_score<>expected THEN RAISE EXCEPTION 'performance submission score is not reproducible'; END IF;
 RETURN NEW;END $$;



--
-- Name: hr_performance_template_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_template_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'performance template is immutable'; END IF;
 IF (NEW.tenant_id,NEW.park_id,NEW.id,NEW.template_code,NEW.template_name,NEW.create_by,NEW.create_time,NEW.is_deleted) IS DISTINCT FROM (OLD.tenant_id,OLD.park_id,OLD.id,OLD.template_code,OLD.template_name,OLD.create_by,OLD.create_time,OLD.is_deleted) THEN RAISE EXCEPTION 'performance template identity is immutable'; END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_performance_threshold_snapshot_grade_v1(numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_threshold_snapshot_grade_v1(p_total numeric, p_levels jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  row_value jsonb;
  field_value jsonb;
  threshold numeric;
  winning_min numeric;
  winning_grade text;
  winning_count bigint := 0;
  result_status text;
BEGIN
  IF jsonb_typeof(p_levels) IS DISTINCT FROM 'array'
     OR (p_total IS NOT NULL AND (p_total::text IN ('NaN','Infinity','-Infinity') OR scale(p_total) > 2)) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Invalid grade snapshot shape or total';
  END IF;
  FOR row_value IN SELECT value FROM jsonb_array_elements(p_levels) LOOP
    IF jsonb_typeof(row_value) IS DISTINCT FROM 'object'
       OR NOT row_value ?& ARRAY['id','grade','minValue']
       OR row_value - ARRAY['id','grade','minValue'] <> '{}'::jsonb
       OR jsonb_typeof(row_value -> 'id') IS DISTINCT FROM 'string'
       OR length(row_value ->> 'id') NOT BETWEEN 1 AND 128
       OR jsonb_typeof(row_value -> 'grade') IS DISTINCT FROM 'string'
       OR length(row_value ->> 'grade') > 64 THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Invalid grade candidate';
    END IF;
    field_value := row_value -> 'minValue';
    IF field_value <> 'null'::jsonb THEN
      IF jsonb_typeof(field_value) <> 'string' OR (field_value #>> '{}') !~ '^-?[0-9]+([.][0-9]{1,2})?$' THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Invalid grade threshold';
      END IF;
      threshold := (field_value #>> '{}')::numeric(18,2);
      IF threshold <= p_total THEN
        IF winning_min IS NULL OR threshold > winning_min THEN
          winning_min := threshold; winning_count := 1; winning_grade := row_value ->> 'grade';
        ELSIF threshold = winning_min THEN
          winning_count := winning_count + 1;
        END IF;
      END IF;
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_levels) GROUP BY value ->> 'id' HAVING count(*) > 1) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Duplicate grade candidate identity';
  END IF;
  result_status := CASE WHEN p_total IS NULL THEN 'TOTAL_UNAVAILABLE'
    WHEN winning_count=0 THEN 'NO_ELIGIBLE_GRADE'
    WHEN winning_count>1 THEN 'AMBIGUOUS_TOP_THRESHOLD' ELSE 'RESOLVED' END;
  RETURN jsonb_build_object('status',result_status,
    'expectedGrade',CASE WHEN winning_count=1 THEN winning_grade END,
    'winningMinValue',winning_min::text,'winningCandidateCount',winning_count);
EXCEPTION WHEN numeric_value_out_of_range THEN
  RAISE EXCEPTION USING ERRCODE='22003', MESSAGE='Grade snapshot numeric range exceeded';
END
$_$;



--
-- Name: hr_performance_version_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_version_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ DECLARE dimension_weight numeric; level_count integer; level_invalid boolean; BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'performance template version is immutable'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.calculation_mode='five_channel_v1' AND NEW.status<>'draft' THEN RAISE EXCEPTION 'five-channel definitions are draft only'; END IF;
  RETURN NEW;
 END IF;
 IF (NEW.id,NEW.calculation_mode) IS DISTINCT FROM (OLD.id,OLD.calculation_mode) THEN RAISE EXCEPTION 'performance version identity is immutable'; END IF;
 IF (NEW.tenant_id,NEW.park_id,NEW.template_id,NEW.version_no,NEW.version_name,NEW.total_weight,NEW.create_by,NEW.create_time) IS DISTINCT FROM (OLD.tenant_id,OLD.park_id,OLD.template_id,OLD.version_no,OLD.version_name,OLD.total_weight,OLD.create_by,OLD.create_time) THEN RAISE EXCEPTION 'performance template version identity is immutable'; END IF;
 IF OLD.status='published' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'published performance configuration is immutable'; END IF;
 IF NEW.calculation_mode='five_channel_v1' THEN
  IF NEW.status NOT IN('draft','published') THEN RAISE EXCEPTION 'invalid channel version state';END IF;
  IF NEW.status='published' AND NOT EXISTS(SELECT 1 FROM hr_performance_channel_workflow_revision w JOIN hr_performance_channel_definition_revision d ON d.id=w.definition_revision_id WHERE(w.id,w.tenant_id,w.park_id,w.template_version_id)=(NEW.channel_workflow_revision_id,NEW.tenant_id,NEW.park_id,NEW.id) AND d.id=NEW.channel_definition_revision_id AND hr_performance_channel_workflow_valid(w.policy,d.config,true)) THEN RAISE EXCEPTION 'complete frozen workflow policy required';END IF;
  IF NEW.status='published' AND (NOT has_function_privilege(current_user,'hr_performance_five_channel_snapshot_total_v1(jsonb,jsonb,jsonb)','EXECUTE') OR NOT has_function_privilege(current_user,'hr_performance_threshold_snapshot_grade_v1(numeric,jsonb)','EXECUTE')) THEN RAISE EXCEPTION 'channel calculation execution permission required';END IF;
  IF NEW.channel_definition_revision_id IS DISTINCT FROM OLD.channel_definition_revision_id AND NOT EXISTS(SELECT 1 FROM hr_performance_channel_definition_revision r WHERE (r.id,r.tenant_id,r.park_id,r.template_version_id,r.previous_revision_id)=(NEW.channel_definition_revision_id,NEW.tenant_id,NEW.park_id,NEW.id,OLD.channel_definition_revision_id)) THEN RAISE EXCEPTION 'invalid definition successor'; END IF;
 END IF;
 IF NEW.channel_workflow_revision_id IS DISTINCT FROM OLD.channel_workflow_revision_id AND NOT EXISTS(SELECT 1 FROM hr_performance_channel_workflow_revision w WHERE(w.id,w.tenant_id,w.park_id,w.template_version_id)=(NEW.channel_workflow_revision_id,NEW.tenant_id,NEW.park_id,NEW.id) AND w.previous_revision_id IS NOT DISTINCT FROM OLD.channel_workflow_revision_id AND w.definition_revision_id=NEW.channel_definition_revision_id) THEN RAISE EXCEPTION 'invalid workflow successor';END IF;
 IF NEW.status IS DISTINCT FROM OLD.status THEN
  IF OLD.status<>'draft' OR NEW.status<>'published' OR NEW.published_at IS NULL THEN RAISE EXCEPTION 'invalid performance template transition'; END IF;
  IF NEW.calculation_mode='five_channel_v1' THEN RETURN NEW;END IF;
  SELECT COALESCE(sum(weight),0) INTO dimension_weight FROM hr_performance_template_dimension WHERE tenant_id=OLD.tenant_id AND park_id=OLD.park_id AND template_version_id=OLD.id;
  SELECT count(*) INTO level_count FROM hr_performance_template_level WHERE tenant_id=OLD.tenant_id AND park_id=OLD.park_id AND template_version_id=OLD.id;
  SELECT count(*)=0 OR min(score_min)<>0 OR max(score_max)<>100 OR COALESCE(bool_or(score_max<score_min OR (previous_max IS NOT NULL AND score_min<>previous_max+0.01)),false) INTO level_invalid FROM(SELECT score_min,score_max,lag(score_max)OVER(ORDER BY score_min,score_max,level_code)previous_max FROM hr_performance_template_level WHERE tenant_id=OLD.tenant_id AND park_id=OLD.park_id AND template_version_id=OLD.id)levels;
  IF dimension_weight<>OLD.total_weight OR level_count=0 OR level_invalid THEN RAISE EXCEPTION 'performance template children are incomplete'; END IF;
 END IF;
 RETURN NEW;END $$;



--
-- Name: hr_performance_yuzhou_ass_compute_weight_evidence_sha256(uuid, character, integer, integer, integer, uuid, character varying, integer, uuid, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_yuzhou_ass_compute_weight_evidence_sha256(p_master_id uuid, p_source_person_identity_sha256 character, p_source_person_evidence_count integer, p_source_person_assessment_id integer, p_person_template_candidate_count integer, p_person_template_profile_id uuid, p_person_resolution_status character varying, p_detail_template_candidate_count integer, p_detail_template_profile_id uuid, p_detail_resolution_status character varying, p_comparison_status character varying) RETURNS character
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT encode(digest(convert_to(jsonb_build_object(
    'contract','yuzhou-performance-ass-compute-weight-resolution-v1',
    'masterId',p_master_id,
    'sourcePersonIdentitySha256',p_source_person_identity_sha256,
    'sourcePersonEvidenceCount',p_source_person_evidence_count,
    'sourcePersonAssessmentId',p_source_person_assessment_id,
    'personTemplateCandidateCount',p_person_template_candidate_count,
    'personTemplateProfileId',p_person_template_profile_id,
    'personResolutionStatus',p_person_resolution_status,
    'detailTemplateCandidateCount',p_detail_template_candidate_count,
    'detailTemplateProfileId',p_detail_template_profile_id,
    'detailResolutionStatus',p_detail_resolution_status,
    'comparisonStatus',p_comparison_status
  )::text,'UTF8'),'sha256'),'hex')::char(64)
$$;



--
-- Name: hr_performance_yuzhou_ass_compute_weight_expectation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_yuzhou_ass_compute_weight_expectation(p_master_id uuid) RETURNS TABLE(source_person_identity_sha256 character, source_person_evidence_count integer, source_person_assessment_id integer, person_template_candidate_count integer, person_template_profile_id uuid, person_resolution_status character varying, detail_template_candidate_count integer, detail_template_profile_id uuid, detail_resolution_status character varying, comparison_status character varying)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH master_fact AS (
    SELECT master.*,
      hr_performance_yuzhou_person_identity_sha256(master.source_person_code) person_identity
    FROM hr_performance_legacy_master_result master WHERE master.id=p_master_id
  ),
  person_evidence AS (
    SELECT master_fact.*,
      stats.evidence_count,
      CASE WHEN stats.evidence_count=1 THEN stats.assessment_id END assessment_id
    FROM master_fact
    CROSS JOIN LATERAL (
      SELECT count(evidence.id)::integer evidence_count,
        min(evidence.source_assessment_id) assessment_id
      FROM hr_performance_legacy_person_assessment_evidence evidence
      WHERE (evidence.tenant_id,evidence.park_id,evidence.migration_batch_id)=
            (master_fact.tenant_id,master_fact.park_id,master_fact.migration_batch_id)
        AND evidence.source_person_identity_sha256=master_fact.person_identity
    ) stats
  ),
  person_template AS (
    SELECT person_evidence.*,
      stats.candidate_count,
      CASE WHEN stats.candidate_count=1 THEN stats.profile_id END person_profile_id
    FROM person_evidence
    CROSS JOIN LATERAL (
      SELECT count(profile.id)::integer candidate_count,
        min(profile.id::text)::uuid profile_id
      FROM hr_performance_legacy_template_profile profile
      WHERE person_evidence.evidence_count=1
        AND person_evidence.assessment_id IS NOT NULL
        AND (profile.tenant_id,profile.park_id,profile.migration_batch_id,
             profile.source_assessment)=
            (person_evidence.tenant_id,person_evidence.park_id,
             person_evidence.migration_batch_id,person_evidence.assessment_id)
    ) stats
  ),
  detail_template AS (
    SELECT person_template.*,
      stats.candidate_count detail_candidate_count,
      CASE WHEN stats.candidate_count=1 THEN stats.profile_id END detail_profile_id
    FROM person_template
    CROSS JOIN LATERAL (
      SELECT count(candidate.profile_id)::integer candidate_count,
        min(candidate.profile_id::text)::uuid profile_id
      FROM (
        SELECT DISTINCT dimension.legacy_template_profile_id profile_id
        FROM hr_performance_legacy_dimension_result result
        JOIN hr_performance_legacy_dimension_profile dimension
          ON (dimension.id,dimension.tenant_id,dimension.park_id,dimension.migration_batch_id)=
             (result.legacy_dimension_profile_id,result.tenant_id,result.park_id,result.migration_batch_id)
        WHERE (result.tenant_id,result.park_id,result.migration_batch_id)=
              (person_template.tenant_id,person_template.park_id,person_template.migration_batch_id)
          AND result.source_session_id IS NOT DISTINCT FROM person_template.source_session_id
          AND result.source_person_code IS NOT DISTINCT FROM person_template.source_person_code
          AND dimension.legacy_template_profile_id IS NOT NULL
      ) candidate
    ) stats
  ),
  classified AS (
    SELECT detail_template.*,
      CASE
        WHEN person_identity IS NULL THEN 'not_applicable'
        WHEN evidence_count=0 THEN 'evidence_unmatched'
        WHEN evidence_count>1 THEN 'evidence_ambiguous'
        WHEN assessment_id IS NULL THEN 'assessment_missing'
        WHEN candidate_count=0 THEN 'template_unmatched'
        WHEN candidate_count>1 THEN 'template_ambiguous'
        ELSE 'resolved'
      END::varchar person_status,
      CASE
        WHEN detail_candidate_count=0 THEN 'unmatched'
        WHEN detail_candidate_count>1 THEN 'ambiguous'
        ELSE 'resolved'
      END::varchar detail_status
    FROM detail_template
  )
  SELECT person_identity,evidence_count,assessment_id,candidate_count,person_profile_id,
    person_status,detail_candidate_count,detail_profile_id,detail_status,
    CASE
      WHEN person_status<>'resolved' OR detail_status<>'resolved' THEN 'not_comparable'
      WHEN person_profile_id=detail_profile_id THEN 'matched'
      ELSE 'mismatch'
    END::varchar comparison_status
  FROM classified
$$;



--
-- Name: hr_performance_yuzhou_ass_compute_weight_resolution_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_yuzhou_ass_compute_weight_resolution_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_batch public.migration_batch%ROWTYPE;
  v_master public.hr_performance_legacy_master_result%ROWTYPE;
  v_expected record;
  v_expected_evidence char(64);
BEGIN
  IF TG_OP='DELETE' AND (
    (current_setting('yuzhou.ass_compute_weight_rollback_batch_id',true)=OLD.migration_batch_id::text
      AND EXISTS(SELECT 1 FROM public.migration_batch batch WHERE batch.id=OLD.migration_batch_id
        AND batch.execution_context='lab_rehearsal' AND batch.phase='rollback' AND batch.status='running'))
    OR public.hr_yuzhou_performance_person_assessment_production_context_allowed(
      OLD.migration_batch_id,'rollback')
  ) THEN RETURN OLD; END IF;
  IF TG_OP<>'INSERT' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_ASS_COMPUTE_WEIGHT_RESOLUTION_IMMUTABLE';
  END IF;
  SELECT * INTO v_batch FROM public.migration_batch WHERE id=NEW.migration_batch_id FOR SHARE;
  IF NOT FOUND OR v_batch.target_database<>current_database() OR NOT (
    (v_batch.execution_context='lab_rehearsal' AND v_batch.phase='load' AND v_batch.status='running')
    OR public.hr_yuzhou_performance_person_assessment_production_context_allowed(
      NEW.migration_batch_id,'apply')
  ) THEN RAISE EXCEPTION 'HR_PERFORMANCE_ASS_COMPUTE_WEIGHT_BATCH_INVALID'; END IF;
  SELECT * INTO v_master FROM public.hr_performance_legacy_master_result
  WHERE (id,tenant_id,park_id,migration_batch_id)=
    (NEW.legacy_master_result_id,NEW.tenant_id,NEW.park_id,NEW.migration_batch_id);
  IF NOT FOUND THEN RAISE EXCEPTION 'HR_PERFORMANCE_ASS_COMPUTE_WEIGHT_MASTER_MISMATCH'; END IF;
  SELECT * INTO STRICT v_expected
  FROM public.hr_performance_yuzhou_ass_compute_weight_expectation(NEW.legacy_master_result_id);
  IF v_master.legacy_template_profile_id IS DISTINCT FROM v_expected.detail_template_profile_id THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_ASS_COMPUTE_DETAIL_DERIVATION_DRIFT'; END IF;
  IF ROW(NEW.source_person_identity_sha256,NEW.source_person_evidence_count,
      NEW.source_person_assessment_id,NEW.person_template_candidate_count,
      NEW.person_template_profile_id,NEW.person_resolution_status,
      NEW.detail_template_candidate_count,NEW.detail_template_profile_id,
      NEW.detail_resolution_status,NEW.comparison_status)
    IS DISTINCT FROM ROW(v_expected.source_person_identity_sha256,
      v_expected.source_person_evidence_count,v_expected.source_person_assessment_id,
      v_expected.person_template_candidate_count,v_expected.person_template_profile_id,
      v_expected.person_resolution_status,v_expected.detail_template_candidate_count,
      v_expected.detail_template_profile_id,v_expected.detail_resolution_status,
      v_expected.comparison_status) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_ASS_COMPUTE_WEIGHT_RESOLUTION_MISMATCH';
  END IF;
  v_expected_evidence:=public.hr_performance_yuzhou_ass_compute_weight_evidence_sha256(
    NEW.legacy_master_result_id,NEW.source_person_identity_sha256,
    NEW.source_person_evidence_count,NEW.source_person_assessment_id,
    NEW.person_template_candidate_count,NEW.person_template_profile_id,
    NEW.person_resolution_status,NEW.detail_template_candidate_count,
    NEW.detail_template_profile_id,NEW.detail_resolution_status,NEW.comparison_status
  );
  IF NEW.evidence_sha256<>v_expected_evidence THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_ASS_COMPUTE_WEIGHT_EVIDENCE_HASH_MISMATCH'; END IF;
  RETURN NEW;
END$$;



--
-- Name: hr_performance_yuzhou_assert_master_record_map(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_yuzhou_assert_master_record_map(p_map_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_fact hr_performance_legacy_master_result%ROWTYPE;
  v_map legacy_record_map%ROWTYPE;
BEGIN
  SELECT * INTO v_fact FROM hr_performance_legacy_master_result
  WHERE legacy_record_map_id=p_map_id;
  IF NOT FOUND THEN RETURN; END IF;

  SELECT * INTO v_map FROM legacy_record_map WHERE id=p_map_id FOR SHARE;
  IF NOT FOUND
     OR v_map.batch_id<>v_fact.migration_batch_id
     OR v_map.source_system<>'yuzhou-v10'
     OR v_map.source_table<>'dbo.assessmentmaster'
     OR v_map.source_identity_sha256<>v_fact.source_identity_sha256
     OR v_map.source_row_sha256<>v_fact.source_row_sha256
     OR v_map.target_table<>'hr_performance_legacy_master_result'
     OR v_map.target_id<>v_fact.id
     OR v_map.mapping_status NOT IN('loaded','verified')
     OR NOT v_map.is_active THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_MASTER_RECORD_MAP_MISMATCH';
  END IF;
END$$;



--
-- Name: hr_performance_yuzhou_assert_record_map(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_yuzhou_assert_record_map(p_map_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_fact record;
  v_map legacy_record_map%ROWTYPE;
BEGIN
  SELECT fact.*,count(*) OVER() AS fact_count INTO v_fact FROM (
    SELECT legacy_record_map_id,migration_batch_id,id,source_identity_sha256,source_row_sha256,
           'dbo.assessmentcode'::varchar AS source_table,
           'hr_performance_legacy_template_profile'::varchar AS target_table
      FROM hr_performance_legacy_template_profile WHERE legacy_record_map_id=p_map_id
    UNION ALL
    SELECT legacy_record_map_id,migration_batch_id,id,source_identity_sha256,source_row_sha256,
           'dbo.assgradecode','hr_performance_legacy_level_rule'
      FROM hr_performance_legacy_level_rule WHERE legacy_record_map_id=p_map_id
    UNION ALL
    SELECT legacy_record_map_id,migration_batch_id,id,source_identity_sha256,source_row_sha256,
           'dbo.assitem','hr_performance_legacy_dimension_profile'
      FROM hr_performance_legacy_dimension_profile WHERE legacy_record_map_id=p_map_id
    UNION ALL
    SELECT legacy_record_map_id,migration_batch_id,id,source_identity_sha256,source_row_sha256,
           'dbo.assitemgradedes','hr_performance_legacy_dimension_level_guide'
      FROM hr_performance_legacy_dimension_level_guide WHERE legacy_record_map_id=p_map_id
    UNION ALL
    SELECT legacy_record_map_id,migration_batch_id,id,source_identity_sha256,source_row_sha256,
           'dbo.assessmentdetail','hr_performance_legacy_dimension_result'
      FROM hr_performance_legacy_dimension_result WHERE legacy_record_map_id=p_map_id
  ) fact;
  IF NOT FOUND THEN RETURN; END IF;
  IF v_fact.fact_count<>1 THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_RECORD_MAP_COLLISION';
  END IF;

  SELECT * INTO v_map FROM legacy_record_map WHERE id=p_map_id FOR SHARE;
  IF NOT FOUND
     OR v_map.batch_id<>v_fact.migration_batch_id
     OR v_map.source_system<>'yuzhou-v10'
     OR v_map.source_table<>v_fact.source_table
     OR v_map.source_identity_sha256<>v_fact.source_identity_sha256
     OR v_map.source_row_sha256<>v_fact.source_row_sha256
     OR v_map.target_table<>v_fact.target_table
     OR v_map.target_id<>v_fact.id
     OR v_map.mapping_status NOT IN('loaded','verified')
     OR NOT v_map.is_active THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_RECORD_MAP_MISMATCH';
  END IF;
END$$;



--
-- Name: hr_performance_yuzhou_assert_relation_record_map(uuid); Type: FUNCTION; Schema: public; Owner: -
