    FROM hr_performance_legacy_source_person_assignment WHERE legacy_record_map_id=p_map_id
  ) fact;
  IF NOT FOUND THEN RETURN; END IF;
  IF v_fact.fact_count<>1 THEN RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_RELATION_MAP_COLLISION'; END IF;
  SELECT * INTO v_map FROM legacy_record_map WHERE id=p_map_id FOR SHARE;
  IF NOT FOUND OR v_map.batch_id<>v_fact.migration_batch_id
    OR v_map.source_system<>'yuzhou-v10' OR v_map.source_table<>v_fact.source_table
    OR v_map.source_identity_sha256<>v_fact.source_identity_sha256
    OR v_map.source_row_sha256<>v_fact.source_row_sha256 OR v_map.target_table<>v_fact.target_table
    OR v_map.target_id<>v_fact.id OR v_map.mapping_status NOT IN('loaded','verified') OR NOT v_map.is_active THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_RELATION_MAP_MISMATCH';
  END IF;
END$$;



--
-- Name: hr_performance_yuzhou_employee_resolution_reverse_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_yuzhou_employee_resolution_reverse_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM hr_performance_legacy_identity_resolution resolution
    WHERE resolution.target_employee_id=OLD.id) THEN
    RETURN COALESCE(NEW,OLD);
  END IF;
  IF TG_OP='DELETE' OR NEW.is_deleted
    OR ROW(NEW.id,NEW.tenant_id,NEW.park_id) IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.park_id) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_EMPLOYEE_RESOLUTION_REFERENCED';
  END IF;
  RETURN NEW;
END$$;



--
-- Name: hr_performance_yuzhou_identity_resolution_delete_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_yuzhou_identity_resolution_delete_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP='DELETE'
    AND current_setting('yuzhou.performance_identity_resolution_rollback_batch_id',true)=OLD.migration_batch_id::text
    AND (
      EXISTS(SELECT 1 FROM public.migration_batch batch WHERE batch.id=OLD.migration_batch_id
        AND batch.execution_context='lab_rehearsal' AND batch.phase='rollback' AND batch.status='running')
      OR (OLD.fact_kind IN('dimension_result','master_result')
        AND public.hr_yuzhou_performance_fact_identity_context_allowed_v1(OLD.migration_batch_id,'rollback'))
      OR (OLD.fact_kind NOT IN('dimension_result','master_result')
        AND public.hr_yuzhou_performance_relations_production_context_allowed(OLD.migration_batch_id,'rollback'))
    ) THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_IDENTITY_RESOLUTION_IMMUTABLE';
END$$;



--
-- Name: hr_performance_yuzhou_identity_resolution_evidence_sha256(character varying, uuid, character varying, character, character varying, character varying, uuid, uuid, uuid, character varying, character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_yuzhou_identity_resolution_evidence_sha256(p_fact_kind character varying, p_fact_id uuid, p_person_role character varying, p_source_person_identity_sha256 character, p_person_resolution_status character varying, p_person_resolution_reason_code character varying, p_owner_t0_record_map_id uuid, p_target_employee_id uuid, p_session_binding_id uuid, p_cycle_resolution_status character varying, p_cycle_resolution_reason_code character varying, p_target_cycle_employee_id uuid) RETURNS character
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT encode(digest(convert_to(jsonb_build_object(
    'contract','yuzhou-performance-identity-resolution-v1',
    'factKind',p_fact_kind,'factId',p_fact_id,'personRole',p_person_role,
    'sourcePersonIdentitySha256',p_source_person_identity_sha256,
    'personResolutionStatus',p_person_resolution_status,
    'personResolutionReasonCode',p_person_resolution_reason_code,
    'ownerT0RecordMapId',p_owner_t0_record_map_id,'targetEmployeeId',p_target_employee_id,
    'sessionBindingId',p_session_binding_id,'cycleResolutionStatus',p_cycle_resolution_status,
    'cycleResolutionReasonCode',p_cycle_resolution_reason_code,
    'targetCycleEmployeeId',p_target_cycle_employee_id
  )::text,'UTF8'),'sha256'),'hex')::char(64)
$$;



--
-- Name: hr_performance_yuzhou_identity_resolution_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_yuzhou_identity_resolution_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_source_code varchar; v_source_session_id integer; v_fact_batch_id uuid;
  v_expected_identity char(64); v_candidate_count integer;
  v_candidate_map_id uuid; v_candidate_employee_id uuid;
  v_binding hr_performance_legacy_session_binding%ROWTYPE;
  v_cycle_count integer; v_cycle_employee_id uuid;
  v_batch migration_batch%ROWTYPE; v_fact_id uuid;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_IDENTITY_RESOLUTION_IMMUTABLE'; END IF;
  SELECT * INTO v_batch FROM migration_batch WHERE id=NEW.migration_batch_id FOR SHARE;
  IF NOT FOUND OR v_batch.target_database<>current_database() OR NOT (
    (v_batch.execution_context='lab_rehearsal' AND v_batch.phase='load' AND v_batch.status='running')
    OR hr_yuzhou_performance_relations_production_context_allowed(NEW.migration_batch_id,'apply')
  ) THEN RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_IDENTITY_WRITER_BATCH_INVALID'; END IF;

  IF NEW.fact_kind='dimension_result' THEN
    SELECT migration_batch_id,source_person_code,source_session_id
      INTO v_fact_batch_id,v_source_code,v_source_session_id
    FROM hr_performance_legacy_dimension_result
    WHERE (id,tenant_id,park_id)=(NEW.legacy_dimension_result_id,NEW.tenant_id,NEW.park_id);
  ELSIF NEW.fact_kind='master_result' THEN
    SELECT migration_batch_id,source_person_code,source_session_id
      INTO v_fact_batch_id,v_source_code,v_source_session_id
    FROM hr_performance_legacy_master_result
    WHERE (id,tenant_id,park_id)=(NEW.legacy_master_result_id,NEW.tenant_id,NEW.park_id);
  ELSIF NEW.fact_kind='score_source' THEN
    SELECT migration_batch_id,source_person_code,source_session_id
      INTO v_fact_batch_id,v_source_code,v_source_session_id
    FROM hr_performance_legacy_score_source
    WHERE (id,tenant_id,park_id)=(NEW.legacy_score_source_id,NEW.tenant_id,NEW.park_id);
  ELSE
    SELECT migration_batch_id,
      CASE NEW.person_role WHEN 'subject' THEN source_person_code ELSE source_assessor_code END,
      source_session_id INTO v_fact_batch_id,v_source_code,v_source_session_id
    FROM hr_performance_legacy_source_person_assignment
    WHERE (id,tenant_id,park_id)=
      (NEW.legacy_source_person_assignment_id,NEW.tenant_id,NEW.park_id);
  END IF;
  IF NOT FOUND OR v_fact_batch_id<>NEW.migration_batch_id THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_IDENTITY_RESOLUTION_FACT_MISMATCH'; END IF;

  v_expected_identity:=hr_performance_yuzhou_person_identity_sha256(v_source_code);
  IF NEW.source_person_identity_sha256 IS DISTINCT FROM v_expected_identity THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_IDENTITY_RESOLUTION_HASH_MISMATCH'; END IF;
  IF NEW.person_role='assessor' THEN
    IF v_expected_identity IS NULL THEN
      IF NEW.person_resolution_status<>'not_applicable'
        OR NEW.person_resolution_reason_code<>'ASSESSOR_CODE_EMPTY' THEN
        RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_ASSESSOR_EMPTY_REQUIRES_NOT_APPLICABLE'; END IF;
    ELSIF NEW.person_resolution_status<>'semantics_unverified'
      OR NEW.person_resolution_reason_code<>'ASSESSOR_SEMANTICS_UNVERIFIED' THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_ASSESSOR_SEMANTICS_UNVERIFIED';
    END IF;
  ELSIF v_expected_identity IS NULL THEN
    IF NEW.person_resolution_status<>'not_applicable'
      OR NEW.person_resolution_reason_code<>'SUBJECT_CODE_EMPTY' THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_SUBJECT_EMPTY_REQUIRES_NOT_APPLICABLE'; END IF;
  ELSE
    SELECT count(*) INTO v_candidate_count FROM hr_performance_yuzhou_t0_person_candidate(
      NEW.tenant_id,NEW.park_id,v_expected_identity);
    IF v_candidate_count=1 THEN
      SELECT owner_t0_record_map_id,target_employee_id INTO v_candidate_map_id,v_candidate_employee_id
      FROM hr_performance_yuzhou_t0_person_candidate(NEW.tenant_id,NEW.park_id,v_expected_identity);
      IF NEW.person_resolution_status<>'resolved'
        OR NEW.person_resolution_reason_code<>'EXACT_T0_PERSON_MAP'
        OR NEW.owner_t0_record_map_id IS DISTINCT FROM v_candidate_map_id
        OR NEW.target_employee_id IS DISTINCT FROM v_candidate_employee_id THEN
        RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_T0_PERSON_RESOLUTION_MISMATCH'; END IF;
    ELSIF v_candidate_count=0 THEN
      IF NEW.person_resolution_status<>'unmatched'
        OR NEW.person_resolution_reason_code<>'T0_PERSON_MAP_NOT_FOUND' THEN
        RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_T0_PERSON_UNMATCHED_REQUIRED'; END IF;
    ELSE
      IF NEW.person_resolution_status<>'ambiguous'
        OR NEW.person_resolution_reason_code<>'T0_PERSON_MAP_AMBIGUOUS' THEN
        RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_T0_PERSON_AMBIGUOUS_REQUIRED'; END IF;
    END IF;
  END IF;

  SELECT binding.* INTO v_binding
  FROM hr_performance_legacy_session source_session
  JOIN hr_performance_legacy_session_binding binding ON binding.legacy_session_id=source_session.id
  WHERE (source_session.tenant_id,source_session.park_id,source_session.migration_batch_id,
    source_session.source_session_id)=(NEW.tenant_id,NEW.park_id,NEW.migration_batch_id,v_source_session_id);
  IF FOUND THEN
    IF NEW.session_binding_id IS DISTINCT FROM v_binding.id THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_SESSION_BINDING_MISMATCH'; END IF;
  ELSIF NEW.session_binding_id IS NOT NULL THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_SESSION_BINDING_MISMATCH';
  END IF;

  IF NEW.person_role='assessor' OR NEW.person_resolution_status<>'resolved'
    OR v_source_session_id IS NULL THEN
    IF NEW.cycle_resolution_status<>'not_applicable'
      OR NEW.cycle_resolution_reason_code<>(CASE
        WHEN NEW.person_role='assessor' THEN 'ASSESSOR_CYCLE_NOT_APPLICABLE'
        WHEN NEW.person_resolution_status<>'resolved' THEN 'PERSON_UNRESOLVED'
        ELSE 'SESSION_NOT_APPLICABLE' END) THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_CYCLE_NOT_APPLICABLE_REQUIRED'; END IF;
  ELSIF NEW.session_binding_id IS NULL OR v_binding.resolution_status<>'resolved' THEN
    IF NEW.cycle_resolution_status<>'unmatched'
      OR NEW.cycle_resolution_reason_code<>'SESSION_BINDING_UNRESOLVED' THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_SESSION_UNRESOLVED_REQUIRED'; END IF;
  ELSE
    SELECT count(*),(array_agg(id ORDER BY id))[1] INTO v_cycle_count,v_cycle_employee_id
    FROM hr_performance_cycle_employee
    WHERE (tenant_id,park_id,cycle_id,employee_id)=
      (NEW.tenant_id,NEW.park_id,v_binding.target_review_cycle_id,NEW.target_employee_id);
    IF v_cycle_count=1 THEN
      IF NEW.cycle_resolution_status<>'resolved'
        OR NEW.cycle_resolution_reason_code<>'EXACT_CYCLE_EMPLOYEE'
        OR NEW.target_cycle_employee_id IS DISTINCT FROM v_cycle_employee_id THEN
        RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_CYCLE_EMPLOYEE_MISMATCH'; END IF;
    ELSIF v_cycle_count=0 THEN
      IF NEW.cycle_resolution_status<>'unmatched'
        OR NEW.cycle_resolution_reason_code<>'CYCLE_EMPLOYEE_NOT_FOUND' THEN
        RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_CYCLE_EMPLOYEE_UNMATCHED_REQUIRED'; END IF;
    ELSE
      IF NEW.cycle_resolution_status<>'ambiguous'
        OR NEW.cycle_resolution_reason_code<>'CYCLE_EMPLOYEE_AMBIGUOUS' THEN
        RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_CYCLE_EMPLOYEE_AMBIGUOUS_REQUIRED'; END IF;
    END IF;
  END IF;
  v_fact_id:=COALESCE(NEW.legacy_dimension_result_id,NEW.legacy_master_result_id,
    NEW.legacy_score_source_id,NEW.legacy_source_person_assignment_id);
  IF NEW.evidence_sha256<>hr_performance_yuzhou_identity_resolution_evidence_sha256(
    NEW.fact_kind,v_fact_id,NEW.person_role,NEW.source_person_identity_sha256,
    NEW.person_resolution_status,NEW.person_resolution_reason_code,NEW.owner_t0_record_map_id,
    NEW.target_employee_id,NEW.session_binding_id,NEW.cycle_resolution_status,
    NEW.cycle_resolution_reason_code,NEW.target_cycle_employee_id
  ) THEN RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_IDENTITY_EVIDENCE_MISMATCH'; END IF;
  RETURN NEW;
END$$;



--
-- Name: hr_performance_yuzhou_jsonb_exact_keys(jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_yuzhou_jsonb_exact_keys(p_value jsonb, p_keys text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(jsonb_typeof(p_value)='object'
    AND p_value ?& p_keys
    AND NOT EXISTS(
      SELECT 1 FROM jsonb_object_keys(p_value) key
      WHERE NOT key=ANY(p_keys)
    ),false)
$$;



--
-- Name: hr_performance_yuzhou_legacy_fact_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_yuzhou_legacy_fact_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_batch_id uuid:=COALESCE(NEW.migration_batch_id,OLD.migration_batch_id);
  v_rollback_batch text:=current_setting('yuzhou.performance_legacy_rollback_batch_id',true);
BEGIN
  IF TG_OP='DELETE' AND v_rollback_batch=v_batch_id::text THEN
    IF EXISTS(SELECT 1 FROM public.migration_batch batch WHERE batch.id=v_batch_id
      AND batch.target_database=current_database() AND batch.phase='rollback' AND batch.status='running') THEN
      RETURN OLD;
    END IF;
    IF TG_TABLE_NAME IN(
        'hr_performance_legacy_template_profile','hr_performance_legacy_level_rule',
        'hr_performance_legacy_dimension_profile','hr_performance_legacy_dimension_level_guide',
        'hr_performance_legacy_dimension_result','hr_performance_legacy_master_result')
      AND public.hr_yuzhou_performance_facts_production_context_allowed_v1(v_batch_id,'rollback') THEN
      RETURN OLD;
    END IF;
    IF TG_TABLE_NAME IN(
        'hr_performance_legacy_session','hr_performance_legacy_score_source',
        'hr_performance_legacy_source_person_assignment')
      AND public.hr_yuzhou_performance_relations_production_context_allowed(v_batch_id,'rollback') THEN
      RETURN OLD;
    END IF;
  END IF;
  RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_FACT_APPEND_ONLY' USING ERRCODE='55000';
END$$;



--
-- Name: hr_performance_yuzhou_legacy_full_total(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_yuzhou_legacy_full_total(p_master_id uuid) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE WHEN subtotal.value IS NULL THEN NULL ELSE round(
    subtotal.value
      + COALESCE(master.source_master_value,0)
      + COALESCE(master.source_timekeep_value,0)
      + COALESCE(master.source_bonus_value,0),
    2
  ) END
  FROM hr_performance_legacy_master_result master
  CROSS JOIN LATERAL (
    SELECT (
      sum(COALESCE(result.source_self_value,0)) * COALESCE(template.source_s_percent,0) / 100::numeric
    + sum(COALESCE(result.source_m_item_value,0))::numeric(18,0) * COALESCE(template.source_m_percent,0) / 100::numeric
    + sum(COALESCE(result.source_item_value,0)) * COALESCE(template.source_t_percent,0) / 100::numeric
    + sum(COALESCE(result.source_x_item_value,0))::numeric(18,0) * COALESCE(template.source_x_percent,0) / 100::numeric
    + sum(COALESCE(result.source_c_item_value,0))::numeric(18,0) * COALESCE(template.source_c_percent,0) / 100::numeric
    ) AS value
    FROM hr_performance_legacy_template_profile template
    JOIN hr_performance_legacy_dimension_profile dimension
      ON (dimension.tenant_id,dimension.park_id,dimension.migration_batch_id,dimension.legacy_template_profile_id)=
         (template.tenant_id,template.park_id,template.migration_batch_id,template.id)
    JOIN hr_performance_legacy_dimension_result result
      ON (result.tenant_id,result.park_id,result.migration_batch_id,result.legacy_dimension_profile_id)=
         (dimension.tenant_id,dimension.park_id,dimension.migration_batch_id,dimension.id)
    WHERE (template.tenant_id,template.park_id,template.migration_batch_id,template.id)=
          (master.tenant_id,master.park_id,master.migration_batch_id,master.legacy_template_profile_id)
      AND result.source_session_id IS NOT DISTINCT FROM master.source_session_id
      AND result.source_person_code IS NOT DISTINCT FROM master.source_person_code
    GROUP BY template.source_s_percent,template.source_m_percent,template.source_t_percent,
             template.source_x_percent,template.source_c_percent
  ) subtotal
  WHERE master.id=p_master_id
$$;



--
-- Name: hr_performance_yuzhou_legacy_grade_parity(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_yuzhou_legacy_grade_parity(p_master_id uuid) RETURNS TABLE(calculated_total numeric, source_total numeric, expected_ass_grade character varying, source_ass_grade character varying, winning_min_value integer, winning_candidate_count bigint, parity_status text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH master AS (
    SELECT fact.*,
           hr_performance_yuzhou_legacy_full_total(fact.id) AS replayed_total
    FROM hr_performance_legacy_master_result fact
    WHERE fact.id=p_master_id
  ), eligible AS (
    SELECT level.source_ass_grade,level.source_min_value,
           max(level.source_min_value) OVER () AS top_min_value
    FROM master
    JOIN hr_performance_legacy_level_rule level
      ON (level.tenant_id,level.park_id,level.migration_batch_id)=
         (master.tenant_id,master.park_id,master.migration_batch_id)
     AND level.source_min_value<=master.replayed_total
  ), winning AS (
    SELECT source_ass_grade,source_min_value
    FROM eligible
    WHERE source_min_value=top_min_value
  ), choice AS (
    SELECT min(source_ass_grade) AS sole_grade,
           min(source_min_value) AS threshold,
           count(*) AS candidate_count
    FROM winning
  )
  SELECT master.replayed_total,
         master.source_total_value,
         CASE WHEN choice.candidate_count=1 THEN choice.sole_grade END,
         master.source_ass_grade,
         choice.threshold,
         choice.candidate_count,
         CASE
           WHEN master.replayed_total IS NULL THEN 'TOTAL_UNAVAILABLE'
           WHEN choice.candidate_count=0 THEN 'NO_ELIGIBLE_GRADE'
           WHEN choice.candidate_count>1 THEN 'AMBIGUOUS_TOP_THRESHOLD'
           WHEN choice.sole_grade IS NOT DISTINCT FROM master.source_ass_grade
             AND master.replayed_total IS NOT DISTINCT FROM master.source_total_value THEN 'MATCH'
           ELSE 'MISMATCH'
         END
  FROM master
  CROSS JOIN choice
$$;



--
-- Name: hr_performance_yuzhou_person_assessment_evidence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_yuzhou_person_assessment_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_batch public.migration_batch%ROWTYPE;
BEGIN
  IF TG_OP='DELETE' AND (
    (current_setting('yuzhou.ass_compute_weight_rollback_batch_id',true)=OLD.migration_batch_id::text
      AND EXISTS(SELECT 1 FROM public.migration_batch batch WHERE batch.id=OLD.migration_batch_id
        AND batch.execution_context='lab_rehearsal' AND batch.phase='rollback' AND batch.status='running'))
    OR public.hr_yuzhou_performance_person_assessment_production_context_allowed(
      OLD.migration_batch_id,'rollback')
  ) THEN RETURN OLD; END IF;
  IF TG_OP<>'INSERT' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_PERSON_ASSESSMENT_EVIDENCE_IMMUTABLE';
  END IF;
  SELECT * INTO v_batch FROM public.migration_batch WHERE id=NEW.migration_batch_id FOR SHARE;
  IF NOT FOUND OR v_batch.target_database<>current_database() OR NOT (
    (v_batch.execution_context='lab_rehearsal' AND v_batch.phase='load' AND v_batch.status='running')
    OR public.hr_yuzhou_performance_person_assessment_production_context_allowed(
      NEW.migration_batch_id,'apply')
  ) THEN RAISE EXCEPTION 'HR_PERFORMANCE_ASS_COMPUTE_WEIGHT_BATCH_INVALID'; END IF;
  IF NEW.evidence_sha256<>public.hr_performance_yuzhou_person_assessment_evidence_sha256(
      NEW.source_person_identity_sha256,NEW.source_assessment_id) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_PERSON_ASSESSMENT_EVIDENCE_HASH_MISMATCH';
  END IF;
  RETURN NEW;
END$$;



--
-- Name: hr_performance_yuzhou_person_assessment_evidence_sha256(character, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_yuzhou_person_assessment_evidence_sha256(p_source_person_identity_sha256 character, p_source_assessment_id integer) RETURNS character
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT encode(digest(convert_to(jsonb_build_object(
    'contract','yuzhou-performance-person-assessment-v1',
    'sourcePersonIdentitySha256',p_source_person_identity_sha256,
    'sourceAssessmentId',p_source_assessment_id
  )::text,'UTF8'),'sha256'),'hex')::char(64)
$$;



--
-- Name: hr_performance_yuzhou_person_identity_sha256(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_yuzhou_person_identity_sha256(p_source_person_code character varying) RETURNS character
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE WHEN NULLIF(btrim(p_source_person_code),'') IS NULL THEN NULL
    ELSE encode(digest(
      convert_to('dbo.person','UTF8') || decode('00','hex')
      || convert_to(btrim(p_source_person_code),'UTF8'),'sha256'
    ),'hex')::char(64)
  END
$$;



--
-- Name: hr_performance_yuzhou_prepare_master_record_map(uuid, character, character); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_yuzhou_prepare_master_record_map(p_batch_id uuid, p_source_identity_sha256 character, p_source_row_sha256 character) RETURNS TABLE(map_id uuid, fact_id uuid)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_existing legacy_record_map%ROWTYPE;
  v_namespace constant uuid:='4c377793-4707-4adb-b2bb-7d61ecf73157';
BEGIN
  IF p_source_identity_sha256!~'^[0-9a-f]{64}$'
    OR p_source_row_sha256!~'^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_MASTER_WRITER_IDENTITY_INVALID';
  END IF;
  fact_id:=uuid_generate_v5(
    v_namespace,'fact:'||p_batch_id::text||':dbo.assessmentmaster:'||p_source_identity_sha256
  );
  map_id:=uuid_generate_v5(
    v_namespace,'map:'||p_batch_id::text||':dbo.assessmentmaster:'||p_source_identity_sha256
  );

  SELECT * INTO v_existing FROM legacy_record_map
  WHERE source_system='yuzhou-v10'
    AND source_table='dbo.assessmentmaster'
    AND source_identity_sha256=p_source_identity_sha256
    AND is_active
  FOR SHARE;
  IF FOUND THEN
    IF v_existing.id<>map_id OR v_existing.batch_id<>p_batch_id
      OR v_existing.source_row_sha256<>p_source_row_sha256
      OR v_existing.target_table<>'hr_performance_legacy_master_result'
      OR v_existing.target_id<>fact_id
      OR v_existing.mapping_status NOT IN('loaded','verified') THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_MASTER_WRITER_REPLAY_DRIFT';
    END IF;
    RETURN NEXT;
    RETURN;
  END IF;

  INSERT INTO legacy_record_map(
    id,batch_id,source_system,source_table,source_pk_canonical,
    source_identity_sha256,source_row_sha256,target_table,target_id,mapping_status,is_active
  ) VALUES(
    map_id,p_batch_id,'yuzhou-v10','dbo.assessmentmaster',
    'sha256:'||p_source_identity_sha256,p_source_identity_sha256,p_source_row_sha256,
    'hr_performance_legacy_master_result',fact_id,'loaded',true
  );
  RETURN NEXT;
END$_$;



--
-- Name: hr_performance_yuzhou_prepare_record_map(uuid, character varying, character, character, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_yuzhou_prepare_record_map(p_batch_id uuid, p_source_table character varying, p_source_identity_sha256 character, p_source_row_sha256 character, p_target_table character varying) RETURNS TABLE(map_id uuid, fact_id uuid)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_existing legacy_record_map%ROWTYPE;
  v_namespace constant uuid:='4c377793-4707-4adb-b2bb-7d61ecf73157';
BEGIN
  IF p_source_table NOT IN(
    'dbo.assessmentcode','dbo.assgradecode','dbo.assitem',
    'dbo.assitemgradedes','dbo.assessmentdetail'
  ) OR p_target_table NOT IN(
    'hr_performance_legacy_template_profile','hr_performance_legacy_level_rule',
    'hr_performance_legacy_dimension_profile','hr_performance_legacy_dimension_level_guide',
    'hr_performance_legacy_dimension_result'
  ) OR p_target_table<>(CASE p_source_table
    WHEN 'dbo.assessmentcode' THEN 'hr_performance_legacy_template_profile'
    WHEN 'dbo.assgradecode' THEN 'hr_performance_legacy_level_rule'
    WHEN 'dbo.assitem' THEN 'hr_performance_legacy_dimension_profile'
    WHEN 'dbo.assitemgradedes' THEN 'hr_performance_legacy_dimension_level_guide'
    WHEN 'dbo.assessmentdetail' THEN 'hr_performance_legacy_dimension_result'
    END) OR p_source_identity_sha256!~'^[0-9a-f]{64}$'
    OR p_source_row_sha256!~'^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_WRITER_IDENTITY_INVALID';
  END IF;

  fact_id:=uuid_generate_v5(
    v_namespace,
    'fact:'||p_batch_id::text||':'||p_source_table||':'||p_source_identity_sha256
  );
  map_id:=uuid_generate_v5(
    v_namespace,
    'map:'||p_batch_id::text||':'||p_source_table||':'||p_source_identity_sha256
  );

  SELECT * INTO v_existing
  FROM legacy_record_map
  WHERE source_system='yuzhou-v10'
    AND source_table=p_source_table
    AND source_identity_sha256=p_source_identity_sha256
    AND is_active
  FOR SHARE;

  IF FOUND THEN
    IF v_existing.id<>map_id OR v_existing.batch_id<>p_batch_id
      OR v_existing.source_row_sha256<>p_source_row_sha256
      OR v_existing.target_table<>p_target_table OR v_existing.target_id<>fact_id
      OR v_existing.mapping_status NOT IN('loaded','verified') THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_WRITER_REPLAY_DRIFT';
    END IF;
    RETURN NEXT;
    RETURN;
  END IF;

  INSERT INTO legacy_record_map(
    id,batch_id,source_system,source_table,source_pk_canonical,
    source_identity_sha256,source_row_sha256,target_table,target_id,mapping_status,is_active
  ) VALUES(
    map_id,p_batch_id,'yuzhou-v10',p_source_table,
    'sha256:'||p_source_identity_sha256,p_source_identity_sha256,p_source_row_sha256,
    p_target_table,fact_id,'loaded',true
  );
  RETURN NEXT;
END$_$;



--
-- Name: hr_performance_yuzhou_prepare_relation_record_map(uuid, character varying, character, character, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_yuzhou_prepare_relation_record_map(p_batch_id uuid, p_source_table character varying, p_source_identity_sha256 character, p_source_row_sha256 character, p_target_table character varying) RETURNS TABLE(map_id uuid, fact_id uuid)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_existing legacy_record_map%ROWTYPE;
  v_namespace constant uuid:='4c377793-4707-4adb-b2bb-7d61ecf73157';
BEGIN
  IF p_target_table<>(CASE p_source_table
      WHEN 'dbo.asssession' THEN 'hr_performance_legacy_session'
      WHEN 'dbo.asssour' THEN 'hr_performance_legacy_score_source'
      WHEN 'dbo.asssourperson' THEN 'hr_performance_legacy_source_person_assignment'
    END)
    OR p_source_identity_sha256!~'^[0-9a-f]{64}$' OR p_source_row_sha256!~'^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_RELATION_WRITER_IDENTITY_INVALID';
  END IF;
  fact_id:=uuid_generate_v5(v_namespace,'fact:'||p_batch_id::text||':'||p_source_table||':'||p_source_identity_sha256);
  map_id:=uuid_generate_v5(v_namespace,'map:'||p_batch_id::text||':'||p_source_table||':'||p_source_identity_sha256);
  SELECT * INTO v_existing FROM legacy_record_map
  WHERE source_system='yuzhou-v10' AND source_table=p_source_table
    AND source_identity_sha256=p_source_identity_sha256 AND is_active FOR SHARE;
  IF FOUND THEN
    IF v_existing.id<>map_id OR v_existing.batch_id<>p_batch_id
      OR v_existing.source_row_sha256<>p_source_row_sha256 OR v_existing.target_table<>p_target_table
      OR v_existing.target_id<>fact_id OR v_existing.mapping_status NOT IN('loaded','verified') THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_RELATION_WRITER_REPLAY_DRIFT';
    END IF;
    RETURN NEXT; RETURN;
  END IF;
  INSERT INTO legacy_record_map(
    id,batch_id,source_system,source_table,source_pk_canonical,source_identity_sha256,
    source_row_sha256,target_table,target_id,mapping_status,is_active
  ) VALUES(
    map_id,p_batch_id,'yuzhou-v10',p_source_table,'sha256:'||p_source_identity_sha256,
    p_source_identity_sha256,p_source_row_sha256,p_target_table,fact_id,'loaded',true
  );
  RETURN NEXT;
END$_$;



--
-- Name: hr_performance_yuzhou_session_binding_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_yuzhou_session_binding_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_session hr_performance_legacy_session%ROWTYPE; v_batch migration_batch%ROWTYPE;
BEGIN
  IF TG_OP<>'INSERT' THEN
    IF TG_OP='DELETE'
      AND current_setting('yuzhou.performance_identity_resolution_rollback_batch_id',true)=OLD.migration_batch_id::text
      AND (EXISTS(SELECT 1 FROM migration_batch batch WHERE batch.id=OLD.migration_batch_id
        AND batch.execution_context='lab_rehearsal' AND batch.phase='rollback' AND batch.status='running')
        OR hr_yuzhou_performance_relations_production_context_allowed(OLD.migration_batch_id,'rollback'))
    THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_SESSION_BINDING_IMMUTABLE';
  END IF;
  SELECT * INTO v_batch FROM migration_batch WHERE id=NEW.migration_batch_id FOR SHARE;
  IF NOT FOUND OR v_batch.target_database<>current_database() OR NOT (
    (v_batch.execution_context='lab_rehearsal' AND v_batch.phase='load' AND v_batch.status='running')
    OR hr_yuzhou_performance_relations_production_context_allowed(NEW.migration_batch_id,'apply')
  ) THEN RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_IDENTITY_WRITER_BATCH_INVALID'; END IF;
  SELECT * INTO v_session FROM hr_performance_legacy_session
  WHERE (id,tenant_id,park_id,migration_batch_id)=
    (NEW.legacy_session_id,NEW.tenant_id,NEW.park_id,NEW.migration_batch_id);
  IF NOT FOUND OR v_session.source_identity_sha256<>NEW.source_session_identity_sha256 THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_SESSION_BINDING_SOURCE_MISMATCH'; END IF;
  IF NEW.resolution_status='resolved' AND v_session.target_review_cycle_id IS NOT NULL
    AND v_session.target_review_cycle_id<>NEW.target_review_cycle_id THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_SESSION_BINDING_TARGET_DRIFT'; END IF;
  RETURN NEW;
END$$;



--
-- Name: hr_performance_yuzhou_t0_map_resolution_reverse_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_yuzhou_t0_map_resolution_reverse_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM hr_performance_legacy_identity_resolution resolution
    WHERE resolution.owner_t0_record_map_id=OLD.id) THEN
    RETURN COALESCE(NEW,OLD);
  END IF;
  IF TG_OP='DELETE' OR NOT NEW.is_active OR NEW.mapping_status NOT IN('loaded','verified')
    OR ROW(NEW.source_system,NEW.source_table,NEW.source_identity_sha256,NEW.target_table,NEW.target_id)
      IS DISTINCT FROM ROW(OLD.source_system,OLD.source_table,OLD.source_identity_sha256,OLD.target_table,OLD.target_id) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_T0_MAP_REFERENCED';
  END IF;
  RETURN NEW;
END$$;



--
-- Name: hr_performance_yuzhou_t0_person_candidate(character varying, character varying, character); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_yuzhou_t0_person_candidate(p_tenant_id character varying, p_park_id character varying, p_source_person_identity_sha256 character) RETURNS TABLE(owner_t0_record_map_id uuid, target_employee_id uuid)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT source_map.id,employee.id
  FROM legacy_record_map source_map
  JOIN hr_yuzhou_production_import_projection_receipt receipt
    ON receipt.legacy_record_map_id=source_map.id AND receipt.phase='T0'
  JOIN hr_yuzhou_production_import_record import_record
    ON (import_record.operation_id,import_record.phase,import_record.source_identity_sha256)=
       (receipt.operation_id,receipt.phase,receipt.source_identity_sha256)
  JOIN hr_yuzhou_production_import_phase import_phase
    ON (import_phase.operation_id,import_phase.phase)=(receipt.operation_id,receipt.phase)
  JOIN hr_yuzhou_production_import_operation import_operation
    ON import_operation.operation_id=receipt.operation_id
  JOIN migration_batch source_batch
    ON source_batch.id=receipt.migration_batch_id AND source_batch.id=source_map.batch_id
  JOIN hr_employee employee
    ON (employee.id,employee.tenant_id,employee.park_id)=
       (source_map.target_id,p_tenant_id,p_park_id)
  WHERE source_map.source_system='yuzhou-v10' AND source_map.source_table='dbo.person'
    AND source_map.source_identity_sha256=p_source_person_identity_sha256
    AND source_map.target_table='hr_employee' AND source_map.mapping_status IN('loaded','verified')
    AND source_map.is_active AND receipt.source_identity_sha256=source_map.source_identity_sha256
    AND import_record.source_system='yuzhou-v10' AND import_record.source_table='dbo.person'
    AND import_record.source_pk_canonical='sha256:'||source_map.source_identity_sha256
    AND import_record.target_table='hr_employee' AND import_record.target_id=source_map.target_id
    AND import_record.disposition IN('insert','merge','skip_approved')
    AND import_record.rollback_status='not_started' AND import_phase.status='succeeded'
    AND (import_operation.status='succeeded' OR (
      import_operation.status='running' AND import_operation.current_phase='T0'
      AND current_setting('yuzhou.performance_relations_operation_id',true)=import_operation.operation_id
      AND current_setting('yuzhou.performance_relations_mode',true)='apply'
      AND hr_yuzhou_performance_relations_production_context_allowed(source_batch.id,'apply')
    ))
    AND import_operation.execution_contract_version=2
    AND (import_operation.target_tenant_id,import_operation.target_park_id)=(p_tenant_id,p_park_id)
    AND source_batch.execution_context='production_import'
    AND source_batch.production_import_operation_id=receipt.operation_id
    AND source_batch.production_import_phase='T0' AND source_batch.status='succeeded'
    AND NOT employee.is_deleted
$$;



