--
-- Name: hr_performance_yuzhou_weighted_detail_total(character varying, character varying, uuid, uuid, integer, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_performance_yuzhou_weighted_detail_total(p_tenant_id character varying, p_park_id character varying, p_migration_batch_id uuid, p_legacy_template_profile_id uuid, p_source_session_id integer, p_source_person_code character varying) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT round(
      sum(COALESCE(result.source_self_value,0)) * COALESCE(template.source_s_percent,0) / 100::numeric
    + sum(COALESCE(result.source_m_item_value,0))::numeric(18,0) * COALESCE(template.source_m_percent,0) / 100::numeric
    + sum(COALESCE(result.source_item_value,0)) * COALESCE(template.source_t_percent,0) / 100::numeric
    + sum(COALESCE(result.source_x_item_value,0))::numeric(18,0) * COALESCE(template.source_x_percent,0) / 100::numeric
    + sum(COALESCE(result.source_c_item_value,0))::numeric(18,0) * COALESCE(template.source_c_percent,0) / 100::numeric,
    2
  )
  FROM hr_performance_legacy_template_profile template
  JOIN hr_performance_legacy_dimension_profile dimension
    ON (dimension.tenant_id,dimension.park_id,dimension.migration_batch_id,dimension.legacy_template_profile_id)=
       (template.tenant_id,template.park_id,template.migration_batch_id,template.id)
  JOIN hr_performance_legacy_dimension_result result
    ON (result.tenant_id,result.park_id,result.migration_batch_id,result.legacy_dimension_profile_id)=
       (dimension.tenant_id,dimension.park_id,dimension.migration_batch_id,dimension.id)
  WHERE (template.tenant_id,template.park_id,template.migration_batch_id,template.id)=
        (p_tenant_id,p_park_id,p_migration_batch_id,p_legacy_template_profile_id)
    AND result.source_session_id IS NOT DISTINCT FROM p_source_session_id
    AND result.source_person_code IS NOT DISTINCT FROM p_source_person_code
  GROUP BY template.source_s_percent,template.source_m_percent,template.source_t_percent,
           template.source_x_percent,template.source_c_percent
$$;



--
-- Name: hr_personnel_correction_commit_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_personnel_correction_commit_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE expected integer; actual integer; intent text;
BEGIN
 intent := CASE WHEN TG_TABLE_NAME='hr_personnel_correction_operation' THEN 'apply' ELSE 'rollback' END;
 SELECT (o.binding->'seal'->>'plannedProfiles')::integer INTO STRICT expected
  FROM public.hr_personnel_correction_operation o WHERE o.operation_id=NEW.operation_id;
 SELECT count(*) INTO actual FROM public.hr_personnel_correction_detail WHERE operation_id=NEW.operation_id;
 IF expected IS NULL OR expected<1 OR actual<>expected OR NOT EXISTS(
  SELECT 1 FROM public.hr_personnel_correction_authorization_use u WHERE u.operation_id=NEW.operation_id
   AND u.action=intent AND u.execution_xid=pg_current_xact_id()) THEN
  RAISE EXCEPTION 'PERSONNEL_CORRECTION_ATOMIC_RECEIPT_REQUIRED';
 END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_personnel_correction_detail_cas_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_personnel_correction_detail_cas_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE op public.hr_personnel_correction_operation%ROWTYPE; expected_after jsonb;
BEGIN
 IF current_database() !~ '^jinhu_hr_correction_lab_[0-9a-f]{24}$' THEN
  RAISE EXCEPTION 'PERSONNEL_CORRECTION_LAB_ONLY';
 END IF;
 SELECT * INTO STRICT op FROM public.hr_personnel_correction_operation WHERE operation_id=NEW.operation_id;
 expected_after := NEW.before_image || NEW.patch;
 IF op.receipt ? 'receiptVersion' THEN
  IF op.receipt->'receiptVersion' IS DISTINCT FROM '2'::jsonb
   OR op.receipt->>'profileVersionPolicy' IS DISTINCT FROM 'monotonic-v1'
   OR op.receipt->'changedMetadata' IS DISTINCT FROM '["version"]'::jsonb
   OR op.binding->>'profileBeforeSha256' IS NULL
   OR op.binding->>'profileBeforeSha256' !~ '^[0-9a-f]{64}$'
   OR op.receipt->>'profileBeforeSha256' IS DISTINCT FROM op.binding->>'profileBeforeSha256'
   OR jsonb_typeof(NEW.before_image->'version') IS DISTINCT FROM 'number'
   OR (NEW.before_image->>'version') !~ '^[1-9][0-9]{0,9}$'
  THEN RAISE EXCEPTION 'PERSONNEL_CORRECTION_DETAIL_INVALID'; END IF;
  -- Reserve one further increment for rollback. Never wrap or restore a version.
  IF (NEW.before_image->>'version')::bigint > 2147483645 THEN
   RAISE EXCEPTION 'PERSONNEL_CORRECTION_DETAIL_INVALID';
  END IF;
  expected_after := expected_after || jsonb_build_object('version',(NEW.before_image->>'version')::integer+1);
 END IF;
 IF op.execution_xid<>pg_current_xact_id()
  OR NEW.binding->>'profileId' IS DISTINCT FROM NEW.profile_id::text
  OR NEW.binding->>'tenantId' IS DISTINCT FROM op.binding->>'tenantId'
  OR NEW.binding->>'parkId' IS DISTINCT FROM op.binding->>'parkId'
  OR NEW.binding->>'operationId' IS DISTINCT FROM op.binding->>'sourceOperationId'
  OR NEW.binding->>'parentOperationId' IS DISTINCT FROM op.binding->>'parentOperationId'
  OR NEW.before_image->>'id' IS DISTINCT FROM NEW.profile_id::text
  OR NEW.after_image->>'id' IS DISTINCT FROM NEW.profile_id::text
  OR NEW.after_image IS DISTINCT FROM expected_after
  OR EXISTS(SELECT 1 FROM jsonb_each(NEW.patch) p WHERE jsonb_typeof(p.value)<>'string'
    OR NEW.before_image->p.key IS DISTINCT FROM 'null'::jsonb)
 THEN RAISE EXCEPTION 'PERSONNEL_CORRECTION_DETAIL_INVALID'; END IF;
 RETURN NEW;
END $_$;



