--
-- Name: hr_personnel_correction_insert_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_personnel_correction_insert_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE op public.hr_personnel_correction_operation%ROWTYPE;
BEGIN
 IF current_database() !~ '^jinhu_hr_correction_lab_[0-9a-f]{24}$' THEN
  RAISE EXCEPTION 'PERSONNEL_CORRECTION_LAB_ONLY';
 END IF;
 IF TG_TABLE_NAME='hr_personnel_correction_lab' THEN
  IF NEW.database_name<>current_database() OR NEW.database_user<>current_user THEN
   RAISE EXCEPTION 'PERSONNEL_CORRECTION_LAB_IDENTITY_INVALID';
  END IF;
  RETURN NEW;
 END IF;
 IF TG_TABLE_NAME='hr_personnel_correction_operation' THEN
  IF NOT EXISTS(SELECT 1 FROM public.hr_personnel_correction_lab l WHERE l.lab_id=NEW.lab_id
   AND l.database_name=current_database() AND l.database_user=current_user)
   OR NEW.execution_xid<>pg_current_xact_id()
   OR NEW.binding->>'operationId' IS DISTINCT FROM NEW.operation_id::text
   OR NEW.binding->>'idempotencyKey' IS DISTINCT FROM NEW.idempotency_key::text
  THEN RAISE EXCEPTION 'PERSONNEL_CORRECTION_OPERATION_INVALID'; END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO STRICT op FROM public.hr_personnel_correction_operation WHERE operation_id=NEW.operation_id;
 IF TG_TABLE_NAME='hr_personnel_correction_detail' THEN
  IF op.execution_xid<>pg_current_xact_id()
   OR NEW.binding->>'profileId' IS DISTINCT FROM NEW.profile_id::text
   OR NEW.binding->>'tenantId' IS DISTINCT FROM op.binding->>'tenantId'
   OR NEW.binding->>'parkId' IS DISTINCT FROM op.binding->>'parkId'
   OR NEW.binding->>'operationId' IS DISTINCT FROM op.binding->>'sourceOperationId'
   OR NEW.binding->>'parentOperationId' IS DISTINCT FROM op.binding->>'parentOperationId'
   OR NEW.before_image->>'id' IS DISTINCT FROM NEW.profile_id::text
   OR NEW.after_image->>'id' IS DISTINCT FROM NEW.profile_id::text
   OR NEW.after_image IS DISTINCT FROM NEW.before_image || NEW.patch
   OR EXISTS(SELECT 1 FROM jsonb_each(NEW.patch) p WHERE jsonb_typeof(p.value)<>'string'
     OR NEW.before_image->p.key IS DISTINCT FROM 'null'::jsonb)
  THEN RAISE EXCEPTION 'PERSONNEL_CORRECTION_DETAIL_INVALID'; END IF;
 ELSIF TG_TABLE_NAME='hr_personnel_correction_rollback' THEN
  IF op.execution_xid=pg_current_xact_id() OR NEW.execution_xid<>pg_current_xact_id()
   OR NEW.binding_sha256<>op.binding_sha256 THEN
   RAISE EXCEPTION 'PERSONNEL_CORRECTION_ROLLBACK_INVALID';
  END IF;
 ELSIF TG_TABLE_NAME='hr_personnel_correction_authorization_use' THEN
  IF NEW.execution_xid<>pg_current_xact_id()
   OR (NEW.action='apply' AND op.execution_xid<>pg_current_xact_id())
   OR (NEW.action='rollback' AND NOT EXISTS(SELECT 1 FROM public.hr_personnel_correction_rollback r
     WHERE r.operation_id=NEW.operation_id AND r.execution_xid=pg_current_xact_id()))
  THEN RAISE EXCEPTION 'PERSONNEL_CORRECTION_AUTHORIZATION_INVALID'; END IF;
 END IF;
 RETURN NEW;
END $_$;



--
-- Name: hr_position_assignment_continuity_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_position_assignment_continuity_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- A fixed snapshot can miss an assignment committed while this row lock was
  -- waiting. Structural edits must use the ordinary READ COMMITTED workflow.
  IF current_setting('transaction_isolation') <> 'read committed' AND (
    (NEW.tenant_id, NEW.park_id, NEW.org_id) IS DISTINCT FROM (OLD.tenant_id, OLD.park_id, OLD.org_id)
    OR (NEW.is_deleted AND NOT OLD.is_deleted)
    OR (NEW.status <> 'enabled' AND NEW.status IS DISTINCT FROM OLD.status)
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '40001',
      MESSAGE = 'Retry structural position edits through the current assignment workflow';
  END IF;
  IF ((NEW.tenant_id, NEW.park_id, NEW.org_id) IS DISTINCT FROM (OLD.tenant_id, OLD.park_id, OLD.org_id)
      OR (NEW.is_deleted AND NOT OLD.is_deleted)) AND EXISTS (
    SELECT 1 FROM hr_employee e WHERE e.position_id = OLD.id AND e.is_deleted = false
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'hr_position_assignment_continuity',
      MESSAGE = 'Position has retained employee assignments; use the assignment workflow first';
  END IF;
  IF NEW.status <> 'enabled' AND NEW.status IS DISTINCT FROM OLD.status AND EXISTS (
    SELECT 1 FROM hr_employee e WHERE e.position_id = OLD.id
      AND e.is_deleted = false AND e.employment_status <> 'departed'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', CONSTRAINT = 'hr_position_assignment_continuity',
      MESSAGE = 'Position still has current employee assignments';
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: hr_position_hierarchy_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_position_hierarchy_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  has_cycle boolean;
  parent_active boolean;
BEGIN
  IF (NEW.is_deleted OR NEW.status <> 'enabled') AND EXISTS (
    SELECT 1 FROM hr_position child
    WHERE (child.tenant_id, child.park_id, child.reports_to_position_id) = (NEW.tenant_id, NEW.park_id, NEW.id)
      AND child.is_deleted = false
  ) THEN
    RAISE EXCEPTION 'position with active reports cannot be disabled or deleted';
  END IF;
  IF NEW.reports_to_position_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT true INTO parent_active
    FROM hr_position parent
    WHERE (parent.tenant_id, parent.park_id, parent.id) = (NEW.tenant_id, NEW.park_id, NEW.reports_to_position_id)
      AND parent.is_deleted = false AND parent.status = 'enabled'
    FOR SHARE;
  IF COALESCE(parent_active, false) = false THEN
    RAISE EXCEPTION 'parent position must be active in the same scope';
  END IF;
  WITH RECURSIVE ancestors AS (
    SELECT parent.id, parent.reports_to_position_id, ARRAY[parent.id] AS path, false AS cycle
    FROM hr_position parent
    WHERE (parent.tenant_id, parent.park_id, parent.id) = (NEW.tenant_id, NEW.park_id, NEW.reports_to_position_id)
      AND parent.is_deleted = false
    UNION ALL
    SELECT parent.id, parent.reports_to_position_id, ancestors.path || parent.id, parent.id = ANY(ancestors.path)
    FROM ancestors
    JOIN hr_position parent
      ON (parent.tenant_id, parent.park_id, parent.id) = (NEW.tenant_id, NEW.park_id, ancestors.reports_to_position_id)
     AND parent.is_deleted = false
    WHERE ancestors.reports_to_position_id IS NOT NULL AND NOT ancestors.cycle
  )
  SELECT EXISTS(SELECT 1 FROM ancestors WHERE id = NEW.id OR cycle) INTO has_cycle;
  IF has_cycle THEN
    RAISE EXCEPTION 'position hierarchy cannot contain a cycle';
  END IF;
  RETURN NEW;
END;
$$;



