--
-- Name: hr_work_report_goal_mutation_guard_t6(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_work_report_goal_mutation_guard_t6() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE report_status varchar(32);v_tenant varchar(64);v_park varchar(64);v_report uuid;
BEGIN
 IF TG_OP='DELETE' THEN v_tenant=OLD.tenant_id;v_park=OLD.park_id;v_report=OLD.report_id;ELSE v_tenant=NEW.tenant_id;v_park=NEW.park_id;v_report=NEW.report_id;END IF;
 SELECT status INTO report_status FROM hr_work_report WHERE tenant_id=v_tenant AND park_id=v_park AND id=v_report FOR SHARE;
 IF report_status NOT IN('draft','returned') THEN RAISE EXCEPTION 'submitted work report suggestions are immutable' USING ERRCODE='55000'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;RETURN NEW;
END$$;



--
-- Name: hr_work_report_state_guard_t6(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_work_report_state_guard_t6() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN
   RAISE EXCEPTION 'work report physical deletion is forbidden' USING ERRCODE='55000';
 END IF;
 IF OLD.is_deleted THEN RAISE EXCEPTION 'cancelled work report is immutable' USING ERRCODE='55000';END IF;
 IF NEW.is_deleted AND NOT OLD.is_deleted THEN
   IF OLD.status NOT IN('draft','returned') THEN RAISE EXCEPTION 'only draft or returned work report may be cancelled' USING ERRCODE='23514';END IF;
   IF ROW(NEW.employee_id,NEW.report_type,NEW.period_start,NEW.period_end,NEW.title,NEW.completed_work,NEW.next_plan,NEW.risks,NEW.questions_and_suggestions,NEW.collaboration_needs,NEW.hours,NEW.status)
      IS DISTINCT FROM
      ROW(OLD.employee_id,OLD.report_type,OLD.period_start,OLD.period_end,OLD.title,OLD.completed_work,OLD.next_plan,OLD.risks,OLD.questions_and_suggestions,OLD.collaboration_needs,OLD.hours,OLD.status)
   THEN RAISE EXCEPTION 'work report content cannot change while cancelling' USING ERRCODE='55000';END IF;
   RETURN NEW;
 END IF;
 IF OLD.status='confirmed' THEN RAISE EXCEPTION 'confirmed work report is immutable' USING ERRCODE='55000';END IF;
 IF OLD.status IN('submitted','resubmitted') THEN
   IF NEW.status NOT IN('returned','confirmed') THEN RAISE EXCEPTION 'invalid submitted work report transition' USING ERRCODE='23514';END IF;
   IF ROW(NEW.employee_id,NEW.report_type,NEW.period_start,NEW.period_end,NEW.title,NEW.completed_work,NEW.next_plan,NEW.risks,NEW.questions_and_suggestions,NEW.collaboration_needs,NEW.hours)
      IS DISTINCT FROM
      ROW(OLD.employee_id,OLD.report_type,OLD.period_start,OLD.period_end,OLD.title,OLD.completed_work,OLD.next_plan,OLD.risks,OLD.questions_and_suggestions,OLD.collaboration_needs,OLD.hours)
   THEN RAISE EXCEPTION 'submitted work report content is immutable' USING ERRCODE='55000';END IF;
 ELSIF OLD.status='draft' AND NEW.status NOT IN('draft','submitted') THEN RAISE EXCEPTION 'invalid draft work report transition' USING ERRCODE='23514';
 ELSIF OLD.status='returned' AND NEW.status NOT IN('returned','resubmitted') THEN RAISE EXCEPTION 'invalid returned work report transition' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END$$;



--
-- Name: hr_yuzhou_apply_performance_fact_identity_production_v1(character varying, character, character, character, character, character, character, character, character, character varying, character varying, character, character, character, character, character, bigint, bigint, character, character, character); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_apply_performance_fact_identity_production_v1(p_operation_id character varying, p_sealed_plan_sha256 character, p_authorization_artifact_sha256 character, p_authorization_nonce_sha256 character, p_extension_nonce_sha256 character, p_code_sha character, p_source_snapshot_sha256 character, p_mapping_contract_sha256 character, p_target_identity_sha256 character, p_tenant_id character varying, p_park_id character varying, p_target_scope_sha256 character, p_t0_phase_receipt_sha256 character, p_parent_relations_receipt_sha256 character, p_parent_performance_relations_contract_sha256 character, p_fact_loader_receipt_sha256 character, p_expected_dimension_rows bigint, p_expected_master_rows bigint, p_expected_fact_set_sha256 character, p_migration_308_sha256 character, p_migration_310_sha256 character) RETURNS TABLE(status character varying, replayed boolean, dimension_rows bigint, master_rows bigint, fact_rows bigint, resolved_rows bigint, unmatched_rows bigint, ambiguous_rows bigint, not_applicable_rows bigint, cycle_resolved_rows bigint, cycle_unmatched_rows bigint, cycle_ambiguous_rows bigint, cycle_not_applicable_rows bigint, fact_set_sha256 character, resolution_state_sha256 character, fact_owner_maps bigint, relation_owner_maps bigint, verified_owner_maps bigint, owner_map_state_sha256 character, receipt_sha256 character)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_parent public.hr_yuzhou_performance_relations_production_receipt%ROWTYPE;
  v_existing public.hr_yuzhou_performance_fact_identity_production_receipt%ROWTYPE;
  v_dimension bigint; v_master bigint; v_facts bigint; v_fact_set char(64);
  v_resolved bigint; v_unmatched bigint; v_ambiguous bigint; v_na bigint;
  v_cycle_resolved bigint; v_cycle_unmatched bigint; v_cycle_ambiguous bigint; v_cycle_na bigint;
  v_state char(64); v_fact_owner_maps bigint; v_relation_owner_maps bigint;
  v_verified_owner_maps bigint; v_owner_map_state char(64);
  v_receipt char(64); v_replayed boolean:=false;
BEGIN
  IF current_setting('transaction_isolation')<>'serializable' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_FACT_IDENTITY_PRODUCTION_REQUIRES_SERIALIZABLE'; END IF;
  IF p_migration_308_sha256<>'ad77e0cf12cf73f98a5984835a9943a9e15c96cde37fe6bd95133845c711befa'
    OR p_target_scope_sha256<>public.hr_yuzhou_production_target_scope_sha256(p_tenant_id,p_park_id)
    OR p_expected_dimension_rows<0 OR p_expected_master_rows<0
    OR p_parent_performance_relations_contract_sha256!~'^[0-9a-f]{64}$'
    OR p_fact_loader_receipt_sha256!~'^[0-9a-f]{64}$'
    OR p_expected_fact_set_sha256!~'^[0-9a-f]{64}$'
    OR p_extension_nonce_sha256!~'^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_FACT_IDENTITY_PRODUCTION_BINDING_INVALID'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.sys_schema_migration_history a
      JOIN public.schema_migrations b USING(filename,checksum,status)
      WHERE a.filename='000308_hr_yuzhou_performance_relations_production.sql'
        AND a.status='succeeded' AND a.checksum=p_migration_308_sha256)
    OR NOT EXISTS(SELECT 1 FROM public.sys_schema_migration_history a
      JOIN public.schema_migrations b USING(filename,checksum,status)
      WHERE a.filename='000310_hr_yuzhou_performance_fact_identity_production.sql'
        AND a.status='succeeded' AND a.checksum=p_migration_310_sha256) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_FACT_IDENTITY_PRODUCTION_MIGRATION_DRIFT'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('hr_yuzhou_performance_relations_production',0));
  SELECT * INTO v_parent FROM public.hr_yuzhou_performance_relations_production_receipt
    WHERE operation_id=p_operation_id FOR UPDATE;
  IF NOT FOUND OR v_parent.status<>'succeeded'
    OR ROW(v_parent.sealed_plan_sha256,v_parent.authorization_artifact_sha256,
      v_parent.authorization_nonce_sha256,v_parent.code_sha,v_parent.source_snapshot_sha256,
      v_parent.mapping_contract_sha256,v_parent.target_identity_sha256,v_parent.tenant_id,
      v_parent.park_id,v_parent.target_scope_sha256,v_parent.t0_phase_receipt_sha256,
      v_parent.receipt_sha256)
    IS DISTINCT FROM ROW(p_sealed_plan_sha256,p_authorization_artifact_sha256,
      p_authorization_nonce_sha256,p_code_sha,p_source_snapshot_sha256,
      p_mapping_contract_sha256,p_target_identity_sha256,p_tenant_id,p_park_id,
      p_target_scope_sha256,p_t0_phase_receipt_sha256,p_parent_relations_receipt_sha256) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_FACT_IDENTITY_PRODUCTION_PARENT_INVALID'; END IF;
  IF NOT public.hr_yuzhou_performance_fact_loader_dependency_valid_v1(
    p_operation_id,v_parent.migration_batch_id,p_tenant_id,p_park_id,
    p_target_scope_sha256,p_t0_phase_receipt_sha256,p_fact_loader_receipt_sha256,
    p_expected_fact_set_sha256) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_FACT_IDENTITY_PRODUCTION_FACT_LOADER_INVALID'; END IF;
  SELECT * INTO v_existing FROM public.hr_yuzhou_performance_fact_identity_production_receipt
    WHERE operation_id=p_operation_id FOR UPDATE;
  IF FOUND THEN
    IF v_existing.status<>'succeeded' OR ROW(v_existing.extension_nonce_sha256,
      v_existing.parent_performance_relations_contract_sha256,
      v_existing.parent_relations_receipt_sha256,v_existing.fact_loader_receipt_sha256,
      v_existing.dimension_rows,v_existing.master_rows,
      v_existing.fact_set_sha256,v_existing.migration_308_sha256,v_existing.migration_310_sha256)
      IS DISTINCT FROM ROW(p_extension_nonce_sha256,p_parent_performance_relations_contract_sha256,
        p_parent_relations_receipt_sha256,
        p_fact_loader_receipt_sha256,
        p_expected_dimension_rows,p_expected_master_rows,p_expected_fact_set_sha256,
        p_migration_308_sha256,p_migration_310_sha256) THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_FACT_IDENTITY_PRODUCTION_REPLAY_DRIFT'; END IF;
    v_replayed:=true;
  ELSE
    SELECT * INTO STRICT v_dimension,v_master,v_facts,v_fact_set
      FROM public.hr_yuzhou_performance_fact_identity_set_v1(p_tenant_id,p_park_id,v_parent.migration_batch_id);
    IF ROW(v_dimension,v_master,v_facts,v_fact_set) IS DISTINCT FROM
      ROW(p_expected_dimension_rows,p_expected_master_rows,
        p_expected_dimension_rows+p_expected_master_rows,p_expected_fact_set_sha256) THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_FACT_IDENTITY_PRODUCTION_FACT_SET_DRIFT'; END IF;
    PERFORM set_config('yuzhou.performance_relations_operation_id',p_operation_id,true);
    PERFORM set_config('yuzhou.performance_relations_mode','apply',true);
    PERFORM set_config('yuzhou.performance_fact_identity_operation_id',p_operation_id,true);
    PERFORM set_config('yuzhou.performance_fact_identity_mode','apply',true);
    CALL public.hr_yuzhou_materialize_performance_fact_identity_production_v1(
      p_tenant_id,p_park_id,v_parent.migration_batch_id);
  END IF;
  SELECT * INTO STRICT v_dimension,v_master,v_facts,v_fact_set
    FROM public.hr_yuzhou_performance_fact_identity_set_v1(p_tenant_id,p_park_id,v_parent.migration_batch_id);
  SELECT count(*) FILTER(WHERE person_resolution_status='resolved'),
    count(*) FILTER(WHERE person_resolution_status='unmatched'),
    count(*) FILTER(WHERE person_resolution_status='ambiguous'),
    count(*) FILTER(WHERE person_resolution_status='not_applicable'),
    count(*) FILTER(WHERE cycle_resolution_status='resolved'),
    count(*) FILTER(WHERE cycle_resolution_status='unmatched'),
    count(*) FILTER(WHERE cycle_resolution_status='ambiguous'),
    count(*) FILTER(WHERE cycle_resolution_status='not_applicable')
    INTO v_resolved,v_unmatched,v_ambiguous,v_na,v_cycle_resolved,v_cycle_unmatched,
      v_cycle_ambiguous,v_cycle_na
  FROM public.hr_performance_legacy_identity_resolution
  WHERE (tenant_id,park_id,migration_batch_id)=(p_tenant_id,p_park_id,v_parent.migration_batch_id)
    AND fact_kind IN('dimension_result','master_result');
  IF v_resolved+v_unmatched+v_ambiguous+v_na<>v_facts
    OR v_cycle_resolved+v_cycle_unmatched+v_cycle_ambiguous+v_cycle_na<>v_facts
    OR v_fact_set<>p_expected_fact_set_sha256 THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_FACT_IDENTITY_PRODUCTION_CONSERVATION_FAILED'; END IF;
  v_state:=public.hr_yuzhou_performance_fact_identity_state_v1(
    p_tenant_id,p_park_id,v_parent.migration_batch_id);
  SELECT * INTO STRICT v_fact_owner_maps,v_relation_owner_maps,v_verified_owner_maps,
    v_owner_map_state
  FROM public.hr_yuzhou_verify_performance_owner_maps_v1(
    p_tenant_id,p_park_id,v_parent.migration_batch_id,v_parent.active_relation_maps,v_replayed);
  v_receipt:=encode(digest(convert_to(jsonb_build_object(
    'contract','jinhu-yuzhou-performance-fact-identity-production-v1',
    'operationId',p_operation_id,'extensionNonceSha256',p_extension_nonce_sha256,
    'parentPerformanceRelationsContractSha256',p_parent_performance_relations_contract_sha256,
    'parentRelationsReceiptSha256',p_parent_relations_receipt_sha256,
    'factLoaderReceiptSha256',p_fact_loader_receipt_sha256,
    'targetScopeSha256',p_target_scope_sha256,'t0PhaseReceiptSha256',p_t0_phase_receipt_sha256,
    'migration308Sha256',p_migration_308_sha256,'migration310Sha256',p_migration_310_sha256,
    'factSetSha256',v_fact_set,'resolutionStateSha256',v_state,
    'ownerMapStateSha256',v_owner_map_state,
    'counts',jsonb_build_array(v_dimension,v_master,v_facts,v_resolved,v_unmatched,v_ambiguous,v_na,
      v_cycle_resolved,v_cycle_unmatched,v_cycle_ambiguous,v_cycle_na,
      v_fact_owner_maps,v_relation_owner_maps,v_verified_owner_maps))::text,'UTF8'),'sha256'),'hex');
  INSERT INTO public.hr_yuzhou_performance_fact_identity_production_receipt(
    operation_id,migration_batch_id,sealed_plan_sha256,authorization_artifact_sha256,
    authorization_nonce_sha256,extension_nonce_sha256,code_sha,source_snapshot_sha256,
    mapping_contract_sha256,target_identity_sha256,tenant_id,park_id,target_scope_sha256,
    t0_phase_receipt_sha256,parent_performance_relations_contract_sha256,
    parent_relations_receipt_sha256,fact_loader_receipt_sha256,migration_308_sha256,
    migration_310_sha256,dimension_rows,master_rows,fact_rows,resolved_rows,unmatched_rows,
    ambiguous_rows,not_applicable_rows,cycle_resolved_rows,cycle_unmatched_rows,
    cycle_ambiguous_rows,cycle_not_applicable_rows,fact_set_sha256,resolution_state_sha256,
    fact_owner_maps,relation_owner_maps,verified_owner_maps,owner_map_state_sha256,receipt_sha256
  ) VALUES(p_operation_id,v_parent.migration_batch_id,p_sealed_plan_sha256,
    p_authorization_artifact_sha256,p_authorization_nonce_sha256,p_extension_nonce_sha256,
    p_code_sha,p_source_snapshot_sha256,p_mapping_contract_sha256,p_target_identity_sha256,
    p_tenant_id,p_park_id,p_target_scope_sha256,p_t0_phase_receipt_sha256,
    p_parent_performance_relations_contract_sha256,p_parent_relations_receipt_sha256,
    p_fact_loader_receipt_sha256,
    p_migration_308_sha256,p_migration_310_sha256,
    v_dimension,v_master,v_facts,v_resolved,v_unmatched,v_ambiguous,v_na,v_cycle_resolved,
    v_cycle_unmatched,v_cycle_ambiguous,v_cycle_na,v_fact_set,v_state,
    v_fact_owner_maps,v_relation_owner_maps,v_verified_owner_maps,v_owner_map_state,v_receipt)
  ON CONFLICT(operation_id) DO NOTHING;
  IF v_replayed AND (v_existing.resolution_state_sha256<>v_state
    OR v_existing.fact_owner_maps<>v_fact_owner_maps
    OR v_existing.relation_owner_maps<>v_relation_owner_maps
    OR v_existing.verified_owner_maps<>v_verified_owner_maps
    OR v_existing.owner_map_state_sha256<>v_owner_map_state
    OR v_existing.receipt_sha256<>v_receipt) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_FACT_IDENTITY_PRODUCTION_REPLAY_DRIFT'; END IF;
  RETURN QUERY SELECT 'succeeded'::varchar,v_replayed,v_dimension,v_master,v_facts,
    v_resolved,v_unmatched,v_ambiguous,v_na,v_cycle_resolved,v_cycle_unmatched,
    v_cycle_ambiguous,v_cycle_na,v_fact_set,v_state,v_fact_owner_maps,
    v_relation_owner_maps,v_verified_owner_maps,v_owner_map_state,v_receipt;
END$_$;



--
-- Name: hr_yuzhou_apply_performance_facts_production_v1(character varying, character, character, character, character, character, character, character, character, character varying, character varying, character, character, character, character, character, character, character, bytea, bytea, bigint, bigint, bigint, bigint, bigint, bigint, bigint, character, character, character, character, character, character, character, character); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_apply_performance_facts_production_v1(p_operation_id character varying, p_sealed_plan_sha256 character, p_performance_fact_loader_contract_sha256 character, p_authorization_artifact_sha256 character, p_authorization_nonce_sha256 character, p_code_sha character, p_source_snapshot_sha256 character, p_mapping_contract_sha256 character, p_target_identity_sha256 character, p_tenant_id character varying, p_park_id character varying, p_target_scope_sha256 character, p_t0_phase_receipt_sha256 character, p_source_restore_receipt_sha256 character, p_source_fact_location_receipt_sha256 character, p_source_fact_location_canonical_sha256 character, p_fact_payload_artifact_sha256 character, p_master_payload_artifact_sha256 character, p_fact_payload bytea, p_master_payload bytea, p_expected_template_rows bigint, p_expected_level_rule_rows bigint, p_expected_dimension_rows bigint, p_expected_guide_rows bigint, p_expected_dimension_result_rows bigint, p_expected_master_result_rows bigint, p_expected_active_fact_maps bigint, p_expected_identity_fact_set_sha256 character, p_expected_full_fact_set_sha256 character, p_migration_300_sha256 character, p_migration_301_sha256 character, p_migration_302_sha256 character, p_migration_303_sha256 character, p_migration_310_sha256 character, p_migration_311_sha256 character) RETURNS TABLE(status character varying, replayed boolean, template_rows bigint, level_rule_rows bigint, dimension_rows bigint, guide_rows bigint, dimension_result_rows bigint, master_result_rows bigint, active_fact_maps bigint, identity_fact_set_sha256 character, full_fact_set_sha256 character, receipt_sha256 character)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_operation public.hr_yuzhou_production_import_operation%ROWTYPE;
  v_phase public.hr_yuzhou_production_import_phase%ROWTYPE;
  v_batch public.migration_batch%ROWTYPE;
  v_existing public.hr_yuzhou_performance_facts_production_receipt%ROWTYPE;
  v_fact_payload jsonb; v_master_payload jsonb;
  v_template bigint; v_level bigint; v_dimension bigint; v_guide bigint;
  v_dimension_result bigint; v_master_result bigint; v_maps bigint;
  v_identity_dimension bigint; v_identity_master bigint; v_identity_total bigint;
  v_identity_hash char(64); v_full_hash char(64); v_receipt char(64);
  v_replayed boolean:=false; v_source_status varchar(32);
BEGIN
  IF current_setting('transaction_isolation')<>'serializable' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_FACTS_PRODUCTION_REQUIRES_SERIALIZABLE'; END IF;
  IF p_target_scope_sha256<>public.hr_yuzhou_production_target_scope_sha256(p_tenant_id,p_park_id)
    OR p_performance_fact_loader_contract_sha256!~'^[0-9a-f]{64}$'
    OR p_source_restore_receipt_sha256!~'^[0-9a-f]{64}$'
    OR p_source_fact_location_receipt_sha256!~'^[0-9a-f]{64}$'
    OR p_source_fact_location_canonical_sha256!~'^[0-9a-f]{64}$'
    OR p_expected_identity_fact_set_sha256!~'^[0-9a-f]{64}$'
    OR p_expected_full_fact_set_sha256!~'^[0-9a-f]{64}$'
    OR encode(digest(p_fact_payload,'sha256'),'hex')<>p_fact_payload_artifact_sha256
    OR encode(digest(p_master_payload,'sha256'),'hex')<>p_master_payload_artifact_sha256
    OR p_expected_template_rows<0 OR p_expected_level_rule_rows<0
    OR p_expected_dimension_rows<0 OR p_expected_guide_rows<0
    OR p_expected_dimension_result_rows<0 OR p_expected_master_result_rows<0
    OR p_expected_active_fact_maps<>p_expected_template_rows+p_expected_level_rule_rows+
      p_expected_dimension_rows+p_expected_guide_rows+p_expected_dimension_result_rows+
      p_expected_master_result_rows THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_FACTS_PRODUCTION_BINDING_INVALID';
  END IF;
  IF ROW(p_migration_300_sha256,p_migration_301_sha256,p_migration_302_sha256,p_migration_303_sha256)
    IS DISTINCT FROM ROW(
      'ab3410b2121e0772c4b0cc6f273c893340b7925dcecf26414ea336f15dd0656a'::char(64),
      '4a4de62295d7e4ac7e752c435eba49483da7d79384c34aa992b9bc5f1f618e7e'::char(64),
      '7b45377d252a9593d779af779bcb9d6f91ceb326f6b5da1273da50b89f52e43a'::char(64),
      '853d7632ebd2c2c3a9211e0088a3ccda7979a788539db2123aaf43c59c070648'::char(64))
    OR p_migration_310_sha256<>'e67936f0983dea544d09d4885c75bf1ee50cc9e08fa5684a2fbe46f8ca8afee5'
    OR EXISTS(
      SELECT 1 FROM (VALUES
        ('000300_hr_performance_yuzhou_legacy_model.sql',p_migration_300_sha256),
        ('000301_hr_performance_yuzhou_legacy_writer.sql',p_migration_301_sha256),
        ('000302_hr_performance_yuzhou_legacy_master.sql',p_migration_302_sha256),
        ('000303_hr_performance_yuzhou_legacy_master_writer.sql',p_migration_303_sha256),
        ('000310_hr_yuzhou_performance_fact_identity_production.sql',p_migration_310_sha256),
        ('000311_hr_yuzhou_performance_facts_production.sql',p_migration_311_sha256)
      ) expected(filename,checksum)
      WHERE NOT EXISTS(SELECT 1 FROM public.sys_schema_migration_history a
        JOIN public.schema_migrations b USING(filename,checksum,status)
        WHERE a.filename=expected.filename AND a.checksum=expected.checksum
          AND a.status='succeeded')
    ) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_FACTS_PRODUCTION_MIGRATION_DRIFT';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('hr_yuzhou_performance_relations_production',0));
  SELECT * INTO v_operation FROM public.hr_yuzhou_production_import_operation
    WHERE operation_id=p_operation_id FOR UPDATE;
  IF NOT FOUND OR v_operation.status<>'running' OR v_operation.current_phase<>'T0'
    OR v_operation.execution_contract_version<>2
    OR ROW(v_operation.sealed_plan_sha256,v_operation.code_sha,
      v_operation.source_snapshot_sha256,v_operation.mapping_contract_sha256,
      v_operation.target_identity_sha256,v_operation.target_tenant_id,
      v_operation.target_park_id,v_operation.target_scope_sha256)
      IS DISTINCT FROM ROW(p_sealed_plan_sha256,p_code_sha,p_source_snapshot_sha256,
        p_mapping_contract_sha256,p_target_identity_sha256,p_tenant_id,p_park_id,
        p_target_scope_sha256) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_FACTS_PRODUCTION_OPERATION_INVALID';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.hr_yuzhou_production_import_authorization_use auth
    WHERE auth.intent='production_import' AND auth.operation_id=p_operation_id
      AND auth.import_operation_id=p_operation_id
      AND auth.authorization_artifact_sha256=p_authorization_artifact_sha256
      AND auth.authorization_nonce_sha256=p_authorization_nonce_sha256) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_FACTS_PRODUCTION_AUTHORIZATION_INVALID';
  END IF;
  SELECT * INTO v_phase FROM public.hr_yuzhou_production_import_phase
    WHERE operation_id=p_operation_id AND phase='T0' FOR SHARE;
  IF NOT FOUND OR v_phase.status<>'succeeded'
    OR v_phase.after_canonical_sha256<>p_t0_phase_receipt_sha256 THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_FACTS_PRODUCTION_T0_RECEIPT_INVALID';
  END IF;
  SELECT * INTO v_batch FROM public.migration_batch batch
    WHERE batch.execution_context='production_import'
      AND batch.production_import_operation_id=p_operation_id
      AND batch.production_import_phase='T0' AND batch.status='succeeded'
      AND batch.target_database=current_database() FOR SHARE;
  IF NOT FOUND OR v_batch.source_system<>'yuzhou-v10'
    OR v_batch.source_snapshot_sha256<>p_source_snapshot_sha256 THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_FACTS_PRODUCTION_T0_BATCH_INVALID';
  END IF;
  SELECT * INTO v_existing FROM public.hr_yuzhou_performance_facts_production_receipt
    WHERE operation_id=p_operation_id FOR UPDATE;
  IF FOUND THEN
    IF v_existing.status<>'succeeded' OR ROW(
      v_existing.migration_batch_id,v_existing.sealed_plan_sha256,
      v_existing.performance_fact_loader_contract_sha256,
      v_existing.authorization_artifact_sha256,v_existing.authorization_nonce_sha256,
      v_existing.code_sha,v_existing.source_snapshot_sha256,v_existing.mapping_contract_sha256,
      v_existing.target_identity_sha256,v_existing.tenant_id,v_existing.park_id,
      v_existing.target_scope_sha256,v_existing.t0_phase_receipt_sha256,
      v_existing.source_restore_receipt_sha256,v_existing.source_fact_location_receipt_sha256,
      v_existing.source_fact_location_canonical_sha256,v_existing.fact_payload_artifact_sha256,
      v_existing.master_payload_artifact_sha256,v_existing.template_rows,
      v_existing.level_rule_rows,v_existing.dimension_rows,v_existing.guide_rows,
      v_existing.dimension_result_rows,v_existing.master_result_rows,v_existing.active_fact_maps,
      v_existing.identity_fact_set_sha256,v_existing.full_fact_set_sha256,
      v_existing.migration_300_sha256,v_existing.migration_301_sha256,
      v_existing.migration_302_sha256,v_existing.migration_303_sha256,
      v_existing.migration_310_sha256,v_existing.migration_311_sha256)
      IS DISTINCT FROM ROW(v_batch.id,p_sealed_plan_sha256,
        p_performance_fact_loader_contract_sha256,p_authorization_artifact_sha256,
        p_authorization_nonce_sha256,p_code_sha,p_source_snapshot_sha256,
        p_mapping_contract_sha256,p_target_identity_sha256,p_tenant_id,p_park_id,
        p_target_scope_sha256,p_t0_phase_receipt_sha256,p_source_restore_receipt_sha256,
        p_source_fact_location_receipt_sha256,p_source_fact_location_canonical_sha256,
        p_fact_payload_artifact_sha256,p_master_payload_artifact_sha256,
        p_expected_template_rows,p_expected_level_rule_rows,p_expected_dimension_rows,
        p_expected_guide_rows,p_expected_dimension_result_rows,p_expected_master_result_rows,
        p_expected_active_fact_maps,p_expected_identity_fact_set_sha256,
        p_expected_full_fact_set_sha256,p_migration_300_sha256,p_migration_301_sha256,
        p_migration_302_sha256,p_migration_303_sha256,p_migration_310_sha256,
        p_migration_311_sha256) THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_FACTS_PRODUCTION_REPLAY_DRIFT';
    END IF;
    v_replayed:=true;
  ELSE
    BEGIN
      v_fact_payload:=convert_from(p_fact_payload,'UTF8')::jsonb;
      v_master_payload:=convert_from(p_master_payload,'UTF8')::jsonb;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_FACTS_PRODUCTION_ARTIFACT_INVALID';
    END;
    PERFORM set_config('yuzhou.performance_facts_operation_id',p_operation_id,true);
    PERFORM set_config('yuzhou.performance_facts_mode','apply',true);
    SET CONSTRAINTS ALL DEFERRED;
    CALL public.materialize_yuzhou_performance_legacy_lab(
      p_tenant_id,p_park_id,v_batch.id,v_fact_payload);
    SET CONSTRAINTS ALL DEFERRED;
    CALL public.materialize_yuzhou_performance_legacy_master_lab(
      p_tenant_id,p_park_id,v_batch.id,v_master_payload);
  END IF;
  SELECT * INTO STRICT v_template,v_level,v_dimension,v_guide,v_dimension_result,
    v_master_result,v_maps,v_full_hash
    FROM public.hr_yuzhou_performance_full_fact_set_v1(p_tenant_id,p_park_id,v_batch.id);
  SELECT * INTO STRICT v_identity_dimension,v_identity_master,v_identity_total,v_identity_hash
    FROM public.hr_yuzhou_performance_fact_identity_set_v1(p_tenant_id,p_park_id,v_batch.id);
  IF ROW(v_template,v_level,v_dimension,v_guide,v_dimension_result,v_master_result,v_maps,
    v_identity_dimension,v_identity_master,v_identity_hash,v_full_hash)
    IS DISTINCT FROM ROW(p_expected_template_rows,p_expected_level_rule_rows,
      p_expected_dimension_rows,p_expected_guide_rows,p_expected_dimension_result_rows,
      p_expected_master_result_rows,p_expected_active_fact_maps,p_expected_dimension_result_rows,
      p_expected_master_result_rows,p_expected_identity_fact_set_sha256,
      p_expected_full_fact_set_sha256) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_FACTS_PRODUCTION_CONSERVATION_FAILED';
  END IF;
  v_source_status:=CASE WHEN v_dimension_result+v_master_result=0
    THEN 'AUTHORITATIVE_EMPTY' ELSE 'AUTHORITATIVE_NONEMPTY' END;
  v_receipt:=encode(digest(convert_to(jsonb_build_object(
    'contract','jinhu-yuzhou-performance-fact-loader-production-v1',
    'operationId',p_operation_id,'sealedPlanSha256',p_sealed_plan_sha256,
    'performanceFactLoaderContractSha256',p_performance_fact_loader_contract_sha256,
    'authorizationArtifactSha256',p_authorization_artifact_sha256,
    'authorizationNonceSha256',p_authorization_nonce_sha256,'codeSha',p_code_sha,
    'sourceSnapshotSha256',p_source_snapshot_sha256,
    'mappingContractSha256',p_mapping_contract_sha256,
    'targetIdentitySha256',p_target_identity_sha256,'targetScopeSha256',p_target_scope_sha256,
    't0PhaseReceiptSha256',p_t0_phase_receipt_sha256,
    'sourceRestoreReceiptSha256',p_source_restore_receipt_sha256,
    'sourceFactLocationReceiptSha256',p_source_fact_location_receipt_sha256,
    'sourceFactLocationCanonicalSha256',p_source_fact_location_canonical_sha256,
    'factPayloadArtifactSha256',p_fact_payload_artifact_sha256,
    'masterPayloadArtifactSha256',p_master_payload_artifact_sha256,
    'counts',jsonb_build_array(v_template,v_level,v_dimension,v_guide,
      v_dimension_result,v_master_result,v_maps),
    'identityFactSetSha256',v_identity_hash,'fullFactSetSha256',v_full_hash,
    'migrations',jsonb_build_array(p_migration_300_sha256,p_migration_301_sha256,
      p_migration_302_sha256,p_migration_303_sha256,p_migration_310_sha256,
      p_migration_311_sha256))::text,'UTF8'),'sha256'),'hex');
  IF v_replayed THEN
    IF v_existing.receipt_sha256<>v_receipt THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_FACTS_PRODUCTION_REPLAY_DRIFT'; END IF;
  ELSE
    INSERT INTO public.hr_yuzhou_performance_facts_production_receipt(
      operation_id,migration_batch_id,sealed_plan_sha256,
      performance_fact_loader_contract_sha256,authorization_artifact_sha256,
      authorization_nonce_sha256,code_sha,source_snapshot_sha256,mapping_contract_sha256,
      target_identity_sha256,tenant_id,park_id,target_scope_sha256,t0_phase_receipt_sha256,
      source_restore_receipt_sha256,source_fact_location_receipt_sha256,
      source_fact_location_canonical_sha256,fact_payload_artifact_sha256,
      master_payload_artifact_sha256,migration_300_sha256,migration_301_sha256,
      migration_302_sha256,migration_303_sha256,migration_310_sha256,migration_311_sha256,
      template_rows,level_rule_rows,dimension_rows,guide_rows,dimension_result_rows,
      master_result_rows,active_fact_maps,identity_fact_set_sha256,full_fact_set_sha256,
      source_outcome_fact_status,receipt_sha256
    ) VALUES(p_operation_id,v_batch.id,p_sealed_plan_sha256,
      p_performance_fact_loader_contract_sha256,p_authorization_artifact_sha256,
      p_authorization_nonce_sha256,p_code_sha,p_source_snapshot_sha256,
      p_mapping_contract_sha256,p_target_identity_sha256,p_tenant_id,p_park_id,
      p_target_scope_sha256,p_t0_phase_receipt_sha256,p_source_restore_receipt_sha256,
      p_source_fact_location_receipt_sha256,p_source_fact_location_canonical_sha256,
      p_fact_payload_artifact_sha256,p_master_payload_artifact_sha256,
      p_migration_300_sha256,p_migration_301_sha256,p_migration_302_sha256,
      p_migration_303_sha256,p_migration_310_sha256,p_migration_311_sha256,
      v_template,v_level,v_dimension,v_guide,v_dimension_result,v_master_result,v_maps,
      v_identity_hash,v_full_hash,v_source_status,v_receipt);
  END IF;
  RETURN QUERY SELECT 'succeeded'::varchar,v_replayed,v_template,v_level,v_dimension,
    v_guide,v_dimension_result,v_master_result,v_maps,v_identity_hash,v_full_hash,v_receipt;
END$_$;



--
-- Name: hr_yuzhou_apply_performance_relations_production_v1(character varying, character, character, character, character, character, character, character, character varying, character varying, character, character, character, character, bytea, bytea, character, character); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_apply_performance_relations_production_v1(p_operation_id character varying, p_sealed_plan_sha256 character, p_authorization_artifact_sha256 character, p_authorization_nonce_sha256 character, p_code_sha character, p_source_snapshot_sha256 character, p_mapping_contract_sha256 character, p_target_identity_sha256 character, p_tenant_id character varying, p_park_id character varying, p_target_scope_sha256 character, p_t0_phase_receipt_sha256 character, p_relation_payload_artifact_sha256 character, p_identity_decision_artifact_sha256 character, p_relation_payload bytea, p_identity_decision bytea, p_migration_305_sha256 character, p_migration_306_sha256 character) RETURNS TABLE(status character varying, replayed boolean, session_rows integer, score_source_rows integer, assignment_rows integer, active_relation_maps integer, identity_resolution_rows integer, session_binding_rows integer, subject_unmatched_rows integer, blank_assessor_rows integer, receipt_sha256 character)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_operation public.hr_yuzhou_production_import_operation%ROWTYPE;
  v_t0_phase public.hr_yuzhou_production_import_phase%ROWTYPE;
  v_batch public.migration_batch%ROWTYPE;
  v_existing public.hr_yuzhou_performance_relations_production_receipt%ROWTYPE;
  v_relations jsonb; v_identity jsonb; v_receipt char(64);
  v_session_rows integer; v_score_rows integer; v_assignment_rows integer;
  v_map_rows integer; v_identity_rows integer; v_binding_rows integer;
  v_subject_unmatched integer; v_blank_assessor integer;
BEGIN
  IF current_setting('transaction_isolation')<>'serializable' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_REQUIRES_SERIALIZABLE'; END IF;
  IF p_migration_305_sha256<>'d3784218fc8272bd28b93e44b19a02d5c8124466b6b3c218294920603909dfc0'
    OR p_migration_306_sha256<>'cd49f294f4c9e4105b9f7fd4c678b7b2d29c5433d0348f6e6632d6e7c135a56d' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_MIGRATION_DRIFT'; END IF;
  IF p_target_scope_sha256<>public.hr_yuzhou_production_target_scope_sha256(p_tenant_id,p_park_id)
    OR encode(digest(p_relation_payload,'sha256'),'hex')<>p_relation_payload_artifact_sha256
    OR encode(digest(p_identity_decision,'sha256'),'hex')<>p_identity_decision_artifact_sha256 THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_BINDING_INVALID'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('hr_yuzhou_performance_relations_production',0));
  SELECT * INTO v_operation FROM public.hr_yuzhou_production_import_operation
  WHERE operation_id=p_operation_id FOR UPDATE;
  IF NOT FOUND OR v_operation.status<>'running' OR v_operation.current_phase<>'T0'
    OR v_operation.execution_contract_version<>2
    OR v_operation.sealed_plan_sha256<>p_sealed_plan_sha256
    OR v_operation.code_sha<>p_code_sha
    OR v_operation.source_snapshot_sha256<>p_source_snapshot_sha256
    OR v_operation.mapping_contract_sha256<>p_mapping_contract_sha256
    OR v_operation.target_identity_sha256<>p_target_identity_sha256
    OR (v_operation.target_tenant_id,v_operation.target_park_id,v_operation.target_scope_sha256)
      IS DISTINCT FROM (p_tenant_id,p_park_id,p_target_scope_sha256) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_OPERATION_INVALID'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.hr_yuzhou_production_import_authorization_use auth
    WHERE auth.intent='production_import' AND auth.operation_id=p_operation_id
      AND auth.import_operation_id=p_operation_id
      AND auth.authorization_artifact_sha256=p_authorization_artifact_sha256
      AND auth.authorization_nonce_sha256=p_authorization_nonce_sha256) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_AUTHORIZATION_INVALID'; END IF;
  SELECT * INTO v_t0_phase FROM public.hr_yuzhou_production_import_phase phase
  WHERE phase.operation_id=p_operation_id AND phase.phase='T0' FOR SHARE;
  IF NOT FOUND OR v_t0_phase.status<>'succeeded'
    OR v_t0_phase.after_canonical_sha256 IS NULL
    OR v_t0_phase.after_canonical_sha256<>p_t0_phase_receipt_sha256 THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_T0_RECEIPT_INVALID'; END IF;
  SELECT * INTO v_batch FROM public.migration_batch batch
  WHERE batch.execution_context='production_import'
    AND batch.production_import_operation_id=p_operation_id
    AND batch.production_import_phase='T0' AND batch.status='succeeded'
    AND batch.target_database=current_database() FOR SHARE;
  IF NOT FOUND OR v_batch.source_system<>'yuzhou-v10'
    OR v_batch.source_snapshot_sha256<>p_source_snapshot_sha256 THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_T0_BATCH_INVALID'; END IF;

  SELECT * INTO v_existing FROM public.hr_yuzhou_performance_relations_production_receipt
    WHERE operation_id=p_operation_id FOR UPDATE;
  IF FOUND THEN
    IF v_existing.status<>'succeeded' OR ROW(
      v_existing.migration_batch_id,v_existing.sealed_plan_sha256,
      v_existing.authorization_artifact_sha256,v_existing.authorization_nonce_sha256,
      v_existing.code_sha,v_existing.source_snapshot_sha256,v_existing.mapping_contract_sha256,
      v_existing.target_identity_sha256,v_existing.tenant_id,v_existing.park_id,
      v_existing.target_scope_sha256,v_existing.t0_phase_receipt_sha256,
      v_existing.relation_payload_artifact_sha256,v_existing.identity_decision_artifact_sha256,
      v_existing.migration_305_sha256,v_existing.migration_306_sha256
    ) IS DISTINCT FROM ROW(
      v_batch.id,p_sealed_plan_sha256,p_authorization_artifact_sha256,p_authorization_nonce_sha256,
      p_code_sha,p_source_snapshot_sha256,p_mapping_contract_sha256,p_target_identity_sha256,
      p_tenant_id,p_park_id,p_target_scope_sha256,p_t0_phase_receipt_sha256,
      p_relation_payload_artifact_sha256,p_identity_decision_artifact_sha256,
      p_migration_305_sha256,p_migration_306_sha256
    ) THEN RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_REPLAY_DRIFT'; END IF;
  ELSE
    BEGIN
      v_relations:=convert_from(p_relation_payload,'UTF8')::jsonb;
      v_identity:=convert_from(p_identity_decision,'UTF8')::jsonb;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_ARTIFACT_INVALID';
    END;
    PERFORM set_config('yuzhou.performance_relations_operation_id',p_operation_id,true);
    PERFORM set_config('yuzhou.performance_relations_mode','apply',true);
    CALL public.hr_yuzhou_materialize_performance_relations_production_v1(
      p_tenant_id,p_park_id,v_batch.id,v_relations);
    CALL public.hr_yuzhou_materialize_performance_identity_production_v1(
      p_tenant_id,p_park_id,v_batch.id,v_identity);
  END IF;

  SELECT count(*) INTO v_session_rows FROM public.hr_performance_legacy_session
    WHERE (tenant_id,park_id,migration_batch_id)=(p_tenant_id,p_park_id,v_batch.id);
  SELECT count(*) INTO v_score_rows FROM public.hr_performance_legacy_score_source
    WHERE (tenant_id,park_id,migration_batch_id)=(p_tenant_id,p_park_id,v_batch.id);
  SELECT count(*) INTO v_assignment_rows FROM public.hr_performance_legacy_source_person_assignment
    WHERE (tenant_id,park_id,migration_batch_id)=(p_tenant_id,p_park_id,v_batch.id);
  SELECT count(*) INTO v_map_rows FROM public.legacy_record_map WHERE batch_id=v_batch.id AND is_active
    AND target_table IN('hr_performance_legacy_session','hr_performance_legacy_score_source',
      'hr_performance_legacy_source_person_assignment');
  SELECT count(*) INTO v_identity_rows FROM public.hr_performance_legacy_identity_resolution
    WHERE (tenant_id,park_id,migration_batch_id)=(p_tenant_id,p_park_id,v_batch.id);
  SELECT count(*) INTO v_binding_rows FROM public.hr_performance_legacy_session_binding
    WHERE (tenant_id,park_id,migration_batch_id)=(p_tenant_id,p_park_id,v_batch.id);
  SELECT count(*) INTO v_subject_unmatched FROM public.hr_performance_legacy_identity_resolution
    WHERE (tenant_id,park_id,migration_batch_id)=(p_tenant_id,p_park_id,v_batch.id)
      AND person_role='subject' AND person_resolution_status='unmatched';
  SELECT count(*) INTO v_blank_assessor FROM public.hr_performance_legacy_identity_resolution
    WHERE (tenant_id,park_id,migration_batch_id)=(p_tenant_id,p_park_id,v_batch.id)
      AND person_role='assessor' AND person_resolution_status='not_applicable'
      AND person_resolution_reason_code='ASSESSOR_CODE_EMPTY';
  IF ROW(v_session_rows,v_score_rows,v_assignment_rows,v_map_rows,v_identity_rows,
    v_binding_rows,v_subject_unmatched,v_blank_assessor)
    IS DISTINCT FROM ROW(7,0,117,124,234,7,108,117) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_CONSERVATION_FAILED'; END IF;
  v_receipt:=encode(digest(convert_to(jsonb_build_object(
    'contract','jinhu-yuzhou-performance-relations-production-v1','operationId',p_operation_id,
    'sealedPlanSha256',p_sealed_plan_sha256,
    'authorizationArtifactSha256',p_authorization_artifact_sha256,
    'authorizationNonceSha256',p_authorization_nonce_sha256,'codeSha',p_code_sha,
    'sourceSnapshotSha256',p_source_snapshot_sha256,'mappingContractSha256',p_mapping_contract_sha256,
    'targetIdentitySha256',p_target_identity_sha256,'targetScopeSha256',p_target_scope_sha256,
    't0PhaseReceiptSha256',p_t0_phase_receipt_sha256,
    'relationPayloadArtifactSha256',p_relation_payload_artifact_sha256,
    'identityDecisionArtifactSha256',p_identity_decision_artifact_sha256,
    'migration305Sha256',p_migration_305_sha256,'migration306Sha256',p_migration_306_sha256,
    'counts',jsonb_build_array(7,0,117,124,234,7,108,117))::text,'UTF8'),'sha256'),'hex');
  INSERT INTO public.hr_yuzhou_performance_relations_production_receipt(
    operation_id,migration_batch_id,sealed_plan_sha256,authorization_artifact_sha256,
    authorization_nonce_sha256,code_sha,source_snapshot_sha256,mapping_contract_sha256,
    target_identity_sha256,tenant_id,park_id,target_scope_sha256,t0_phase_receipt_sha256,
    relation_payload_artifact_sha256,identity_decision_artifact_sha256,
    migration_305_sha256,migration_306_sha256,session_rows,score_source_rows,assignment_rows,
    active_relation_maps,identity_resolution_rows,session_binding_rows,subject_unmatched_rows,
    blank_assessor_rows,receipt_sha256
  ) VALUES(p_operation_id,v_batch.id,p_sealed_plan_sha256,p_authorization_artifact_sha256,
    p_authorization_nonce_sha256,p_code_sha,p_source_snapshot_sha256,p_mapping_contract_sha256,
    p_target_identity_sha256,p_tenant_id,p_park_id,p_target_scope_sha256,p_t0_phase_receipt_sha256,
    p_relation_payload_artifact_sha256,p_identity_decision_artifact_sha256,
    p_migration_305_sha256,p_migration_306_sha256,7,0,117,124,234,7,108,117,v_receipt)
  ON CONFLICT(operation_id) DO NOTHING;
  RETURN QUERY SELECT 'succeeded'::varchar,(v_existing.operation_id IS NOT NULL),
    7,0,117,124,234,7,108,117,v_receipt;
END$$;



--
-- Name: hr_yuzhou_assert_production_projection_record(character varying, character varying, character); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_assert_production_projection_record(p_operation_id character varying, p_phase character varying, p_source_identity_sha256 character) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_record hr_yuzhou_production_import_record%ROWTYPE;
  v_batch migration_batch%ROWTYPE;
  v_receipt hr_yuzhou_production_import_projection_receipt%ROWTYPE;
  v_map legacy_record_map%ROWTYPE;
  v_receipt_count integer;
BEGIN
  SELECT * INTO v_record FROM hr_yuzhou_production_import_record
  WHERE operation_id=p_operation_id AND phase=p_phase AND source_identity_sha256=p_source_identity_sha256;
  IF NOT FOUND THEN RETURN; END IF;

  SELECT * INTO v_batch FROM migration_batch
  WHERE execution_context='production_import'
    AND production_import_operation_id=p_operation_id AND production_import_phase=p_phase;
  IF NOT FOUND THEN RETURN; END IF;

  IF v_record.source_system IS DISTINCT FROM 'yuzhou-v10'
     OR v_record.source_table IS NULL OR btrim(v_record.source_table)=''
     OR v_record.source_pk_canonical IS DISTINCT FROM 'sha256:'||v_record.source_identity_sha256 THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_SOURCE_RECEIPT_REQUIRED';
  END IF;
  IF (v_record.disposition='quarantine' AND v_record.business_identity_sha256 IS NOT NULL)
     OR (v_record.disposition<>'quarantine' AND v_record.business_identity_sha256 IS NULL) THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_BUSINESS_IDENTITY_RECEIPT_INVALID';
  END IF;

  IF (v_record.disposition='insert' AND (
        v_record.expected_target_version_before IS NOT NULL
        OR v_record.target_version_after IS NULL OR v_record.target_version_after<1))
     OR (v_record.disposition='merge' AND (
        v_record.expected_target_version_before IS NULL OR v_record.target_version_after IS NULL
        OR v_record.target_version_after<>v_record.expected_target_version_before+1))
     OR (v_record.disposition='skip_approved' AND (
        v_record.expected_target_version_before IS NULL OR v_record.target_version_after IS NULL
        OR v_record.target_version_after<>v_record.expected_target_version_before))
     OR (v_record.disposition='quarantine' AND (
        v_record.expected_target_version_before IS NOT NULL OR v_record.target_version_after IS NOT NULL)) THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_CAS_VERSION_RECEIPT_INVALID';
  END IF;

  IF (v_record.disposition='insert' AND v_record.rollback_status NOT IN ('not_started','deleted_insert'))
     OR (v_record.disposition='merge' AND v_record.rollback_status NOT IN ('not_started','restored_merge'))
     OR (v_record.disposition='skip_approved' AND v_record.rollback_status NOT IN ('not_started','skip_noop'))
     OR (v_record.disposition='quarantine' AND v_record.rollback_status NOT IN ('not_started','quarantine_noop'))
     OR ((v_record.rollback_status='not_started')<>(v_record.rolled_back_at IS NULL)) THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_RECORD_ROLLBACK_STATE_INVALID';
  END IF;

  SELECT count(*) INTO v_receipt_count FROM hr_yuzhou_production_import_projection_receipt
  WHERE operation_id=p_operation_id AND phase=p_phase AND source_identity_sha256=p_source_identity_sha256;
  IF v_receipt_count<>1 THEN RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_PROJECTION_RECEIPT_REQUIRED'; END IF;

  SELECT * INTO v_receipt FROM hr_yuzhou_production_import_projection_receipt
  WHERE operation_id=p_operation_id AND phase=p_phase AND source_identity_sha256=p_source_identity_sha256;
  SELECT * INTO v_map FROM legacy_record_map WHERE id=v_receipt.legacy_record_map_id;
  IF NOT FOUND
     OR v_receipt.migration_batch_id<>v_batch.id
     OR v_map.batch_id<>v_batch.id
     OR v_map.source_system<>v_record.source_system
     OR v_map.source_table<>v_record.source_table
     OR v_map.source_pk_canonical<>v_record.source_pk_canonical
     OR v_map.source_identity_sha256<>v_record.source_identity_sha256
     OR v_map.source_row_sha256<>v_record.source_row_sha256
     OR v_map.target_table<>COALESCE(v_record.target_table,v_record.planned_target_table)
     OR v_map.target_id IS DISTINCT FROM v_record.target_id THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_PROJECTION_MAP_MISMATCH';
  END IF;
  IF v_record.rollback_status IN ('deleted_insert','restored_merge','quarantine_noop','skip_noop') THEN
    IF v_map.is_active OR v_map.mapping_status<>'rolled_back' THEN
      RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_PROJECTION_ROLLBACK_MISMATCH';
    END IF;
  ELSIF v_record.disposition='quarantine' THEN
    IF NOT v_map.is_active OR v_map.mapping_status<>'quarantined' OR v_map.target_id IS NOT NULL THEN
      RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_QUARANTINE_PROJECTION_INVALID';
    END IF;
  ELSE
    IF NOT v_map.is_active OR v_map.mapping_status NOT IN ('loaded','verified') THEN
      RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_PROJECTION_MAP_INACTIVE';
    END IF;
  END IF;
END$$;



--
-- Name: hr_yuzhou_assert_t5_nonfile_writer_context(character varying, character, character varying, character varying, character, uuid, character, character, character, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_assert_t5_nonfile_writer_context(p_operation_id character varying, p_target_identity_sha256 character, p_target_tenant_id character varying, p_target_park_id character varying, p_target_scope_sha256 character, p_actor_id uuid, p_code_sha character, p_source_snapshot_sha256 character, p_mapping_contract_sha256 character, p_record_count bigint) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_setting('transaction_isolation') <> 'serializable' THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_REQUIRES_SERIALIZABLE';
  END IF;
  IF p_target_scope_sha256 <> hr_yuzhou_production_target_scope_sha256(p_target_tenant_id,p_target_park_id) THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_TARGET_SCOPE_MISMATCH';
  END IF;

  PERFORM 1
  FROM hr_yuzhou_production_import_operation operation
  JOIN hr_yuzhou_production_import_phase phase
    ON phase.operation_id=operation.operation_id AND phase.phase='T5'
  JOIN sys_user actor
    ON actor.id=p_actor_id
   AND actor.tenant_id::text=operation.target_tenant_id
   AND actor.park_id::text=operation.target_park_id
   AND actor.is_enabled=true AND actor.status='enabled' AND actor.is_deleted=false
  WHERE operation.operation_id=p_operation_id
    AND operation.execution_contract_version=2
    AND operation.status='running' AND operation.current_phase='T5'
    AND operation.target_identity_sha256=p_target_identity_sha256
    AND operation.target_tenant_id=p_target_tenant_id
    AND operation.target_park_id=p_target_park_id
    AND operation.target_scope_sha256=p_target_scope_sha256
    AND operation.code_sha=p_code_sha
    AND operation.source_snapshot_sha256=p_source_snapshot_sha256
    AND operation.mapping_contract_sha256=p_mapping_contract_sha256
    AND phase.status='running' AND phase.planned_record_count=p_record_count
  FOR SHARE OF operation,phase,actor;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_T5_WRITER_CONTEXT_INVALID';
  END IF;
  RETURN true;
END $$;



--
-- Name: hr_yuzhou_bind_t5_nonfile_rollback_context(character varying, character varying, character, character varying, character varying, character, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_bind_t5_nonfile_rollback_context(p_rollback_operation_id character varying, p_import_operation_id character varying, p_target_identity_sha256 character, p_target_tenant_id character varying, p_target_park_id character varying, p_target_scope_sha256 character, p_actor_id uuid) RETURNS TABLE(batch_id uuid, run_id character varying)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_batch_id uuid;
  v_run_id varchar(64);
BEGIN
  IF current_setting('transaction_isolation') <> 'serializable' THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_REQUIRES_SERIALIZABLE';
  END IF;
  IF p_target_scope_sha256 <> hr_yuzhou_production_target_scope_sha256(p_target_tenant_id,p_target_park_id) THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_TARGET_SCOPE_MISMATCH';
  END IF;

  SELECT batch.id,batch.run_id INTO v_batch_id,v_run_id
  FROM hr_yuzhou_production_import_rollback_operation rollback_operation
  JOIN hr_yuzhou_production_import_operation operation
    ON operation.operation_id=rollback_operation.import_operation_id
  JOIN hr_yuzhou_production_import_authorization_use authorization_use
    ON authorization_use.intent='production_import_rollback'
   AND authorization_use.operation_id=rollback_operation.rollback_operation_id
   AND authorization_use.import_operation_id=operation.operation_id
   AND authorization_use.authorization_artifact_sha256=rollback_operation.authorization_artifact_sha256
   AND authorization_use.authorization_nonce_sha256=rollback_operation.authorization_nonce_sha256
  JOIN hr_yuzhou_production_import_phase phase
    ON phase.operation_id=operation.operation_id AND phase.phase='T5'
  JOIN migration_batch batch
    ON batch.production_import_operation_id=operation.operation_id
   AND batch.production_import_phase='T5'
   AND batch.execution_context='production_import'
  JOIN sys_user actor
    ON actor.id=p_actor_id
   AND actor.tenant_id::text=operation.target_tenant_id
   AND actor.park_id::text=operation.target_park_id
   AND actor.is_enabled=true AND actor.status='enabled' AND actor.is_deleted=false
  WHERE rollback_operation.rollback_operation_id=p_rollback_operation_id
    AND rollback_operation.import_operation_id=p_import_operation_id
    AND rollback_operation.status='running'
    AND now()>=rollback_operation.authorization_issued_at
    AND now()<rollback_operation.authorization_expires_at
    AND rollback_operation.target_identity_sha256=p_target_identity_sha256
    AND rollback_operation.target_identity_sha256=operation.target_identity_sha256
    AND rollback_operation.sealed_plan_sha256=operation.sealed_plan_sha256
    AND operation.execution_contract_version=2
    AND operation.status='succeeded' AND operation.current_phase='T5'
    AND operation.target_tenant_id=p_target_tenant_id
    AND operation.target_park_id=p_target_park_id
    AND operation.target_scope_sha256=p_target_scope_sha256
    AND phase.status='rolling_back'
    AND batch.status='succeeded'
    AND batch.run_id=operation.operation_id||'-t5'
    AND batch.target_database=current_database()
    AND batch.production_import_actor_id=p_actor_id
  FOR UPDATE OF rollback_operation,operation,phase,batch,actor;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_T5_ROLLBACK_AUTH_INVALID';
  END IF;

  UPDATE hr_yuzhou_production_import_rollback_operation rollback_operation
  SET t5_nonfile_executor_actor_id=p_actor_id,
      t5_nonfile_execution_xid=pg_current_xact_id()
  WHERE rollback_operation.rollback_operation_id=p_rollback_operation_id
    AND (
      rollback_operation.t5_nonfile_execution_xid IS NULL
      OR (
        rollback_operation.t5_nonfile_execution_xid=pg_current_xact_id()
        AND rollback_operation.t5_nonfile_executor_actor_id=p_actor_id
      )
    );
  IF NOT FOUND THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_T5_ROLLBACK_TRANSACTION_MISMATCH';
  END IF;

  RETURN QUERY SELECT v_batch_id,v_run_id;
END $$;



--
-- Name: hr_yuzhou_consume_import_authorization(character varying, character, character, character, character, character, character, character, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, character, character, character, character, character); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_consume_import_authorization(p_operation_id character varying, p_code_sha character, p_source_snapshot_sha256 character, p_mapping_contract_sha256 character, p_sealed_plan_sha256 character, p_target_identity_sha256 character, p_authorization_artifact_sha256 character, p_authorization_nonce_sha256 character, p_authorization_issued_at timestamp with time zone, p_authorization_expires_at timestamp with time zone, p_window_starts_at timestamp with time zone, p_window_ends_at timestamp with time zone, p_approval_set_sha256 character, p_manifest_sha256 character, p_final_rehearsal_pair_sha256 character, p_rehearsal_a_manifest_sha256 character, p_rehearsal_b_manifest_sha256 character) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_setting('transaction_isolation') <> 'serializable' THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_REQUIRES_SERIALIZABLE';
  END IF;
  IF now() < p_window_starts_at OR now() >= p_window_ends_at
     OR now() < p_authorization_issued_at OR now() >= p_authorization_expires_at
     OR p_authorization_issued_at < p_window_starts_at OR p_authorization_expires_at > p_window_ends_at THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_AUTH_STALE';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('hr_yuzhou_production_import',0));
  INSERT INTO hr_yuzhou_production_import_operation(
    operation_id,intent,status,code_sha,source_snapshot_sha256,mapping_contract_sha256,sealed_plan_sha256,
    target_identity_sha256,authorization_artifact_sha256,authorization_nonce_sha256,
    authorization_issued_at,authorization_expires_at,window_starts_at,window_ends_at,approval_set_sha256,
    manifest_sha256,final_rehearsal_pair_sha256,rehearsal_a_manifest_sha256,rehearsal_b_manifest_sha256,phase_order
  ) VALUES (
    p_operation_id,'production_import','authorized',p_code_sha,p_source_snapshot_sha256,p_mapping_contract_sha256,p_sealed_plan_sha256,
    p_target_identity_sha256,p_authorization_artifact_sha256,p_authorization_nonce_sha256,
    p_authorization_issued_at,p_authorization_expires_at,p_window_starts_at,p_window_ends_at,p_approval_set_sha256,
    p_manifest_sha256,p_final_rehearsal_pair_sha256,p_rehearsal_a_manifest_sha256,p_rehearsal_b_manifest_sha256,'["T0","T1","T2","T3"]'::jsonb
  );
  INSERT INTO hr_yuzhou_production_import_authorization_use(intent,operation_id,import_operation_id,authorization_artifact_sha256,authorization_nonce_sha256)
  VALUES('production_import',p_operation_id,p_operation_id,p_authorization_artifact_sha256,p_authorization_nonce_sha256);
END$$;



