CREATE FUNCTION public.hr_yuzhou_consume_import_authorization_v2(p_operation_id character varying, p_code_sha character, p_source_snapshot_sha256 character, p_mapping_contract_sha256 character, p_sealed_plan_sha256 character, p_target_identity_sha256 character, p_target_tenant_id character varying, p_target_park_id character varying, p_target_scope_sha256 character, p_authorization_artifact_sha256 character, p_authorization_nonce_sha256 character, p_authorization_issued_at timestamp with time zone, p_authorization_expires_at timestamp with time zone, p_window_starts_at timestamp with time zone, p_window_ends_at timestamp with time zone, p_approval_set_sha256 character, p_manifest_sha256 character, p_final_rehearsal_pair_sha256 character, p_rehearsal_a_manifest_sha256 character, p_rehearsal_b_manifest_sha256 character) RETURNS void
