--
-- Name: hr_yuzhou_consume_performance_person_assessment_authorization(character varying, character varying, character, character, character, character, character, character, character, character, character, character, character, character, character, character, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_consume_performance_person_assessment_authorization(p_operation_id character varying, p_parent_import_operation_id character varying, p_code_sha character, p_source_snapshot_sha256 character, p_mapping_contract_sha256 character, p_t0_artifact_sha256 character, p_contract_artifact_sha256 character, p_source_restore_receipt_sha256 character, p_source_payload_artifact_sha256 character, p_safe_receipt_artifact_sha256 character, p_migration_artifact_sha256 character, p_payload_sha256 character, p_sealed_artifact_sha256 character, p_binding_sha256 character, p_authorization_artifact_sha256 character, p_authorization_nonce_sha256 character, p_authorization_expires_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_parent public.hr_yuzhou_production_import_operation%ROWTYPE;
  v_relations public.hr_yuzhou_performance_relations_production_receipt%ROWTYPE;
  v_existing public.hr_yuzhou_performance_person_assessment_operation%ROWTYPE;
  v_owner_state char(64);
BEGIN
  IF current_setting('transaction_isolation')<>'serializable' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_PERSON_ASSESSMENT_REQUIRES_SERIALIZABLE'; END IF;
  IF now()>=p_authorization_expires_at THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_PERSON_ASSESSMENT_AUTH_STALE'; END IF;
  IF p_operation_id!~'^yzprod-perfrel-[0-9]{8}T[0-9]{6}Z-[0-9a-f]{12}$'
    OR p_code_sha!~'^[0-9a-f]{40}$'
    OR p_source_snapshot_sha256!~'^[0-9a-f]{64}$'
    OR p_mapping_contract_sha256!~'^[0-9a-f]{64}$'
    OR p_t0_artifact_sha256!~'^[0-9a-f]{64}$'
    OR p_source_restore_receipt_sha256!~'^[0-9a-f]{64}$'
    OR p_source_payload_artifact_sha256!~'^[0-9a-f]{64}$'
    OR p_safe_receipt_artifact_sha256!~'^[0-9a-f]{64}$'
    OR p_payload_sha256!~'^[0-9a-f]{64}$'
    OR p_sealed_artifact_sha256!~'^[0-9a-f]{64}$'
    OR p_binding_sha256!~'^[0-9a-f]{64}$'
    OR p_authorization_artifact_sha256!~'^[0-9a-f]{64}$'
    OR p_authorization_nonce_sha256!~'^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_PERSON_ASSESSMENT_AUTH_INVALID'; END IF;
  IF p_contract_artifact_sha256<>'f9eac8435900c05251c82c0c1be04bbe63992ca9f65a9879c21c838af898f62c'
    OR p_migration_artifact_sha256<>'0467f31888a5fb52c7c63ab1e754a68ab76822b2e177318bf249f71eb1f8887a' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_PERSON_ASSESSMENT_ARTIFACT_DRIFT'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('hr_yuzhou_performance_person_assessment',0));
  SELECT * INTO v_existing FROM public.hr_yuzhou_performance_person_assessment_operation
    WHERE operation_id=p_operation_id FOR UPDATE;
  IF FOUND THEN
    IF ROW(v_existing.parent_import_operation_id,v_existing.code_sha,
        v_existing.source_snapshot_sha256,v_existing.mapping_contract_sha256,
        v_existing.t0_artifact_sha256,v_existing.contract_artifact_sha256,
        v_existing.source_restore_receipt_sha256,v_existing.source_payload_artifact_sha256,
        v_existing.safe_receipt_artifact_sha256,v_existing.migration_307_sha256,
        v_existing.payload_sha256,v_existing.sealed_artifact_sha256,
        v_existing.binding_sha256,v_existing.authorization_artifact_sha256,
        v_existing.authorization_nonce_sha256)
      IS DISTINCT FROM ROW(p_parent_import_operation_id,p_code_sha,
        p_source_snapshot_sha256,p_mapping_contract_sha256,p_t0_artifact_sha256,
        p_contract_artifact_sha256,p_source_restore_receipt_sha256,
        p_source_payload_artifact_sha256,p_safe_receipt_artifact_sha256,
        p_migration_artifact_sha256,p_payload_sha256,p_sealed_artifact_sha256,
        p_binding_sha256,p_authorization_artifact_sha256,p_authorization_nonce_sha256) THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_PERSON_ASSESSMENT_AUTH_REPLAY_DRIFT'; END IF;
    RETURN;
  END IF;
  SELECT * INTO v_parent FROM public.hr_yuzhou_production_import_operation
    WHERE operation_id=p_parent_import_operation_id FOR SHARE;
  SELECT * INTO v_relations FROM public.hr_yuzhou_performance_relations_production_receipt
    WHERE operation_id=p_parent_import_operation_id FOR SHARE;
  IF v_parent.operation_id IS NULL OR v_relations.operation_id IS NULL
    OR v_parent.execution_contract_version<>2 OR v_parent.status<>'running'
    OR v_parent.current_phase<>'T0'
    OR ROW(v_parent.code_sha,v_parent.source_snapshot_sha256,v_parent.mapping_contract_sha256)
      IS DISTINCT FROM ROW(p_code_sha,p_source_snapshot_sha256,p_mapping_contract_sha256)
    OR v_relations.status<>'succeeded'
    OR ROW(v_relations.code_sha,v_relations.source_snapshot_sha256,
      v_relations.mapping_contract_sha256,v_relations.target_identity_sha256,
      v_relations.tenant_id,v_relations.park_id,v_relations.target_scope_sha256,
      v_relations.t0_phase_receipt_sha256)
      IS DISTINCT FROM ROW(v_parent.code_sha,v_parent.source_snapshot_sha256,
        v_parent.mapping_contract_sha256,v_parent.target_identity_sha256,
        v_parent.target_tenant_id,v_parent.target_park_id,v_parent.target_scope_sha256,
        p_t0_artifact_sha256)
    OR p_authorization_expires_at>v_parent.window_ends_at
    OR NOT public.hr_yuzhou_performance_person_assessment_dependency_valid(
      p_parent_import_operation_id,v_relations.migration_batch_id) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_PERSON_ASSESSMENT_PARENT_BINDING_INVALID'; END IF;
  v_owner_state:=public.hr_yuzhou_performance_person_assessment_owner_state_sha256(
    v_relations.migration_batch_id);
  IF EXISTS(SELECT 1 FROM public.hr_yuzhou_performance_person_assessment_authorization_use
    WHERE authorization_artifact_sha256=p_authorization_artifact_sha256
      OR authorization_nonce_sha256=p_authorization_nonce_sha256) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_PERSON_ASSESSMENT_AUTH_REUSED'; END IF;
  INSERT INTO public.hr_yuzhou_performance_person_assessment_operation(
    operation_id,parent_import_operation_id,migration_batch_id,status,code_sha,
    source_snapshot_sha256,mapping_contract_sha256,target_identity_sha256,
    target_tenant_id,target_park_id,target_scope_sha256,t0_artifact_sha256,
    source_restore_receipt_sha256,source_payload_artifact_sha256,
    safe_receipt_artifact_sha256,contract_artifact_sha256,migration_307_sha256,
    migration_308_sha256,payload_sha256,sealed_artifact_sha256,binding_sha256,
    authorization_artifact_sha256,authorization_nonce_sha256,
    authorization_expires_at,owner_state_sha256
  ) VALUES(
    p_operation_id,p_parent_import_operation_id,v_relations.migration_batch_id,'authorized',p_code_sha,
    p_source_snapshot_sha256,p_mapping_contract_sha256,v_parent.target_identity_sha256,
    v_parent.target_tenant_id,v_parent.target_park_id,v_parent.target_scope_sha256,p_t0_artifact_sha256,
    p_source_restore_receipt_sha256,p_source_payload_artifact_sha256,
    p_safe_receipt_artifact_sha256,p_contract_artifact_sha256,p_migration_artifact_sha256,
    'ad77e0cf12cf73f98a5984835a9943a9e15c96cde37fe6bd95133845c711befa',p_payload_sha256,p_sealed_artifact_sha256,p_binding_sha256,
    p_authorization_artifact_sha256,p_authorization_nonce_sha256,p_authorization_expires_at,v_owner_state
  );
  INSERT INTO public.hr_yuzhou_performance_person_assessment_authorization_use(
    intent,operation_id,import_operation_id,authorization_artifact_sha256,authorization_nonce_sha256
  ) VALUES('production_performance_person_assessment_import',p_operation_id,p_operation_id,
    p_authorization_artifact_sha256,p_authorization_nonce_sha256);
END$_$;



--
-- Name: hr_yuzhou_consume_performance_person_assessment_rollback_author(character varying, character varying, character, character, character, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_consume_performance_person_assessment_rollback_author(p_rollback_operation_id character varying, p_import_operation_id character varying, p_sealed_artifact_sha256 character, p_authorization_artifact_sha256 character, p_authorization_nonce_sha256 character, p_authorization_expires_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_import public.hr_yuzhou_performance_person_assessment_operation%ROWTYPE;
  v_existing public.hr_yuzhou_performance_person_assessment_rollback_operation%ROWTYPE;
  v_parent public.hr_yuzhou_production_import_operation%ROWTYPE;
BEGIN
  IF current_setting('transaction_isolation')<>'serializable' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_PERSON_ASSESSMENT_REQUIRES_SERIALIZABLE'; END IF;
  IF now()>=p_authorization_expires_at
    OR p_rollback_operation_id!~'^yzprod-perfrel-rollback-[0-9]{8}T[0-9]{6}Z-[0-9a-f]{12}$'
    OR p_authorization_artifact_sha256!~'^[0-9a-f]{64}$'
    OR p_authorization_nonce_sha256!~'^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_PERSON_ASSESSMENT_ROLLBACK_AUTH_INVALID'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('hr_yuzhou_performance_person_assessment',0));
  SELECT * INTO v_existing
    FROM public.hr_yuzhou_performance_person_assessment_rollback_operation
    WHERE rollback_operation_id=p_rollback_operation_id FOR UPDATE;
  IF FOUND THEN
    IF ROW(v_existing.import_operation_id,v_existing.sealed_artifact_sha256,
        v_existing.authorization_artifact_sha256,v_existing.authorization_nonce_sha256)
      IS DISTINCT FROM ROW(p_import_operation_id,p_sealed_artifact_sha256,
        p_authorization_artifact_sha256,p_authorization_nonce_sha256) THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_PERSON_ASSESSMENT_ROLLBACK_AUTH_REPLAY_DRIFT'; END IF;
    RETURN;
  END IF;
  SELECT * INTO v_import FROM public.hr_yuzhou_performance_person_assessment_operation
    WHERE operation_id=p_import_operation_id FOR UPDATE;
  SELECT * INTO v_parent FROM public.hr_yuzhou_production_import_operation
    WHERE operation_id=v_import.parent_import_operation_id FOR SHARE;
  IF v_import.operation_id IS NULL OR v_parent.operation_id IS NULL
    OR v_import.status<>'succeeded'
    OR v_import.sealed_artifact_sha256<>p_sealed_artifact_sha256
    OR p_authorization_expires_at>v_parent.window_ends_at
    OR NOT public.hr_yuzhou_performance_person_assessment_dependency_valid(
      v_import.parent_import_operation_id,v_import.migration_batch_id)
    OR public.hr_yuzhou_performance_person_assessment_owner_state_sha256(
      v_import.migration_batch_id)<>v_import.owner_state_sha256 THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_PERSON_ASSESSMENT_ROLLBACK_SOURCE_INVALID'; END IF;
  IF EXISTS(SELECT 1 FROM public.hr_yuzhou_performance_person_assessment_authorization_use
    WHERE authorization_artifact_sha256=p_authorization_artifact_sha256
      OR authorization_nonce_sha256=p_authorization_nonce_sha256) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_PERSON_ASSESSMENT_AUTH_REUSED'; END IF;
  INSERT INTO public.hr_yuzhou_performance_person_assessment_rollback_operation(
    rollback_operation_id,import_operation_id,status,sealed_artifact_sha256,
    authorization_artifact_sha256,authorization_nonce_sha256,authorization_expires_at
  ) VALUES(p_rollback_operation_id,p_import_operation_id,'authorized',p_sealed_artifact_sha256,
    p_authorization_artifact_sha256,p_authorization_nonce_sha256,p_authorization_expires_at);
  INSERT INTO public.hr_yuzhou_performance_person_assessment_authorization_use(
    intent,operation_id,import_operation_id,authorization_artifact_sha256,authorization_nonce_sha256
  ) VALUES('production_performance_person_assessment_rollback',p_rollback_operation_id,
    p_import_operation_id,p_authorization_artifact_sha256,p_authorization_nonce_sha256);
END$_$;



--
-- Name: hr_yuzhou_consume_rollback_authorization(character varying, character varying, character, character, character, character, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_consume_rollback_authorization(p_rollback_operation_id character varying, p_import_operation_id character varying, p_sealed_plan_sha256 character, p_target_identity_sha256 character, p_authorization_artifact_sha256 character, p_authorization_nonce_sha256 character, p_authorization_issued_at timestamp with time zone, p_authorization_expires_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_setting('transaction_isolation') <> 'serializable' THEN RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_REQUIRES_SERIALIZABLE'; END IF;
  IF now() < p_authorization_issued_at OR now() >= p_authorization_expires_at THEN RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_AUTH_STALE'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('hr_yuzhou_production_import_rollback',0));
  IF NOT EXISTS(SELECT 1 FROM hr_yuzhou_production_import_operation WHERE operation_id=p_import_operation_id AND sealed_plan_sha256=p_sealed_plan_sha256 AND target_identity_sha256=p_target_identity_sha256 AND status='succeeded') THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_ROLLBACK_SOURCE_INVALID';
  END IF;
  INSERT INTO hr_yuzhou_production_import_rollback_operation(rollback_operation_id,import_operation_id,status,sealed_plan_sha256,target_identity_sha256,authorization_artifact_sha256,authorization_nonce_sha256,authorization_issued_at,authorization_expires_at)
  VALUES(p_rollback_operation_id,p_import_operation_id,'authorized',p_sealed_plan_sha256,p_target_identity_sha256,p_authorization_artifact_sha256,p_authorization_nonce_sha256,p_authorization_issued_at,p_authorization_expires_at);
  INSERT INTO hr_yuzhou_production_import_authorization_use(intent,operation_id,import_operation_id,authorization_artifact_sha256,authorization_nonce_sha256)
  VALUES('production_import_rollback',p_rollback_operation_id,p_import_operation_id,p_authorization_artifact_sha256,p_authorization_nonce_sha256);
END$$;



--
-- Name: hr_yuzhou_guard_production_record_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_guard_production_record_receipt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP='UPDATE' AND (
    NEW.source_system IS DISTINCT FROM OLD.source_system
    OR NEW.source_table IS DISTINCT FROM OLD.source_table
    OR NEW.source_pk_canonical IS DISTINCT FROM OLD.source_pk_canonical
    OR NEW.business_identity_sha256 IS DISTINCT FROM OLD.business_identity_sha256
    OR NEW.source_identity_sha256 IS DISTINCT FROM OLD.source_identity_sha256
    OR NEW.source_row_sha256 IS DISTINCT FROM OLD.source_row_sha256
    OR NEW.disposition IS DISTINCT FROM OLD.disposition
    OR NEW.planned_target_table IS DISTINCT FROM OLD.planned_target_table
    OR NEW.target_table IS DISTINCT FROM OLD.target_table
    OR NEW.target_id IS DISTINCT FROM OLD.target_id
    OR NEW.expected_target_before_sha256 IS DISTINCT FROM OLD.expected_target_before_sha256
    OR NEW.target_after_sha256 IS DISTINCT FROM OLD.target_after_sha256
    OR NEW.expected_target_version_before IS DISTINCT FROM OLD.expected_target_version_before
    OR NEW.target_version_after IS DISTINCT FROM OLD.target_version_after
  ) AND EXISTS(
    SELECT 1 FROM hr_yuzhou_production_import_projection_receipt receipt
    WHERE (receipt.operation_id,receipt.phase,receipt.source_identity_sha256)=
      (OLD.operation_id,OLD.phase,OLD.source_identity_sha256)
  ) THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_RECORD_RECEIPT_IMMUTABLE';
  END IF;
  RETURN NEW;
END$$;



--
-- Name: hr_yuzhou_guard_t0_owner_map_reverse(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_guard_t0_owner_map_reverse() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS(
    SELECT 1 FROM hr_legacy_identity_registry registry
    WHERE registry.owner_record_map_id=OLD.id
      AND registry.mapping_status IN ('mapped','resolved')
  ) THEN RETURN COALESCE(NEW,OLD); END IF;
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'HR_LEGACY_T0_OWNER_MAP_REFERENCED';
  END IF;
  IF NOT NEW.is_active
     OR NEW.mapping_status NOT IN ('loaded','verified')
     OR ROW(NEW.source_system,NEW.source_table,NEW.source_identity_sha256,NEW.target_table,NEW.target_id)
        IS DISTINCT FROM
        ROW(OLD.source_system,OLD.source_table,OLD.source_identity_sha256,OLD.target_table,OLD.target_id) THEN
    RAISE EXCEPTION 'HR_LEGACY_T0_OWNER_MAP_REFERENCED';
  END IF;
  RETURN NEW;
END$$;



--
-- Name: hr_yuzhou_materialize_performance_fact_identity_production_v1(character varying, character varying, uuid); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.hr_yuzhou_materialize_performance_fact_identity_production_v1(IN p_tenant_id character varying, IN p_park_id character varying, IN p_batch_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_fact record; v_identity char(64); v_candidate_count integer;
  v_owner_map_id uuid; v_employee_id uuid; v_binding public.hr_performance_legacy_session_binding%ROWTYPE;
  v_person_status varchar; v_person_reason varchar; v_cycle_status varchar; v_cycle_reason varchar;
  v_cycle_count integer; v_cycle_employee_id uuid; v_resolution_id uuid;
  v_namespace constant uuid:='71382084-c80d-4bbf-b735-a816c79a0f6c';
BEGIN
  IF current_setting('transaction_isolation')<>'serializable'
    OR NOT public.hr_yuzhou_performance_fact_identity_context_allowed_v1(p_batch_id,'apply') THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_FACT_IDENTITY_PRODUCTION_CONTEXT_INVALID'; END IF;
  LOCK TABLE public.hr_performance_legacy_identity_resolution,public.legacy_record_map,
    public.hr_yuzhou_production_import_projection_receipt,
    public.hr_performance_legacy_session_binding,public.hr_performance_cycle_employee
    IN SHARE ROW EXCLUSIVE MODE;
  FOR v_fact IN
    SELECT 'dimension_result'::varchar fact_kind,fact.id fact_id,fact.source_person_code,
      fact.source_session_id,fact.id dimension_id,NULL::uuid master_id
    FROM public.hr_performance_legacy_dimension_result fact
    WHERE (fact.tenant_id,fact.park_id,fact.migration_batch_id)=(p_tenant_id,p_park_id,p_batch_id)
    UNION ALL
    SELECT 'master_result',fact.id,fact.source_person_code,fact.source_session_id,
      NULL::uuid,fact.id
    FROM public.hr_performance_legacy_master_result fact
    WHERE (fact.tenant_id,fact.park_id,fact.migration_batch_id)=(p_tenant_id,p_park_id,p_batch_id)
    ORDER BY fact_kind,fact_id
  LOOP
    v_identity:=public.hr_performance_yuzhou_person_identity_sha256(v_fact.source_person_code);
    v_owner_map_id:=NULL; v_employee_id:=NULL;
    IF v_identity IS NULL THEN
      v_person_status:='not_applicable'; v_person_reason:='SUBJECT_CODE_EMPTY';
    ELSE
      SELECT count(*),(array_agg(owner_t0_record_map_id ORDER BY owner_t0_record_map_id))[1],
        (array_agg(target_employee_id ORDER BY owner_t0_record_map_id))[1]
        INTO v_candidate_count,v_owner_map_id,v_employee_id
      FROM public.hr_performance_yuzhou_t0_person_candidate(p_tenant_id,p_park_id,v_identity);
      IF v_candidate_count=1 THEN
        v_person_status:='resolved'; v_person_reason:='EXACT_T0_PERSON_MAP';
      ELSIF v_candidate_count=0 THEN
        v_owner_map_id:=NULL; v_employee_id:=NULL;
        v_person_status:='unmatched'; v_person_reason:='T0_PERSON_MAP_NOT_FOUND';
      ELSE
        v_owner_map_id:=NULL; v_employee_id:=NULL;
        v_person_status:='ambiguous'; v_person_reason:='T0_PERSON_MAP_AMBIGUOUS';
      END IF;
    END IF;
    SELECT binding.* INTO v_binding
    FROM public.hr_performance_legacy_session source_session
    JOIN public.hr_performance_legacy_session_binding binding
      ON binding.legacy_session_id=source_session.id
    WHERE (source_session.tenant_id,source_session.park_id,source_session.migration_batch_id,
      source_session.source_session_id)=
      (p_tenant_id,p_park_id,p_batch_id,v_fact.source_session_id);
    IF NOT FOUND THEN v_binding:=NULL; END IF;
    v_cycle_employee_id:=NULL;
    IF v_person_status<>'resolved' THEN
      v_cycle_status:='not_applicable'; v_cycle_reason:='PERSON_UNRESOLVED';
    ELSIF v_fact.source_session_id IS NULL THEN
      v_cycle_status:='not_applicable'; v_cycle_reason:='SESSION_NOT_APPLICABLE';
    ELSIF v_binding.id IS NULL OR v_binding.resolution_status<>'resolved' THEN
      v_cycle_status:='unmatched'; v_cycle_reason:='SESSION_BINDING_UNRESOLVED';
    ELSE
      SELECT count(*),(array_agg(id ORDER BY id))[1] INTO v_cycle_count,v_cycle_employee_id
      FROM public.hr_performance_cycle_employee
      WHERE (tenant_id,park_id,cycle_id,employee_id)=
        (p_tenant_id,p_park_id,v_binding.target_review_cycle_id,v_employee_id);
      IF v_cycle_count=1 THEN
        v_cycle_status:='resolved'; v_cycle_reason:='EXACT_CYCLE_EMPLOYEE';
      ELSIF v_cycle_count=0 THEN
        v_cycle_employee_id:=NULL; v_cycle_status:='unmatched';
        v_cycle_reason:='CYCLE_EMPLOYEE_NOT_FOUND';
      ELSE
        v_cycle_employee_id:=NULL; v_cycle_status:='ambiguous';
        v_cycle_reason:='CYCLE_EMPLOYEE_AMBIGUOUS';
      END IF;
    END IF;
    v_resolution_id:=uuid_generate_v5(v_namespace,
      'fact:'||p_batch_id::text||':'||v_fact.fact_kind||':'||v_fact.fact_id::text||':subject');
    INSERT INTO public.hr_performance_legacy_identity_resolution(
      id,tenant_id,park_id,migration_batch_id,fact_kind,person_role,
      legacy_dimension_result_id,legacy_master_result_id,source_person_identity_sha256,
      person_resolution_status,person_resolution_reason_code,owner_t0_record_map_id,
      target_employee_id,session_binding_id,cycle_resolution_status,
      cycle_resolution_reason_code,target_cycle_employee_id,evidence_sha256
    ) VALUES(v_resolution_id,p_tenant_id,p_park_id,p_batch_id,v_fact.fact_kind,'subject',
      v_fact.dimension_id,v_fact.master_id,v_identity,v_person_status,v_person_reason,v_owner_map_id,
      v_employee_id,v_binding.id,v_cycle_status,v_cycle_reason,v_cycle_employee_id,
      public.hr_performance_yuzhou_identity_resolution_evidence_sha256(
        v_fact.fact_kind,v_fact.fact_id,'subject',v_identity,v_person_status,v_person_reason,
        v_owner_map_id,v_employee_id,v_binding.id,v_cycle_status,v_cycle_reason,v_cycle_employee_id))
    ON CONFLICT(id) DO NOTHING;
    IF NOT EXISTS(SELECT 1 FROM public.hr_performance_legacy_identity_resolution resolution
      WHERE resolution.id=v_resolution_id AND resolution.fact_kind=v_fact.fact_kind
        AND resolution.source_person_identity_sha256 IS NOT DISTINCT FROM v_identity
        AND resolution.person_resolution_status=v_person_status
        AND resolution.person_resolution_reason_code=v_person_reason
        AND resolution.owner_t0_record_map_id IS NOT DISTINCT FROM v_owner_map_id
        AND resolution.target_employee_id IS NOT DISTINCT FROM v_employee_id
        AND resolution.session_binding_id IS NOT DISTINCT FROM v_binding.id
        AND resolution.cycle_resolution_status=v_cycle_status
        AND resolution.cycle_resolution_reason_code=v_cycle_reason
        AND resolution.target_cycle_employee_id IS NOT DISTINCT FROM v_cycle_employee_id) THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_FACT_IDENTITY_PRODUCTION_REPLAY_DRIFT'; END IF;
  END LOOP;
END$$;



--
-- Name: hr_yuzhou_materialize_performance_identity_production_v1(character varying, character varying, uuid, jsonb); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.hr_yuzhou_materialize_performance_identity_production_v1(IN p_tenant_id character varying, IN p_park_id character varying, IN p_batch_id uuid, IN p_payload jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_row jsonb; v_session hr_performance_legacy_session%ROWTYPE; v_binding_id uuid;
  v_target_cycle_id uuid; v_assignment hr_performance_legacy_source_person_assignment%ROWTYPE;
  v_role varchar; v_source_code varchar; v_identity char(64); v_person_status varchar;
  v_person_reason varchar; v_candidate_count integer; v_owner_map_id uuid; v_employee_id uuid;
  v_binding hr_performance_legacy_session_binding%ROWTYPE; v_cycle_status varchar;
  v_cycle_reason varchar; v_cycle_count integer; v_cycle_employee_id uuid; v_resolution_id uuid;
  v_namespace constant uuid:='71382084-c80d-4bbf-b735-a816c79a0f6c';
BEGIN
  IF current_setting('transaction_isolation')<>'serializable'
    OR NOT public.hr_yuzhou_performance_relations_production_context_allowed(p_batch_id,'apply') THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_CONTEXT_INVALID'; END IF;
  IF NOT public.hr_performance_yuzhou_jsonb_exact_keys(p_payload,ARRAY['sessions'])
    OR jsonb_typeof(p_payload->'sessions')<>'array'
    OR jsonb_array_length(p_payload->'sessions')<>7 THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_IDENTITY_PAYLOAD_INVALID'; END IF;
  LOCK TABLE public.hr_performance_legacy_session_binding,
    public.hr_performance_legacy_identity_resolution,public.legacy_record_map,
    public.hr_yuzhou_production_import_projection_receipt,
    public.hr_performance_cycle_employee IN SHARE ROW EXCLUSIVE MODE;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_payload->'sessions') LOOP
    IF NOT public.hr_performance_yuzhou_jsonb_exact_keys(v_row,ARRAY[
      'sourceSessionIdentitySha256','status','reasonCode','targetReviewCycleId','decisionAttestationSha256'])
      OR (v_row->>'sourceSessionIdentitySha256')!~'^[0-9a-f]{64}$'
      OR (v_row->>'decisionAttestationSha256')!~'^[0-9a-f]{64}$'
      OR (v_row->>'status') NOT IN('resolved','unmatched','ambiguous','semantics_unverified')
      OR (v_row->>'reasonCode')!~'^[A-Z][A-Z0-9_]{2,63}$' THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_SESSION_DECISION_INVALID'; END IF;
    SELECT * INTO STRICT v_session FROM public.hr_performance_legacy_session
    WHERE (tenant_id,park_id,migration_batch_id,source_identity_sha256)=
      (p_tenant_id,p_park_id,p_batch_id,(v_row->>'sourceSessionIdentitySha256')::char(64));
    v_target_cycle_id:=NULLIF(v_row->>'targetReviewCycleId','')::uuid;
    IF ((v_row->>'status')='resolved')<>(v_target_cycle_id IS NOT NULL) THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_SESSION_TARGET_INVALID'; END IF;
    IF (v_row->>'status')='resolved' AND NOT EXISTS(SELECT 1
      FROM public.hr_performance_review_cycle cycle
      WHERE (cycle.id,cycle.tenant_id,cycle.park_id)=(v_target_cycle_id,p_tenant_id,p_park_id)) THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_SESSION_TARGET_INVALID'; END IF;
    v_binding_id:=uuid_generate_v5(v_namespace,
      'session:'||p_batch_id::text||':'||v_session.source_identity_sha256);
    INSERT INTO public.hr_performance_legacy_session_binding(
      id,tenant_id,park_id,migration_batch_id,legacy_session_id,source_session_identity_sha256,
      resolution_status,resolution_reason_code,target_review_cycle_id,decision_attestation_sha256
    ) VALUES(v_binding_id,p_tenant_id,p_park_id,p_batch_id,v_session.id,v_session.source_identity_sha256,
      v_row->>'status',v_row->>'reasonCode',v_target_cycle_id,v_row->>'decisionAttestationSha256')
    ON CONFLICT(id) DO NOTHING;
    IF NOT EXISTS(SELECT 1 FROM public.hr_performance_legacy_session_binding binding
      WHERE binding.id=v_binding_id AND binding.legacy_session_id=v_session.id
        AND binding.resolution_status=v_row->>'status'
        AND binding.resolution_reason_code=v_row->>'reasonCode'
        AND binding.target_review_cycle_id IS NOT DISTINCT FROM v_target_cycle_id
        AND binding.decision_attestation_sha256=v_row->>'decisionAttestationSha256') THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_REPLAY_DRIFT'; END IF;
  END LOOP;
  IF (SELECT count(*) FROM public.hr_performance_legacy_session_binding
    WHERE (tenant_id,park_id,migration_batch_id)=(p_tenant_id,p_park_id,p_batch_id))<>7 THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_SESSION_CONSERVATION_FAILED'; END IF;

  FOR v_assignment IN SELECT * FROM public.hr_performance_legacy_source_person_assignment
    WHERE (tenant_id,park_id,migration_batch_id)=(p_tenant_id,p_park_id,p_batch_id)
    ORDER BY id
  LOOP
    FOREACH v_role IN ARRAY ARRAY['subject'::varchar,'assessor'::varchar] LOOP
      v_source_code:=CASE v_role WHEN 'subject' THEN v_assignment.source_person_code
        ELSE v_assignment.source_assessor_code END;
      v_identity:=public.hr_performance_yuzhou_person_identity_sha256(v_source_code);
      v_owner_map_id:=NULL; v_employee_id:=NULL;
      IF v_role='assessor' THEN
        IF v_identity IS NULL THEN v_person_status:='not_applicable'; v_person_reason:='ASSESSOR_CODE_EMPTY';
        ELSE v_person_status:='semantics_unverified'; v_person_reason:='ASSESSOR_SEMANTICS_UNVERIFIED'; END IF;
      ELSIF v_identity IS NULL THEN
        v_person_status:='not_applicable'; v_person_reason:='SUBJECT_CODE_EMPTY';
      ELSE
        SELECT count(*) INTO v_candidate_count
        FROM public.hr_performance_yuzhou_t0_person_candidate(p_tenant_id,p_park_id,v_identity);
        IF v_candidate_count=1 THEN
          SELECT owner_t0_record_map_id,target_employee_id INTO v_owner_map_id,v_employee_id
          FROM public.hr_performance_yuzhou_t0_person_candidate(p_tenant_id,p_park_id,v_identity);
          v_person_status:='resolved'; v_person_reason:='EXACT_T0_PERSON_MAP';
        ELSIF v_candidate_count=0 THEN
          v_person_status:='unmatched'; v_person_reason:='T0_PERSON_MAP_NOT_FOUND';
        ELSE v_person_status:='ambiguous'; v_person_reason:='T0_PERSON_MAP_AMBIGUOUS'; END IF;
      END IF;
      SELECT binding.* INTO v_binding FROM public.hr_performance_legacy_session source_session
      JOIN public.hr_performance_legacy_session_binding binding ON binding.legacy_session_id=source_session.id
      WHERE (source_session.tenant_id,source_session.park_id,source_session.migration_batch_id,
        source_session.source_session_id)=
        (p_tenant_id,p_park_id,p_batch_id,v_assignment.source_session_id);
      IF NOT FOUND THEN v_binding:=NULL; END IF;
      v_cycle_employee_id:=NULL;
      IF v_role='assessor' THEN v_cycle_status:='not_applicable'; v_cycle_reason:='ASSESSOR_CYCLE_NOT_APPLICABLE';
      ELSIF v_person_status<>'resolved' THEN v_cycle_status:='not_applicable'; v_cycle_reason:='PERSON_UNRESOLVED';
      ELSIF v_assignment.source_session_id IS NULL THEN v_cycle_status:='not_applicable'; v_cycle_reason:='SESSION_NOT_APPLICABLE';
      ELSIF v_binding.id IS NULL OR v_binding.resolution_status<>'resolved' THEN
        v_cycle_status:='unmatched'; v_cycle_reason:='SESSION_BINDING_UNRESOLVED';
      ELSE
        SELECT count(*),(array_agg(id ORDER BY id))[1] INTO v_cycle_count,v_cycle_employee_id
        FROM public.hr_performance_cycle_employee WHERE (tenant_id,park_id,cycle_id,employee_id)=
          (p_tenant_id,p_park_id,v_binding.target_review_cycle_id,v_employee_id);
        IF v_cycle_count=1 THEN v_cycle_status:='resolved'; v_cycle_reason:='EXACT_CYCLE_EMPLOYEE';
        ELSIF v_cycle_count=0 THEN v_cycle_employee_id:=NULL; v_cycle_status:='unmatched';
          v_cycle_reason:='CYCLE_EMPLOYEE_NOT_FOUND';
        ELSE v_cycle_employee_id:=NULL; v_cycle_status:='ambiguous';
          v_cycle_reason:='CYCLE_EMPLOYEE_AMBIGUOUS'; END IF;
      END IF;
      v_resolution_id:=uuid_generate_v5(v_namespace,
        'fact:'||p_batch_id::text||':source_person_assignment:'||v_assignment.id::text||':'||v_role);
      INSERT INTO public.hr_performance_legacy_identity_resolution(
        id,tenant_id,park_id,migration_batch_id,fact_kind,person_role,
        legacy_source_person_assignment_id,source_person_identity_sha256,
        person_resolution_status,person_resolution_reason_code,owner_t0_record_map_id,
        target_employee_id,session_binding_id,cycle_resolution_status,
        cycle_resolution_reason_code,target_cycle_employee_id,evidence_sha256
      ) VALUES(v_resolution_id,p_tenant_id,p_park_id,p_batch_id,'source_person_assignment',v_role,
        v_assignment.id,v_identity,v_person_status,v_person_reason,v_owner_map_id,v_employee_id,
        v_binding.id,v_cycle_status,v_cycle_reason,v_cycle_employee_id,
        public.hr_performance_yuzhou_identity_resolution_evidence_sha256(
          'source_person_assignment',v_assignment.id,v_role,v_identity,v_person_status,v_person_reason,
          v_owner_map_id,v_employee_id,v_binding.id,v_cycle_status,v_cycle_reason,v_cycle_employee_id))
      ON CONFLICT(id) DO NOTHING;
      IF NOT EXISTS(SELECT 1 FROM public.hr_performance_legacy_identity_resolution r
        WHERE r.id=v_resolution_id AND r.person_resolution_status=v_person_status
          AND r.person_resolution_reason_code=v_person_reason
          AND r.owner_t0_record_map_id IS NOT DISTINCT FROM v_owner_map_id
          AND r.target_employee_id IS NOT DISTINCT FROM v_employee_id
          AND r.session_binding_id IS NOT DISTINCT FROM v_binding.id
          AND r.cycle_resolution_status=v_cycle_status
          AND r.cycle_resolution_reason_code=v_cycle_reason
          AND r.target_cycle_employee_id IS NOT DISTINCT FROM v_cycle_employee_id) THEN
        RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_REPLAY_DRIFT'; END IF;
    END LOOP;
  END LOOP;
  IF (SELECT count(*) FROM public.hr_performance_legacy_identity_resolution
    WHERE (tenant_id,park_id,migration_batch_id)=(p_tenant_id,p_park_id,p_batch_id))<>234 THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_IDENTITY_CONSERVATION_FAILED'; END IF;
  SET CONSTRAINTS ALL IMMEDIATE;
END$_$;



--
-- Name: hr_yuzhou_materialize_performance_relations_production_v1(character varying, character varying, uuid, jsonb); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.hr_yuzhou_materialize_performance_relations_production_v1(IN p_tenant_id character varying, IN p_park_id character varying, IN p_batch_id uuid, IN p_payload jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_row jsonb; v_map_id uuid; v_fact_id uuid; v_session_id uuid; v_dimension_id uuid;
  v_expected bigint; v_actual bigint;
BEGIN
  IF current_setting('transaction_isolation')<>'serializable'
    OR NOT public.hr_yuzhou_performance_relations_production_context_allowed(p_batch_id,'apply') THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_CONTEXT_INVALID'; END IF;
  IF NOT public.hr_performance_yuzhou_jsonb_exact_keys(p_payload,ARRAY['asssession','asssour','asssourperson'])
    OR jsonb_typeof(p_payload->'asssession')<>'array'
    OR jsonb_typeof(p_payload->'asssour')<>'array'
    OR jsonb_typeof(p_payload->'asssourperson')<>'array'
    OR jsonb_array_length(p_payload->'asssession')<>7
    OR jsonb_array_length(p_payload->'asssour')<>0
    OR jsonb_array_length(p_payload->'asssourperson')<>117 THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_PAYLOAD_CONSERVATION_FAILED'; END IF;
  LOCK TABLE public.legacy_record_map,public.hr_performance_legacy_session,
    public.hr_performance_legacy_score_source,
    public.hr_performance_legacy_source_person_assignment IN SHARE ROW EXCLUSIVE MODE;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_payload->'asssession') LOOP
    IF NOT public.hr_performance_yuzhou_jsonb_exact_keys(v_row,ARRAY[
      'sourceIdentitySha256','sourceRowSha256','id','asssession','description',
      'assessmenttype','year','month','quarter','myorder']) THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_SESSION_INVALID'; END IF;
    SELECT map_id,fact_id INTO v_map_id,v_fact_id
    FROM public.hr_performance_yuzhou_prepare_relation_record_map(
      p_batch_id,'dbo.asssession',v_row->>'sourceIdentitySha256',v_row->>'sourceRowSha256',
      'hr_performance_legacy_session');
    INSERT INTO public.hr_performance_legacy_session(
      id,tenant_id,park_id,migration_batch_id,legacy_record_map_id,source_identity_sha256,
      source_row_sha256,source_session_id,source_session_name,source_description,
      source_assessment_type,source_year,source_month,source_quarter,source_my_order
    ) VALUES(
      v_fact_id,p_tenant_id,p_park_id,p_batch_id,v_map_id,v_row->>'sourceIdentitySha256',
      v_row->>'sourceRowSha256',(v_row->>'id')::integer,v_row->>'asssession',v_row->>'description',
      v_row->>'assessmenttype',(v_row->>'year')::integer,(v_row->>'month')::integer,
      (v_row->>'quarter')::integer,(v_row->>'myorder')::integer
    ) ON CONFLICT(migration_batch_id,tenant_id,park_id,source_session_id) DO NOTHING;
    IF NOT EXISTS(SELECT 1 FROM public.hr_performance_legacy_session fact
      WHERE fact.id=v_fact_id AND fact.legacy_record_map_id=v_map_id
        AND fact.source_row_sha256=v_row->>'sourceRowSha256') THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_REPLAY_DRIFT'; END IF;
  END LOOP;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_payload->'asssour') LOOP
    IF NOT public.hr_performance_yuzhou_jsonb_exact_keys(v_row,ARRAY[
      'sourceIdentitySha256','sourceRowSha256','id','asssessionid','person','assitemid',
      'lb','itemvalue','assgrade','appraisal']) THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_SCORE_INVALID'; END IF;
    SELECT id INTO v_session_id FROM public.hr_performance_legacy_session WHERE
      (tenant_id,park_id,migration_batch_id,source_session_id)=
      (p_tenant_id,p_park_id,p_batch_id,(v_row->>'asssessionid')::integer);
    SELECT id INTO v_dimension_id FROM public.hr_performance_legacy_dimension_profile WHERE
      (tenant_id,park_id,migration_batch_id,source_item_id)=
      (p_tenant_id,p_park_id,p_batch_id,(v_row->>'assitemid')::integer);
    SELECT map_id,fact_id INTO v_map_id,v_fact_id
    FROM public.hr_performance_yuzhou_prepare_relation_record_map(
      p_batch_id,'dbo.asssour',v_row->>'sourceIdentitySha256',v_row->>'sourceRowSha256',
      'hr_performance_legacy_score_source');
    INSERT INTO public.hr_performance_legacy_score_source(
      id,tenant_id,park_id,migration_batch_id,legacy_record_map_id,source_identity_sha256,
      source_row_sha256,source_score_id,source_session_id,source_person_code,source_item_id,
      source_relation_type,source_item_value,source_ass_grade,source_appraisal,
      legacy_session_id,legacy_dimension_profile_id
    ) VALUES(
      v_fact_id,p_tenant_id,p_park_id,p_batch_id,v_map_id,v_row->>'sourceIdentitySha256',
      v_row->>'sourceRowSha256',(v_row->>'id')::integer,(v_row->>'asssessionid')::integer,
      v_row->>'person',(v_row->>'assitemid')::integer,(v_row->>'lb')::integer,
      (v_row->>'itemvalue')::numeric(18,2),v_row->>'assgrade',v_row->>'appraisal',
      v_session_id,v_dimension_id
    ) ON CONFLICT(migration_batch_id,tenant_id,park_id,source_score_id) DO NOTHING;
    IF NOT EXISTS(SELECT 1 FROM public.hr_performance_legacy_score_source fact
      WHERE fact.id=v_fact_id AND fact.legacy_record_map_id=v_map_id
        AND fact.source_row_sha256=v_row->>'sourceRowSha256'
        AND fact.legacy_session_id IS NOT DISTINCT FROM v_session_id
        AND fact.legacy_dimension_profile_id IS NOT DISTINCT FROM v_dimension_id) THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_REPLAY_DRIFT'; END IF;
  END LOOP;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_payload->'asssourperson') LOOP
    IF NOT public.hr_performance_yuzhou_jsonb_exact_keys(v_row,ARRAY[
      'sourceIdentitySha256','sourceRowSha256','id','asssessionid','person','assperson','lb']) THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_ASSIGNMENT_INVALID'; END IF;
    SELECT id INTO v_session_id FROM public.hr_performance_legacy_session WHERE
      (tenant_id,park_id,migration_batch_id,source_session_id)=
      (p_tenant_id,p_park_id,p_batch_id,(v_row->>'asssessionid')::integer);
    SELECT map_id,fact_id INTO v_map_id,v_fact_id
    FROM public.hr_performance_yuzhou_prepare_relation_record_map(
      p_batch_id,'dbo.asssourperson',v_row->>'sourceIdentitySha256',v_row->>'sourceRowSha256',
      'hr_performance_legacy_source_person_assignment');
    INSERT INTO public.hr_performance_legacy_source_person_assignment(
      id,tenant_id,park_id,migration_batch_id,legacy_record_map_id,source_identity_sha256,
      source_row_sha256,source_assignment_id,source_session_id,source_person_code,
      source_assessor_code,source_relation_type,legacy_session_id
    ) VALUES(
      v_fact_id,p_tenant_id,p_park_id,p_batch_id,v_map_id,v_row->>'sourceIdentitySha256',
      v_row->>'sourceRowSha256',(v_row->>'id')::integer,(v_row->>'asssessionid')::integer,
      v_row->>'person',v_row->>'assperson',(v_row->>'lb')::integer,v_session_id
    ) ON CONFLICT(migration_batch_id,tenant_id,park_id,source_assignment_id) DO NOTHING;
    IF NOT EXISTS(SELECT 1 FROM public.hr_performance_legacy_source_person_assignment fact
      WHERE fact.id=v_fact_id AND fact.legacy_record_map_id=v_map_id
        AND fact.source_row_sha256=v_row->>'sourceRowSha256'
        AND fact.legacy_session_id IS NOT DISTINCT FROM v_session_id) THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_REPLAY_DRIFT'; END IF;
  END LOOP;
  v_expected:=124;
  SELECT count(*) INTO v_actual FROM public.legacy_record_map WHERE batch_id=p_batch_id AND is_active
    AND target_table IN('hr_performance_legacy_session','hr_performance_legacy_score_source',
      'hr_performance_legacy_source_person_assignment');
  IF v_actual<>v_expected THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_MAP_CONSERVATION_FAILED'; END IF;
  SET CONSTRAINTS ALL IMMEDIATE;
END$$;



--
-- Name: hr_yuzhou_performance_fact_identity_context_allowed_v1(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_performance_fact_identity_context_allowed_v1(p_batch_id uuid, p_mode character varying) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT CASE p_mode
    WHEN 'apply' THEN EXISTS(
      SELECT 1
      FROM public.hr_yuzhou_performance_relations_production_receipt parent
      JOIN public.migration_batch batch ON batch.id=parent.migration_batch_id
      WHERE batch.id=p_batch_id AND parent.status='succeeded'
        AND current_setting('yuzhou.performance_fact_identity_operation_id',true)=parent.operation_id
        AND current_setting('yuzhou.performance_fact_identity_mode',true)='apply'
        AND public.hr_yuzhou_performance_relations_production_context_allowed(p_batch_id,'apply')
    )
    WHEN 'rollback' THEN EXISTS(
      SELECT 1
      FROM public.hr_yuzhou_performance_fact_identity_production_receipt receipt
      JOIN public.hr_yuzhou_production_import_rollback_operation rollback
        ON rollback.rollback_operation_id=
          current_setting('yuzhou.performance_fact_identity_rollback_operation_id',true)
       AND rollback.import_operation_id=receipt.operation_id AND rollback.status='running'
      JOIN public.hr_yuzhou_production_import_authorization_use auth
        ON auth.operation_id=rollback.rollback_operation_id
       AND auth.import_operation_id=receipt.operation_id
       AND auth.intent='production_import_rollback'
      WHERE receipt.migration_batch_id=p_batch_id AND receipt.status='succeeded'
        AND current_setting('yuzhou.performance_fact_identity_operation_id',true)=receipt.operation_id
        AND current_setting('yuzhou.performance_fact_identity_mode',true)='rollback'
    )
    ELSE false
  END
$$;



--
-- Name: hr_yuzhou_performance_fact_identity_production_capability_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_performance_fact_identity_production_capability_v1() RETURNS TABLE(capability_id text, migration_308_sha256 character, production_context_supported boolean, fact_kinds text, rollback_order text)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT 'jinhu-yuzhou-performance-fact-identity-production-v1'::text,
    'ad77e0cf12cf73f98a5984835a9943a9e15c96cde37fe6bd95133845c711befa'::char(64),
    true,'dimension_result>master_result'::text,
    'fact_identity>performance_relations>performance_facts'::text
$$;



--
-- Name: hr_yuzhou_performance_fact_identity_set_v1(character varying, character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_performance_fact_identity_set_v1(p_tenant_id character varying, p_park_id character varying, p_batch_id uuid) RETURNS TABLE(dimension_rows bigint, master_rows bigint, fact_rows bigint, fact_set_sha256 character)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  WITH facts AS (
    SELECT 'dimension_result'::text fact_kind,fact.source_identity_sha256,
      fact.source_row_sha256,
      public.hr_performance_yuzhou_person_identity_sha256(fact.source_person_code)
        source_person_identity_sha256,
      fact.source_session_id
    FROM public.hr_performance_legacy_dimension_result fact
    WHERE (fact.tenant_id,fact.park_id,fact.migration_batch_id)=(p_tenant_id,p_park_id,p_batch_id)
    UNION ALL
    SELECT 'master_result',fact.source_identity_sha256,fact.source_row_sha256,
      public.hr_performance_yuzhou_person_identity_sha256(fact.source_person_code),
      fact.source_session_id
    FROM public.hr_performance_legacy_master_result fact
    WHERE (fact.tenant_id,fact.park_id,fact.migration_batch_id)=(p_tenant_id,p_park_id,p_batch_id)
  ), counts AS (
    SELECT count(*) FILTER(WHERE fact_kind='dimension_result') dimension_rows,
      count(*) FILTER(WHERE fact_kind='master_result') master_rows,count(*) fact_rows
    FROM facts
  ), canonical AS (
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'factKind',fact_kind,'sourceIdentitySha256',source_identity_sha256,
      'sourceRowSha256',source_row_sha256,
      'sourcePersonIdentitySha256',source_person_identity_sha256,
      'sourceSessionId',source_session_id
    ) ORDER BY fact_kind,source_identity_sha256),'[]'::jsonb) body FROM facts
  )
  SELECT counts.dimension_rows,counts.master_rows,counts.fact_rows,
    encode(digest(convert_to(canonical.body::text,'UTF8'),'sha256'),'hex')::char(64)
  FROM counts CROSS JOIN canonical
$$;



--
-- Name: hr_yuzhou_performance_fact_identity_state_v1(character varying, character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_performance_fact_identity_state_v1(p_tenant_id character varying, p_park_id character varying, p_batch_id uuid) RETURNS character
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT encode(digest(convert_to(COALESCE(jsonb_agg(jsonb_build_array(
    resolution.fact_kind,resolution.id,resolution.source_person_identity_sha256,
    resolution.person_resolution_status,resolution.person_resolution_reason_code,
    resolution.owner_t0_record_map_id,resolution.target_employee_id,
    resolution.session_binding_id,resolution.cycle_resolution_status,
    resolution.cycle_resolution_reason_code,resolution.target_cycle_employee_id,
    resolution.evidence_sha256
  ) ORDER BY resolution.fact_kind,resolution.id),'[]'::jsonb)::text,'UTF8'),'sha256'),'hex')::char(64)
  FROM public.hr_performance_legacy_identity_resolution resolution
  WHERE (resolution.tenant_id,resolution.park_id,resolution.migration_batch_id)=
      (p_tenant_id,p_park_id,p_batch_id)
    AND resolution.fact_kind IN('dimension_result','master_result')
$$;



--
-- Name: hr_yuzhou_performance_fact_loader_dependency_valid_v1(character varying, uuid, character varying, character varying, character, character, character, character); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_performance_fact_loader_dependency_valid_v1(p_operation_id character varying, p_batch_id uuid, p_tenant_id character varying, p_park_id character varying, p_target_scope_sha256 character, p_t0_phase_receipt_sha256 character, p_fact_loader_receipt_sha256 character, p_identity_fact_set_sha256 character) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT EXISTS(
    SELECT 1
    FROM public.hr_yuzhou_performance_facts_production_receipt receipt
    CROSS JOIN LATERAL public.hr_yuzhou_performance_fact_identity_set_v1(
      receipt.tenant_id,receipt.park_id,receipt.migration_batch_id) identity_set
    CROSS JOIN LATERAL public.hr_yuzhou_performance_full_fact_set_v1(
      receipt.tenant_id,receipt.park_id,receipt.migration_batch_id) full_set
    WHERE receipt.operation_id=p_operation_id AND receipt.migration_batch_id=p_batch_id
      AND (receipt.tenant_id,receipt.park_id)=(p_tenant_id,p_park_id)
      AND receipt.target_scope_sha256=p_target_scope_sha256
      AND receipt.t0_phase_receipt_sha256=p_t0_phase_receipt_sha256
      AND receipt.receipt_sha256=p_fact_loader_receipt_sha256
      AND receipt.identity_fact_set_sha256=p_identity_fact_set_sha256
      AND receipt.status='succeeded'
      AND identity_set.dimension_rows=receipt.dimension_result_rows
      AND identity_set.master_rows=receipt.master_result_rows
      AND identity_set.fact_set_sha256=receipt.identity_fact_set_sha256
      AND ROW(full_set.template_rows,full_set.level_rule_rows,full_set.dimension_rows,
        full_set.guide_rows,full_set.dimension_result_rows,full_set.master_result_rows,
        full_set.active_fact_maps,full_set.full_fact_set_sha256)
        IS NOT DISTINCT FROM ROW(receipt.template_rows,receipt.level_rule_rows,
          receipt.dimension_rows,receipt.guide_rows,receipt.dimension_result_rows,
          receipt.master_result_rows,receipt.active_fact_maps,receipt.full_fact_set_sha256)
  )
$$;



--
-- Name: hr_yuzhou_performance_facts_production_capability_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_performance_facts_production_capability_v1() RETURNS TABLE(capability_id text, migration_300_sha256 character, migration_301_sha256 character, migration_302_sha256 character, migration_303_sha256 character, fact_identity_dependency_supported boolean, reverse_order text)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT 'jinhu-yuzhou-performance-fact-loader-production-v1'::text,
    'ab3410b2121e0772c4b0cc6f273c893340b7925dcecf26414ea336f15dd0656a'::char(64),
    '4a4de62295d7e4ac7e752c435eba49483da7d79384c34aa992b9bc5f1f618e7e'::char(64),
    '7b45377d252a9593d779af779bcb9d6f91ceb326f6b5da1273da50b89f52e43a'::char(64),
    '853d7632ebd2c2c3a9211e0088a3ccda7979a788539db2123aaf43c59c070648'::char(64),
    true,
    'master_result>dimension_result>dimension_level_guide>dimension_profile>level_rule>template_profile'::text
$$;



--
-- Name: hr_yuzhou_performance_facts_production_context_allowed_v1(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_performance_facts_production_context_allowed_v1(p_batch_id uuid, p_mode character varying) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT CASE p_mode
    WHEN 'apply' THEN EXISTS(
      SELECT 1
      FROM public.migration_batch batch
      JOIN public.hr_yuzhou_production_import_operation operation
        ON operation.operation_id=batch.production_import_operation_id
      JOIN public.hr_yuzhou_production_import_phase phase
        ON (phase.operation_id,phase.phase)=(operation.operation_id,'T0')
      JOIN public.hr_yuzhou_production_import_authorization_use auth
        ON auth.operation_id=operation.operation_id
       AND auth.import_operation_id=operation.operation_id
       AND auth.intent='production_import'
      WHERE batch.id=p_batch_id AND batch.execution_context='production_import'
        AND batch.production_import_phase='T0' AND batch.target_database=current_database()
        AND batch.status='succeeded' AND operation.execution_contract_version=2
        AND operation.status='running' AND operation.current_phase='T0'
        AND phase.status='succeeded'
        AND current_setting('yuzhou.performance_facts_operation_id',true)=operation.operation_id
        AND current_setting('yuzhou.performance_facts_mode',true)='apply'
    )
    WHEN 'rollback' THEN EXISTS(
      SELECT 1
      FROM public.hr_yuzhou_performance_facts_production_receipt receipt
      JOIN public.migration_batch batch ON batch.id=receipt.migration_batch_id
      JOIN public.hr_yuzhou_production_import_rollback_operation rollback_operation
        ON rollback_operation.rollback_operation_id=
          current_setting('yuzhou.performance_facts_rollback_operation_id',true)
       AND rollback_operation.import_operation_id=receipt.operation_id
       AND rollback_operation.status='running'
      JOIN public.hr_yuzhou_production_import_authorization_use auth
        ON auth.operation_id=rollback_operation.rollback_operation_id
       AND auth.import_operation_id=receipt.operation_id
       AND auth.intent='production_import_rollback'
      WHERE receipt.migration_batch_id=p_batch_id AND receipt.status='succeeded'
        AND batch.execution_context='production_import'
        AND batch.production_import_phase='T0' AND batch.target_database=current_database()
        AND current_setting('yuzhou.performance_facts_operation_id',true)=receipt.operation_id
        AND current_setting('yuzhou.performance_facts_mode',true)='rollback'
        AND NOT EXISTS(SELECT 1
          FROM public.hr_yuzhou_performance_fact_identity_production_receipt identity_receipt
          WHERE identity_receipt.operation_id=receipt.operation_id
            AND (identity_receipt.fact_loader_receipt_sha256<>receipt.receipt_sha256
              OR identity_receipt.status<>'rolled_back'))
        AND NOT EXISTS(SELECT 1
          FROM public.hr_yuzhou_performance_relations_production_receipt relation_receipt
          WHERE relation_receipt.operation_id=receipt.operation_id
            AND relation_receipt.status<>'rolled_back')
    )
    ELSE false
  END
$$;



--
-- Name: hr_yuzhou_performance_full_fact_set_v1(character varying, character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_performance_full_fact_set_v1(p_tenant_id character varying, p_park_id character varying, p_batch_id uuid) RETURNS TABLE(template_rows bigint, level_rule_rows bigint, dimension_rows bigint, guide_rows bigint, dimension_result_rows bigint, master_result_rows bigint, active_fact_maps bigint, full_fact_set_sha256 character)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  WITH facts AS (
    SELECT 'template_profile'::text fact_kind,source_identity_sha256,source_row_sha256
      FROM public.hr_performance_legacy_template_profile
      WHERE (tenant_id,park_id,migration_batch_id)=(p_tenant_id,p_park_id,p_batch_id)
    UNION ALL
    SELECT 'level_rule',source_identity_sha256,source_row_sha256
      FROM public.hr_performance_legacy_level_rule
      WHERE (tenant_id,park_id,migration_batch_id)=(p_tenant_id,p_park_id,p_batch_id)
    UNION ALL
    SELECT 'dimension_profile',source_identity_sha256,source_row_sha256
      FROM public.hr_performance_legacy_dimension_profile
      WHERE (tenant_id,park_id,migration_batch_id)=(p_tenant_id,p_park_id,p_batch_id)
    UNION ALL
    SELECT 'dimension_level_guide',source_identity_sha256,source_row_sha256
      FROM public.hr_performance_legacy_dimension_level_guide
      WHERE (tenant_id,park_id,migration_batch_id)=(p_tenant_id,p_park_id,p_batch_id)
    UNION ALL
    SELECT 'dimension_result',source_identity_sha256,source_row_sha256
      FROM public.hr_performance_legacy_dimension_result
      WHERE (tenant_id,park_id,migration_batch_id)=(p_tenant_id,p_park_id,p_batch_id)
    UNION ALL
    SELECT 'master_result',source_identity_sha256,source_row_sha256
      FROM public.hr_performance_legacy_master_result
      WHERE (tenant_id,park_id,migration_batch_id)=(p_tenant_id,p_park_id,p_batch_id)
  ), counts AS (
    SELECT count(*) FILTER(WHERE fact_kind='template_profile') template_rows,
      count(*) FILTER(WHERE fact_kind='level_rule') level_rule_rows,
      count(*) FILTER(WHERE fact_kind='dimension_profile') dimension_rows,
      count(*) FILTER(WHERE fact_kind='dimension_level_guide') guide_rows,
      count(*) FILTER(WHERE fact_kind='dimension_result') dimension_result_rows,
      count(*) FILTER(WHERE fact_kind='master_result') master_result_rows
    FROM facts
  ), maps AS (
    SELECT count(*) active_fact_maps FROM public.legacy_record_map
    WHERE batch_id=p_batch_id AND is_active AND target_table IN(
      'hr_performance_legacy_template_profile','hr_performance_legacy_level_rule',
      'hr_performance_legacy_dimension_profile','hr_performance_legacy_dimension_level_guide',
      'hr_performance_legacy_dimension_result','hr_performance_legacy_master_result')
  ), canonical AS (
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'factKind',fact_kind,'sourceIdentitySha256',source_identity_sha256,
      'sourceRowSha256',source_row_sha256
    ) ORDER BY fact_kind,source_identity_sha256),'[]'::jsonb) body FROM facts
  )
  SELECT counts.*,maps.active_fact_maps,
    encode(digest(convert_to(canonical.body::text,'UTF8'),'sha256'),'hex')::char(64)
  FROM counts CROSS JOIN maps CROSS JOIN canonical
$$;



--
-- Name: hr_yuzhou_performance_owner_map_projection_v1(character varying, character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_performance_owner_map_projection_v1(p_tenant_id character varying, p_park_id character varying, p_batch_id uuid) RETURNS TABLE(owner_family text, source_table character varying, target_table character varying, target_id uuid, legacy_record_map_id uuid, source_identity_sha256 character, source_row_sha256 character, mapping_status character varying, is_active boolean, exact_binding boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  WITH owners AS (
    SELECT 'fact'::text owner_family,'dbo.assessmentcode'::varchar source_table,
      'hr_performance_legacy_template_profile'::varchar target_table,
      fact.id target_id,fact.legacy_record_map_id,fact.source_identity_sha256,fact.source_row_sha256
    FROM public.hr_performance_legacy_template_profile fact
    WHERE (fact.tenant_id,fact.park_id,fact.migration_batch_id)=(p_tenant_id,p_park_id,p_batch_id)
    UNION ALL
    SELECT 'fact','dbo.assgradecode','hr_performance_legacy_level_rule',
      fact.id,fact.legacy_record_map_id,fact.source_identity_sha256,fact.source_row_sha256
    FROM public.hr_performance_legacy_level_rule fact
    WHERE (fact.tenant_id,fact.park_id,fact.migration_batch_id)=(p_tenant_id,p_park_id,p_batch_id)
    UNION ALL
    SELECT 'fact','dbo.assitem','hr_performance_legacy_dimension_profile',
      fact.id,fact.legacy_record_map_id,fact.source_identity_sha256,fact.source_row_sha256
    FROM public.hr_performance_legacy_dimension_profile fact
    WHERE (fact.tenant_id,fact.park_id,fact.migration_batch_id)=(p_tenant_id,p_park_id,p_batch_id)
    UNION ALL
    SELECT 'fact','dbo.assitemgradedes','hr_performance_legacy_dimension_level_guide',
      fact.id,fact.legacy_record_map_id,fact.source_identity_sha256,fact.source_row_sha256
    FROM public.hr_performance_legacy_dimension_level_guide fact
    WHERE (fact.tenant_id,fact.park_id,fact.migration_batch_id)=(p_tenant_id,p_park_id,p_batch_id)
    UNION ALL
    SELECT 'fact','dbo.assessmentdetail','hr_performance_legacy_dimension_result',
      fact.id,fact.legacy_record_map_id,fact.source_identity_sha256,fact.source_row_sha256
    FROM public.hr_performance_legacy_dimension_result fact
    WHERE (fact.tenant_id,fact.park_id,fact.migration_batch_id)=(p_tenant_id,p_park_id,p_batch_id)
    UNION ALL
    SELECT 'fact','dbo.assessmentmaster','hr_performance_legacy_master_result',
      fact.id,fact.legacy_record_map_id,fact.source_identity_sha256,fact.source_row_sha256
    FROM public.hr_performance_legacy_master_result fact
    WHERE (fact.tenant_id,fact.park_id,fact.migration_batch_id)=(p_tenant_id,p_park_id,p_batch_id)
    UNION ALL
    SELECT 'relation','dbo.asssession','hr_performance_legacy_session',
      fact.id,fact.legacy_record_map_id,fact.source_identity_sha256,fact.source_row_sha256
    FROM public.hr_performance_legacy_session fact
    WHERE (fact.tenant_id,fact.park_id,fact.migration_batch_id)=(p_tenant_id,p_park_id,p_batch_id)
    UNION ALL
    SELECT 'relation','dbo.asssour','hr_performance_legacy_score_source',
      fact.id,fact.legacy_record_map_id,fact.source_identity_sha256,fact.source_row_sha256
    FROM public.hr_performance_legacy_score_source fact
    WHERE (fact.tenant_id,fact.park_id,fact.migration_batch_id)=(p_tenant_id,p_park_id,p_batch_id)
    UNION ALL
    SELECT 'relation','dbo.asssourperson','hr_performance_legacy_source_person_assignment',
      fact.id,fact.legacy_record_map_id,fact.source_identity_sha256,fact.source_row_sha256
    FROM public.hr_performance_legacy_source_person_assignment fact
    WHERE (fact.tenant_id,fact.park_id,fact.migration_batch_id)=(p_tenant_id,p_park_id,p_batch_id)
  )
  SELECT owner.owner_family,owner.source_table,owner.target_table,owner.target_id,
    owner.legacy_record_map_id,owner.source_identity_sha256,owner.source_row_sha256,
    map.mapping_status,map.is_active,
    (map.id IS NOT NULL AND map.batch_id=p_batch_id AND map.source_system='yuzhou-v10'
      AND map.source_table=owner.source_table
      AND map.source_pk_canonical='sha256:'||owner.source_identity_sha256
      AND map.source_identity_sha256=owner.source_identity_sha256
      AND map.source_row_sha256=owner.source_row_sha256
      AND map.target_table=owner.target_table AND map.target_id=owner.target_id
      AND map.mapping_status IN('loaded','verified') AND map.is_active) exact_binding
  FROM owners owner
  LEFT JOIN public.legacy_record_map map ON map.id=owner.legacy_record_map_id
$$;



--
-- Name: hr_yuzhou_performance_owner_map_state_v1(character varying, character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_performance_owner_map_state_v1(p_tenant_id character varying, p_park_id character varying, p_batch_id uuid) RETURNS TABLE(fact_owner_maps bigint, relation_owner_maps bigint, owner_maps bigint, distinct_owner_maps bigint, active_target_maps bigint, loaded_owner_maps bigint, verified_owner_maps bigint, invalid_owner_maps bigint, owner_map_state_sha256 character)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  WITH owners AS MATERIALIZED (
    SELECT * FROM public.hr_yuzhou_performance_owner_map_projection_v1(
      p_tenant_id,p_park_id,p_batch_id)
  ), aggregate_state AS (
    SELECT count(*) FILTER(WHERE owner_family='fact') fact_owner_maps,
      count(*) FILTER(WHERE owner_family='relation') relation_owner_maps,
      count(*) owner_maps,count(DISTINCT legacy_record_map_id) distinct_owner_maps,
      count(*) FILTER(WHERE exact_binding AND mapping_status='loaded') loaded_owner_maps,
      count(*) FILTER(WHERE exact_binding AND mapping_status='verified') verified_owner_maps,
      count(*) FILTER(WHERE NOT exact_binding OR mapping_status NOT IN('loaded','verified'))
        invalid_owner_maps,
      COALESCE(jsonb_agg(jsonb_build_array(owner_family,source_table,target_table,target_id,
        legacy_record_map_id,source_identity_sha256,source_row_sha256,mapping_status,
        is_active,exact_binding) ORDER BY owner_family,source_table,source_identity_sha256),
        '[]'::jsonb) canonical
    FROM owners
  ), active_maps AS (
    SELECT count(*) active_target_maps FROM public.legacy_record_map map
    WHERE map.batch_id=p_batch_id AND map.is_active AND map.target_table IN(
      'hr_performance_legacy_template_profile','hr_performance_legacy_level_rule',
      'hr_performance_legacy_dimension_profile','hr_performance_legacy_dimension_level_guide',
      'hr_performance_legacy_dimension_result','hr_performance_legacy_master_result',
      'hr_performance_legacy_session','hr_performance_legacy_score_source',
      'hr_performance_legacy_source_person_assignment')
  )
  SELECT aggregate_state.fact_owner_maps,aggregate_state.relation_owner_maps,
    aggregate_state.owner_maps,aggregate_state.distinct_owner_maps,active_maps.active_target_maps,
    aggregate_state.loaded_owner_maps,aggregate_state.verified_owner_maps,
    aggregate_state.invalid_owner_maps,
    encode(digest(convert_to(aggregate_state.canonical::text,'UTF8'),'sha256'),'hex')::char(64)
  FROM aggregate_state CROSS JOIN active_maps
$$;



--
-- Name: hr_yuzhou_performance_person_assessment_dependency_valid(character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_performance_person_assessment_dependency_valid(p_parent_import_operation_id character varying, p_batch_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_capability record;
BEGIN
  SELECT * INTO STRICT v_capability
  FROM public.hr_yuzhou_performance_relations_production_capability_v1();
  IF v_capability.capability_id<>'jinhu-yuzhou-performance-relations-production-v1'
    OR v_capability.migration_305_sha256<>'d3784218fc8272bd28b93e44b19a02d5c8124466b6b3c218294920603909dfc0'
    OR v_capability.migration_306_sha256<>'cd49f294f4c9e4105b9f7fd4c678b7b2d29c5433d0348f6e6632d6e7c135a56d'
    OR v_capability.production_context_supported IS DISTINCT FROM true
    OR v_capability.reverse_order<>'identity_resolution>source_person_assignments' THEN
    RETURN false;
  END IF;
  IF NOT EXISTS(
      SELECT 1
      FROM public.sys_schema_migration_history primary_history
      JOIN public.schema_migrations standard_history
        ON standard_history.filename=primary_history.filename
       AND standard_history.checksum=primary_history.checksum
       AND standard_history.status=primary_history.status
      WHERE primary_history.filename='000308_hr_yuzhou_performance_relations_production.sql'
        AND primary_history.status='succeeded'
        AND primary_history.checksum='ad77e0cf12cf73f98a5984835a9943a9e15c96cde37fe6bd95133845c711befa'
    ) THEN
    RETURN false;
  END IF;
  RETURN EXISTS(
    SELECT 1
    FROM public.hr_yuzhou_performance_relations_production_receipt receipt
    JOIN public.migration_batch batch ON batch.id=receipt.migration_batch_id
    JOIN public.hr_yuzhou_production_import_phase phase
      ON (phase.operation_id,phase.phase)=(receipt.operation_id,'T0')
    WHERE receipt.operation_id=p_parent_import_operation_id
      AND receipt.migration_batch_id=p_batch_id
      AND receipt.status='succeeded'
      AND phase.status='succeeded'
      AND phase.after_canonical_sha256 IS NOT NULL
      AND receipt.t0_phase_receipt_sha256=phase.after_canonical_sha256
      AND batch.execution_context='production_import'
      AND batch.production_import_operation_id=p_parent_import_operation_id
      AND batch.production_import_phase='T0'
      AND batch.target_database=current_database()
      AND batch.status='succeeded'
  );
EXCEPTION WHEN undefined_function OR undefined_table OR no_data_found OR too_many_rows THEN
  RETURN false;
END$$;



--
-- Name: hr_yuzhou_performance_person_assessment_owner_state_sha256(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_performance_person_assessment_owner_state_sha256(p_batch_id uuid) RETURNS character
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT encode(digest(convert_to(jsonb_build_object(
    'contract','yuzhou-performance-person-assessment-owner-state-v1',
    'templateProfiles',COALESCE((SELECT jsonb_agg(jsonb_build_array(
      profile.id,profile.source_identity_sha256,profile.source_row_sha256,
      profile.source_assessment,profile.legacy_record_map_id
    ) ORDER BY profile.id) FROM public.hr_performance_legacy_template_profile profile
      WHERE profile.migration_batch_id=p_batch_id),'[]'::jsonb),
    'dimensionProfiles',COALESCE((SELECT jsonb_agg(jsonb_build_array(
      dimension.id,dimension.source_identity_sha256,dimension.source_row_sha256,
      dimension.legacy_template_profile_id,dimension.legacy_record_map_id
    ) ORDER BY dimension.id) FROM public.hr_performance_legacy_dimension_profile dimension
      WHERE dimension.migration_batch_id=p_batch_id),'[]'::jsonb),
    'dimensionResults',COALESCE((SELECT jsonb_agg(jsonb_build_array(
      result.id,result.source_identity_sha256,result.source_row_sha256,
      result.legacy_dimension_profile_id,result.legacy_record_map_id
    ) ORDER BY result.id) FROM public.hr_performance_legacy_dimension_result result
      WHERE result.migration_batch_id=p_batch_id),'[]'::jsonb),
    'masterResults',COALESCE((SELECT jsonb_agg(jsonb_build_array(
      master.id,master.source_identity_sha256,master.source_row_sha256,
      master.legacy_template_profile_id,master.legacy_record_map_id
    ) ORDER BY master.id) FROM public.hr_performance_legacy_master_result master
      WHERE master.migration_batch_id=p_batch_id),'[]'::jsonb)
  )::text,'UTF8'),'sha256'),'hex')::char(64)
$$;



--
-- Name: hr_yuzhou_performance_person_assessment_payload_sha256(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_performance_person_assessment_payload_sha256(p_payload jsonb) RETURNS character
    LANGUAGE sql IMMUTABLE STRICT SECURITY DEFINER PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT encode(digest(convert_to(
    '{"personAssessments":['
      ||COALESCE((SELECT string_agg(
        '{"sourceAssessmentId":'||COALESCE(value->>'sourceAssessmentId','null')
          ||',"sourcePersonIdentitySha256":'||to_json(value->>'sourcePersonIdentitySha256')::text||'}',
        ',' ORDER BY ordinal)
        FROM jsonb_array_elements(p_payload->'personAssessments') WITH ORDINALITY rows(value,ordinal)
      ),'')
      ||']}'||chr(10),
    'UTF8'),'sha256'),'hex')::char(64)
$$;



--
-- Name: hr_yuzhou_performance_person_assessment_production_capability(character varying, character, character, character, character); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_performance_person_assessment_production_capability(p_parent_import_operation_id character varying, p_t0_artifact_sha256 character, p_contract_artifact_sha256 character, p_migration_artifact_sha256 character, p_target_scope_sha256 character) RETURNS TABLE(execution_context character varying, phase character varying, migration_artifact_sha256 character, parent_import_operation_id character varying, t0_artifact_sha256 character, contract_artifact_sha256 character, apply_procedure character varying, rollback_procedure character varying)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_operation public.hr_yuzhou_production_import_operation%ROWTYPE;
  v_receipt public.hr_yuzhou_performance_relations_production_receipt%ROWTYPE;
BEGIN
  IF p_contract_artifact_sha256<>'f9eac8435900c05251c82c0c1be04bbe63992ca9f65a9879c21c838af898f62c'
    OR p_migration_artifact_sha256<>'0467f31888a5fb52c7c63ab1e754a68ab76822b2e177318bf249f71eb1f8887a' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_PERSON_ASSESSMENT_CAPABILITY_ARTIFACT_DRIFT'; END IF;
  SELECT * INTO v_operation FROM public.hr_yuzhou_production_import_operation
    WHERE operation_id=p_parent_import_operation_id;
  SELECT * INTO v_receipt FROM public.hr_yuzhou_performance_relations_production_receipt
    WHERE operation_id=p_parent_import_operation_id;
  IF v_operation.operation_id IS NULL OR v_receipt.operation_id IS NULL
    OR v_operation.execution_contract_version<>2
    OR v_operation.status NOT IN('running','succeeded')
    OR v_operation.target_scope_sha256<>p_target_scope_sha256
    OR v_receipt.status<>'succeeded'
    OR v_receipt.t0_phase_receipt_sha256<>p_t0_artifact_sha256
    OR NOT public.hr_yuzhou_performance_person_assessment_dependency_valid(
      p_parent_import_operation_id,v_receipt.migration_batch_id) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_PERSON_ASSESSMENT_CAPABILITY_DEPENDENCY_INVALID'; END IF;
  RETURN QUERY SELECT
    'production_import'::varchar,'PERFREL'::varchar,
    '0467f31888a5fb52c7c63ab1e754a68ab76822b2e177318bf249f71eb1f8887a'::char(64),
    p_parent_import_operation_id,p_t0_artifact_sha256,p_contract_artifact_sha256,
    'materialize_yuzhou_performance_ass_compute_weight_relation_production'::varchar,
    'rollback_yuzhou_performance_ass_compute_weight_relation_production'::varchar;
END$$;



--
-- Name: hr_yuzhou_performance_person_assessment_production_context_allo(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_performance_person_assessment_production_context_allo(p_batch_id uuid, p_mode character varying) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT CASE p_mode
    WHEN 'apply' THEN EXISTS(
      SELECT 1
      FROM public.hr_yuzhou_performance_person_assessment_operation operation
      WHERE operation.migration_batch_id=p_batch_id
        AND operation.status='running'
        AND operation.migration_308_sha256='ad77e0cf12cf73f98a5984835a9943a9e15c96cde37fe6bd95133845c711befa'
        AND current_setting('yuzhou.performance_person_assessment_operation_id',true)=operation.operation_id
        AND current_setting('yuzhou.performance_person_assessment_mode',true)='apply'
        AND public.hr_yuzhou_performance_person_assessment_dependency_valid(
          operation.parent_import_operation_id,operation.migration_batch_id)
        AND public.hr_yuzhou_performance_relations_production_context_allowed(p_batch_id,'apply')
    )
    WHEN 'rollback' THEN EXISTS(
      SELECT 1
      FROM public.hr_yuzhou_performance_person_assessment_operation operation
      JOIN public.hr_yuzhou_performance_person_assessment_rollback_operation rollback_operation
        ON rollback_operation.import_operation_id=operation.operation_id
      JOIN public.hr_yuzhou_performance_person_assessment_authorization_use auth_use
        ON auth_use.operation_id=rollback_operation.rollback_operation_id
       AND auth_use.import_operation_id=operation.operation_id
       AND auth_use.intent='production_performance_person_assessment_rollback'
      WHERE operation.migration_batch_id=p_batch_id
        AND operation.status='succeeded'
        AND operation.migration_308_sha256='ad77e0cf12cf73f98a5984835a9943a9e15c96cde37fe6bd95133845c711befa'
        AND rollback_operation.status='running'
        AND current_setting('yuzhou.performance_person_assessment_operation_id',true)=operation.operation_id
        AND current_setting('yuzhou.performance_person_assessment_rollback_operation_id',true)=rollback_operation.rollback_operation_id
        AND current_setting('yuzhou.performance_person_assessment_mode',true)='rollback'
        AND public.hr_yuzhou_performance_person_assessment_dependency_valid(
          operation.parent_import_operation_id,operation.migration_batch_id)
    )
    ELSE false
  END
$$;



--
-- Name: hr_yuzhou_performance_person_assessment_production_receipt(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_performance_person_assessment_production_receipt(p_operation_id character varying) RETURNS TABLE(operation_id character varying, status character varying, sealed_artifact_sha256 character, binding_sha256 character, target_scope_sha256 character, evidence_rows bigint, master_rows bigint, resolution_rows bigint, state_sha256 character)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_operation public.hr_yuzhou_performance_person_assessment_operation%ROWTYPE;
  v_evidence bigint; v_master bigint; v_resolution bigint; v_state char(64);
BEGIN
  SELECT operation_row.* INTO v_operation
    FROM public.hr_yuzhou_performance_person_assessment_operation operation_row
    WHERE operation_row.operation_id=p_operation_id;
  IF NOT FOUND OR v_operation.status NOT IN('succeeded','rolled_back') THEN RETURN; END IF;
  SELECT count(*) INTO v_evidence
    FROM public.hr_performance_legacy_person_assessment_evidence
    WHERE migration_batch_id=v_operation.migration_batch_id;
  SELECT count(*) INTO v_resolution
    FROM public.hr_performance_legacy_ass_compute_weight_resolution
    WHERE migration_batch_id=v_operation.migration_batch_id;
  IF public.hr_yuzhou_performance_person_assessment_owner_state_sha256(
      v_operation.migration_batch_id)<>v_operation.owner_state_sha256 THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_PERSON_ASSESSMENT_OWNER_DRIFT'; END IF;
  IF v_operation.status='succeeded' THEN
    SELECT count(*) INTO v_master FROM public.hr_performance_legacy_master_result
      WHERE migration_batch_id=v_operation.migration_batch_id;
    IF ROW(v_evidence,v_master,v_resolution)
      IS DISTINCT FROM ROW(v_operation.applied_evidence_rows,
        v_operation.applied_master_rows,v_operation.applied_resolution_rows) THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_PERSON_ASSESSMENT_RECEIPT_DRIFT'; END IF;
  ELSE
    v_master:=0;
    IF v_evidence<>0 OR v_resolution<>0 THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_PERSON_ASSESSMENT_ROLLBACK_RESIDUAL'; END IF;
  END IF;
  v_state:=public.hr_yuzhou_performance_person_assessment_state_sha256(
    v_operation.migration_batch_id,v_operation.status,v_operation.binding_sha256);
  IF v_state<>v_operation.applied_state_sha256 THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_PERSON_ASSESSMENT_STATE_DRIFT'; END IF;
  RETURN QUERY SELECT v_operation.operation_id,v_operation.status,
    v_operation.sealed_artifact_sha256,v_operation.binding_sha256,
    v_operation.target_scope_sha256,v_evidence,v_master,v_resolution,v_state;
END$$;



--
-- Name: hr_yuzhou_performance_person_assessment_state_sha256(uuid, character varying, character); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_performance_person_assessment_state_sha256(p_batch_id uuid, p_status character varying, p_binding_sha256 character) RETURNS character
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT encode(digest(convert_to(jsonb_build_object(
    'contract','yuzhou-performance-person-assessment-state-v1',
    'status',p_status,
    'bindingSha256',p_binding_sha256,
    'evidence',COALESCE((SELECT jsonb_agg(jsonb_build_array(
      evidence.id,evidence.source_person_identity_sha256,
      evidence.source_assessment_id,evidence.evidence_sha256
    ) ORDER BY evidence.id)
      FROM public.hr_performance_legacy_person_assessment_evidence evidence
      WHERE evidence.migration_batch_id=p_batch_id),'[]'::jsonb),
    'resolutions',COALESCE((SELECT jsonb_agg(jsonb_build_array(
      resolution.id,resolution.legacy_master_result_id,
      resolution.person_resolution_status,resolution.detail_resolution_status,
      resolution.comparison_status,resolution.evidence_sha256
    ) ORDER BY resolution.id)
      FROM public.hr_performance_legacy_ass_compute_weight_resolution resolution
      WHERE resolution.migration_batch_id=p_batch_id),'[]'::jsonb)
  )::text,'UTF8'),'sha256'),'hex')::char(64)
$$;



--
-- Name: hr_yuzhou_performance_production_receipt_chain_v1(character varying, character, character, character, character, character, character varying, character varying, character, character); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_performance_production_receipt_chain_v1(p_operation_id character varying, p_sealed_plan_sha256 character, p_code_sha character, p_source_snapshot_sha256 character, p_mapping_contract_sha256 character, p_target_identity_sha256 character, p_tenant_id character varying, p_park_id character varying, p_target_scope_sha256 character, p_t0_phase_receipt_sha256 character) RETURNS TABLE(relations_receipt_sha256 character, fact_loader_receipt_sha256 character, fact_identity_receipt_sha256 character)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_relations public.hr_yuzhou_performance_relations_production_receipt%ROWTYPE;
  v_facts public.hr_yuzhou_performance_facts_production_receipt%ROWTYPE;
  v_identity public.hr_yuzhou_performance_fact_identity_production_receipt%ROWTYPE;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('hr_yuzhou_performance_relations_production',0));
  SELECT * INTO v_relations FROM public.hr_yuzhou_performance_relations_production_receipt
    WHERE operation_id=p_operation_id FOR SHARE;
  SELECT * INTO v_facts FROM public.hr_yuzhou_performance_facts_production_receipt
    WHERE operation_id=p_operation_id FOR SHARE;
  SELECT * INTO v_identity FROM public.hr_yuzhou_performance_fact_identity_production_receipt
    WHERE operation_id=p_operation_id FOR SHARE;
  IF v_relations.operation_id IS NULL OR v_facts.operation_id IS NULL OR v_identity.operation_id IS NULL
    OR v_relations.status<>'succeeded' OR v_facts.status<>'succeeded' OR v_identity.status<>'succeeded'
    OR ROW(v_relations.migration_batch_id,v_relations.sealed_plan_sha256,v_relations.code_sha,
      v_relations.source_snapshot_sha256,v_relations.mapping_contract_sha256,
      v_relations.target_identity_sha256,v_relations.tenant_id,v_relations.park_id,
      v_relations.target_scope_sha256,v_relations.t0_phase_receipt_sha256)
      IS DISTINCT FROM ROW(v_facts.migration_batch_id,p_sealed_plan_sha256,p_code_sha,
        p_source_snapshot_sha256,p_mapping_contract_sha256,p_target_identity_sha256,
        p_tenant_id,p_park_id,p_target_scope_sha256,p_t0_phase_receipt_sha256)
    OR ROW(v_facts.sealed_plan_sha256,v_facts.code_sha,v_facts.source_snapshot_sha256,
      v_facts.mapping_contract_sha256,v_facts.target_identity_sha256,v_facts.tenant_id,
      v_facts.park_id,v_facts.target_scope_sha256,v_facts.t0_phase_receipt_sha256)
      IS DISTINCT FROM ROW(p_sealed_plan_sha256,p_code_sha,p_source_snapshot_sha256,
        p_mapping_contract_sha256,p_target_identity_sha256,p_tenant_id,p_park_id,
        p_target_scope_sha256,p_t0_phase_receipt_sha256)
    OR v_identity.migration_batch_id<>v_facts.migration_batch_id
    OR v_identity.sealed_plan_sha256<>p_sealed_plan_sha256
    OR v_identity.code_sha<>p_code_sha
    OR v_identity.source_snapshot_sha256<>p_source_snapshot_sha256
    OR v_identity.mapping_contract_sha256<>p_mapping_contract_sha256
    OR v_identity.target_identity_sha256<>p_target_identity_sha256
    OR (v_identity.tenant_id,v_identity.park_id,v_identity.target_scope_sha256,
      v_identity.t0_phase_receipt_sha256)
      IS DISTINCT FROM (p_tenant_id,p_park_id,p_target_scope_sha256,p_t0_phase_receipt_sha256)
    OR v_identity.parent_relations_receipt_sha256<>v_relations.receipt_sha256
    OR v_identity.fact_loader_receipt_sha256<>v_facts.receipt_sha256
    OR v_identity.dimension_rows<>v_facts.dimension_result_rows
    OR v_identity.master_rows<>v_facts.master_result_rows
    OR v_identity.fact_set_sha256<>v_facts.identity_fact_set_sha256 THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_PRODUCTION_RECEIPT_CHAIN_INVALID';
  END IF;
  RETURN QUERY SELECT v_relations.receipt_sha256,v_facts.receipt_sha256,
    v_identity.receipt_sha256;
END$$;



