--
-- Name: hr_yuzhou_performance_relations_production_context_allowed(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_performance_relations_production_context_allowed(p_batch_id uuid, p_mode character varying) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT CASE p_mode
    WHEN 'apply' THEN EXISTS(
      SELECT 1
      FROM public.migration_batch batch
      JOIN public.hr_yuzhou_production_import_operation operation
        ON operation.operation_id=batch.production_import_operation_id
      JOIN public.hr_yuzhou_production_import_phase phase
        ON (phase.operation_id,phase.phase)=(operation.operation_id,'T0')
      JOIN public.hr_yuzhou_production_import_authorization_use auth
        ON auth.operation_id=operation.operation_id
       AND auth.import_operation_id=operation.operation_id
       AND auth.intent='production_import'
      WHERE batch.id=p_batch_id
        AND batch.execution_context='production_import'
        AND batch.production_import_phase='T0'
        AND batch.target_database=current_database()
        AND batch.status='succeeded'
        AND operation.execution_contract_version=2
        AND operation.status='running'
        AND operation.current_phase='T0'
        AND phase.status='succeeded'
        AND current_setting('yuzhou.performance_relations_operation_id',true)=operation.operation_id
        AND current_setting('yuzhou.performance_relations_mode',true)='apply'
    )
    WHEN 'rollback' THEN EXISTS(
      SELECT 1
      FROM public.migration_batch batch
      JOIN public.hr_yuzhou_performance_relations_production_receipt receipt
        ON receipt.migration_batch_id=batch.id AND receipt.status='succeeded'
      JOIN public.hr_yuzhou_production_import_rollback_operation rollback_operation
        ON rollback_operation.rollback_operation_id=
          current_setting('yuzhou.performance_relations_rollback_operation_id',true)
       AND rollback_operation.import_operation_id=receipt.operation_id
       AND rollback_operation.status='running'
      JOIN public.hr_yuzhou_production_import_authorization_use auth
        ON auth.operation_id=rollback_operation.rollback_operation_id
       AND auth.import_operation_id=receipt.operation_id
       AND auth.intent='production_import_rollback'
      WHERE batch.id=p_batch_id
        AND batch.execution_context='production_import'
        AND batch.production_import_phase='T0'
        AND batch.target_database=current_database()
        AND current_setting('yuzhou.performance_relations_operation_id',true)=receipt.operation_id
        AND current_setting('yuzhou.performance_relations_mode',true)='rollback'
    )
    ELSE false
  END
$$;



--
-- Name: hr_yuzhou_production_target_scope_sha256(character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_production_target_scope_sha256(p_tenant_id character varying, p_park_id character varying) RETURNS character
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT encode(digest(
    convert_to('yuzhou-hr-production-target-scope-v1','UTF8')
    || decode('00','hex') || convert_to(p_tenant_id,'UTF8')
    || decode('00','hex') || convert_to(p_park_id,'UTF8'),
    'sha256'
  ),'hex')::char(64)
$$;



--
-- Name: hr_yuzhou_rollback_performance_fact_identity_production_v1(character varying, character varying, character, character, character, character, character, character, character, character, character varying, character varying, character, character, character, character, character, character, character); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_rollback_performance_fact_identity_production_v1(p_rollback_operation_id character varying, p_operation_id character varying, p_sealed_plan_sha256 character, p_authorization_artifact_sha256 character, p_authorization_nonce_sha256 character, p_extension_rollback_nonce_sha256 character, p_code_sha character, p_source_snapshot_sha256 character, p_mapping_contract_sha256 character, p_target_identity_sha256 character, p_tenant_id character varying, p_park_id character varying, p_target_scope_sha256 character, p_t0_phase_receipt_sha256 character, p_parent_performance_relations_contract_sha256 character, p_parent_relations_receipt_sha256 character, p_fact_loader_receipt_sha256 character, p_migration_308_sha256 character, p_migration_310_sha256 character) RETURNS TABLE(status character varying, rollback_order text, residual_count bigint, replayed boolean, receipt_sha256 character)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_receipt public.hr_yuzhou_performance_fact_identity_production_receipt%ROWTYPE;
  v_parent public.hr_yuzhou_performance_relations_production_receipt%ROWTYPE;
  v_residual bigint; v_assignment_rows bigint; v_rollback_receipt char(64); v_replayed boolean:=false;
BEGIN
  IF current_setting('transaction_isolation')<>'serializable' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_FACT_IDENTITY_PRODUCTION_REQUIRES_SERIALIZABLE'; END IF;
  IF p_extension_rollback_nonce_sha256!~'^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_FACT_IDENTITY_PRODUCTION_ROLLBACK_BINDING_INVALID'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('hr_yuzhou_performance_relations_production',0));
  SELECT * INTO v_receipt FROM public.hr_yuzhou_performance_fact_identity_production_receipt
    WHERE operation_id=p_operation_id FOR UPDATE;
  SELECT * INTO v_parent FROM public.hr_yuzhou_performance_relations_production_receipt
    WHERE operation_id=p_operation_id FOR UPDATE;
  IF v_receipt.operation_id IS NULL OR v_parent.operation_id IS NULL
    OR ROW(v_receipt.sealed_plan_sha256,v_receipt.code_sha,v_receipt.source_snapshot_sha256,
      v_receipt.mapping_contract_sha256,v_receipt.target_identity_sha256,v_receipt.tenant_id,
      v_receipt.park_id,v_receipt.target_scope_sha256,v_receipt.t0_phase_receipt_sha256,
      v_receipt.parent_performance_relations_contract_sha256,
      v_receipt.parent_relations_receipt_sha256,v_receipt.fact_loader_receipt_sha256,
      v_receipt.migration_308_sha256,v_receipt.migration_310_sha256)
    IS DISTINCT FROM ROW(p_sealed_plan_sha256,p_code_sha,p_source_snapshot_sha256,
      p_mapping_contract_sha256,p_target_identity_sha256,p_tenant_id,p_park_id,
      p_target_scope_sha256,p_t0_phase_receipt_sha256,
      p_parent_performance_relations_contract_sha256,p_parent_relations_receipt_sha256,
      p_fact_loader_receipt_sha256,p_migration_308_sha256,p_migration_310_sha256)
    OR v_parent.receipt_sha256<>p_parent_relations_receipt_sha256
    OR NOT EXISTS(SELECT 1 FROM public.hr_yuzhou_production_import_operation operation
      WHERE operation.operation_id=p_operation_id AND operation.status='succeeded')
    OR NOT EXISTS(SELECT 1 FROM public.hr_yuzhou_production_import_rollback_operation rollback
      WHERE rollback.rollback_operation_id=p_rollback_operation_id
        AND rollback.import_operation_id=p_operation_id
        AND rollback.status IN('running','succeeded')
        AND rollback.sealed_plan_sha256=p_sealed_plan_sha256
        AND rollback.target_identity_sha256=p_target_identity_sha256
        AND rollback.authorization_artifact_sha256=p_authorization_artifact_sha256
        AND rollback.authorization_nonce_sha256=p_authorization_nonce_sha256)
    OR NOT EXISTS(SELECT 1 FROM public.hr_yuzhou_production_import_authorization_use auth
      WHERE auth.intent='production_import_rollback' AND auth.operation_id=p_rollback_operation_id
        AND auth.import_operation_id=p_operation_id
        AND auth.authorization_artifact_sha256=p_authorization_artifact_sha256
        AND auth.authorization_nonce_sha256=p_authorization_nonce_sha256) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_FACT_IDENTITY_PRODUCTION_ROLLBACK_BINDING_INVALID'; END IF;
  IF v_receipt.status='rolled_back' THEN
    IF v_receipt.rollback_operation_id<>p_rollback_operation_id
      OR v_receipt.extension_rollback_nonce_sha256<>p_extension_rollback_nonce_sha256
      OR v_parent.status NOT IN('succeeded','rolled_back') THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_FACT_IDENTITY_PRODUCTION_ROLLBACK_REPLAY_DRIFT'; END IF;
    SELECT count(*) INTO v_residual FROM public.hr_performance_legacy_identity_resolution
      WHERE migration_batch_id=v_receipt.migration_batch_id
        AND fact_kind IN('dimension_result','master_result');
    IF v_residual<>0 THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_FACT_IDENTITY_PRODUCTION_ROLLBACK_REPLAY_DRIFT'; END IF;
    v_replayed:=true; v_rollback_receipt:=v_receipt.rollback_receipt_sha256;
  ELSE
    IF v_receipt.status<>'succeeded' OR v_parent.status<>'succeeded'
      OR NOT EXISTS(SELECT 1 FROM public.hr_yuzhou_production_import_rollback_operation rollback
        WHERE rollback.rollback_operation_id=p_rollback_operation_id
          AND rollback.status='running') THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_FACT_IDENTITY_PRODUCTION_ROLLBACK_BINDING_INVALID'; END IF;
    PERFORM set_config('yuzhou.performance_fact_identity_operation_id',p_operation_id,true);
    PERFORM set_config('yuzhou.performance_fact_identity_rollback_operation_id',p_rollback_operation_id,true);
    PERFORM set_config('yuzhou.performance_fact_identity_mode','rollback',true);
    PERFORM set_config('yuzhou.performance_identity_resolution_rollback_batch_id',v_receipt.migration_batch_id::text,true);
    DELETE FROM public.hr_performance_legacy_identity_resolution
    WHERE migration_batch_id=v_receipt.migration_batch_id
      AND fact_kind IN('dimension_result','master_result');
    SELECT count(*) INTO v_residual FROM public.hr_performance_legacy_identity_resolution
      WHERE migration_batch_id=v_receipt.migration_batch_id
        AND fact_kind IN('dimension_result','master_result');
    SELECT count(*) INTO v_assignment_rows FROM public.hr_performance_legacy_identity_resolution
      WHERE migration_batch_id=v_receipt.migration_batch_id
        AND fact_kind='source_person_assignment';
    IF v_residual<>0 OR v_assignment_rows<>234 THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_FACT_IDENTITY_PRODUCTION_ROLLBACK_RESIDUAL'; END IF;
    v_rollback_receipt:=encode(digest(convert_to(jsonb_build_object(
      'contract','jinhu-yuzhou-performance-fact-identity-production-rollback-v1',
      'rollbackOperationId',p_rollback_operation_id,'operationId',p_operation_id,
      'extensionRollbackNonceSha256',p_extension_rollback_nonce_sha256,
      'parentRelationsReceiptSha256',p_parent_relations_receipt_sha256,
      'factSetSha256',v_receipt.fact_set_sha256,
      'rollbackOrder','fact_identity>performance_relations>performance_facts',
      'residualCount',0)::text,'UTF8'),'sha256'),'hex');
    UPDATE public.hr_yuzhou_performance_fact_identity_production_receipt SET
      status='rolled_back',rollback_operation_id=p_rollback_operation_id,
      extension_rollback_nonce_sha256=p_extension_rollback_nonce_sha256,
      rollback_receipt_sha256=v_rollback_receipt,rolled_back_at=now()
    WHERE operation_id=p_operation_id;
  END IF;
  RETURN QUERY SELECT 'rolled_back'::varchar,
    'fact_identity>performance_relations>performance_facts'::text,
    COALESCE(v_residual,0)::bigint,v_replayed,v_rollback_receipt;
END$_$;



--
-- Name: hr_yuzhou_rollback_performance_facts_production_v1(character varying, character varying, character, character, character, character, character, character, character, character, character varying, character varying, character, character, character, character, character, character, character, bigint, bigint, bigint, bigint, bigint, bigint, bigint, character, character, character, character, character, character, character, character); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_rollback_performance_facts_production_v1(p_rollback_operation_id character varying, p_operation_id character varying, p_sealed_plan_sha256 character, p_performance_fact_loader_contract_sha256 character, p_authorization_artifact_sha256 character, p_authorization_nonce_sha256 character, p_code_sha character, p_source_snapshot_sha256 character, p_mapping_contract_sha256 character, p_target_identity_sha256 character, p_tenant_id character varying, p_park_id character varying, p_target_scope_sha256 character, p_t0_phase_receipt_sha256 character, p_source_restore_receipt_sha256 character, p_source_fact_location_receipt_sha256 character, p_source_fact_location_canonical_sha256 character, p_fact_payload_artifact_sha256 character, p_master_payload_artifact_sha256 character, p_expected_template_rows bigint, p_expected_level_rule_rows bigint, p_expected_dimension_rows bigint, p_expected_guide_rows bigint, p_expected_dimension_result_rows bigint, p_expected_master_result_rows bigint, p_expected_active_fact_maps bigint, p_expected_identity_fact_set_sha256 character, p_expected_full_fact_set_sha256 character, p_migration_300_sha256 character, p_migration_301_sha256 character, p_migration_302_sha256 character, p_migration_303_sha256 character, p_migration_310_sha256 character, p_migration_311_sha256 character) RETURNS TABLE(status character varying, rollback_order text, residual_count bigint, replayed boolean, receipt_sha256 character)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_receipt public.hr_yuzhou_performance_facts_production_receipt%ROWTYPE;
  v_residual bigint; v_rollback_receipt char(64); v_replayed boolean:=false;
BEGIN
  IF current_setting('transaction_isolation')<>'serializable' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_FACTS_PRODUCTION_REQUIRES_SERIALIZABLE'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('hr_yuzhou_performance_relations_production',0));
  SELECT * INTO v_receipt FROM public.hr_yuzhou_performance_facts_production_receipt
    WHERE operation_id=p_operation_id FOR UPDATE;
  IF NOT FOUND OR ROW(v_receipt.sealed_plan_sha256,
    v_receipt.performance_fact_loader_contract_sha256,v_receipt.code_sha,v_receipt.source_snapshot_sha256,
    v_receipt.mapping_contract_sha256,v_receipt.target_identity_sha256,v_receipt.tenant_id,
    v_receipt.park_id,v_receipt.target_scope_sha256,v_receipt.t0_phase_receipt_sha256,
    v_receipt.source_restore_receipt_sha256,v_receipt.source_fact_location_receipt_sha256,
    v_receipt.source_fact_location_canonical_sha256,v_receipt.fact_payload_artifact_sha256,
    v_receipt.master_payload_artifact_sha256,v_receipt.template_rows,v_receipt.level_rule_rows,
    v_receipt.dimension_rows,v_receipt.guide_rows,v_receipt.dimension_result_rows,
    v_receipt.master_result_rows,v_receipt.identity_fact_set_sha256,
    v_receipt.full_fact_set_sha256,v_receipt.migration_300_sha256,v_receipt.migration_301_sha256,
    v_receipt.migration_302_sha256,v_receipt.migration_303_sha256,
    v_receipt.migration_310_sha256,v_receipt.migration_311_sha256)
    IS DISTINCT FROM ROW(p_sealed_plan_sha256,p_performance_fact_loader_contract_sha256,
      p_code_sha,p_source_snapshot_sha256,p_mapping_contract_sha256,p_target_identity_sha256,
      p_tenant_id,p_park_id,p_target_scope_sha256,p_t0_phase_receipt_sha256,
      p_source_restore_receipt_sha256,p_source_fact_location_receipt_sha256,
      p_source_fact_location_canonical_sha256,p_fact_payload_artifact_sha256,
      p_master_payload_artifact_sha256,p_expected_template_rows,p_expected_level_rule_rows,
      p_expected_dimension_rows,p_expected_guide_rows,p_expected_dimension_result_rows,
      p_expected_master_result_rows,p_expected_identity_fact_set_sha256,
      p_expected_full_fact_set_sha256,p_migration_300_sha256,p_migration_301_sha256,
      p_migration_302_sha256,p_migration_303_sha256,p_migration_310_sha256,
      p_migration_311_sha256)
    OR NOT ((v_receipt.status='succeeded' AND v_receipt.active_fact_maps=p_expected_active_fact_maps)
      OR (v_receipt.status='rolled_back' AND v_receipt.active_fact_maps=0)) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_FACTS_PRODUCTION_ROLLBACK_BINDING_INVALID';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.hr_yuzhou_production_import_rollback_operation rollback
      WHERE rollback.rollback_operation_id=p_rollback_operation_id
        AND rollback.import_operation_id=p_operation_id
        AND ((v_receipt.status='succeeded' AND rollback.status='running')
          OR (v_receipt.status='rolled_back' AND rollback.status IN('running','succeeded')))
        AND rollback.sealed_plan_sha256=p_sealed_plan_sha256
        AND rollback.target_identity_sha256=p_target_identity_sha256
        AND rollback.authorization_artifact_sha256=p_authorization_artifact_sha256
        AND rollback.authorization_nonce_sha256=p_authorization_nonce_sha256)
    OR NOT EXISTS(SELECT 1 FROM public.hr_yuzhou_production_import_authorization_use auth
      WHERE auth.intent='production_import_rollback' AND auth.operation_id=p_rollback_operation_id
        AND auth.import_operation_id=p_operation_id
        AND auth.authorization_artifact_sha256=p_authorization_artifact_sha256
        AND auth.authorization_nonce_sha256=p_authorization_nonce_sha256) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_FACTS_PRODUCTION_ROLLBACK_AUTHORIZATION_INVALID';
  END IF;
  IF v_receipt.status='rolled_back' THEN
    IF v_receipt.rollback_operation_id<>p_rollback_operation_id THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_FACTS_PRODUCTION_ROLLBACK_REPLAY_DRIFT'; END IF;
    v_replayed:=true; v_rollback_receipt:=v_receipt.rollback_receipt_sha256;
  ELSE
    IF EXISTS(SELECT 1 FROM public.hr_yuzhou_performance_fact_identity_production_receipt identity_receipt
        WHERE identity_receipt.operation_id=p_operation_id
          AND (identity_receipt.fact_loader_receipt_sha256<>v_receipt.receipt_sha256
            OR identity_receipt.status<>'rolled_back'))
      OR EXISTS(SELECT 1 FROM public.hr_yuzhou_performance_relations_production_receipt relation_receipt
        WHERE relation_receipt.operation_id=p_operation_id AND relation_receipt.status<>'rolled_back') THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_FACTS_PRODUCTION_ROLLBACK_ORDER_INVALID';
    END IF;
    PERFORM set_config('yuzhou.performance_facts_operation_id',p_operation_id,true);
    PERFORM set_config('yuzhou.performance_facts_rollback_operation_id',p_rollback_operation_id,true);
    PERFORM set_config('yuzhou.performance_facts_mode','rollback',true);
    PERFORM set_config('yuzhou.performance_legacy_rollback_batch_id',v_receipt.migration_batch_id::text,true);
    DELETE FROM public.hr_performance_legacy_master_result
      WHERE migration_batch_id=v_receipt.migration_batch_id;
    DELETE FROM public.hr_performance_legacy_dimension_result
      WHERE migration_batch_id=v_receipt.migration_batch_id;
    DELETE FROM public.hr_performance_legacy_dimension_level_guide
      WHERE migration_batch_id=v_receipt.migration_batch_id;
    DELETE FROM public.hr_performance_legacy_dimension_profile
      WHERE migration_batch_id=v_receipt.migration_batch_id;
    DELETE FROM public.hr_performance_legacy_level_rule
      WHERE migration_batch_id=v_receipt.migration_batch_id;
    DELETE FROM public.hr_performance_legacy_template_profile
      WHERE migration_batch_id=v_receipt.migration_batch_id;
    UPDATE public.legacy_record_map SET is_active=false,mapping_status='rolled_back'
      WHERE batch_id=v_receipt.migration_batch_id AND is_active AND target_table IN(
        'hr_performance_legacy_template_profile','hr_performance_legacy_level_rule',
        'hr_performance_legacy_dimension_profile','hr_performance_legacy_dimension_level_guide',
        'hr_performance_legacy_dimension_result','hr_performance_legacy_master_result');
    SET CONSTRAINTS ALL IMMEDIATE;
    SELECT (SELECT count(*) FROM public.hr_performance_legacy_template_profile WHERE migration_batch_id=v_receipt.migration_batch_id)
      +(SELECT count(*) FROM public.hr_performance_legacy_level_rule WHERE migration_batch_id=v_receipt.migration_batch_id)
      +(SELECT count(*) FROM public.hr_performance_legacy_dimension_profile WHERE migration_batch_id=v_receipt.migration_batch_id)
      +(SELECT count(*) FROM public.hr_performance_legacy_dimension_level_guide WHERE migration_batch_id=v_receipt.migration_batch_id)
      +(SELECT count(*) FROM public.hr_performance_legacy_dimension_result WHERE migration_batch_id=v_receipt.migration_batch_id)
      +(SELECT count(*) FROM public.hr_performance_legacy_master_result WHERE migration_batch_id=v_receipt.migration_batch_id)
      +(SELECT count(*) FROM public.legacy_record_map WHERE batch_id=v_receipt.migration_batch_id
        AND is_active AND target_table IN('hr_performance_legacy_template_profile',
          'hr_performance_legacy_level_rule','hr_performance_legacy_dimension_profile',
          'hr_performance_legacy_dimension_level_guide','hr_performance_legacy_dimension_result',
          'hr_performance_legacy_master_result')) INTO v_residual;
    IF v_residual<>0 THEN RAISE EXCEPTION 'HR_PERFORMANCE_FACTS_PRODUCTION_ROLLBACK_RESIDUAL'; END IF;
    v_rollback_receipt:=encode(digest(convert_to(jsonb_build_object(
      'contract','jinhu-yuzhou-performance-fact-loader-production-rollback-v1',
      'rollbackOperationId',p_rollback_operation_id,'operationId',p_operation_id,
      'sealedPlanSha256',p_sealed_plan_sha256,
      'performanceFactLoaderContractSha256',p_performance_fact_loader_contract_sha256,
      'authorizationArtifactSha256',p_authorization_artifact_sha256,
      'authorizationNonceSha256',p_authorization_nonce_sha256,
      'identityFactSetSha256',p_expected_identity_fact_set_sha256,
      'fullFactSetSha256',p_expected_full_fact_set_sha256,
      'rollbackOrder','master_result>dimension_result>dimension_level_guide>dimension_profile>level_rule>template_profile',
      'residualCount',0)::text,'UTF8'),'sha256'),'hex');
    UPDATE public.hr_yuzhou_performance_facts_production_receipt SET
      status='rolled_back',active_fact_maps=0,rollback_operation_id=p_rollback_operation_id,
      rollback_receipt_sha256=v_rollback_receipt,rolled_back_at=now()
      WHERE operation_id=p_operation_id;
  END IF;
  SELECT (SELECT count(*) FROM public.hr_performance_legacy_template_profile WHERE migration_batch_id=v_receipt.migration_batch_id)
    +(SELECT count(*) FROM public.hr_performance_legacy_level_rule WHERE migration_batch_id=v_receipt.migration_batch_id)
    +(SELECT count(*) FROM public.hr_performance_legacy_dimension_profile WHERE migration_batch_id=v_receipt.migration_batch_id)
    +(SELECT count(*) FROM public.hr_performance_legacy_dimension_level_guide WHERE migration_batch_id=v_receipt.migration_batch_id)
    +(SELECT count(*) FROM public.hr_performance_legacy_dimension_result WHERE migration_batch_id=v_receipt.migration_batch_id)
    +(SELECT count(*) FROM public.hr_performance_legacy_master_result WHERE migration_batch_id=v_receipt.migration_batch_id)
    +(SELECT count(*) FROM public.legacy_record_map WHERE batch_id=v_receipt.migration_batch_id
      AND is_active AND target_table IN('hr_performance_legacy_template_profile',
        'hr_performance_legacy_level_rule','hr_performance_legacy_dimension_profile',
        'hr_performance_legacy_dimension_level_guide','hr_performance_legacy_dimension_result',
        'hr_performance_legacy_master_result')) INTO v_residual;
  IF v_residual<>0 THEN RAISE EXCEPTION 'HR_PERFORMANCE_FACTS_PRODUCTION_ROLLBACK_RESIDUAL'; END IF;
  RETURN QUERY SELECT 'rolled_back'::varchar,
    'master_result>dimension_result>dimension_level_guide>dimension_profile>level_rule>template_profile'::text,
    0::bigint,v_replayed,v_rollback_receipt;
END$$;



--
-- Name: hr_yuzhou_rollback_performance_relations_production_v1(character varying, character varying, character, character, character, character, character, character, character, character varying, character varying, character, character, character, character); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_rollback_performance_relations_production_v1(p_rollback_operation_id character varying, p_operation_id character varying, p_sealed_plan_sha256 character, p_authorization_artifact_sha256 character, p_authorization_nonce_sha256 character, p_code_sha character, p_source_snapshot_sha256 character, p_mapping_contract_sha256 character, p_target_identity_sha256 character, p_tenant_id character varying, p_park_id character varying, p_target_scope_sha256 character, p_t0_phase_receipt_sha256 character, p_migration_305_sha256 character, p_migration_306_sha256 character) RETURNS TABLE(status character varying, rollback_order text, residual_count integer, replayed boolean, receipt_sha256 character)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_receipt public.hr_yuzhou_performance_relations_production_receipt%ROWTYPE;
  v_residual integer; v_rollback_receipt char(64); v_replayed boolean:=false;
BEGIN
  IF current_setting('transaction_isolation')<>'serializable' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_REQUIRES_SERIALIZABLE'; END IF;
  IF p_migration_305_sha256<>'d3784218fc8272bd28b93e44b19a02d5c8124466b6b3c218294920603909dfc0'
    OR p_migration_306_sha256<>'cd49f294f4c9e4105b9f7fd4c678b7b2d29c5433d0348f6e6632d6e7c135a56d'
    OR p_target_scope_sha256<>public.hr_yuzhou_production_target_scope_sha256(p_tenant_id,p_park_id) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_BINDING_INVALID'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('hr_yuzhou_performance_relations_production',0));
  SELECT * INTO v_receipt FROM public.hr_yuzhou_performance_relations_production_receipt
    WHERE operation_id=p_operation_id FOR UPDATE;
  IF NOT FOUND OR ROW(v_receipt.sealed_plan_sha256,v_receipt.code_sha,
    v_receipt.source_snapshot_sha256,v_receipt.mapping_contract_sha256,
    v_receipt.target_identity_sha256,v_receipt.tenant_id,v_receipt.park_id,
    v_receipt.target_scope_sha256,v_receipt.t0_phase_receipt_sha256,
    v_receipt.migration_305_sha256,v_receipt.migration_306_sha256)
    IS DISTINCT FROM ROW(p_sealed_plan_sha256,p_code_sha,p_source_snapshot_sha256,
      p_mapping_contract_sha256,p_target_identity_sha256,p_tenant_id,p_park_id,
      p_target_scope_sha256,p_t0_phase_receipt_sha256,p_migration_305_sha256,p_migration_306_sha256)
  THEN RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_ROLLBACK_BINDING_INVALID'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.hr_yuzhou_production_import_operation operation
      WHERE operation.operation_id=p_operation_id AND operation.status='succeeded')
    OR NOT EXISTS(SELECT 1 FROM public.hr_yuzhou_production_import_rollback_operation rollback_operation
      WHERE rollback_operation.rollback_operation_id=p_rollback_operation_id
        AND rollback_operation.import_operation_id=p_operation_id
        AND rollback_operation.status='running'
        AND rollback_operation.sealed_plan_sha256=p_sealed_plan_sha256
        AND rollback_operation.target_identity_sha256=p_target_identity_sha256
        AND rollback_operation.authorization_artifact_sha256=p_authorization_artifact_sha256
        AND rollback_operation.authorization_nonce_sha256=p_authorization_nonce_sha256)
    OR NOT EXISTS(SELECT 1 FROM public.hr_yuzhou_production_import_authorization_use auth
      WHERE auth.intent='production_import_rollback' AND auth.operation_id=p_rollback_operation_id
        AND auth.import_operation_id=p_operation_id
        AND auth.authorization_artifact_sha256=p_authorization_artifact_sha256
        AND auth.authorization_nonce_sha256=p_authorization_nonce_sha256) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_ROLLBACK_AUTHORIZATION_INVALID'; END IF;
  IF v_receipt.status='rolled_back' THEN
    IF v_receipt.rollback_operation_id<>p_rollback_operation_id THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_ROLLBACK_REPLAY_DRIFT'; END IF;
    v_replayed:=true; v_rollback_receipt:=v_receipt.rollback_receipt_sha256;
  ELSE
    PERFORM set_config('yuzhou.performance_relations_operation_id',p_operation_id,true);
    PERFORM set_config('yuzhou.performance_relations_rollback_operation_id',p_rollback_operation_id,true);
    PERFORM set_config('yuzhou.performance_relations_mode','rollback',true);
    PERFORM set_config('yuzhou.performance_identity_resolution_rollback_batch_id',v_receipt.migration_batch_id::text,true);
    PERFORM set_config('yuzhou.performance_legacy_rollback_batch_id',v_receipt.migration_batch_id::text,true);
    DELETE FROM public.hr_performance_legacy_identity_resolution
      WHERE migration_batch_id=v_receipt.migration_batch_id;
    DELETE FROM public.hr_performance_legacy_session_binding
      WHERE migration_batch_id=v_receipt.migration_batch_id;
    DELETE FROM public.hr_performance_legacy_score_source
      WHERE migration_batch_id=v_receipt.migration_batch_id;
    DELETE FROM public.hr_performance_legacy_source_person_assignment
      WHERE migration_batch_id=v_receipt.migration_batch_id;
    DELETE FROM public.hr_performance_legacy_session
      WHERE migration_batch_id=v_receipt.migration_batch_id;
    UPDATE public.legacy_record_map SET is_active=false,mapping_status='rolled_back'
    WHERE batch_id=v_receipt.migration_batch_id AND is_active
      AND target_table IN('hr_performance_legacy_session','hr_performance_legacy_score_source',
        'hr_performance_legacy_source_person_assignment');
    SET CONSTRAINTS ALL IMMEDIATE;
    SELECT
      (SELECT count(*) FROM public.hr_performance_legacy_identity_resolution WHERE migration_batch_id=v_receipt.migration_batch_id)
      +(SELECT count(*) FROM public.hr_performance_legacy_session_binding WHERE migration_batch_id=v_receipt.migration_batch_id)
      +(SELECT count(*) FROM public.hr_performance_legacy_score_source WHERE migration_batch_id=v_receipt.migration_batch_id)
      +(SELECT count(*) FROM public.hr_performance_legacy_source_person_assignment WHERE migration_batch_id=v_receipt.migration_batch_id)
      +(SELECT count(*) FROM public.hr_performance_legacy_session WHERE migration_batch_id=v_receipt.migration_batch_id)
      +(SELECT count(*) FROM public.legacy_record_map WHERE batch_id=v_receipt.migration_batch_id AND is_active
        AND target_table IN('hr_performance_legacy_session','hr_performance_legacy_score_source',
          'hr_performance_legacy_source_person_assignment')) INTO v_residual;
    IF v_residual<>0 THEN RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_ROLLBACK_RESIDUAL'; END IF;
    v_rollback_receipt:=encode(digest(convert_to(jsonb_build_object(
      'contract','jinhu-yuzhou-performance-relations-production-rollback-v1',
      'rollbackOperationId',p_rollback_operation_id,'operationId',p_operation_id,
      'sealedPlanSha256',p_sealed_plan_sha256,
      'authorizationArtifactSha256',p_authorization_artifact_sha256,
      'authorizationNonceSha256',p_authorization_nonce_sha256,
      'codeSha',p_code_sha,'sourceSnapshotSha256',p_source_snapshot_sha256,
      'mappingContractSha256',p_mapping_contract_sha256,
      'targetIdentitySha256',p_target_identity_sha256,
      'targetScopeSha256',p_target_scope_sha256,'t0PhaseReceiptSha256',p_t0_phase_receipt_sha256,
      'migration305Sha256',p_migration_305_sha256,'migration306Sha256',p_migration_306_sha256,
      'rollbackOrder','identity_resolution>source_person_assignments','residualCount',0)::text,'UTF8'),
      'sha256'),'hex');
    UPDATE public.hr_yuzhou_performance_relations_production_receipt SET
      status='rolled_back',active_relation_maps=0,identity_resolution_rows=0,session_binding_rows=0,
      rollback_operation_id=p_rollback_operation_id,rollback_receipt_sha256=v_rollback_receipt,
      rolled_back_at=now() WHERE operation_id=p_operation_id;
  END IF;
  SELECT
    (SELECT count(*) FROM public.hr_performance_legacy_identity_resolution WHERE migration_batch_id=v_receipt.migration_batch_id)
    +(SELECT count(*) FROM public.hr_performance_legacy_session_binding WHERE migration_batch_id=v_receipt.migration_batch_id)
    +(SELECT count(*) FROM public.hr_performance_legacy_score_source WHERE migration_batch_id=v_receipt.migration_batch_id)
    +(SELECT count(*) FROM public.hr_performance_legacy_source_person_assignment WHERE migration_batch_id=v_receipt.migration_batch_id)
    +(SELECT count(*) FROM public.hr_performance_legacy_session WHERE migration_batch_id=v_receipt.migration_batch_id)
    +(SELECT count(*) FROM public.legacy_record_map WHERE batch_id=v_receipt.migration_batch_id AND is_active
      AND target_table IN('hr_performance_legacy_session','hr_performance_legacy_score_source',
        'hr_performance_legacy_source_person_assignment')) INTO v_residual;
  IF v_residual<>0 THEN RAISE EXCEPTION 'HR_PERFORMANCE_RELATIONS_PRODUCTION_ROLLBACK_RESIDUAL'; END IF;
  RETURN QUERY SELECT 'rolled_back'::varchar,
    'identity_resolution>source_person_assignments'::text,0,v_replayed,v_rollback_receipt;
END$$;



--
-- Name: hr_yuzhou_start_production_import(character varying, character); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_start_production_import(p_operation_id character varying, p_sealed_plan_sha256 character) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_setting('transaction_isolation') <> 'serializable' THEN RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_REQUIRES_SERIALIZABLE'; END IF;
  UPDATE hr_yuzhou_production_import_operation
  SET status='running',started_at=now()
  WHERE operation_id=p_operation_id AND sealed_plan_sha256=p_sealed_plan_sha256 AND status='authorized';
  IF NOT FOUND THEN RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_AUTH_RECEIPT_INVALID'; END IF;
END$$;



--
-- Name: hr_yuzhou_t4_followon_batch_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_t4_followon_batch_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE receipt public.hr_yuzhou_t4_followon_operation%ROWTYPE;
BEGIN
  IF NEW.execution_context<>'t4_production_followon' THEN RETURN NEW; END IF;
  SELECT * INTO STRICT receipt FROM public.hr_yuzhou_t4_followon_operation WHERE operation_id=NEW.t4_followon_operation_id;
  IF current_setting('transaction_isolation')<>'serializable' OR NEW.target_database<>current_database()
    OR NEW.source_system<>'yuzhou-v10' OR NEW.source_snapshot_sha256<>receipt.binding->'triple'->>'sourceSnapshotHash'
    OR NEW.tool_version<>'t4-followon-v1@'||(receipt.binding->>'executionCodeSha')
    OR NOT EXISTS(SELECT 1 FROM public.hr_yuzhou_t4_followon_authorization_use WHERE operation_id=receipt.operation_id AND intent='append')
    OR NOT EXISTS(SELECT 1 FROM public.hr_yuzhou_production_import_operation WHERE operation_id=receipt.parent_operation_id AND status='succeeded' AND target_scope_sha256=receipt.binding->>'targetScopeSha256')
  THEN RAISE EXCEPTION 'T4_BATCH_BINDING_INVALID'; END IF;
  RETURN NEW;
END $$;



--
-- Name: hr_yuzhou_t4_followon_control_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_t4_followon_control_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP='DELETE' OR TG_TABLE_NAME='hr_yuzhou_t4_followon_authorization_use'
  THEN RAISE EXCEPTION 'T4_CONTROL_IMMUTABLE'; END IF;
  IF OLD.status<>'succeeded' OR NEW.status<>'rolled_back' OR NEW.rolled_back_at IS NULL
    OR (to_jsonb(NEW)-'status'-'rolled_back_at') IS DISTINCT FROM (to_jsonb(OLD)-'status'-'rolled_back_at')
  THEN RAISE EXCEPTION 'T4_CONTROL_IMMUTABLE'; END IF;
  RETURN NEW;
END $$;



--
-- Name: hr_yuzhou_t4_followon_fresh_authorization(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_t4_followon_fresh_authorization() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF EXISTS(SELECT 1 FROM public.hr_yuzhou_production_import_operation WHERE operation_id=NEW.operation_id OR authorization_nonce_sha256=NEW.nonce_sha256)
    OR EXISTS(SELECT 1 FROM public.hr_yuzhou_production_import_authorization_use WHERE authorization_nonce_sha256=NEW.nonce_sha256)
  THEN RAISE EXCEPTION 'T4_FRESH_OPERATION_AND_NONCE_REQUIRED'; END IF;
  RETURN NEW;
END $$;



--
-- Name: hr_yuzhou_t4_followon_owned_state(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_t4_followon_owned_state(p_operation_id character varying) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE control_batch uuid; t text; n bigint; h text; result jsonb:='{}';
BEGIN
  SELECT id INTO STRICT control_batch FROM public.migration_batch WHERE run_id=p_operation_id;
  FOREACH t IN ARRAY ARRAY['hr_payroll_legacy_batch','hr_payroll_book','hr_payroll_item_definition','hr_payroll_item_version','hr_payroll_formula_version','hr_payroll_book_period','hr_payroll_book_membership','hr_payroll_tax_rule_version','hr_payroll_legacy_snapshot','hr_payroll_legacy_snapshot_item','hr_payroll_review_case'] LOOP
    EXECUTE format('SELECT count(*),encode(digest(COALESCE(string_agg(row_hash,'''' ORDER BY row_hash),''''),''sha256''),''hex'') FROM (SELECT encode(digest(to_jsonb(x)::text,''sha256''),''hex'') row_hash FROM public.%I x JOIN public.legacy_record_map m ON m.target_id=x.id AND m.target_table=$1 AND m.batch_id=$2 AND m.is_active) q',t) INTO n,h USING t,control_batch;
    IF n<>(SELECT count(*) FROM public.legacy_record_map WHERE batch_id=control_batch AND target_table=t AND is_active) THEN RAISE EXCEPTION 'T4_OWNED_MAP_DRIFT'; END IF;
    result:=result||jsonb_build_object(t,jsonb_build_object('count',n,'sha256',h));
  END LOOP;
  SELECT count(*),encode(digest(COALESCE(string_agg(row_hash,'' ORDER BY row_hash),''),'sha256'),'hex') INTO n,h FROM (SELECT encode(digest(to_jsonb(m)::text,'sha256'),'hex') row_hash FROM public.legacy_record_map m WHERE batch_id=control_batch) q;
  RETURN result||jsonb_build_object('maps',jsonb_build_object('count',n,'sha256',h));
END $_$;



--
-- Name: hr_yuzhou_t4_followon_rollback(character varying, character, character, character); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.hr_yuzhou_t4_followon_rollback(IN p_operation_id character varying, IN p_binding_sha256 character, IN p_authorization_sha256 character, IN p_nonce_sha256 character)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE receipt public.hr_yuzhou_t4_followon_operation%ROWTYPE; control_batch uuid; legacy_batch uuid;
BEGIN
  SELECT * INTO STRICT receipt FROM public.hr_yuzhou_t4_followon_operation WHERE operation_id=p_operation_id FOR UPDATE;
  IF receipt.status<>'succeeded' OR receipt.binding_sha256<>p_binding_sha256
    OR NOT EXISTS(SELECT 1 FROM public.hr_yuzhou_t4_followon_authorization_use WHERE operation_id=p_operation_id AND intent='rollback' AND authorization_sha256=p_authorization_sha256 AND nonce_sha256=p_nonce_sha256 AND consumed_at>=transaction_timestamp())
  THEN RAISE EXCEPTION 'T4_ROLLBACK_AUTHORIZATION_REQUIRED'; END IF;
  LOCK TABLE public.legacy_record_map IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.hr_payroll_legacy_batch,public.hr_payroll_book,public.hr_payroll_item_definition,public.hr_payroll_item_version,public.hr_payroll_formula_version,public.hr_payroll_book_period,public.hr_payroll_book_membership,public.hr_payroll_tax_rule_version,public.hr_payroll_legacy_snapshot,public.hr_payroll_legacy_snapshot_item,public.hr_payroll_review_case IN ACCESS EXCLUSIVE MODE;
  IF public.hr_yuzhou_t4_followon_owned_state(p_operation_id) IS DISTINCT FROM receipt.owned_state THEN RAISE EXCEPTION 'T4_ROLLBACK_STATE_DRIFT'; END IF;
  SELECT id INTO STRICT control_batch FROM public.migration_batch WHERE run_id=p_operation_id AND target_database=current_database() AND status='succeeded';
  SELECT id INTO STRICT legacy_batch FROM public.hr_payroll_legacy_batch WHERE batch_code=p_operation_id AND status='staged' AND published_at IS NULL AND tenant_id=receipt.binding->'targetScope'->>'tenantId' AND park_id=receipt.binding->'targetScope'->>'parkId';
  -- Named guard suspension is confined to exact receipt-owned, undrifted rows.
  -- All table locks and changes remain inside the caller's one transaction.
  ALTER TABLE public.hr_payroll_review_case DISABLE TRIGGER trg_hr_payroll_review_case_guard;
  ALTER TABLE public.hr_payroll_legacy_snapshot_item DISABLE TRIGGER trg_hr_payroll_legacy_snapshot_item_guard;
  ALTER TABLE public.hr_payroll_legacy_snapshot DISABLE TRIGGER trg_hr_payroll_legacy_snapshot_guard;
  ALTER TABLE public.hr_payroll_formula_version DISABLE TRIGGER trg_hr_payroll_formula_version_guard;
  ALTER TABLE public.hr_payroll_item_version DISABLE TRIGGER trg_hr_payroll_item_version_guard;
  ALTER TABLE public.hr_payroll_item_definition DISABLE TRIGGER trg_hr_payroll_item_definition_guard;
  ALTER TABLE public.hr_payroll_book_membership DISABLE TRIGGER trg_hr_payroll_book_membership_guard;
  ALTER TABLE public.hr_payroll_tax_rule_version DISABLE TRIGGER trg_hr_payroll_tax_rule_version_guard;
  ALTER TABLE public.hr_payroll_book_period DISABLE TRIGGER trg_hr_payroll_book_period_guard;
  ALTER TABLE public.hr_payroll_book DISABLE TRIGGER trg_hr_payroll_book_guard;
  ALTER TABLE public.hr_payroll_legacy_batch DISABLE TRIGGER trg_hr_payroll_legacy_batch_guard;
  DELETE FROM public.hr_payroll_review_case x USING public.legacy_record_map m WHERE m.batch_id=control_batch AND m.target_table='hr_payroll_review_case' AND m.target_id=x.id AND m.is_active;
  DELETE FROM public.hr_payroll_legacy_snapshot_item x USING public.legacy_record_map m WHERE m.batch_id=control_batch AND m.target_table='hr_payroll_legacy_snapshot_item' AND m.target_id=x.id AND m.is_active;
  DELETE FROM public.hr_payroll_legacy_snapshot x USING public.legacy_record_map m WHERE m.batch_id=control_batch AND m.target_table='hr_payroll_legacy_snapshot' AND m.target_id=x.id AND m.is_active;
  DELETE FROM public.hr_payroll_formula_version x USING public.legacy_record_map m WHERE m.batch_id=control_batch AND m.target_table='hr_payroll_formula_version' AND m.target_id=x.id AND m.is_active;
  DELETE FROM public.hr_payroll_item_version x USING public.legacy_record_map m WHERE m.batch_id=control_batch AND m.target_table='hr_payroll_item_version' AND m.target_id=x.id AND m.is_active;
  DELETE FROM public.hr_payroll_item_definition x USING public.legacy_record_map m WHERE m.batch_id=control_batch AND m.target_table='hr_payroll_item_definition' AND m.target_id=x.id AND m.is_active;
  DELETE FROM public.hr_payroll_book_membership x USING public.legacy_record_map m WHERE m.batch_id=control_batch AND m.target_table='hr_payroll_book_membership' AND m.target_id=x.id AND m.is_active;
  DELETE FROM public.hr_payroll_tax_rule_version x USING public.legacy_record_map m WHERE m.batch_id=control_batch AND m.target_table='hr_payroll_tax_rule_version' AND m.target_id=x.id AND m.is_active;
  DELETE FROM public.hr_payroll_book_period x USING public.legacy_record_map m WHERE m.batch_id=control_batch AND m.target_table='hr_payroll_book_period' AND m.target_id=x.id AND m.is_active;
  DELETE FROM public.hr_payroll_book x USING public.legacy_record_map m WHERE m.batch_id=control_batch AND m.target_table='hr_payroll_book' AND m.target_id=x.id AND m.is_active;
  DELETE FROM public.hr_payroll_legacy_batch WHERE id=legacy_batch;
  ALTER TABLE public.hr_payroll_review_case ENABLE TRIGGER trg_hr_payroll_review_case_guard;
  ALTER TABLE public.hr_payroll_legacy_snapshot_item ENABLE TRIGGER trg_hr_payroll_legacy_snapshot_item_guard;
  ALTER TABLE public.hr_payroll_legacy_snapshot ENABLE TRIGGER trg_hr_payroll_legacy_snapshot_guard;
  ALTER TABLE public.hr_payroll_formula_version ENABLE TRIGGER trg_hr_payroll_formula_version_guard;
  ALTER TABLE public.hr_payroll_item_version ENABLE TRIGGER trg_hr_payroll_item_version_guard;
  ALTER TABLE public.hr_payroll_item_definition ENABLE TRIGGER trg_hr_payroll_item_definition_guard;
  ALTER TABLE public.hr_payroll_book_membership ENABLE TRIGGER trg_hr_payroll_book_membership_guard;
  ALTER TABLE public.hr_payroll_tax_rule_version ENABLE TRIGGER trg_hr_payroll_tax_rule_version_guard;
  ALTER TABLE public.hr_payroll_book_period ENABLE TRIGGER trg_hr_payroll_book_period_guard;
  ALTER TABLE public.hr_payroll_book ENABLE TRIGGER trg_hr_payroll_book_guard;
  ALTER TABLE public.hr_payroll_legacy_batch ENABLE TRIGGER trg_hr_payroll_legacy_batch_guard;

  UPDATE public.legacy_record_map SET mapping_status='rolled_back',is_active=false,update_time=now() WHERE batch_id=control_batch AND is_active;
  UPDATE public.migration_batch SET phase='rollback',status='rolled_back',finished_at=now(),update_time=now() WHERE id=control_batch;
  UPDATE public.hr_yuzhou_t4_followon_operation SET status='rolled_back',rolled_back_at=clock_timestamp() WHERE operation_id=p_operation_id;
  IF EXISTS(SELECT 1 FROM public.legacy_record_map WHERE batch_id=control_batch AND is_active) THEN RAISE EXCEPTION 'T4_ROLLBACK_RESIDUAL'; END IF;
END $$;



--
-- Name: hr_yuzhou_t5_followon_batch_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_t5_followon_batch_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE operation public.hr_yuzhou_t5_followon_operation%ROWTYPE;
BEGIN
 IF TG_OP='UPDATE' AND OLD.execution_context='t5_production_followon'
  AND (to_jsonb(NEW)-'phase'-'status'-'counts'-'finished_at'-'update_time') IS DISTINCT FROM
      (to_jsonb(OLD)-'phase'-'status'-'counts'-'finished_at'-'update_time')
 THEN RAISE EXCEPTION 'T5_BATCH_IDENTITY_IMMUTABLE'; END IF;
 IF NEW.execution_context<>'t5_production_followon' THEN RETURN NEW; END IF;
 SELECT * INTO STRICT operation FROM public.hr_yuzhou_t5_followon_operation WHERE operation_id=NEW.t5_followon_operation_id;
 PERFORM public.hr_yuzhou_t5_followon_context(operation.operation_id,operation.binding_sha256);
 IF NEW.target_database<>current_database() OR NEW.source_system<>'yuzhou-v10'
  OR NEW.source_snapshot_sha256<>operation.binding->'triple'->>'sourceSnapshotHash'
  OR NEW.tool_version<>'t5-followon-v1@'||(operation.binding->>'executionCodeSha')
 THEN RAISE EXCEPTION 'T5_BATCH_BINDING_INVALID'; END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_yuzhou_t5_followon_commit_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_t5_followon_commit_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE operation public.hr_yuzhou_t5_followon_operation%ROWTYPE; domain text; expected bigint; actual bigint; t text;
BEGIN
 SELECT * INTO STRICT operation FROM public.hr_yuzhou_t5_followon_operation WHERE operation_id=NEW.operation_id;
 IF operation.status='running' THEN RAISE EXCEPTION 'T5_APPEND_NOT_TERMINAL'; END IF;
 IF operation.status='rolled_back' THEN
  FOREACH t IN ARRAY ARRAY['hr_employee_profile','hr_employee_family','hr_employee_skill','hr_employee_credential',
   'hr_custom_field_definition','hr_custom_field_legacy_logic_fingerprint','hr_employee_custom_value',
   'hr_legacy_identity_registry','hr_legacy_archive_record','hr_legacy_file_logical_record','hr_legacy_file_blob_object','hr_yuzhou_t5_followon_source','sys_file'] LOOP
   EXECUTE format('SELECT count(*) FROM public.%I x JOIN public.hr_yuzhou_t5_followon_projection_receipt r ON r.target_id=x.id AND r.target_table=$1 AND r.operation_id=$2 AND r.disposition=''insert''',t)
    INTO actual USING t,operation.operation_id;
   IF actual<>0 THEN RAISE EXCEPTION 'T5_ROLLBACK_RESIDUAL_TARGET'; END IF;
  END LOOP;
  IF EXISTS(SELECT 1 FROM public.hr_yuzhou_t5_followon_source WHERE operation_id=operation.operation_id)
  THEN RAISE EXCEPTION 'T5_ROLLBACK_RESIDUAL_SOURCE'; END IF;
  RETURN NEW;
 END IF;
 FOR domain,expected IN SELECT * FROM (VALUES
  ('accept',0),('family',4560),('his',375),('knowhow',6),('ticket',237),('person_core',2949),
  ('person_user',0),('person_user_item',8),('readjust',6887),('readjustitem',8),('jobstatecode',8),
  ('compact',802),('compact_c',357),('compacttypecode',4),('photo',2949),('docs',1003),
  ('course',0),('train',0),('trainhis',2),('jobtrain',0),('bonuscode',8),('bonusrecord',0),('jch_1',0),('definitions',19)
 ) expected_domains LOOP
  SELECT count(*) INTO actual FROM public.hr_yuzhou_t5_followon_source
   WHERE operation_id=operation.operation_id AND source_domain=domain;
  IF actual<>expected THEN RAISE EXCEPTION 'T5_SOURCE_DOMAIN_CONSERVATION_FAILED'; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM public.hr_yuzhou_t5_followon_source s
  LEFT JOIN public.hr_yuzhou_t5_followon_projection_receipt r
   ON r.operation_id=s.operation_id AND r.target_table='hr_yuzhou_t5_followon_source'
    AND r.target_id=s.id AND r.disposition='insert'
    AND r.source_identity_sha256=s.source_identity_sha256 AND r.source_row_sha256=s.source_row_sha256
  WHERE s.operation_id=operation.operation_id AND r.target_id IS NULL)
  OR (SELECT count(*) FROM public.hr_yuzhou_t5_followon_projection_receipt
   WHERE operation_id=operation.operation_id AND target_table='hr_yuzhou_t5_followon_source')<>20182
 THEN RAISE EXCEPTION 'T5_SOURCE_RECEIPT_CONSERVATION_FAILED'; END IF;
 SELECT count(*) INTO actual FROM public.hr_yuzhou_t5_followon_projection_receipt
  WHERE operation_id=operation.operation_id AND target_table IN ('hr_employee_profile','hr_employee_family','hr_employee_skill','hr_employee_credential','hr_custom_field_definition','hr_custom_field_legacy_logic_fingerprint','hr_employee_custom_value');
 IF actual<>63992 THEN RAISE EXCEPTION 'T5_TYPED_PROJECTION_CONSERVATION_FAILED'; END IF;
 SELECT count(*) INTO actual FROM public.hr_yuzhou_t5_followon_projection_receipt
  WHERE operation_id=operation.operation_id AND target_table='sys_file';
 IF actual<>2949 THEN RAISE EXCEPTION 'T5_PHOTO_SOURCE_CONSERVATION_FAILED'; END IF;
 IF operation.photo_state->>'bundleSha256' IS DISTINCT FROM operation.binding->>'photoBundleSha256'
  OR operation.photo_state->>'sourceRows' IS DISTINCT FROM '2949'
  OR operation.photo_state->>'distinctPhysicalFiles' IS DISTINCT FROM '2150'
  OR operation.photo_state->>'physicalFilesVerified' IS DISTINCT FROM 'true'
 THEN RAISE EXCEPTION 'T5_PHYSICAL_PHOTO_PROOF_REQUIRED'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.migration_batch WHERE t5_followon_operation_id=operation.operation_id
  AND status='succeeded' AND target_database=current_database())
 THEN RAISE EXCEPTION 'T5_SUCCEEDED_BATCH_REQUIRED'; END IF;
 IF operation.owned_state IS DISTINCT FROM public.hr_yuzhou_t5_followon_owned_state(operation.operation_id)
 THEN RAISE EXCEPTION 'T5_COMMITTED_OWNED_STATE_DRIFT'; END IF;
 RETURN NEW;
END $_$;



--
-- Name: hr_yuzhou_t5_followon_context(character varying, character); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_t5_followon_context(p_operation_id character varying, p_binding_sha256 character) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE operation public.hr_yuzhou_t5_followon_operation%ROWTYPE;
BEGIN
 SELECT * INTO STRICT operation FROM public.hr_yuzhou_t5_followon_operation WHERE operation_id=p_operation_id;
 IF current_setting('transaction_isolation')<>'serializable' OR operation.status<>'running'
  OR operation.binding_sha256<>p_binding_sha256
  OR NOT EXISTS(SELECT 1 FROM public.hr_yuzhou_t5_followon_authorization_use WHERE operation_id=p_operation_id
   AND intent='append' AND execution_xid=pg_current_xact_id())
  OR NOT EXISTS(SELECT 1 FROM public.hr_yuzhou_production_import_operation core WHERE core.operation_id=operation.parent_operation_id
   AND core.status='succeeded' AND core.code_sha=operation.binding->'triple'->>'codeSha'
   AND core.source_snapshot_sha256=operation.binding->'triple'->>'sourceSnapshotHash'
   AND core.mapping_contract_sha256=operation.binding->'triple'->>'mappingContractHash'
   AND core.sealed_plan_sha256=operation.binding->'parent'->>'sealedPlanSha256'
   AND core.target_identity_sha256=operation.binding->>'targetIdentitySha256'
   AND core.target_scope_sha256=operation.binding->>'targetScopeSha256'
   AND core.target_tenant_id=operation.binding->'targetScope'->>'tenantId'
   AND core.target_park_id=operation.binding->'targetScope'->>'parkId')
  OR NOT EXISTS(SELECT 1 FROM public.hr_yuzhou_t4_followon_operation payroll WHERE payroll.operation_id=operation.payroll_operation_id
   AND payroll.status='succeeded' AND payroll.parent_operation_id=operation.parent_operation_id
   AND payroll.binding_sha256=operation.binding->'payrollParent'->>'bindingSha256')
 THEN RAISE EXCEPTION 'T5_FOLLOWON_CONTEXT_INVALID'; END IF;
 RETURN true;
END $$;



--
-- Name: hr_yuzhou_t5_followon_control_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_t5_followon_control_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
 IF TG_OP='DELETE' OR TG_TABLE_NAME='hr_yuzhou_t5_followon_authorization_use' THEN RAISE EXCEPTION 'T5_CONTROL_IMMUTABLE'; END IF;
 IF (OLD.status='running' AND NEW.status='succeeded' AND NEW.finished_at IS NOT NULL AND NEW.rolled_back_at IS NULL
  AND (to_jsonb(NEW)-'status'-'finished_at'-'owned_state'-'photo_state')=(to_jsonb(OLD)-'status'-'finished_at'-'owned_state'-'photo_state'))
  OR (OLD.status='succeeded' AND NEW.status='rolled_back' AND NEW.rolled_back_at IS NOT NULL
   AND current_setting('transaction_isolation')='serializable'
   AND EXISTS(SELECT 1 FROM public.hr_yuzhou_t5_followon_authorization_use a
    WHERE a.operation_id=OLD.operation_id AND a.intent='rollback' AND a.execution_xid=pg_current_xact_id())
   AND (to_jsonb(NEW)-'status'-'rolled_back_at')=(to_jsonb(OLD)-'status'-'rolled_back_at'))
 THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'T5_CONTROL_IMMUTABLE';
END $$;



--
-- Name: hr_yuzhou_t5_followon_fresh_authorization(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_t5_followon_fresh_authorization() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM public.hr_yuzhou_production_import_operation WHERE operation_id=NEW.operation_id OR authorization_nonce_sha256=NEW.nonce_sha256)
  OR EXISTS(SELECT 1 FROM public.hr_yuzhou_production_import_authorization_use WHERE authorization_nonce_sha256=NEW.nonce_sha256)
  OR EXISTS(SELECT 1 FROM public.hr_yuzhou_t4_followon_authorization_use WHERE operation_id=NEW.operation_id OR nonce_sha256=NEW.nonce_sha256)
 THEN RAISE EXCEPTION 'T5_FRESH_OPERATION_AND_NONCE_REQUIRED'; END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_yuzhou_t5_followon_owned_state(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_t5_followon_owned_state(p_operation_id character varying) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE operation public.hr_yuzhou_t5_followon_operation%ROWTYPE; t text; n bigint; h text; result jsonb:='{}';
BEGIN
 SELECT * INTO STRICT operation FROM public.hr_yuzhou_t5_followon_operation WHERE operation_id=p_operation_id;
 FOREACH t IN ARRAY ARRAY['hr_employee_profile','hr_employee_family','hr_employee_skill','hr_employee_credential',
  'hr_custom_field_definition','hr_custom_field_legacy_logic_fingerprint','hr_employee_custom_value',
  'hr_legacy_identity_registry','hr_legacy_archive_record','hr_legacy_file_logical_record','hr_legacy_file_blob_object','hr_yuzhou_t5_followon_source','sys_file'] LOOP
  EXECUTE format('SELECT count(*),encode(digest(COALESCE(string_agg(row_hash,'''' ORDER BY row_hash),''''),''sha256''),''hex'') FROM (SELECT encode(digest(to_jsonb(x)::text,''sha256''),''hex'') row_hash FROM public.%I x JOIN public.hr_yuzhou_t5_followon_projection_receipt r ON r.target_id=x.id AND r.target_table=$1 AND r.operation_id=$2 AND r.disposition=''insert'' WHERE x.tenant_id=$3 AND x.park_id=$4) q',t)
   INTO n,h USING t,p_operation_id,operation.binding->'targetScope'->>'tenantId',operation.binding->'targetScope'->>'parkId';
  IF n<>(SELECT count(*) FROM public.hr_yuzhou_t5_followon_projection_receipt WHERE operation_id=p_operation_id AND target_table=t AND disposition='insert')
  THEN RAISE EXCEPTION 'T5_OWNED_TARGET_DRIFT'; END IF;
  result:=result||jsonb_build_object(t,jsonb_build_object('count',n,'sha256',h));
 END LOOP;
 SELECT count(*),encode(digest(COALESCE(string_agg(row_hash,'' ORDER BY row_hash),''),'sha256'),'hex') INTO n,h FROM (
  SELECT encode(digest(to_jsonb(r)::text,'sha256'),'hex') row_hash FROM public.hr_yuzhou_t5_followon_projection_receipt r WHERE operation_id=p_operation_id
 ) q;
 RETURN result||jsonb_build_object('receipts',jsonb_build_object('count',n,'sha256',h));
END $_$;



--
-- Name: hr_yuzhou_t5_followon_receipt_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_t5_followon_receipt_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE binding_hash char(64);
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'T5_RECEIPT_IMMUTABLE'; END IF;
 SELECT binding_sha256 INTO STRICT binding_hash FROM public.hr_yuzhou_t5_followon_operation WHERE operation_id=NEW.operation_id;
 PERFORM public.hr_yuzhou_t5_followon_context(NEW.operation_id,binding_hash);
 RETURN NEW;
END $$;



--
-- Name: hr_yuzhou_t5_followon_rollback(character varying, character, character, character); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.hr_yuzhou_t5_followon_rollback(IN p_operation_id character varying, IN p_binding_sha256 character, IN p_authorization_sha256 character, IN p_nonce_sha256 character)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE operation public.hr_yuzhou_t5_followon_operation%ROWTYPE; t text;
BEGIN
 SELECT * INTO STRICT operation FROM public.hr_yuzhou_t5_followon_operation WHERE operation_id=p_operation_id FOR UPDATE;
 IF current_setting('transaction_isolation')<>'serializable' OR operation.status<>'succeeded' OR operation.binding_sha256<>p_binding_sha256
  OR NOT EXISTS(SELECT 1 FROM public.hr_yuzhou_t5_followon_authorization_use WHERE operation_id=p_operation_id AND intent='rollback'
   AND authorization_sha256=p_authorization_sha256 AND nonce_sha256=p_nonce_sha256 AND execution_xid=pg_current_xact_id())
 THEN RAISE EXCEPTION 'T5_ROLLBACK_AUTHORIZATION_REQUIRED'; END IF;
 LOCK TABLE public.hr_employee_profile,public.hr_employee_family,public.hr_employee_skill,public.hr_employee_credential,
  public.hr_custom_field_definition,public.hr_custom_field_legacy_logic_fingerprint,public.hr_employee_custom_value,
  public.hr_legacy_identity_registry,public.hr_legacy_archive_record,public.hr_legacy_file_logical_record,public.hr_legacy_file_blob_object,
  public.hr_yuzhou_t5_followon_source,public.hr_yuzhou_t5_followon_projection_receipt,public.sys_file IN ACCESS EXCLUSIVE MODE;
 IF operation.owned_state IS DISTINCT FROM public.hr_yuzhou_t5_followon_owned_state(p_operation_id)
 THEN RAISE EXCEPTION 'T5_ROLLBACK_STATE_DRIFT'; END IF;
 ALTER TABLE public.hr_custom_field_definition DISABLE TRIGGER trg_hr_custom_field_definition_legacy_guard;
 ALTER TABLE public.hr_employee_custom_value DISABLE TRIGGER trg_hr_employee_custom_value_legacy_guard;
 ALTER TABLE public.hr_custom_field_legacy_logic_fingerprint DISABLE TRIGGER trg_hr_custom_field_logic_guard;
 ALTER TABLE public.hr_legacy_identity_registry DISABLE TRIGGER trg_hr_legacy_identity_registry_guard;
 ALTER TABLE public.hr_legacy_archive_record DISABLE TRIGGER trg_hr_legacy_archive_record_immutable;
 ALTER TABLE public.hr_legacy_file_logical_record DISABLE TRIGGER trg_hr_legacy_file_logical_immutable;
 ALTER TABLE public.hr_legacy_file_blob_object DISABLE TRIGGER trg_hr_legacy_file_blob_immutable;
 ALTER TABLE public.hr_yuzhou_t5_followon_source DISABLE TRIGGER trg_t5_followon_source_guard;
 FOREACH t IN ARRAY ARRAY['hr_employee_custom_value','hr_custom_field_legacy_logic_fingerprint','hr_custom_field_definition',
  'hr_employee_credential','hr_employee_skill','hr_employee_family','hr_employee_profile','hr_legacy_file_logical_record',
  'hr_legacy_file_blob_object','hr_legacy_archive_record','hr_legacy_identity_registry','hr_yuzhou_t5_followon_source','sys_file'] LOOP
  EXECUTE format('DELETE FROM public.%I x USING public.hr_yuzhou_t5_followon_projection_receipt r WHERE r.operation_id=$1 AND r.target_table=$2 AND r.target_id=x.id AND r.disposition=''insert''',t) USING p_operation_id,t;
 END LOOP;
 ALTER TABLE public.hr_custom_field_definition ENABLE TRIGGER trg_hr_custom_field_definition_legacy_guard;
 ALTER TABLE public.hr_employee_custom_value ENABLE TRIGGER trg_hr_employee_custom_value_legacy_guard;
 ALTER TABLE public.hr_custom_field_legacy_logic_fingerprint ENABLE TRIGGER trg_hr_custom_field_logic_guard;
 ALTER TABLE public.hr_legacy_identity_registry ENABLE TRIGGER trg_hr_legacy_identity_registry_guard;
 ALTER TABLE public.hr_legacy_archive_record ENABLE TRIGGER trg_hr_legacy_archive_record_immutable;
 ALTER TABLE public.hr_legacy_file_logical_record ENABLE TRIGGER trg_hr_legacy_file_logical_immutable;
 ALTER TABLE public.hr_legacy_file_blob_object ENABLE TRIGGER trg_hr_legacy_file_blob_immutable;
 ALTER TABLE public.hr_yuzhou_t5_followon_source ENABLE TRIGGER trg_t5_followon_source_guard;
 -- The original batch remains immutable evidence; the rollback operation is
 -- recorded on this new control row and never changes its succeeded parents.
 UPDATE public.hr_yuzhou_t5_followon_operation SET status='rolled_back',rolled_back_at=clock_timestamp() WHERE operation_id=p_operation_id;
END $_$;



--
-- Name: hr_yuzhou_t5_followon_source_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_t5_followon_source_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE operation public.hr_yuzhou_t5_followon_operation%ROWTYPE;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'T5_SOURCE_IMMUTABLE'; END IF;
 SELECT * INTO STRICT operation FROM public.hr_yuzhou_t5_followon_operation WHERE operation_id=NEW.operation_id;
 PERFORM public.hr_yuzhou_t5_followon_context(NEW.operation_id,operation.binding_sha256);
 IF NEW.tenant_id<>operation.binding->'targetScope'->>'tenantId' OR NEW.park_id<>operation.binding->'targetScope'->>'parkId'
  THEN RAISE EXCEPTION 'T5_SOURCE_SCOPE_INVALID'; END IF;
 IF NEW.owner_status='mapped' AND NOT EXISTS(
  SELECT 1 FROM public.hr_yuzhou_production_import_record r
  JOIN public.hr_yuzhou_production_import_projection_receipt p USING(operation_id,phase,source_identity_sha256)
  JOIN public.legacy_record_map m ON m.id=p.legacy_record_map_id AND m.batch_id=p.migration_batch_id
  JOIN public.hr_employee e ON e.id=r.target_id
  WHERE r.operation_id=operation.parent_operation_id AND r.phase='T0' AND r.target_table='hr_employee'
   AND r.disposition='insert' AND r.rollback_status='not_started' AND e.id=NEW.employee_id
   AND e.tenant_id=NEW.tenant_id AND e.park_id=NEW.park_id AND NOT e.is_deleted
   AND m.id=NEW.owner_record_map_id AND m.target_id=e.id AND m.target_table='hr_employee'
   AND m.source_system='yuzhou-v10' AND m.source_table='dbo.person' AND m.is_active
   AND m.mapping_status IN ('loaded','verified') AND m.source_identity_sha256=r.source_identity_sha256
   AND m.source_row_sha256=r.source_row_sha256 AND m.source_pk_canonical='sha256:'||r.source_identity_sha256
 ) THEN RAISE EXCEPTION 'T5_SOURCE_OWNER_INVALID'; END IF;
 RETURN NEW;
END $$;



--
-- Name: hr_yuzhou_t5_nonfile_rollback_context_allowed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_t5_nonfile_rollback_context_allowed(p_batch_id uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
  SELECT EXISTS(
    SELECT 1
    FROM public.migration_batch batch
    WHERE batch.id=p_batch_id
      AND batch.target_database=current_database()
      AND batch.status='succeeded'
      AND (
        (
          batch.execution_context='lab_rehearsal'
          AND batch.target_database~'^jinhu_hr_migration_lab_[A-Za-z0-9_]{6,64}$'
          AND batch.run_id=current_setting('yuzhou.custom_field_rollback',true)
        )
        OR
        (
          batch.execution_context='production_import'
          AND batch.production_import_phase='T5'
          AND batch.run_id=batch.production_import_operation_id||'-t5'
          AND EXISTS (
            SELECT 1
            FROM public.hr_yuzhou_production_import_operation operation
            JOIN public.hr_yuzhou_production_import_phase phase
              ON phase.operation_id=operation.operation_id AND phase.phase='T5'
            JOIN public.hr_yuzhou_production_import_rollback_operation rollback_operation
              ON rollback_operation.import_operation_id=operation.operation_id
            JOIN public.hr_yuzhou_production_import_authorization_use authorization_use
              ON authorization_use.intent='production_import_rollback'
             AND authorization_use.operation_id=rollback_operation.rollback_operation_id
             AND authorization_use.import_operation_id=operation.operation_id
             AND authorization_use.authorization_artifact_sha256=rollback_operation.authorization_artifact_sha256
             AND authorization_use.authorization_nonce_sha256=rollback_operation.authorization_nonce_sha256
            JOIN public.sys_user actor
              ON actor.id=rollback_operation.t5_nonfile_executor_actor_id
             AND actor.tenant_id::text=operation.target_tenant_id
             AND actor.park_id::text=operation.target_park_id
             AND actor.is_enabled=true AND actor.status='enabled' AND actor.is_deleted=false
            WHERE operation.operation_id=batch.production_import_operation_id
              AND operation.execution_contract_version=2
              AND operation.status='succeeded' AND operation.current_phase='T5'
              AND operation.target_identity_sha256=rollback_operation.target_identity_sha256
              AND operation.sealed_plan_sha256=rollback_operation.sealed_plan_sha256
              AND operation.target_scope_sha256=public.hr_yuzhou_production_target_scope_sha256(operation.target_tenant_id,operation.target_park_id)
              AND phase.status='rolling_back'
              AND rollback_operation.status='running'
              AND now()>=rollback_operation.authorization_issued_at
              AND now()<rollback_operation.authorization_expires_at
              AND rollback_operation.t5_nonfile_executor_actor_id=batch.production_import_actor_id
              AND rollback_operation.t5_nonfile_execution_xid=pg_current_xact_id()
          )
        )
      )
  )
$_$;



--
-- Name: hr_yuzhou_validate_production_import_owner_map(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_validate_production_import_owner_map() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  owner_record hr_yuzhou_production_import_record%ROWTYPE;
  v_contract_version smallint;
BEGIN
  SELECT execution_contract_version INTO v_contract_version
  FROM hr_yuzhou_production_import_operation WHERE operation_id=NEW.operation_id;
  IF v_contract_version=2 THEN
    IF NEW.owner_source_identity_sha256 IS NOT NULL THEN
      RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_V2_LEGACY_OWNER_FORBIDDEN';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.phase = 'T0' THEN
    IF NEW.owner_source_identity_sha256 IS NOT NULL THEN RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_T0_OWNER_FORBIDDEN'; END IF;
    RETURN NEW;
  END IF;
  IF NEW.owner_source_identity_sha256 IS NULL THEN RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_OWNER_RECORD_MAP_REQUIRED'; END IF;
  SELECT * INTO owner_record FROM hr_yuzhou_production_import_record
  WHERE operation_id=NEW.operation_id AND phase='T0' AND source_identity_sha256=NEW.owner_source_identity_sha256;
  IF NOT FOUND THEN RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_OWNER_RECORD_MAP_REQUIRED'; END IF;
  IF NEW.disposition <> 'quarantine'
     AND (owner_record.disposition='quarantine' OR owner_record.target_table <> 'hr_employee' OR owner_record.target_id IS NULL) THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_OWNER_RECORD_MAP_REQUIRED';
  END IF;
  RETURN NEW;
END$$;



--
-- Name: hr_yuzhou_validate_production_import_v2_dependency_dependents(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_validate_production_import_v2_dependency_dependents() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_contract_version smallint;
  v_invalid integer;
BEGIN
  SELECT execution_contract_version INTO v_contract_version
  FROM hr_yuzhou_production_import_operation WHERE operation_id=NEW.operation_id;
  IF v_contract_version IS DISTINCT FROM 2 THEN RETURN NEW; END IF;

  SELECT count(*) INTO v_invalid
  FROM hr_yuzhou_production_import_record_dependency d
  JOIN hr_yuzhou_production_import_record child
    ON child.operation_id=d.operation_id AND child.phase=d.phase
   AND child.source_identity_sha256=d.source_identity_sha256
  WHERE d.operation_id=NEW.operation_id
    AND d.depends_on_phase=NEW.phase
    AND d.depends_on_source_identity_sha256=NEW.source_identity_sha256
    AND (
      NEW.planned_target_table<>d.expected_target_table
      OR (
        child.disposition<>'quarantine'
        AND (NEW.disposition='quarantine' OR NEW.target_table<>d.expected_target_table OR NEW.target_id IS NULL)
      )
    );
  IF v_invalid <> 0 THEN RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_V2_DEPENDENCY_TARGET_INVALID'; END IF;
  RETURN NEW;
END$$;



--
-- Name: hr_yuzhou_validate_production_import_v2_dependency_graph(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_validate_production_import_v2_dependency_graph() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_operation_id varchar(64) := COALESCE(NEW.operation_id,OLD.operation_id);
  v_phase varchar(8) := COALESCE(NEW.phase,OLD.phase);
  v_source_identity char(64) := COALESCE(NEW.source_identity_sha256,OLD.source_identity_sha256);
  v_record hr_yuzhou_production_import_record%ROWTYPE;
  v_contract_version smallint;
  v_total integer;
  v_invalid integer;
  v_required text[] := ARRAY[]::text[];
  v_optional text[] := ARRAY[]::text[];
BEGIN
  SELECT execution_contract_version INTO v_contract_version
  FROM hr_yuzhou_production_import_operation WHERE operation_id=v_operation_id;
  IF v_contract_version IS DISTINCT FROM 2 THEN RETURN COALESCE(NEW,OLD); END IF;

  SELECT * INTO v_record FROM hr_yuzhou_production_import_record
  WHERE operation_id=v_operation_id AND phase=v_phase AND source_identity_sha256=v_source_identity;
  IF NOT FOUND THEN RETURN COALESCE(NEW,OLD); END IF;
  IF v_record.planned_target_table IS NULL THEN RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_V2_PLANNED_TARGET_REQUIRED'; END IF;

  CASE v_record.planned_target_table
    WHEN 'sys_org' THEN v_optional := ARRAY['parent_org:sys_org'];
    WHEN 'hr_position' THEN v_required := ARRAY['org:sys_org']; v_optional := ARRAY['parent_position:hr_position'];
    WHEN 'hr_employee' THEN v_required := ARRAY['primary_org:sys_org']; v_optional := ARRAY['position:hr_position'];
    WHEN 'hr_employment_event' THEN v_required := ARRAY['employee:hr_employee'];
    WHEN 'hr_contract_type' THEN NULL;
    WHEN 'hr_contract' THEN v_required := ARRAY['employee:hr_employee','contract_type:hr_contract_type'];
    WHEN 'hr_contract_change' THEN v_required := ARRAY['contract:hr_contract'];
    WHEN 'hr_contract_legacy_evidence' THEN v_required := ARRAY['contract:hr_contract'];
    WHEN 'hr_attendance_import_batch' THEN NULL;
    WHEN 'hr_attendance_symbol_rule' THEN NULL;
    WHEN 'hr_attendance_calendar_source' THEN v_required := ARRAY['import_batch:hr_attendance_import_batch'];
    WHEN 'hr_attendance_day' THEN v_required := ARRAY['calendar_source:hr_attendance_calendar_source'];
    WHEN 'hr_insurance_policy' THEN NULL;
    WHEN 'hr_insurance_policy_item' THEN v_required := ARRAY['policy:hr_insurance_policy'];
    WHEN 'hr_employee_insurance_period' THEN v_required := ARRAY['employee:hr_employee'];
    WHEN 'hr_employee_insurance_item' THEN v_required := ARRAY['period:hr_employee_insurance_period'];
    WHEN 'hr_employee_profile' THEN IF v_record.disposition='quarantine' THEN v_optional := ARRAY['employee:hr_employee']; ELSE v_required := ARRAY['employee:hr_employee']; END IF;
    WHEN 'hr_employee_family' THEN IF v_record.disposition='quarantine' THEN v_optional := ARRAY['employee:hr_employee']; ELSE v_required := ARRAY['employee:hr_employee']; END IF;
    WHEN 'hr_employee_skill' THEN IF v_record.disposition='quarantine' THEN v_optional := ARRAY['employee:hr_employee']; ELSE v_required := ARRAY['employee:hr_employee']; END IF;
    WHEN 'hr_employee_credential' THEN IF v_record.disposition='quarantine' THEN v_optional := ARRAY['employee:hr_employee']; ELSE v_required := ARRAY['employee:hr_employee']; END IF;
    WHEN 'hr_custom_field_definition' THEN NULL;
    WHEN 'hr_employee_custom_value' THEN
      IF v_record.disposition='quarantine' THEN
        v_optional := ARRAY['employee:hr_employee','custom_field_definition:hr_custom_field_definition'];
      ELSE
        v_required := ARRAY['employee:hr_employee','custom_field_definition:hr_custom_field_definition'];
      END IF;
    ELSE RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_V2_PLANNED_TARGET_INVALID';
  END CASE;

  -- Missing parents are the reason for quarantine, not a reason to lose the source.
  -- Supplied roles/tables/parents remain validated below and by existing graph FKs.
  IF v_record.disposition='quarantine' THEN
    v_optional := v_optional || v_required;
    v_required := ARRAY[]::text[];
  END IF;

  SELECT count(*) INTO v_total FROM hr_yuzhou_production_import_record_dependency
  WHERE operation_id=v_operation_id AND phase=v_phase AND source_identity_sha256=v_source_identity;
  IF v_total <> cardinality(v_required) + (
    SELECT count(*) FROM hr_yuzhou_production_import_record_dependency d
    WHERE d.operation_id=v_operation_id AND d.phase=v_phase AND d.source_identity_sha256=v_source_identity
      AND (d.dependency_role||':'||d.expected_target_table)=ANY(v_optional)
  ) THEN RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_V2_DEPENDENCY_SET_INVALID'; END IF;

  SELECT count(*) INTO v_invalid
  FROM unnest(v_required) required_dependency
  WHERE NOT EXISTS (
    SELECT 1 FROM hr_yuzhou_production_import_record_dependency d
    WHERE d.operation_id=v_operation_id AND d.phase=v_phase AND d.source_identity_sha256=v_source_identity
      AND (d.dependency_role||':'||d.expected_target_table)=required_dependency
  );
  IF v_invalid <> 0 THEN RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_V2_DEPENDENCY_REQUIRED'; END IF;

  SELECT count(*) INTO v_invalid
  FROM hr_yuzhou_production_import_record_dependency d
  JOIN hr_yuzhou_production_import_record parent
    ON parent.operation_id=d.operation_id AND parent.phase=d.depends_on_phase
   AND parent.source_identity_sha256=d.depends_on_source_identity_sha256
  WHERE d.operation_id=v_operation_id AND d.phase=v_phase AND d.source_identity_sha256=v_source_identity
    AND (
      NOT ((d.dependency_role||':'||d.expected_target_table)=ANY(v_required||v_optional))
      OR parent.planned_target_table<>d.expected_target_table
      OR (
        v_record.disposition<>'quarantine'
        AND (parent.disposition='quarantine' OR parent.target_table<>d.expected_target_table OR parent.target_id IS NULL)
      )
    );
  IF v_invalid <> 0 THEN RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_V2_DEPENDENCY_TARGET_INVALID'; END IF;
  RETURN COALESCE(NEW,OLD);
END$$;



--
-- Name: hr_yuzhou_validate_production_import_v2_operation_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_validate_production_import_v2_operation_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND (
    NEW.execution_contract_version IS DISTINCT FROM OLD.execution_contract_version
    OR NEW.target_tenant_id IS DISTINCT FROM OLD.target_tenant_id
    OR NEW.target_park_id IS DISTINCT FROM OLD.target_park_id
    OR NEW.target_scope_sha256 IS DISTINCT FROM OLD.target_scope_sha256
  ) THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_TARGET_SCOPE_IMMUTABLE';
  END IF;
  IF NEW.execution_contract_version = 2
     AND NEW.target_scope_sha256 <> hr_yuzhou_production_target_scope_sha256(NEW.target_tenant_id,NEW.target_park_id) THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_TARGET_SCOPE_MISMATCH';
  END IF;
  RETURN NEW;
END$$;



--
-- Name: hr_yuzhou_validate_production_import_v2_phase_payload(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_validate_production_import_v2_phase_payload() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_contract_version smallint;
BEGIN
  SELECT execution_contract_version INTO v_contract_version
  FROM hr_yuzhou_production_import_operation WHERE operation_id=NEW.operation_id;
  IF v_contract_version=2 AND (
    NEW.payload_bundle_artifact_sha256 IS NULL OR NEW.payload_bundle_sha256 IS NULL OR NEW.canonicalization_version IS NULL
  ) THEN RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_V2_PAYLOAD_BINDING_REQUIRED'; END IF;
  IF v_contract_version=2 AND NEW.canonicalization_version <> 'yuzhou-production-import-canonical-json-v1' THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_V2_CANONICALIZATION_VERSION_INVALID';
  END IF;
  IF v_contract_version=1 AND (
    NEW.payload_bundle_artifact_sha256 IS NOT NULL OR NEW.payload_bundle_sha256 IS NOT NULL OR NEW.canonicalization_version IS NOT NULL
  ) THEN RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_V1_PAYLOAD_BINDING_FORBIDDEN'; END IF;
  RETURN NEW;
END$$;



--
-- Name: hr_yuzhou_validate_production_migration_batch(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_validate_production_migration_batch() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_operation hr_yuzhou_production_import_operation%ROWTYPE;
  v_phase hr_yuzhou_production_import_phase%ROWTYPE;
  v_invalid integer;
BEGIN
  IF TG_OP='UPDATE' AND (
    NEW.execution_context IS DISTINCT FROM OLD.execution_context
    OR NEW.production_import_operation_id IS DISTINCT FROM OLD.production_import_operation_id
    OR NEW.production_import_phase IS DISTINCT FROM OLD.production_import_phase
    OR NEW.run_id IS DISTINCT FROM OLD.run_id
    OR NEW.source_system IS DISTINCT FROM OLD.source_system
    OR NEW.source_snapshot_sha256 IS DISTINCT FROM OLD.source_snapshot_sha256
    OR NEW.target_database IS DISTINCT FROM OLD.target_database
    OR NEW.tool_version IS DISTINCT FROM OLD.tool_version
  ) THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_MIGRATION_BATCH_BINDING_IMMUTABLE';
  END IF;
  IF NEW.execution_context<>'production_import' THEN RETURN NEW; END IF;
  IF current_setting('transaction_isolation')<>'serializable' THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_REQUIRES_SERIALIZABLE';
  END IF;
  IF NEW.target_database<>current_database() THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_TARGET_DATABASE_MISMATCH';
  END IF;
  SELECT * INTO v_operation FROM hr_yuzhou_production_import_operation
    WHERE operation_id=NEW.production_import_operation_id FOR SHARE;
  IF NOT FOUND OR v_operation.execution_contract_version<>2 OR v_operation.status<>'running' THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_OPERATION_NOT_RUNNING';
  END IF;
  SELECT * INTO v_phase FROM hr_yuzhou_production_import_phase
    WHERE operation_id=NEW.production_import_operation_id AND phase=NEW.production_import_phase FOR SHARE;
  IF NOT FOUND OR v_phase.status<>'running' OR v_operation.current_phase IS DISTINCT FROM NEW.production_import_phase THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_PHASE_NOT_RUNNING';
  END IF;
  IF NEW.source_system<>'yuzhou-v10'
     OR NEW.source_snapshot_sha256<>v_operation.source_snapshot_sha256
     OR NEW.run_id<>NEW.production_import_operation_id||'-'||lower(NEW.production_import_phase)
     OR NEW.tool_version<>'prod-import-v2@'||v_operation.code_sha THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_MIGRATION_BATCH_BINDING_INVALID';
  END IF;
  SELECT count(*) INTO v_invalid
  FROM hr_yuzhou_production_import_phase candidate
  WHERE candidate.operation_id=v_operation.operation_id
    AND (
      (candidate.phase_ordinal<v_phase.phase_ordinal AND candidate.status<>'succeeded')
      OR (candidate.phase_ordinal=v_phase.phase_ordinal AND candidate.status<>'running')
      OR (candidate.phase_ordinal>v_phase.phase_ordinal AND candidate.status<>'planned')
    );
  IF v_invalid<>0 THEN RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_PHASE_ORDER_INVALID'; END IF;
  RETURN NEW;
END$$;



--
-- Name: hr_yuzhou_validate_production_projection_batch_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_validate_production_projection_batch_trigger() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_record record;
BEGIN
  IF COALESCE(NEW.execution_context,OLD.execution_context)='production_import' THEN
    FOR v_record IN
      SELECT operation_id,phase,source_identity_sha256
      FROM hr_yuzhou_production_import_record
      WHERE operation_id=COALESCE(NEW.production_import_operation_id,OLD.production_import_operation_id)
        AND phase=COALESCE(NEW.production_import_phase,OLD.production_import_phase)
    LOOP
      PERFORM hr_yuzhou_assert_production_projection_record(
        v_record.operation_id,v_record.phase,v_record.source_identity_sha256);
    END LOOP;
  END IF;
  RETURN COALESCE(NEW,OLD);
END$$;



--
-- Name: hr_yuzhou_validate_production_projection_map_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_validate_production_projection_map_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_receipt public.hr_yuzhou_production_import_projection_receipt%ROWTYPE;
BEGIN
  FOR v_receipt IN
    SELECT * FROM public.hr_yuzhou_production_import_projection_receipt
    WHERE legacy_record_map_id=COALESCE(NEW.id,OLD.id)
  LOOP
    PERFORM public.hr_yuzhou_assert_production_projection_record(
      v_receipt.operation_id,v_receipt.phase,v_receipt.source_identity_sha256);
  END LOOP;
  RETURN COALESCE(NEW,OLD);
END$$;



--
-- Name: hr_yuzhou_validate_production_projection_record_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_validate_production_projection_record_trigger() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP<>'INSERT' THEN
    PERFORM hr_yuzhou_assert_production_projection_record(
      OLD.operation_id,OLD.phase,OLD.source_identity_sha256);
  END IF;
  IF TG_OP<>'DELETE' THEN
    PERFORM hr_yuzhou_assert_production_projection_record(
      NEW.operation_id,NEW.phase,NEW.source_identity_sha256);
  END IF;
  RETURN COALESCE(NEW,OLD);
END$$;



--
-- Name: hr_yuzhou_validate_t5_nonfile_batch_actor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_validate_t5_nonfile_batch_actor() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP='UPDATE' THEN
    IF NEW.production_import_actor_id IS DISTINCT FROM OLD.production_import_actor_id THEN
      RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_T5_ACTOR_IMMUTABLE';
    END IF;
  END IF;
  IF NEW.execution_context='production_import' AND NEW.production_import_phase='T5' THEN
    IF NEW.production_import_actor_id IS NULL OR NOT EXISTS (
      SELECT 1
      FROM hr_yuzhou_production_import_operation operation
      JOIN sys_user actor
        ON actor.id=NEW.production_import_actor_id
       AND actor.tenant_id::text=operation.target_tenant_id
       AND actor.park_id::text=operation.target_park_id
       AND actor.is_enabled=true AND actor.status='enabled' AND actor.is_deleted=false
      WHERE operation.operation_id=NEW.production_import_operation_id
        AND operation.execution_contract_version=2
        AND operation.status='running' AND operation.current_phase='T5'
        AND operation.source_snapshot_sha256=NEW.source_snapshot_sha256
    ) THEN
      RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_T5_ACTOR_SCOPE_INVALID';
    END IF;
  ELSIF NEW.production_import_actor_id IS NOT NULL THEN
    RAISE EXCEPTION 'HR_PRODUCTION_IMPORT_T5_ACTOR_CONTEXT_INVALID';
  END IF;
  RETURN NEW;
END $$;



--
-- Name: hr_yuzhou_verify_performance_owner_maps_v1(character varying, character varying, uuid, bigint, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hr_yuzhou_verify_performance_owner_maps_v1(p_tenant_id character varying, p_park_id character varying, p_batch_id uuid, p_expected_relation_maps bigint, p_replayed boolean) RETURNS TABLE(fact_owner_maps bigint, relation_owner_maps bigint, verified_owner_maps bigint, owner_map_state_sha256 character)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_before record; v_after record; v_updated bigint;
BEGIN
  IF current_setting('transaction_isolation')<>'serializable'
    OR p_expected_relation_maps<0 THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_OWNER_MAP_VERIFICATION_CONTEXT_INVALID'; END IF;
  SELECT * INTO STRICT v_before FROM public.hr_yuzhou_performance_owner_map_state_v1(
    p_tenant_id,p_park_id,p_batch_id);
  IF v_before.relation_owner_maps<>p_expected_relation_maps
    OR v_before.owner_maps<>v_before.fact_owner_maps+v_before.relation_owner_maps
    OR v_before.distinct_owner_maps<>v_before.owner_maps
    OR v_before.active_target_maps<>v_before.owner_maps
    OR v_before.invalid_owner_maps<>0 THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_OWNER_MAP_CONSERVATION_FAILED'; END IF;
  IF p_replayed THEN
    IF v_before.loaded_owner_maps<>0 OR v_before.verified_owner_maps<>v_before.owner_maps THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_OWNER_MAP_REPLAY_DRIFT'; END IF;
  ELSE
    IF v_before.loaded_owner_maps<>v_before.owner_maps OR v_before.verified_owner_maps<>0 THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_OWNER_MAP_PRECONDITION_FAILED'; END IF;
    UPDATE public.legacy_record_map map SET mapping_status='verified',update_time=now()
    FROM public.hr_yuzhou_performance_owner_map_projection_v1(
      p_tenant_id,p_park_id,p_batch_id) owner
    WHERE map.id=owner.legacy_record_map_id AND owner.exact_binding
      AND owner.mapping_status='loaded' AND map.mapping_status='loaded' AND map.is_active;
    GET DIAGNOSTICS v_updated=ROW_COUNT;
    IF v_updated<>v_before.owner_maps THEN
      RAISE EXCEPTION 'HR_PERFORMANCE_OWNER_MAP_PROMOTION_FAILED'; END IF;
    SET CONSTRAINTS ALL IMMEDIATE;
  END IF;
  SELECT * INTO STRICT v_after FROM public.hr_yuzhou_performance_owner_map_state_v1(
    p_tenant_id,p_park_id,p_batch_id);
  IF v_after.fact_owner_maps<>v_before.fact_owner_maps
    OR v_after.relation_owner_maps<>v_before.relation_owner_maps
    OR v_after.owner_maps<>v_before.owner_maps
    OR v_after.distinct_owner_maps<>v_after.owner_maps
    OR v_after.active_target_maps<>v_after.owner_maps
    OR v_after.loaded_owner_maps<>0 OR v_after.verified_owner_maps<>v_after.owner_maps
    OR v_after.invalid_owner_maps<>0 THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_OWNER_MAP_PROMOTION_FAILED'; END IF;
  RETURN QUERY SELECT v_after.fact_owner_maps,v_after.relation_owner_maps,
    v_after.verified_owner_maps,v_after.owner_map_state_sha256;
END$$;



--
-- Name: materialize_yuzhou_performance_legacy_lab(character varying, character varying, uuid, jsonb); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.materialize_yuzhou_performance_legacy_lab(IN p_tenant_id character varying, IN p_park_id character varying, IN p_batch_id uuid, IN p_payload jsonb)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_row jsonb;
  v_map_id uuid;
  v_fact_id uuid;
  v_parent_id uuid;
  v_level_id uuid;
  v_expected bigint;
  v_actual bigint;
  v_entry record;
BEGIN
  IF current_setting('transaction_isolation')<>'serializable' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_WRITER_REQUIRES_SERIALIZABLE';
  END IF;
  PERFORM 1 FROM migration_batch batch
  WHERE batch.id=p_batch_id AND batch.source_system='yuzhou-v10'
    AND batch.target_database=current_database()
    AND (
      (batch.execution_context='lab_rehearsal'
        AND batch.phase='load' AND batch.status='running')
      OR public.hr_yuzhou_performance_facts_production_context_allowed_v1(p_batch_id,'apply')
    )
  FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_WRITER_BATCH_INVALID'; END IF;
  IF btrim(COALESCE(p_tenant_id,''))='' OR btrim(COALESCE(p_park_id,''))='' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_WRITER_SCOPE_INVALID';
  END IF;
  IF NOT hr_performance_yuzhou_jsonb_exact_keys(
    p_payload,ARRAY['assessmentcode','assgradecode','assitem','assitemgradedes','assessmentdetail']
  ) OR EXISTS(
    SELECT 1 FROM jsonb_each(p_payload) entry WHERE jsonb_typeof(entry.value)<>'array'
  ) THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_WRITER_PAYLOAD_INVALID';
  END IF;

  LOCK TABLE legacy_record_map,
    hr_performance_legacy_template_profile,hr_performance_legacy_level_rule,
    hr_performance_legacy_dimension_profile,hr_performance_legacy_dimension_level_guide,
    hr_performance_legacy_dimension_result IN SHARE ROW EXCLUSIVE MODE;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_payload->'assessmentcode') LOOP
    IF NOT hr_performance_yuzhou_jsonb_exact_keys(v_row,ARRAY[
      'sourceIdentitySha256','sourceRowSha256','assessment','assessmentname','department',
      'mpercent','tpercent','xpercent','cpercent','spercent','timekeep','bonus','master'
    ]) THEN RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_WRITER_ASSESSMENTCODE_INVALID'; END IF;
    SELECT map_id,fact_id INTO v_map_id,v_fact_id
    FROM hr_performance_yuzhou_prepare_record_map(
      p_batch_id,'dbo.assessmentcode',v_row->>'sourceIdentitySha256',v_row->>'sourceRowSha256',
      'hr_performance_legacy_template_profile'
    );
    INSERT INTO hr_performance_legacy_template_profile(
      id,tenant_id,park_id,migration_batch_id,legacy_record_map_id,
      source_identity_sha256,source_row_sha256,source_assessment,source_assessment_name,
      source_department,source_m_percent,source_t_percent,source_x_percent,source_c_percent,
      source_s_percent,source_timekeep,source_bonus,source_master
    ) VALUES(
      v_fact_id,p_tenant_id,p_park_id,p_batch_id,v_map_id,
      v_row->>'sourceIdentitySha256',v_row->>'sourceRowSha256',(v_row->>'assessment')::integer,
      v_row->>'assessmentname',v_row->>'department',(v_row->>'mpercent')::integer,
      (v_row->>'tpercent')::integer,(v_row->>'xpercent')::integer,(v_row->>'cpercent')::integer,
      (v_row->>'spercent')::integer,(v_row->>'timekeep')::boolean,
      (v_row->>'bonus')::boolean,(v_row->>'master')::boolean
    ) ON CONFLICT(migration_batch_id,tenant_id,park_id,source_assessment) DO NOTHING;
    IF NOT EXISTS(
      SELECT 1 FROM hr_performance_legacy_template_profile fact
      WHERE fact.id=v_fact_id AND fact.legacy_record_map_id=v_map_id
        AND fact.source_row_sha256=v_row->>'sourceRowSha256'
        AND (fact.tenant_id,fact.park_id,fact.migration_batch_id)=(p_tenant_id,p_park_id,p_batch_id)
    ) THEN RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_WRITER_REPLAY_DRIFT'; END IF;
  END LOOP;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_payload->'assgradecode') LOOP
    IF NOT hr_performance_yuzhou_jsonb_exact_keys(v_row,ARRAY[
      'sourceIdentitySha256','sourceRowSha256','assgrade','description','myorder',
      'assessmentid','minvalue','maxvalue'
    ]) THEN RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_WRITER_ASSGRADECODE_INVALID'; END IF;
    SELECT id INTO v_parent_id FROM hr_performance_legacy_template_profile
    WHERE (tenant_id,park_id,migration_batch_id,source_assessment)=
      (p_tenant_id,p_park_id,p_batch_id,(v_row->>'assessmentid')::integer);
    SELECT map_id,fact_id INTO v_map_id,v_fact_id
    FROM hr_performance_yuzhou_prepare_record_map(
      p_batch_id,'dbo.assgradecode',v_row->>'sourceIdentitySha256',v_row->>'sourceRowSha256',
      'hr_performance_legacy_level_rule'
    );
    INSERT INTO hr_performance_legacy_level_rule(
      id,tenant_id,park_id,migration_batch_id,legacy_record_map_id,source_identity_sha256,
      source_row_sha256,source_ass_grade,source_description,source_my_order,
      source_assessment_id,source_min_value,source_max_value,legacy_template_profile_id
    ) VALUES(
      v_fact_id,p_tenant_id,p_park_id,p_batch_id,v_map_id,v_row->>'sourceIdentitySha256',
      v_row->>'sourceRowSha256',v_row->>'assgrade',v_row->>'description',v_row->>'myorder',
      (v_row->>'assessmentid')::integer,(v_row->>'minvalue')::integer,
      (v_row->>'maxvalue')::integer,v_parent_id
    ) ON CONFLICT(migration_batch_id,tenant_id,park_id,source_ass_grade) DO NOTHING;
    IF NOT EXISTS(
      SELECT 1 FROM hr_performance_legacy_level_rule fact
      WHERE fact.id=v_fact_id AND fact.legacy_record_map_id=v_map_id
        AND fact.source_row_sha256=v_row->>'sourceRowSha256'
        AND fact.legacy_template_profile_id IS NOT DISTINCT FROM v_parent_id
    ) THEN RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_WRITER_REPLAY_DRIFT'; END IF;
  END LOOP;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_payload->'assitem') LOOP
    IF NOT hr_performance_yuzhou_jsonb_exact_keys(v_row,ARRAY[
      'sourceIdentitySha256','sourceRowSha256','id','assid','assitem','fullvalue','myorder'
    ]) THEN RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_WRITER_ASSITEM_INVALID'; END IF;
    SELECT id INTO v_parent_id FROM hr_performance_legacy_template_profile
    WHERE (tenant_id,park_id,migration_batch_id,source_assessment)=
      (p_tenant_id,p_park_id,p_batch_id,(v_row->>'assid')::integer);
    SELECT map_id,fact_id INTO v_map_id,v_fact_id
    FROM hr_performance_yuzhou_prepare_record_map(
      p_batch_id,'dbo.assitem',v_row->>'sourceIdentitySha256',v_row->>'sourceRowSha256',
      'hr_performance_legacy_dimension_profile'
    );
    INSERT INTO hr_performance_legacy_dimension_profile(
      id,tenant_id,park_id,migration_batch_id,legacy_record_map_id,source_identity_sha256,
      source_row_sha256,source_item_id,source_assessment_id,source_item_name,
      source_full_value,source_my_order,legacy_template_profile_id
    ) VALUES(
      v_fact_id,p_tenant_id,p_park_id,p_batch_id,v_map_id,v_row->>'sourceIdentitySha256',
      v_row->>'sourceRowSha256',(v_row->>'id')::integer,(v_row->>'assid')::integer,
      v_row->>'assitem',(v_row->>'fullvalue')::numeric(18,2),(v_row->>'myorder')::integer,v_parent_id
    ) ON CONFLICT(migration_batch_id,tenant_id,park_id,source_item_id) DO NOTHING;
    IF NOT EXISTS(
      SELECT 1 FROM hr_performance_legacy_dimension_profile fact
      WHERE fact.id=v_fact_id AND fact.legacy_record_map_id=v_map_id
        AND fact.source_row_sha256=v_row->>'sourceRowSha256'
        AND fact.legacy_template_profile_id IS NOT DISTINCT FROM v_parent_id
    ) THEN RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_WRITER_REPLAY_DRIFT'; END IF;
  END LOOP;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_payload->'assitemgradedes') LOOP
    IF NOT hr_performance_yuzhou_jsonb_exact_keys(v_row,ARRAY[
      'sourceIdentitySha256','sourceRowSha256','id','assitemid','grade','description',
      'minvalue','maxvalue','myorder'
    ]) THEN RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_WRITER_ASSITEMGRADEDES_INVALID'; END IF;
    SELECT id INTO v_parent_id FROM hr_performance_legacy_dimension_profile
    WHERE (tenant_id,park_id,migration_batch_id,source_item_id)=
      (p_tenant_id,p_park_id,p_batch_id,(v_row->>'assitemid')::integer);
    SELECT id INTO v_level_id FROM hr_performance_legacy_level_rule
    WHERE (tenant_id,park_id,migration_batch_id,source_ass_grade)=
      (p_tenant_id,p_park_id,p_batch_id,v_row->>'grade');
    SELECT map_id,fact_id INTO v_map_id,v_fact_id
    FROM hr_performance_yuzhou_prepare_record_map(
      p_batch_id,'dbo.assitemgradedes',v_row->>'sourceIdentitySha256',v_row->>'sourceRowSha256',
      'hr_performance_legacy_dimension_level_guide'
    );
    INSERT INTO hr_performance_legacy_dimension_level_guide(
      id,tenant_id,park_id,migration_batch_id,legacy_record_map_id,source_identity_sha256,
      source_row_sha256,source_guide_id,source_item_id,source_grade,source_description,
      source_min_value,source_max_value,source_my_order,legacy_dimension_profile_id,legacy_level_rule_id
    ) VALUES(
      v_fact_id,p_tenant_id,p_park_id,p_batch_id,v_map_id,v_row->>'sourceIdentitySha256',
      v_row->>'sourceRowSha256',(v_row->>'id')::integer,(v_row->>'assitemid')::integer,
      v_row->>'grade',v_row->>'description',(v_row->>'minvalue')::integer,
      (v_row->>'maxvalue')::integer,(v_row->>'myorder')::integer,v_parent_id,v_level_id
    ) ON CONFLICT(migration_batch_id,tenant_id,park_id,source_guide_id) DO NOTHING;
    IF NOT EXISTS(
      SELECT 1 FROM hr_performance_legacy_dimension_level_guide fact
      WHERE fact.id=v_fact_id AND fact.legacy_record_map_id=v_map_id
        AND fact.source_row_sha256=v_row->>'sourceRowSha256'
        AND fact.legacy_dimension_profile_id IS NOT DISTINCT FROM v_parent_id
        AND fact.legacy_level_rule_id IS NOT DISTINCT FROM v_level_id
    ) THEN RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_WRITER_REPLAY_DRIFT'; END IF;
  END LOOP;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_payload->'assessmentdetail') LOOP
    IF NOT hr_performance_yuzhou_jsonb_exact_keys(v_row,ARRAY[
      'sourceIdentitySha256','sourceRowSha256','id','asssessionid','person','assitemid',
      'selfvalue','mitemvalue','itemvalue','xitemvalue','citemvalue','selfgrade','assgrade','appraisal'
    ]) THEN RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_WRITER_ASSESSMENTDETAIL_INVALID'; END IF;
    SELECT id INTO v_parent_id FROM hr_performance_legacy_dimension_profile
    WHERE (tenant_id,park_id,migration_batch_id,source_item_id)=
      (p_tenant_id,p_park_id,p_batch_id,(v_row->>'assitemid')::integer);
    SELECT map_id,fact_id INTO v_map_id,v_fact_id
    FROM hr_performance_yuzhou_prepare_record_map(
      p_batch_id,'dbo.assessmentdetail',v_row->>'sourceIdentitySha256',v_row->>'sourceRowSha256',
      'hr_performance_legacy_dimension_result'
    );
    INSERT INTO hr_performance_legacy_dimension_result(
      id,tenant_id,park_id,migration_batch_id,legacy_record_map_id,source_identity_sha256,
      source_row_sha256,source_detail_id,source_session_id,source_person_code,source_item_id,
      source_self_value,source_m_item_value,source_item_value,source_x_item_value,source_c_item_value,
      source_self_grade,source_ass_grade,source_appraisal,legacy_dimension_profile_id
    ) VALUES(
      v_fact_id,p_tenant_id,p_park_id,p_batch_id,v_map_id,v_row->>'sourceIdentitySha256',
      v_row->>'sourceRowSha256',(v_row->>'id')::integer,(v_row->>'asssessionid')::integer,
      v_row->>'person',(v_row->>'assitemid')::integer,(v_row->>'selfvalue')::numeric(18,2),
      (v_row->>'mitemvalue')::numeric(18,2),(v_row->>'itemvalue')::numeric(18,2),
      (v_row->>'xitemvalue')::numeric(18,2),(v_row->>'citemvalue')::numeric(18,2),
      v_row->>'selfgrade',v_row->>'assgrade',v_row->>'appraisal',v_parent_id
    ) ON CONFLICT(migration_batch_id,tenant_id,park_id,source_detail_id) DO NOTHING;
    IF NOT EXISTS(
      SELECT 1 FROM hr_performance_legacy_dimension_result fact
      WHERE fact.id=v_fact_id AND fact.legacy_record_map_id=v_map_id
        AND fact.source_row_sha256=v_row->>'sourceRowSha256'
        AND fact.legacy_dimension_profile_id IS NOT DISTINCT FROM v_parent_id
    ) THEN RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_WRITER_REPLAY_DRIFT'; END IF;
  END LOOP;

  FOR v_entry IN SELECT * FROM jsonb_each(p_payload) LOOP
    v_expected:=jsonb_array_length(v_entry.value);
    EXECUTE format(
      'SELECT count(*) FROM %I WHERE tenant_id=$1 AND park_id=$2 AND migration_batch_id=$3',
      CASE v_entry.key
        WHEN 'assessmentcode' THEN 'hr_performance_legacy_template_profile'
        WHEN 'assgradecode' THEN 'hr_performance_legacy_level_rule'
        WHEN 'assitem' THEN 'hr_performance_legacy_dimension_profile'
        WHEN 'assitemgradedes' THEN 'hr_performance_legacy_dimension_level_guide'
        WHEN 'assessmentdetail' THEN 'hr_performance_legacy_dimension_result'
      END
    ) INTO v_actual USING p_tenant_id,p_park_id,p_batch_id;
    IF v_actual<>v_expected THEN RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_WRITER_CONSERVATION_FAILED'; END IF;
  END LOOP;
  SET CONSTRAINTS ALL IMMEDIATE;
END$_$;



--
-- Name: materialize_yuzhou_performance_legacy_master_lab(character varying, character varying, uuid, jsonb); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.materialize_yuzhou_performance_legacy_master_lab(IN p_tenant_id character varying, IN p_park_id character varying, IN p_batch_id uuid, IN p_payload jsonb)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_row jsonb;
  v_map_id uuid;
  v_fact_id uuid;
  v_template_id uuid;
  v_expected bigint;
  v_actual bigint;
BEGIN
  IF current_setting('transaction_isolation')<>'serializable' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_MASTER_WRITER_REQUIRES_SERIALIZABLE';
  END IF;
  PERFORM 1 FROM migration_batch batch
  WHERE batch.id=p_batch_id AND batch.source_system='yuzhou-v10'
    AND batch.target_database=current_database()
    AND (
      (batch.execution_context='lab_rehearsal'
        AND batch.phase='load' AND batch.status='running')
      OR public.hr_yuzhou_performance_facts_production_context_allowed_v1(p_batch_id,'apply')
    )
  FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_MASTER_WRITER_BATCH_INVALID'; END IF;
  IF btrim(COALESCE(p_tenant_id,''))='' OR btrim(COALESCE(p_park_id,''))='' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_MASTER_WRITER_SCOPE_INVALID';
  END IF;
  IF NOT hr_performance_yuzhou_jsonb_exact_keys(p_payload,ARRAY['assessmentmaster'])
    OR jsonb_typeof(p_payload->'assessmentmaster')<>'array' THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_MASTER_WRITER_PAYLOAD_INVALID';
  END IF;

  LOCK TABLE legacy_record_map,hr_performance_legacy_master_result,
    hr_performance_legacy_template_profile,hr_performance_legacy_dimension_profile,
    hr_performance_legacy_dimension_result IN SHARE ROW EXCLUSIVE MODE;

  FOR v_row IN SELECT value FROM jsonb_array_elements(p_payload->'assessmentmaster') LOOP
    IF NOT hr_performance_yuzhou_jsonb_exact_keys(v_row,ARRAY[
      'sourceIdentitySha256','sourceRowSha256','id','asssessionid','person','selfgrade',
      'assgrade','selfvalue','itemvalue','mitemvalue','xitemvalue','citemvalue',
      'mastervalue','timekeepvalue','bonusvalue','totalvalue','selfappraisal','appraisal',
      'pay','assessmentperson','recdate','operator','des'
    ]) THEN RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_MASTER_WRITER_ROW_INVALID'; END IF;

    v_template_id:=NULL;
    SELECT min(candidate.template_id::text)::uuid INTO v_template_id
    FROM (
      SELECT DISTINCT dimension.legacy_template_profile_id template_id
      FROM hr_performance_legacy_dimension_result result
      JOIN hr_performance_legacy_dimension_profile dimension
        ON (dimension.id,dimension.tenant_id,dimension.park_id,dimension.migration_batch_id)=
           (result.legacy_dimension_profile_id,result.tenant_id,result.park_id,result.migration_batch_id)
      WHERE (result.tenant_id,result.park_id,result.migration_batch_id)=
            (p_tenant_id,p_park_id,p_batch_id)
        AND result.source_session_id IS NOT DISTINCT FROM (v_row->>'asssessionid')::integer
        AND result.source_person_code IS NOT DISTINCT FROM v_row->>'person'
        AND dimension.legacy_template_profile_id IS NOT NULL
    ) candidate
    HAVING count(*)=1;

    SELECT map_id,fact_id INTO v_map_id,v_fact_id
    FROM hr_performance_yuzhou_prepare_master_record_map(
      p_batch_id,v_row->>'sourceIdentitySha256',v_row->>'sourceRowSha256'
    );
    INSERT INTO hr_performance_legacy_master_result(
      id,tenant_id,park_id,migration_batch_id,legacy_record_map_id,
      source_identity_sha256,source_row_sha256,source_master_id,source_session_id,
      source_person_code,source_self_grade,source_ass_grade,source_self_value,source_item_value,
      source_m_item_value,source_x_item_value,source_c_item_value,source_master_value,
      source_timekeep_value,source_bonus_value,source_total_value,source_self_appraisal,
      source_appraisal,source_pay,source_assessment_person,source_recorded_at,
      source_operator_code,source_description,legacy_template_profile_id
    ) VALUES(
      v_fact_id,p_tenant_id,p_park_id,p_batch_id,v_map_id,
      v_row->>'sourceIdentitySha256',v_row->>'sourceRowSha256',(v_row->>'id')::integer,
      (v_row->>'asssessionid')::integer,v_row->>'person',v_row->>'selfgrade',v_row->>'assgrade',
      (v_row->>'selfvalue')::numeric(18,2),(v_row->>'itemvalue')::numeric(18,2),
      (v_row->>'mitemvalue')::numeric(18,0),(v_row->>'xitemvalue')::numeric(18,0),
      (v_row->>'citemvalue')::numeric(18,0),(v_row->>'mastervalue')::numeric(18,2),
      (v_row->>'timekeepvalue')::numeric(18,2),(v_row->>'bonusvalue')::numeric(18,2),
      (v_row->>'totalvalue')::numeric(18,2),v_row->>'selfappraisal',v_row->>'appraisal',
      (v_row->>'pay')::numeric(19,4),v_row->>'assessmentperson',
      (v_row->>'recdate')::timestamp without time zone,v_row->>'operator',v_row->>'des',
      v_template_id
    ) ON CONFLICT(migration_batch_id,tenant_id,park_id,source_master_id) DO NOTHING;
    IF NOT EXISTS(
      SELECT 1 FROM hr_performance_legacy_master_result fact
      WHERE fact.id=v_fact_id AND fact.legacy_record_map_id=v_map_id
        AND fact.source_row_sha256=v_row->>'sourceRowSha256'
        AND fact.legacy_template_profile_id IS NOT DISTINCT FROM v_template_id
        AND (fact.tenant_id,fact.park_id,fact.migration_batch_id)=
            (p_tenant_id,p_park_id,p_batch_id)
    ) THEN RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_MASTER_WRITER_REPLAY_DRIFT'; END IF;
  END LOOP;

  v_expected:=jsonb_array_length(p_payload->'assessmentmaster');
  SELECT count(*) INTO v_actual FROM hr_performance_legacy_master_result
  WHERE (tenant_id,park_id,migration_batch_id)=(p_tenant_id,p_park_id,p_batch_id);
  IF v_actual<>v_expected THEN
    RAISE EXCEPTION 'HR_PERFORMANCE_LEGACY_MASTER_WRITER_CONSERVATION_FAILED';
  END IF;
  SET CONSTRAINTS ALL IMMEDIATE;
END$$;



--
-- Name: prevent_hr_contract_action_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_hr_contract_action_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'hr_contract_action is append-only';
END $$;



--
-- Name: biz_user_message; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.biz_user_message (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    tenant_id character varying(64) NOT NULL,
    park_id character varying(64) NOT NULL,
    recipient_id uuid NOT NULL,
    recipient_name character varying(100),
    sender_id uuid,
    sender_name character varying(100),
    category character varying(64) DEFAULT 'workflow'::character varying NOT NULL,
    priority character varying(32) DEFAULT 'normal'::character varying NOT NULL,
    source_type character varying(64) NOT NULL,
    source_id uuid,
    biz_type character varying(64) NOT NULL,
    biz_id uuid,
    action character varying(64),
    title character varying(200) NOT NULL,
    content text,
    target_url character varying(255),
    read_at timestamp with time zone,
    archived_at timestamp with time zone,
    unique_key character varying(180) NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    create_by uuid,
    create_time timestamp with time zone DEFAULT now() NOT NULL,
    update_by uuid,
    update_time timestamp with time zone DEFAULT now() NOT NULL,
    is_deleted boolean DEFAULT false NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    remark character varying(500)
);



--
-- Name: hr_approval_action; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.hr_approval_action (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    tenant_id character varying(64) NOT NULL,
    park_id character varying(64) NOT NULL,
    request_id uuid NOT NULL,
    action character varying(32) NOT NULL,
    actor_user_id uuid NOT NULL,
    comment character varying(1000),
    before_status character varying(32) NOT NULL,
    after_status character varying(32) NOT NULL,
    create_by uuid,
    create_time timestamp with time zone DEFAULT now() NOT NULL,
    update_by uuid,
    update_time timestamp with time zone DEFAULT now() NOT NULL,
    is_deleted boolean DEFAULT false NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    remark character varying(500),
    before_content jsonb,
    after_content jsonb,
    CONSTRAINT ck_hr_approval_action CHECK (((action)::text = ANY ((ARRAY['submit'::character varying, 'approve'::character varying, 'return'::character varying, 'withdraw'::character varying, 'resubmit'::character varying, 'edit'::character varying])::text[]))),
    CONSTRAINT ck_hr_approval_action_edit_content CHECK ((((action)::text <> 'edit'::text) OR ((before_content IS NOT NULL) AND (after_content IS NOT NULL) AND (jsonb_typeof(before_content) = 'object'::text) AND (jsonb_typeof(after_content) = 'object'::text))))
);



--
