    CONSTRAINT ck_hr_perf_employee_goals CHECK ((jsonb_typeof(goal_snapshot) = 'array'::text)),
    CONSTRAINT ck_hr_perf_employee_result_scores CHECK (((calculation_mode = ANY (ARRAY['dimension_weighted_v1'::text, 'five_channel_v1'::text])) AND public.hr_performance_channel_finite_score(self_score) AND public.hr_performance_channel_finite_score(manager_score) AND public.hr_performance_channel_finite_score(calibrated_score) AND public.hr_performance_channel_finite_score(final_score) AND ((calculation_mode = 'five_channel_v1'::text) OR (((self_score IS NULL) OR ((self_score >= (0)::numeric) AND (self_score <= (100)::numeric))) AND ((manager_score IS NULL) OR ((manager_score >= (0)::numeric) AND (manager_score <= (100)::numeric))) AND ((calibrated_score IS NULL) OR ((calibrated_score >= (0)::numeric) AND (calibrated_score <= (100)::numeric))) AND ((final_score IS NULL) OR ((final_score >= (0)::numeric) AND (final_score <= (100)::numeric)))))))
);



