    CONSTRAINT ck_hr_perf_ass_compute_comparison CHECK ((((comparison_status)::text = ANY ((ARRAY['matched'::character varying, 'mismatch'::character varying, 'not_comparable'::character varying])::text[])) AND ((((comparison_status)::text = ANY ((ARRAY['matched'::character varying, 'mismatch'::character varying])::text[])) AND ((person_resolution_status)::text = 'resolved'::text) AND ((detail_resolution_status)::text = 'resolved'::text)) OR (((comparison_status)::text = 'not_comparable'::text) AND (((person_resolution_status)::text <> 'resolved'::text) OR ((detail_resolution_status)::text <> 'resolved'::text)))) AND (((comparison_status)::text <> 'matched'::text) OR (person_template_profile_id = detail_template_profile_id)) AND (((comparison_status)::text <> 'mismatch'::text) OR (person_template_profile_id <> detail_template_profile_id)))),
    CONSTRAINT ck_hr_perf_ass_compute_detail_status CHECK (((((detail_resolution_status)::text = 'unmatched'::text) AND (detail_template_candidate_count = 0) AND (detail_template_profile_id IS NULL)) OR (((detail_resolution_status)::text = 'ambiguous'::text) AND (detail_template_candidate_count > 1) AND (detail_template_profile_id IS NULL)) OR (((detail_resolution_status)::text = 'resolved'::text) AND (detail_template_candidate_count = 1) AND (detail_template_profile_id IS NOT NULL)))),
    CONSTRAINT ck_hr_perf_ass_compute_person_status CHECK (((person_resolution_status)::text = ANY ((ARRAY['not_applicable'::character varying, 'evidence_unmatched'::character varying, 'evidence_ambiguous'::character varying, 'assessment_missing'::character varying, 'template_unmatched'::character varying, 'template_ambiguous'::character varying, 'resolved'::character varying])::text[]))),
    CONSTRAINT ck_hr_perf_ass_compute_person_target CHECK (((((person_resolution_status)::text = 'not_applicable'::text) AND (source_person_identity_sha256 IS NULL) AND (source_person_evidence_count = 0) AND (source_person_assessment_id IS NULL) AND (person_template_candidate_count = 0) AND (person_template_profile_id IS NULL)) OR (((person_resolution_status)::text = 'evidence_unmatched'::text) AND (source_person_identity_sha256 IS NOT NULL) AND (source_person_evidence_count = 0) AND (source_person_assessment_id IS NULL) AND (person_template_candidate_count = 0) AND (person_template_profile_id IS NULL)) OR (((person_resolution_status)::text = 'evidence_ambiguous'::text) AND (source_person_identity_sha256 IS NOT NULL) AND (source_person_evidence_count > 1) AND (source_person_assessment_id IS NULL) AND (person_template_candidate_count = 0) AND (person_template_profile_id IS NULL)) OR (((person_resolution_status)::text = 'assessment_missing'::text) AND (source_person_identity_sha256 IS NOT NULL) AND (source_person_evidence_count = 1) AND (source_person_assessment_id IS NULL) AND (person_template_candidate_count = 0) AND (person_template_profile_id IS NULL)) OR (((person_resolution_status)::text = 'template_unmatched'::text) AND (source_person_identity_sha256 IS NOT NULL) AND (source_person_evidence_count = 1) AND (source_person_assessment_id IS NOT NULL) AND (person_template_candidate_count = 0) AND (person_template_profile_id IS NULL)) OR (((person_resolution_status)::text = 'template_ambiguous'::text) AND (source_person_identity_sha256 IS NOT NULL) AND (source_person_evidence_count = 1) AND (source_person_assessment_id IS NOT NULL) AND (person_template_candidate_count > 1) AND (person_template_profile_id IS NULL)) OR (((person_resolution_status)::text = 'resolved'::text) AND (source_person_identity_sha256 IS NOT NULL) AND (source_person_evidence_count = 1) AND (source_person_assessment_id IS NOT NULL) AND (person_template_candidate_count = 1) AND (person_template_profile_id IS NOT NULL)))),
    CONSTRAINT ck_hr_perf_ass_compute_resolution_counts CHECK (((source_person_evidence_count >= 0) AND (person_template_candidate_count >= 0) AND (detail_template_candidate_count >= 0))),
    CONSTRAINT ck_hr_perf_ass_compute_resolution_hashes CHECK ((((source_person_identity_sha256 IS NULL) OR (source_person_identity_sha256 ~ '^[0-9a-f]{64}$'::text)) AND (evidence_sha256 ~ '^[0-9a-f]{64}$'::text)))
);



