    CONSTRAINT ck_migration_batch_run_id CHECK (((run_id)::text ~ '^[A-Za-z0-9][A-Za-z0-9._-]{5,63}$'::text)),
    CONSTRAINT ck_migration_batch_snapshot CHECK ((source_snapshot_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ck_migration_batch_status CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'running'::character varying, 'succeeded'::character varying, 'failed'::character varying, 'cancelled'::character varying, 'rolled_back'::character varying])::text[])))
);



