    extracted_count bigint DEFAULT 0 NOT NULL,
    valid_count bigint DEFAULT 0 NOT NULL,
    loaded_count bigint DEFAULT 0 NOT NULL,
    rejected_count bigint DEFAULT 0 NOT NULL,
    checksum_sha256 character(64),
