    CONSTRAINT ck_migration_batch_item_counts CHECK (((extracted_count >= 0) AND (valid_count >= 0) AND (loaded_count >= 0) AND (rejected_count >= 0) AND ((valid_count + rejected_count) <= extracted_count) AND (loaded_count <= valid_count))),
    CONSTRAINT ck_migration_batch_item_phase CHECK (((phase)::text = ANY ((ARRAY['inventory'::character varying, 'extract'::character varying, 'profile'::character varying, 'transform'::character varying, 'load'::character varying, 'verify'::character varying, 'report'::character varying, 'rollback'::character varying])::text[]))),
    CONSTRAINT ck_migration_batch_item_status CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'running'::character varying, 'succeeded'::character varying, 'failed'::character varying, 'skipped'::character varying, 'quarantined'::character varying])::text[])))
);



